{"command":"mkdir -p /workspace/src && cd /workspace/src && cat > ks.h <<'EOF'
/* Simple growable string utilities */
#ifndef KS_H
#define KS_H
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdint.h>

typedef struct { size_t l, m; char *s; } kstr;

static inline void ks_grow(kstr *k, size_t extra) {
    if (k->l + extra + 1 > k->m) {
        size_t nm = k->m ? k->m : 64;
        while (nm < k->l + extra + 1) nm <<= 1;
        k->s = (char*)realloc(k->s, nm);
        k->m = nm;
    }
}
static inline void ks_clear(kstr *k) { k->l = 0; if (k->s) k->s[0] = 0; }
static inline void ks_free(kstr *k) { free(k->s); k->s = NULL; k->l = k->m = 0; }
static inline void ks_putsn(kstr *k, const char *p, size_t n) {
    ks_grow(k, n); memcpy(k->s + k->l, p, n); k->l += n; k->s[k->l] = 0;
}
static inline void ks_puts(kstr *k, const char *p) { ks_putsn(k, p, strlen(p)); }
static inline void ks_putc(kstr *k, int c) { ks_grow(k, 1); k->s[k->l++] = (char)c; k->s[k->l] = 0; }
static inline void ks_putu64(kstr *k, uint64_t v) {
    char b[24]; int i = 0;
    do { b[i++] = '0' + v % 10; v /= 10; } while (v);
    ks_grow(k, i);
    while (i) k->s[k->l++] = b[--i];
    k->s[k->l] = 0;
}
static inline void ks_puti64(kstr *k, int64_t v) {
    if (v < 0) { ks_putc(k, '-'); ks_putu64(k, (uint64_t)0 - (uint64_t)v); }
    else ks_putu64(k, (uint64_t)v);
}
static inline void ks_puti(kstr *k, int64_t v) { ks_puti64(k, v); }
static inline int ks_printf(kstr *k, const char *fmt, ...) {
    va_list ap; int n;
    va_start(ap, fmt);
    n = vsnprintf(k->s ? k->s + k->l : NULL, k->s ? k->m - k->l : 0, fmt, ap);
    va_end(ap);
    if (n < 0) return n;
    if (!k->s || (size_t)n + 1 > k->m - k->l) {
        ks_grow(k, n + 1);
        va_start(ap, fmt);
        n = vsnprintf(k->s + k->l, k->m - k->l, fmt, ap);
        va_end(ap);
    }
    k->l += n;
    return n;
}
static inline char *ks_release(kstr *k) { char *s = k->s; if (!s) s = strdup(""); k->s = NULL; k->l = k->m = 0; return s; }
#endif
EOF"}

