#ifndef BGZF_H
#define BGZF_H
#include <stdint.h>
#include <stdio.h>
#include <zlib.h>
#include "ks.h"

#define BGZF_BLOCK_SIZE 0xff00
#define BGZF_MAX_BLOCK_SIZE 0x10000

enum { BG_RAW = 0, BG_BGZF = 1, BG_GZIP = 2 };

typedef struct bgzf_t {
    int fd;
    int is_write;
    int mode;           /* BG_RAW, BG_BGZF, BG_GZIP */
    int own_fd;
    /* raw input buffer */
    uint8_t *rbuf; int rlen, rpos; int64_t rbase; int reof;
    /* uncompressed buffer */
    uint8_t *ubuf; int ulen, upos;
    int64_t block_addr;
    z_stream zs; int zs_init; int gz_end;
    int eof;
    int err;
    /* write */
    int level;
    uint8_t *wbuf; int wlen;
    int64_t out_addr;
    uint8_t *cbuf;
    int64_t uoffset; /* total uncompressed bytes read so far (for raw/gzip) */
    char *path;
} bgzf_t;

bgzf_t *bg_open_read(const char *path);
bgzf_t *bg_dopen_read(int fd);
/* mode: BG_RAW or BG_BGZF; level -1..9 */
bgzf_t *bg_open_write(const char *path, int mode, int level);
int bg_close(bgzf_t *fp);
/* read up to len bytes; returns bytes read, 0 on EOF, <0 error */
int64_t bg_read(bgzf_t *fp, void *buf, int64_t len);
/* peek: ensure at least n uncompressed bytes available, returns number available (<=n) */
int bg_peek(bgzf_t *fp, uint8_t *buf, int n);
/* read line (without newline) into ks; returns length >=0 or -1 at EOF */
int bg_getline(bgzf_t *fp, kstr *ks);
