cat > bgzf.c <<'EOF'
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include "bgzf.h"

#define RBUF_SIZE 0x20000

static const uint8_t g_magic[16] = "\037\213\010\4\0\0\0\0\0\377\6\0\102\103\2\0";

static bgzf_t *bg_new(void) {
    bgzf_t *fp = calloc(1, sizeof(bgzf_t));
    fp->fd = -1;
    return fp;
}

/* raw layer */
static int raw_fill(bgzf_t *fp, int need) {
    /* ensure at least need bytes in rbuf from rpos */
    if (fp->rlen - fp->rpos >= need) return 1;
    if (!fp->rbuf) fp->rbuf = malloc(RBUF_SIZE);
    if (fp->rpos > 0) {
        memmove(fp->rbuf, fp->rbuf + fp->rpos, fp->rlen - fp->rpos);
        fp->rbase += fp->rpos;
        fp->rlen -= fp->rpos; fp->rpos = 0;
    }
    while (fp->rlen < need && !fp->reof) {
        ssize_t n = read(fp->fd, fp->rbuf + fp->rlen, RBUF_SIZE - fp->rlen);
        if (n < 0) { if (errno == EINTR) continue; fp->err = 1; return -1; }
        if (n == 0) { fp->reof = 1; break; }
        fp->rlen += n;
    }
    return fp->rlen - fp->rpos >= need;
}

int64_t bg_raw_tell(bgzf_t *fp) { return fp->rbase + fp->rpos; }

static void detect_mode(bgzf_t *fp) {
    raw_fill(fp, 18);
    int avail = fp->rlen - fp->rpos;
    uint8_t *p = fp->rbuf + fp->rpos;
    if (avail >= 2 && p[0] == 0x1f && p[1] == 0x8b) {
        if (avail >= 18 && p[2] == 8 && (p[3] & 4) && p[10] == 6 && p[11] == 0 && p[12] == 'B' && p[13] == 'C')
            fp->mode = BG_BGZF;
        else
            fp->mode = BG_GZIP;
    } else fp->mode = BG_RAW;
}

bgzf_t *bg_dopen_read(int fd) {
    bgzf_t *fp = bg_new();
    fp->fd = fd;
    fp->ubuf = malloc(BGZF_MAX_BLOCK_SIZE);
    detect_mode(fp);
    return fp;
}

bgzf_t *bg_open_read(const char *path) {
    int fd;
    if (strcmp(path, "-") == 0) fd = 0;
    else {
        fd = open(path, O_RDONLY);
        if (fd < 0) return NULL;
    }
    bgzf_t *fp = bg_dopen_read(fd);
    fp->own_fd = (fd != 0);
    fp->path = strdup(path);
    return fp;
}

/* read one bgzf block into ubuf; returns 0 ok, -1 err; sets eof on clean EOF */
static int read_bgzf_block(bgzf_t *fp) {
    int r = raw_fill(fp, 18);
    if (r < 0) return -1;
    if (fp->rlen - fp->rpos == 0) { fp->eof = 1; fp->ulen = fp->upos = 0; fp->block_addr = bg_raw_tell(fp); return 0; }
    if (!r) { fp->err = 1; return -1; }
    uint8_t *h = fp->rbuf + fp->rpos;
    if (h[0] != 0x1f || h[1] != 0x8b) { fp->err = 1; return -1; }
    int bsize;
    if ((h[3] & 4) && h[12] == 'B' && h[13] == 'C') bsize = (h[16] | (h[17] << 8)) + 1;
    else { fp->err = 1; return -1; }
    if (raw_fill(fp, bsize) <= 0) { fp->err = 1; return -1; }
    h = fp->rbuf + fp->rpos;
    fp->block_addr = bg_raw_tell(fp);
    int xlen = h[10] | (h[11] << 8);
    int hlen = 12 + xlen;
    uint32_t isize = h[bsize-4] | (h[bsize-3]<<8) | (h[bsize-2]<<16) | ((uint32_t)h[bsize-1]<<24);
    z_stream zs; memset(&zs, 0, sizeof zs);
    inflateInit2(&zs, -15);
    zs.next_in = h + hlen; zs.avail_in = bsize - hlen - 8;
    zs.next_out = fp->ubuf; zs.avail_out = BGZF_MAX_BLOCK_SIZE;
    int ret = inflate(&zs, Z_FINISH);
    if (ret != Z_STREAM_END) { inflateEnd(&zs); fp->err = 1; return -1; }
    int out = BGZF_MAX_BLOCK_SIZE - zs.avail_out;
    inflateEnd(&zs);
    if ((uint32_t)out != isize) { fp->err = 1; return -1; }
    fp->rpos += bsize;
    fp->ulen = out; fp->upos = 0;
    return 0;
}

static int read_gzip_chunk(bgzf_t *fp) {
    if (!fp->zs_init) {
        memset(&fp->zs, 0, sizeof fp->zs);
        inflateInit2(&fp->zs, 15 + 32);
        fp->zs_init = 1;
    }
    fp->ulen = fp->upos = 0;
    while (fp->ulen == 0) {
        if (fp->rlen - fp->rpos == 0) {
            int r = raw_fill(fp, 1);
            if (r < 0) return -1;
            if (r == 0) { fp->eof = 1; return 0; }
        }
        if (fp->gz_end) {
            /* new member? */
            uint8_t *p = fp->rbuf + fp->rpos;
            if (p[0] != 0x1f) { fp->eof = 1; return 0; }
            inflateReset(&fp->zs);
            fp->gz_end = 0;
        }
        fp->zs.next_in = fp->rbuf + fp->rpos;
        fp->zs.avail_in = fp->rlen - fp->rpos;
        fp->zs.next_out = fp->ubuf;
        fp->zs.avail_out = BGZF_MAX_BLOCK_SIZE;
        int ret = inflate(&fp->zs, Z_NO_FLUSH);
        fp->rpos = fp->rlen - fp->zs.avail_in;
        fp->ulen = BGZF_MAX_BLOCK_SIZE - fp->zs.avail_out;
        if (ret == Z_STREAM_END) fp->gz_end = 1;
        else if (ret != Z_OK && ret != Z_BUF_ERROR) { fp->err = 1; return -1; }
        else if (ret == Z_BUF_ERROR && fp->ulen == 0) {
            int r = raw_fill(fp, fp->rlen - fp->rpos + 1);
            if (r < 0) return -1;
            if (r == 0) { fp->err = 1; return -1; } /* truncated */
        }
    }
    return 0;
}

static int read_raw_chunk(bgzf_t *fp) {
    fp->ulen = fp->upos = 0;
    if (fp->rlen - fp->rpos == 0) {
        int r = raw_fill(fp, 1);
        if (r < 0) return -1;
        if (r == 0) { fp->eof = 1; return 0; }
    }
    int n = fp->rlen - fp->rpos;
    if (n > BGZF_MAX_BLOCK_SIZE) n = BGZF_MAX_BLOCK_SIZE;
    memcpy(fp->ubuf, fp->rbuf + fp->rpos, n);
    fp->rpos += n;
    fp->ulen = n;
    return 0;
}

static int fill_ubuf(bgzf_t *fp) {
    if (fp->eof) return 0;
    if (fp->mode == BG_BGZF) {
        /* skip empty blocks */
        do {
            if (read_bgzf_block(fp) < 0) return -1;
        } while (fp->ulen == 0 && !fp->eof);
        return 0;
    } else if (fp->mode == BG_GZIP) return read_gzip_chunk(fp);
    else return read_raw_chunk(fp);
}

int64_t bg_read(bgzf_t *fp, void *buf, int64_t len) {
    uint8_t *out = buf; int64_t got = 0;
    while (got < len) {
        if (fp->upos >= fp->ulen) {
            if (fill_ubuf(fp) < 0) return -1;
            if (fp->ulen == 0) break;
        }
        int64_t n = fp->ulen - fp->upos;
        if (n > len - got) n = len - got;
        memcpy(out + got, fp->ubuf + fp->upos, n);
        fp->upos += n; got += n;
        if (fp->upos == fp->ulen && fp->mode == BG_BGZF) {
            fp->block_addr = bg_raw_tell(fp);
            fp->upos = fp->ulen = 0;
        }
    }
    fp->uoffset += got;
    return got;
}

int bg_getc(bgzf_t *fp) {
    uint8_t c;
    if (fp->upos < fp->ulen && !(fp->mode == BG_BGZF && fp->upos + 1 == fp->ulen)) {
        fp->uoffset++;
        return fp->ubuf[fp->upos++];
    }
    int64_t n = bg_read(fp, &c, 1);
    if (n <= 0) return -1;
    return c;
}

int bg_peek(bgzf_t *fp, uint8_t *buf, int n) {
    if (fp->upos >= fp->ulen) {
        if (fill_ubuf(fp) < 0) return -1;
    }
    /* for simplicity only peek within current buffer, but ensure we try to have enough */
    if (fp->ulen - fp->upos < n && fp->mode != BG_BGZF && !fp->eof) {
        /* move remaining to front and fill more */
        int rem = fp->ulen - fp->upos;
        uint8_t tmp[BGZF_MAX_BLOCK_SIZE];
        memcpy(tmp, fp->ubuf + fp->upos, rem);
        int save_ulen = rem;
        if (fill_ubuf(fp) < 0) return -1;
        int add = fp->ulen;
        if (save_ulen + add > BGZF_MAX_BLOCK_SIZE) add = BGZF_MAX_BLOCK_SIZE - save_ulen; /* unlikely */
        memmove(fp->ubuf + save_ulen, fp->ubuf, add);
        memcpy(fp->ubuf, tmp, save_ulen);
        fp->ulen = save_ulen + add; fp->upos = 0;
        if (fp->eof && fp->ulen > 0) fp->eof = 0;
    }
    int a = fp->ulen - fp->upos;
    if (a > n) a = n;
    if (a > 0) memcpy(buf, fp->ubuf + fp->upos, a);
    return a;
}

int bg_getline(bgzf_t *fp, kstr *ks) {
    ks->l = 0;
    int got_any = 0;
    for (;;) {
        if (fp->upos >= fp->ulen) {
            if (fill_ubuf(fp) < 0) return -1;
            if (fp->ulen == 0) break;
        }
        got_any = 1;
        uint8_t *p = fp->ubuf + fp->upos;
        int n = fp->ulen - fp->upos;
        uint8_t *nl = memchr(p, '\n', n);
        int take = nl ? (int)(nl - p) : n;
        ks_putsn(ks, (char*)p, take);
        fp->upos += take + (nl ? 1 : 0);
        fp->uoffset += take + (nl ? 1 : 0);
        if (fp->upos >= fp->ulen && fp->mode == BG_BGZF) {
            fp->block_addr = bg_raw_tell(fp);
            fp->upos = fp->ulen = 0;
        }
        if (nl) break;
    }
    if (!got_any) { ks_grow(ks, 0); ks->s[0] = 0; return -1; }
    if (ks->l > 0 && ks->s[ks->l-1] == '\r') ks->s[--ks->l] = 0;
    ks_grow(ks, 0);
    return (int)ks->l;
}

int64_t bg_tell(bgzf_t *fp) {
    if (fp->is_write) return (fp->out_addr << 16) | (fp->wlen & 0xffff);
    if (fp->mode != BG_BGZF) return fp->uoffset;
    return (fp->block_addr << 16) | (fp->upos & 0xffff);
}

int bg_seek(bgzf_t *fp, int64_t voff) {
    if (fp->mode != BG_BGZF) return -1;
    int64_t caddr = voff >> 16; int uoff = voff & 0xffff;
    if (lseek(fp->fd, caddr, SEEK_SET) < 0) return -1;
    fp->rbase = caddr; fp->rpos = fp->rlen = 0; fp->reof = 0; fp->eof = 0;
    fp->ulen = fp->upos = 0;
    fp->block_addr = caddr;
    if (read_bgzf_block(fp) < 0) return -1;
    if (uoff > fp->ulen) return -1;
    fp->upos = uoff;
    if (fp->upos == fp->ulen && fp->ulen > 0) { fp->block_addr = bg_raw_tell(fp); fp->upos = fp->ulen = 0; }
    return 0;
}

int bg_check_eof(bgzf_t *fp) {
    static const uint8_t eofm[28] = "\037\213\010\4\0\0\0\0\0\377\6\0\102\103\2\0\033\0\3\0\0\0\0\0\0\0\0\0";
    off_t cur = lseek(fp->fd, 0, SEEK_CUR);
    if (cur < 0) return 2;
    off_t end = lseek(fp->fd, -28, SEEK_END);
    if (end < 0) { lseek(fp->fd, cur, SEEK_SET); return 0; }
    uint8_t b[28];
    ssize_t n = read(fp->fd, b, 28);
    lseek(fp->fd, cur, SEEK_SET);
    if (n != 28) return 0;
    return memcmp(b, eofm, 28) == 0 ? 1 : 0;
}

/* ---------- writing ---------- */
bgzf_t *bg_open_write(const char *path, int mode, int level) {
    int fd;
    if (strcmp(path, "-") == 0) fd = 1;
    else {
        fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0666);
        if (fd < 0) return NULL;
    }
    bgzf_t *fp = bg_new();
    fp->fd = fd; fp->own_fd = (fd != 1);
    fp->is_write = 1; fp->mode = mode; fp->level = level;
    fp->wbuf = malloc(BGZF_MAX_BLOCK_SIZE);
    if (mode == BG_BGZF) fp->cbuf = malloc(BGZF_MAX_BLOCK_SIZE);
    fp->path = strdup(path);
    return fp;
}

static int write_all(int fd, const uint8_t *p, size_t n) {
    while (n > 0) {
        ssize_t w = write(fd, p, n);
        if (w < 0) { if (errno == EINTR) continue; return -1; }
        p += w; n -= w;
    }
    return 0;
}

int bg_compress_block(uint8_t *dst, int *dlen, const uint8_t *src, int slen, int level) {
    memcpy(dst, g_magic, 16);
    int clen;
    if (level == 0) {
        dst[18] = 1;
        dst[19] = slen & 0xff; dst[20] = (slen >> 8) & 0xff;
        dst[21] = (~slen) & 0xff; dst[22] = ((~slen) >> 8) & 0xff;
        memcpy(dst + 23, src, slen);
        clen = slen + 5;
    } else {
        z_stream zs; memset(&zs, 0, sizeof zs);
        if (deflateInit2(&zs, level < 0 ? Z_DEFAULT_COMPRESSION : level, Z_DEFLATED, -15, 8, Z_DEFAULT_STRATEGY) != Z_OK) return -1;
        zs.next_in = (Bytef*)src; zs.avail_in = slen;
        zs.next_out = dst + 18; zs.avail_out = BGZF_MAX_BLOCK_SIZE - 18 - 8;
        int ret = deflate(&zs, Z_FINISH);
        if (ret != Z_STREAM_END) { deflateEnd(&zs); return -1; }
        clen = zs.total_out;
        deflateEnd(&zs);
    }
    int total = clen + 18 + 8;
    dst[16] = (total - 1) & 0xff; dst[17] = ((total - 1) >> 8) & 0xff;
    uint32_t crc = crc32(crc32(0L, NULL, 0L), src, slen);
    uint8_t *f = dst + 18 + clen;
    f[0] = crc; f[1] = crc >> 8; f[2] = crc >> 16; f[3] = crc >> 24;
    f[4] = slen; f[5] = slen >> 8; f[6] = slen >> 16; f[7] = slen >> 24;
    *dlen = total;
    return 0;
}

int bg_flush(bgzf_t *fp) {
    if (!fp->is_write) return 0;
    if (fp->wlen == 0) return 0;
    if (fp->mode == BG_BGZF) {
        int dlen;
        if (bg_compress_block(fp->cbuf, &dlen, fp->wbuf, fp->wlen, fp->level) < 0) return -1;
        if (write_all(fp->fd, fp->cbuf, dlen) < 0) { fp->err = 1; return -1; }
        fp->out_addr += dlen;
    } else {
        if (write_all(fp->fd, fp->wbuf, fp->wlen) < 0) { fp->err = 1; return -1; }
        fp->out_addr += fp->wlen;
    }
    fp->wlen = 0;
    return 0;
}

int bg_flush_try(bgzf_t *fp, int64_t size) {
    if (fp->mode == BG_BGZF && fp->wlen + size > BGZF_BLOCK_SIZE) return bg_flush(fp);
    return 0;
}

int bg_write(bgzf_t *fp, const void *data, int64_t len) {
    const uint8_t *p = data;
    int lim = fp->mode == BG_BGZF ? BGZF_BLOCK_SIZE : BGZF_MAX_BLOCK_SIZE;
    while (len > 0) {
        int64_t n = lim - fp->wlen;
        if (n > len) n = len;
        memcpy(fp->wbuf + fp->wlen, p, n);
        fp->wlen += n; p += n; len -= n;
        if (fp->wlen >= lim) if (bg_flush(fp) < 0) return -1;
    }
    return 0;
}

int bg_close(bgzf_t *fp) {
    int ret = 0;
    if (!fp) return 0;
    if (fp->is_write) {
        if (bg_flush(fp) < 0) ret = -1;
        if (fp->mode == BG_BGZF) {
            static const uint8_t eofm[28] = "\037\213\010\4\0\0\0\0\0\377\6\0\102\103\2\0\033\0\3\0\0\0\0\0\0\0\0\0";
            if (write_all(fp->fd, eofm, 28) < 0) ret = -1;
        }
        free(fp->wbuf); free(fp->cbuf);
    } else {
        if (fp->zs_init) inflateEnd(&fp->zs);
        free(fp->rbuf); free(fp->ubuf);
    }
    if (fp->own_fd) { if (close(fp->fd) < 0) ret = -1; }
    if (fp->err) ret = -1;
    free(fp->path);
    free(fp);
    return ret;
}

int bg_is_bgzf_file(const char *path) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) return -1;
    uint8_t h[18];
    ssize_t n = read(fd, h, 18);
    close(fd);
    if (n < 18) return 0;
    return (h[0] == 0x1f && h[1] == 0x8b && h[2] == 8 && (h[3] & 4) && h[12] == 'B' && h[13] == 'C') ? 1 : 0;
}
