cat > util.c <<'EOF'
#include <stdio.h>
#include <stdarg.h>
#include <errno.h>
#include <ctype.h>
#include "util.h"

char *g_cmdline = NULL;
const char *g_version = "5855b7e";

void *xmalloc(size_t n) { void *p = malloc(n ? n : 1); if (!p) { fprintf(stderr, "Out of memory\n"); exit(1); } return p; }
void *xcalloc(size_t n, size_t m) { void *p = calloc(n ? n : 1, m ? m : 1); if (!p) { fprintf(stderr, "Out of memory\n"); exit(1); } return p; }
void *xrealloc(void *q, size_t n) { void *p = realloc(q, n ? n : 1); if (!p) { fprintf(stderr, "Out of memory\n"); exit(1); } return p; }
char *xstrdup(const char *s) { char *p = strdup(s ? s : ""); if (!p) exit(1); return p; }

static uint32_t hash_str(const char *s) {
    uint32_t h = 2166136261u;
    while (*s) { h ^= (uint8_t)*s++; h *= 16777619u; }
    return h;
}

strmap_t *sm_init(void) {
    strmap_t *h = xcalloc(1, sizeof(strmap_t));
    h->m = 16;
    h->keys = xcalloc(h->m, sizeof(char*));
    h->vals = xcalloc(h->m, sizeof(int64_t));
    return h;
}
void sm_destroy(strmap_t *h) {
    if (!h) return;
    for (int i = 0; i < h->m; i++) free(h->keys[i]);
    free(h->keys); free(h->vals); free(h);
}
static int sm_find(const strmap_t *h, const char *key) {
    uint32_t i = hash_str(key) & (h->m - 1);
    while (h->keys[i]) {
        if (strcmp(h->keys[i], key) == 0) return (int)i;
        i = (i + 1) & (h->m - 1);
    }
    return -(int)i - 1;
}
int sm_get(const strmap_t *h, const char *key, int64_t *val) {
    int i = sm_find(h, key);
    if (i >= 0) { if (val) *val = h->vals[i]; return 1; }
    return 0;
}
int sm_has(const strmap_t *h, const char *key) { return sm_find(h, key) >= 0; }
void sm_put(strmap_t *h, const char *key, int64_t val) {
    if ((h->n + 1) * 2 > h->m) {
        int om = h->m; char **ok = h->keys; int64_t *ov = h->vals;
        h->m *= 2;
        h->keys = xcalloc(h->m, sizeof(char*));
        h->vals = xcalloc(h->m, sizeof(int64_t));
        h->n = 0;
        for (int i = 0; i < om; i++) if (ok[i]) {
            int j = sm_find(h, ok[i]); j = -j - 1;
            h->keys[j] = ok[i]; h->vals[j] = ov[i]; h->n++;
        }
        free(ok); free(ov);
    }
    int i = sm_find(h, key);
    if (i >= 0) { h->vals[i] = val; return; }
    i = -i - 1;
    h->keys[i] = xstrdup(key); h->vals[i] = val; h->n++;
}

void print_error(const char *subcmd, const char *fmt, ...) {
    va_list ap;
    fflush(stdout);
    if (subcmd) fprintf(stderr, "samtools %s: ", subcmd);
    else fprintf(stderr, "samtools: ");
    va_start(ap, fmt); vfprintf(stderr, fmt, ap); va_end(ap);
    fputc('\n', stderr);
    fflush(stderr);
}
void print_error_errno(const char *subcmd, const char *fmt, ...) {
    int err = errno;
    va_list ap;
    fflush(stdout);
    if (subcmd) fprintf(stderr, "samtools %s: ", subcmd);
    else fprintf(stderr, "samtools: ");
    va_start(ap, fmt); vfprintf(stderr, fmt, ap); va_end(ap);
    if (err) fprintf(stderr, ": %s\n", strerror(err));
    else fputc('\n', stderr);
    fflush(stderr);
}
EOF"}

