/* SAM header handling */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdarg.h>
#include "sam.h"

hdr_t *hdr_init(void) {
    hdr_t *h = xcalloc(1, sizeof(hdr_t));
    h->tmap = sm_init();
    h->pg_id_cnt = 1;
    return h;
}

void hline_free(hline_t *l) {
    for (int i = 0; i < l->ntag; i++) { free(l->key[i]); free(l->val[i]); }
    free(l->key); free(l->val); free(l->co);
    memset(l, 0, sizeof *l);
}

void hdr_destroy(hdr_t *h) {
    if (!h) return;
    for (int i = 0; i < h->nl; i++) hline_free(&h->l[i]);
    free(h->l);
    for (int i = 0; i < h->n_targets; i++) free(h->tname[i]);
    free(h->tname); free(h->tlen);
    sm_destroy(h->tmap);
    free(h->raw_text);
    free(h);
}

static void hline_add_tag(hline_t *l, const char *k, const char *v, int vlen) {
    if (l->ntag == l->mtag) {
        l->mtag = l->mtag ? l->mtag * 2 : 4;
        l->key = xrealloc(l->key, l->mtag * sizeof(char*));
        l->val = xrealloc(l->val, l->mtag * sizeof(char*));
    }
    l->key[l->ntag] = xmalloc(3); l->key[l->ntag][0] = k[0]; l->key[l->ntag][1] = k[1]; l->key[l->ntag][2] = 0;
    if (vlen < 0) vlen = strlen(v);
    l->val[l->ntag] = xmalloc(vlen + 1); memcpy(l->val[l->ntag], v, vlen); l->val[l->ntag][vlen] = 0;
    l->ntag++;
}

const char *hline_get(const hline_t *l, const char *key) {
    for (int i = 0; i < l->ntag; i++)
        if (l->key[i][0] == key[0] && l->key[i][1] == key[1]) return l->val[i];
    return NULL;
}

void hline_set(hline_t *l, const char *key, const char *val) {
    for (int i = 0; i < l->ntag; i++)
        if (l->key[i][0] == key[0] && l->key[i][1] == key[1]) {
            free(l->val[i]); l->val[i] = xstrdup(val); return;
        }
    hline_add_tag(l, key, val, -1);
}

static void hline_copy(hline_t *d, const hline_t *s) {
    memset(d, 0, sizeof *d);
    memcpy(d->type, s->type, 3);
    for (int i = 0; i < s->ntag; i++) hline_add_tag(d, s->key[i], s->val[i], -1);
    if (s->co) d->co = xstrdup(s->co);
}

hline_t *hdr_add_line_empty(hdr_t *h, const char *type) {
    if (h->nl == h->ml) {
        h->ml = h->ml ? h->ml * 2 : 16;
        h->l = xrealloc(h->l, h->ml * sizeof(hline_t));
    }
    hline_t *l = &h->l[h->nl++];
    memset(l, 0, sizeof *l);
    l->type[0] = type[0]; l->type[1] = type[1]; l->type[2] = 0;
    return l;
}

int hdr_add_line(hdr_t *h, const char *type, ...) {
    va_list ap;
    hline_t *l = hdr_add_line_empty(h, type);
    va_start(ap, type);
    for (;;) {
        const char *k = va_arg(ap, const char*);
        if (!k) break;
        const char *v = va_arg(ap, const char*);
        if (!v) continue;
        hline_add_tag(l, k, v, -1);
    }
    va_end(ap);
    return 0;
}

void hdr_remove_line(hdr_t *h, int idx) {
    if (idx < 0 || idx >= h->nl) return;
    hline_free(&h->l[idx]);
    memmove(&h->l[idx], &h->l[idx+1], (h->nl - idx - 1) * sizeof(hline_t));
    h->nl--;
}

int hdr_count_type(const hdr_t *h, const char *type) {
    int n = 0;
    for (int i = 0; i < h->nl; i++) if (h->l[i].type[0] == type[0] && h->l[i].type[1] == type[1]) n++;
    return n;
}

int hdr_find_line(const hdr_t *h, const char *type, const char *key, const char *val) {
    for (int i = 0; i < h->nl; i++) {
        if (h->l[i].type[0] != type[0] || h->l[i].type[1] != type[1]) continue;
        const char *v = hline_get(&h->l[i], key);
        if (v && strcmp(v, val) == 0) return i;
    }
    return -1;
}

hdr_t *hdr_dup(const hdr_t *s) {
    hdr_t *h = hdr_init();
    for (int i = 0; i < s->nl; i++) {
        hline_t *l = hdr_add_line_empty(h, s->l[i].type);
        hline_copy(l, &s->l[i]);
    }
    for (int i = 0; i < s->n_targets; i++) hdr_add_target(h, s->tname[i], s->tlen[i]);
    h->pg_id_cnt = s->pg_id_cnt;
    return h;
}

void hdr_add_target(hdr_t *h, const char *name, int64_t len) {
    h->tname = xrealloc(h->tname, (h->n_targets + 1) * sizeof(char*));
    h->tlen = xrealloc(h->tlen, (h->n_targets + 1) * sizeof(int64_t));
    h->tname[h->n_targets] = xstrdup(name);
    h->tlen[h->n_targets] = len;
    if (!sm_has(h->tmap, name)) sm_put(h->tmap, name, h->n_targets);
    h->n_targets++;
}

static int valid_type(const char *s, size_t len) {
    if (len < 3 || s[0] != '@') return 0;
    switch (s[1]) {
    case 'H': return s[2] == 'D' && len > 3 && s[3] == '\t';
    case 'S': return s[2] == 'Q' && len > 3 && s[3] == '\t';
    case 'R': return s[2] == 'G' && len > 3 && s[3] == '\t';
    case 'P': return s[2] == 'G' && len > 3 && s[3] == '\t';
    case 'C': return s[2] == 'O';
    }
    return 0;
}

int hdr_parse_line(hdr_t *h, const char *line, size_t len, int lineno) {
    if (!valid_type(line, len)) {
        fprintf(stderr, "[E::sam_hdr_build_from_sam_file] Invalid header line: must start with @HD/@SQ/@RG/@PG/@CO\n");
        return -1;
    }
    hline_t *l = hdr_add_line_empty(h, line + 1);
    if (line[1] == 'C' && line[2] == 'O') {
        if (len > 3 && line[3] != '\t') {
            fprintf(stderr, "[E::sam_hrecs_error] Missing tab at line %d: \"%.*s\"\n", lineno, (int)(len - 3), line + 3);
            h->nl--; hline_free(l);
            return -1;
        }
        l->co = xmalloc(len > 4 ? len - 3 : 1);
        if (len > 4) { memcpy(l->co, line + 4, len - 4); l->co[len - 4] = 0; }
        else l->co[0] = 0;
        return 0;
    }
    size_t p = 3;
    while (p < len) {
        /* expect \tKK:value */
        if (line[p] != '\t' || p + 3 >= len + 0 || line[p+1] == '\t' || line[p+2] == '\t' || line[p+3] != ':' || p + 3 >= len) {
            fprintf(stderr, "[E::sam_hrecs_error] Malformed key:value pair at line %d: \"%.*s\"\n", lineno, (int)(len - 3), line + 3);
            h->nl--; hline_free(l);
            return -1;
        }
        size_t vs = p + 4, ve = vs;
        while (ve < len && line[ve] != '\t') ve++;
        hline_add_tag(l, line + p + 1, line + vs, (int)(ve - vs));
        p = ve;
    }
    return 0;
}

static int64_t parse_len(const char *s) {
    return strtoll(s, NULL, 10);
}

int hdr_build_targets(hdr_t *h) {
    for (int i = 0; i < h->n_targets; i++) free(h->tname[i]);
    free(h->tname); free(h->tlen); h->tname = NULL; h->tlen = NULL; h->n_targets = 0;
    sm_destroy(h->tmap); h->tmap = sm_init();
    strmap_t *rg = sm_init();
    for (int i = 0; i < h->nl; i++) {
        hline_t *l = &h->l[i];
        if (l->type[0] == 'S' && l->type[1] == 'Q') {
            const char *sn = hline_get(l, "SN");
            if (!sn) { fprintf(stderr, "[E::sam_hrecs_update_hashes] Header includes @SQ line with no SN: tag\n"); sm_destroy(rg); return -1; }
            const char *ln = NULL; int nln = 0;
            for (int j = 0; j < l->ntag; j++) if (l->key[j][0] == 'L' && l->key[j][1] == 'N') {
                if (ln && strcmp(ln, l->val[j]) != 0) {
                    fprintf(stderr, "[E::sam_hrecs_update_hashes] Header includes @SQ line \"%s\" with multiple LN: tag with different values.\n", sn);
                    sm_destroy(rg); return -1;
                }
                ln = l->val[j]; nln++;
            }
            if (!ln) { fprintf(stderr, "[E::sam_hrecs_update_hashes] Header includes @SQ line \"%s\" with no LN: tag\n", sn); sm_destroy(rg); return -1; }
            if (sm_has(h->tmap, sn)) {
                fprintf(stderr, "[E::sam_hrecs_update_hashes] Duplicate entry \"%s\" in sam header\n", sn);
                sm_destroy(rg); return -1;
            }
            hdr_add_target(h, sn, parse_len(ln));
        } else if (l->type[0] == 'R' && l->type[1] == 'G') {
            const char *id = hline_get(l, "ID");
            if (!id) { fprintf(stderr, "[E::sam_hrecs_update_hashes] Header includes @RG line with no ID: tag\n"); sm_destroy(rg); return -1; }
            if (sm_has(rg, id)) fprintf(stderr, "[W::sam_hrecs_update_hashes] Duplicate entry \"%s\" in sam header\n", id);
            else sm_put(rg, id, i);
        } else if (l->type[0] == 'P' && l->type[1] == 'G') {
            const char *id = hline_get(l, "ID");
            if (!id) { sm_destroy(rg); return -1; }
        }
    }
    sm_destroy(rg);
    return 0;
}

int hdr_parse(hdr_t *h, const char *text, size_t len) {
    size_t p = 0; int lineno = 0;
    while (p < len) {
        size_t e = p;
        while (e < len && text[e] != '\n') e++;
        size_t le = e;
        if (le > p && text[le-1] == '\r') le--;
        lineno++;
        if (le > p) {
            if (hdr_parse_line(h, text + p, le - p, lineno) < 0) return -1;
        }
        p = e + 1;
    }
    return 0;
}

static void hline_text(const hline_t *l, kstr *out) {
    ks_putc(out, '@'); ks_putsn(out, l->type, 2);
    if (l->type[0] == 'C' && l->type[1] == 'O') {
        ks_putc(out, '\t');
        if (l->co) ks_puts(out, l->co);
    } else {
        for (int i = 0; i < l->ntag; i++) {
            ks_putc(out, '\t'); ks_putsn(out, l->key[i], 2); ks_putc(out, ':'); ks_puts(out, l->val[i]);
        }
    }
    ks_putc(out, '\n');
}

void hdr_text(const hdr_t *h, kstr *out) {
    out->l = 0; ks_grow(out, 0); out->s[0] = 0;
    int hd = -1;
    for (int i = 0; i < h->nl; i++) if (h->l[i].type[0] == 'H' && h->l[i].type[1] == 'D') { hd = i; break; }
    if (hd >= 0) hline_text(&h->l[hd], out);
    for (int i = 0; i < h->nl; i++) if (i != hd) hline_text(&h->l[i], out);
}

int hdr_name2tid(const hdr_t *h, const char *name) {
    int64_t v;
    if (sm_get(h->tmap, name, &v)) return (int)v;
    return -1;
}

const char *hdr_tname(const hdr_t *h, int tid) {
    if (tid < 0 || tid >= h->n_targets) return "*";
    return h->tname[tid];
}

/* @PG handling */
int hdr_add_pg(hdr_t *h, const char *name, const char *vn, const char *cl) {
    int npg = 0;
    int *idx = NULL;
    for (int i = 0; i < h->nl; i++) if (h->l[i].type[0] == 'P' && h->l[i].type[1] == 'G') {
        idx = xrealloc(idx, (npg + 1) * sizeof(int)); idx[npg++] = i;
    }
    strmap_t *ids = sm_init();
    for (int i = 0; i < npg; i++) {
        const char *id = hline_get(&h->l[idx[i]], "ID");
        if (id && !sm_has(ids, id)) sm_put(ids, id, i);
    }
    int *is_end = xcalloc(npg + 1, sizeof(int));
    int *chain = xcalloc(npg + 1, sizeof(int));
    for (int i = 0; i < npg; i++) is_end[i] = 1;
    for (int i = 0; i < npg; i++) {
        const char *pp = hline_get(&h->l[idx[i]], "PP");
        if (!pp) continue;
        int64_t k;
        if (!sm_get(ids, pp, &k)) continue;
        is_end[k] = 0;
        chain[i] = chain[k] + 1;
    }
    int nends = 0; int *ends = xcalloc(npg + 1, sizeof(int));
    for (int i = 0; i < npg; i++) if (is_end[i] && chain[i] > 0) ends[nends++] = i;
    if (nends == 0 && npg > 0) ends[nends++] = npg - 1;
    /* collect PP names first */
    char **ppn = xcalloc(nends + 1, sizeof(char*));
    for (int e = 0; e < nends; e++) {
        const char *id = hline_get(&h->l[idx[ends[e]]], "ID");
        ppn[e] = xstrdup(id ? id : "");
    }
    int loops = nends ? nends : 1;
    for (int e = 0; e < loops; e++) {
        char buf[1100];
        const char *newid = name;
        if (sm_has(ids, name)) {
            do {
                snprintf(buf, sizeof buf, "%.1000s.%d", name, h->pg_id_cnt++);
            } while (sm_has(ids, buf));
            newid = buf;
        }
        hline_t *l = hdr_add_line_empty(h, "PG");
        hline_add_tag(l, "ID", newid, -1);
        hline_add_tag(l, "PN", name, -1);
        if (nends) hline_add_tag(l, "PP", ppn[e], -1);
        if (vn) hline_add_tag(l, "VN", vn, -1);
        if (cl) hline_add_tag(l, "CL", cl, -1);
        sm_put(ids, newid, -1);
    }
    for (int e = 0; e < nends; e++) free(ppn[e]);
    free(ppn); free(ends); free(chain); free(is_end); free(idx);
    sm_destroy(ids);
    return 0;
}

void hdr_sync_sq(hdr_t *h) {
    /* if there are targets but no @SQ lines, add them */
    if (hdr_count_type(h, "SQ") > 0 || h->n_targets == 0) return;
    for (int i = 0; i < h->n_targets; i++) {
        char lb[32]; snprintf(lb, sizeof lb, "%lld", (long long)h->tlen[i]);
        hdr_add_line(h, "SQ", "SN", h->tname[i], "LN", lb, NULL);
    }
}

int hdr_add_fai(hdr_t *h, const char *fai_fn) {
    FILE *f = fopen(fai_fn, "r");
    if (!f) return -1;
    char *line = NULL; size_t cap = 0; ssize_t n;
    while ((n = getline(&line, &cap, f)) >= 0) {
        while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r')) line[--n] = 0;
        if (n == 0) continue;
        char *p = line; char *name = p;
        while (*p && *p != '\t' && *p != ' ') p++;
        if (!*p) continue;
        *p++ = 0;
        while (*p == '\t' || *p == ' ') p++;
        long long len = strtoll(p, NULL, 10);
        if (hdr_name2tid(h, name) >= 0) continue;
        char lb[32]; snprintf(lb, sizeof lb, "%lld", len);
        hdr_add_line(h, "SQ", "SN", name, "LN", lb, NULL);
        hdr_add_target(h, name, len);
    }
    free(line);
    fclose(f);
    return 0;
}
