rec_t *rec_init(void) { return xcalloc(1, sizeof(rec_t)); }
void rec_destroy(rec_t *b) { if (b) { free(b->data); free(b); } }
void rec_resize(rec_t *b, int n) {
    if (n > b->m_data) {
        int m = b->m_data ? b->m_data : 64;
        while (m < n) m *= 2;
        b->data = xrealloc(b->data, m);
        b->m_data = m;
    }
