    if (!(b->core.flag & FUNMAP) && b->core.n_cigar > 0) rlen = cigar2rlen(b->core.n_cigar, rec_cigar(b));
    if (rlen == 0) rlen = 1;
    return b->core.pos + rlen;
}

int reg2bin(int64_t beg, int64_t end, int min_shift, int n_lvls) {
    int l, s = min_shift, t = ((1 << ((n_lvls << 1) + n_lvls)) - 1) / 7;
    for (--end, l = n_lvls; l > 0; --l, s += 3, t -= 1 << ((l << 1) + l))
        if (beg >> s == end >> s) return (int)(t + (beg >> s));
    return 0;
}

void rec_set_bin(rec_t *b) {
