/* ---------------- aux ---------------- */
static int aux_type_size(char t) {
    switch (t) {
    case 'A': case 'c': case 'C': return 1;
    case 's': case 'S': return 2;
    case 'i': case 'I': case 'f': return 4;
    case 'd': return 8;
    }
    return 0;
}

int aux_size(const uint8_t *s) {
    /* s points at type byte; returns size of type+value */
    char t = s[0];
    int sz = aux_type_size(t);
    if (sz) return 1 + sz;
    if (t == 'Z' || t == 'H') { const uint8_t *p = s + 1; while (*p) p++; return (int)(p - s) + 1; }
