        int m = b->m_data ? b->m_data : 64;
        while (m < n) m *= 2;
        b->data = xrealloc(b->data, m);
        b->m_data = m;
    }
}
void rec_copy(rec_t *d, const rec_t *s) {
    rec_resize(d, s->l_data);
    memcpy(d->data, s->data, s->l_data);
    d->l_data = s->l_data;
    d->core = s->core;
    d->id = s->id;
}
rec_t *rec_dup(const rec_t *s) { rec_t *b = rec_init(); rec_copy(b, s); return b; }

int64_t cigar2rlen(int n, const uint32_t *cig) {
    int64_t l = 0;
    for (int i = 0; i < n; i++) if (cigar_type(cig_op(cig[i])) & 2) l += cig_len(cig[i]);
    return l;
}
int64_t cigar2qlen(int n, const uint32_t *cig) {
    int64_t l = 0;
    for (int i = 0; i < n; i++) if (cigar_type(cig_op(cig[i])) & 1) l += cig_len(cig[i]);
