    if (c->tid >= 0 && c->tid < h->n_targets) ks_puts(s, h->tname[c->tid]); else ks_putc(s, '*');
    ks_putc(s, '\t');
    ks_puti64(s, c->pos + 1); ks_putc(s, '\t');
    ks_puti64(s, c->qual); ks_putc(s, '\t');
    if (c->n_cigar) {
        const uint32_t *cig = rec_cigar(b);
        for (uint32_t i = 0; i < c->n_cigar; i++) {
            uint32_t cv; memcpy(&cv, cig + i, 4);
            ks_putu64(s, cig_len(cv)); ks_putc(s, CIGAR_STR[cig_op(cv)] ? CIGAR_STR[cig_op(cv)] : '?');
        }
    } else ks_putc(s, '*');
    ks_putc(s, '\t');
    if (c->mtid < 0) ks_putc(s, '*');
    else if (c->mtid == c->tid) ks_putc(s, '=');
    else ks_puts(s, hdr_tname(h, c->mtid));
    ks_putc(s, '\t');
    ks_puti64(s, c->mpos + 1); ks_putc(s, '\t');
    ks_puti64(s, c->isize); ks_putc(s, '\t');
    if (c->l_qseq) {
        const uint8_t *sq = rec_seq(b);
        ks_grow(s, c->l_qseq * 2 + 2);
        for (int i = 0; i < c->l_qseq; i++) s->s[s->l++] = seq_nt16_str[seqi(sq, i)];
        s->s[s->l] = 0;
        ks_putc(s, '\t');
        const uint8_t *q = rec_qual(b);
        if (q[0] == 0xff) ks_putc(s, '*');
        else {
            ks_grow(s, c->l_qseq);
            for (int i = 0; i < c->l_qseq; i++) s->s[s->l++] = q[i] + 33;
            s->s[s->l] = 0;
        }
    } else { ks_puts(s, "*\t*"); }
    const uint8_t *p = rec_aux(b), *end = b->data + b->l_data;
    while (p + 3 <= end) {
        ks_putc(s, '\t');
        const uint8_t *nx;
        aux_format1(s, p, &nx);
        if (!nx) return -1;
        p = nx;
    }
    return 0;
}

/* ---------------- SAM parsing ---------------- */
#define W(...) do { fprintf(stderr, __VA_ARGS__); } while (0)

static int64_t str2i64(const char *p, const char **end) {
    errno = 0;
    char *e;
    long long v = strtoll(p, &e, 10);
    *end = e;
    return v;
}

typedef struct { kstr d; } bbuf_t;

static int parse_B(kstr *d, const char *q, const char *qe) {
    /* q points to subtype char */
    char st = *q;
    if (!strchr("cCsSiIf", st) || q >= qe) {
        W("[E::sam_parse_B_vals_r] Unrecognized type B:%c\n", st);
        return -1;
    }
    q++;
    /* count values */
    int n = 0;
    for (const char *r = q; r < qe; r++) if (*r == ',') n++;
    if (st == 'f') {
        size_t off = d->l;
        ks_putc(d, 'B'); ks_putc(d, 'f');
        uint32_t nn = n; ks_putsn(d, (char*)&nn, 4);
        const char *r = q;
        for (int i = 0; i < n; i++) {
            r++; /* skip comma */
            char *e;
            float f = strtof(r, &e);
            if (e == r && !(*r == ',' || r >= qe)) { W("[E::sam_parse_B_vals_r] Malformed B:%c\n", st); return -1; }
            if (e == r) f = 0;
            if (e < qe && *e != ',') { W("[E::sam_parse_B_vals_r] Malformed B:%c\n", st); return -1; }
            ks_putsn(d, (char*)&f, 4);
            r = e;
        }
        (void)off;
        return 0;
    }
    int64_t *vals = xmalloc((n + 1) * sizeof(int64_t));
    int64_t mn = 0, mx = 0;
    const char *r = q;
    for (int i = 0; i < n; i++) {
        r++;
        char *e;
        errno = 0;
        long long v;
        if (*r == '-') v = strtoll(r, &e, 10);
        else { unsigned long long u = strtoull(r, &e, 10); v = (u > (unsigned long long)LLONG_MAX) ? LLONG_MAX : (long long)u; }
        if (e < qe && *e != ',') { free(vals); W("[E::sam_parse_B_vals_r] Malformed B:%c\n", st); return -1; }
        if (e == r && e < qe && *e != ',') { free(vals); W("[E::sam_parse_B_vals_r] Malformed B:%c\n", st); return -1; }
        vals[i] = v;
        if (i == 0) mn = mx = v; else { if (v < mn) mn = v; if (v > mx) mx = v; }
        r = e;
    }
    char t = st;
    if (n > 0) {
        if (mn < 0) {
            if (mn >= INT8_MIN && mx <= INT8_MAX) t = 'c';
            else if (mn >= INT16_MIN && mx <= INT16_MAX) t = 's';
            else if (mn >= INT32_MIN && mx <= INT32_MAX) t = 'i';
            else { free(vals); W("[E::sam_parse_B_vals_r] Numeric value in B array out of allowed range\n"); return -1; }
        } else {
            if (mx <= UINT8_MAX) t = 'C';
            else if (mx <= UINT16_MAX) t = 'S';
            else if (mx <= UINT32_MAX) t = 'I';
            else { free(vals); W("[E::sam_parse_B_vals_r] Numeric value in B array out of allowed range\n"); return -1; }
        }
    }
    ks_putc(d, 'B'); ks_putc(d, t);
    uint32_t nn = n; ks_putsn(d, (char*)&nn, 4);
    for (int i = 0; i < n; i++) {
        switch (t) {
        case 'c': case 'C': { uint8_t x = (uint8_t)vals[i]; ks_putsn(d, (char*)&x, 1); break; }
        case 's': case 'S': { uint16_t x = (uint16_t)vals[i]; ks_putsn(d, (char*)&x, 2); break; }
        default: { uint32_t x = (uint32_t)vals[i]; ks_putsn(d, (char*)&x, 4); break; }
        }
    }
    free(vals);
    return 0;
}

int sam_parse1(const char *line, size_t len, const hdr_t *h, rec_t *b, int lineno) {
    (void)lineno;
    const char *f[12]; size_t fl[12];
    int nf = 0;
    const char *p = line, *end = line + len;
    while (nf < 11) {
        const char *q = p;
        while (q < end && *q != '\t') q++;
        f[nf] = p; fl[nf] = q - p; nf++;
        if (q >= end) { p = end; break; }
        p = q + 1;
    }
    if (nf < 11) return -2;
    const char *aux = (p < end && nf == 11 && f[10] + fl[10] < end) ? f[10] + fl[10] + 1 : NULL;
    core_t *c = &b->core;
    memset(c, 0, sizeof *c);
    kstr d = {0, 0, NULL};
    /* qname */
    if (fl[0] > 254) { W("[E::sam_parse1] query name too long\n"); return -2; }
    if (fl[0] == 0) { W("[E::sam_parse1] empty query name\n"); return -2; }
    ks_putsn(&d, f[0], fl[0]); ks_putc(&d, 0);
    int extranul = (4 - (d.l & 3)) & 3;
    for (int i = 0; i < extranul; i++) ks_putc(&d, 0);
    c->l_qname = d.l; c->l_extranul = extranul;
    /* flag */
    {
        char *e; long v = strtol(f[1], &e, 0);
        if (v < 0 || v > 0xffff) { W("[E::sam_parse1] number outside allowed range\n"); free(d.s); return -2; }
        c->flag = v;
    }
    /* rname */
    char tmp[1024];
    if (fl[2] == 1 && f[2][0] == '*') c->tid = -1;
    else {
        size_t l = fl[2] < sizeof tmp - 1 ? fl[2] : sizeof tmp - 1;
        memcpy(tmp, f[2], l); tmp[l] = 0;
        c->tid = hdr_name2tid(h, tmp);
        if (c->tid < 0) {
            W("[W::sam_parse1] unrecognized reference name \"%s\"; treated as unmapped\n", tmp);
            c->flag |= FUNMAP;
        }
    }
    /* pos */
    {
        const char *e; int64_t v = str2i64(f[3], &e);
        c->pos = v - 1;
        if (c->pos < 0 && c->tid >= 0) {
            W("[W::sam_parse1] mapped query cannot have zero coordinate; treated as unmapped\n");
            c->tid = -1;
            c->flag |= FUNMAP;
        }
        if (c->tid < 0) c->tid = -1;
    }
    /* mapq */
    {
        char *e; long v = strtol(f[4], &e, 10);
        if (v < 0 || v > 255) { W("[E::sam_parse1] number outside allowed range\n"); free(d.s); return -2; }
        c->qual = v;
    }
    /* cigar */
    if (!(fl[5] == 1 && f[5][0] == '*')) {
        const char *q = f[5], *qe = f[5] + fl[5];
        while (q < qe) {
            char *e;
            unsigned long n = strtoul(q, &e, 10);
            if (e == q || e >= qe) { W("[E::parse_cigar] Unrecognized CIGAR operator\n"); free(d.s); return -2; }
            const char *op = strchr(CIGAR_STR, *e);
            if (!op || !*e) { W("[E::parse_cigar] Unrecognized CIGAR operator\n"); free(d.s); return -2; }
            uint32_t cv = (uint32_t)(n << 4) | (uint32_t)(op - CIGAR_STR);
            ks_putsn(&d, (char*)&cv, 4);
            c->n_cigar++;
            q = e + 1;
        }
    }
    if (c->n_cigar == 0 && !(c->flag & FUNMAP)) {
        W("[W::sam_parse1] mapped query must have a CIGAR; treated as unmapped\n");
        c->flag |= FUNMAP;
    }
    int64_t qlen_cig = 0, rlen = 0;
    if (c->n_cigar) {
        uint32_t *cg = (uint32_t*)(d.s + c->l_qname);
        qlen_cig = cigar2qlen(c->n_cigar, cg);
        rlen = cigar2rlen(c->n_cigar, cg);
    }
    /* rnext */
    if (fl[6] == 1 && f[6][0] == '*') c->mtid = -1;
    else if (fl[6] == 1 && f[6][0] == '=') c->mtid = c->tid;
    else {
        size_t l = fl[6] < sizeof tmp - 1 ? fl[6] : sizeof tmp - 1;
        memcpy(tmp, f[6], l); tmp[l] = 0;
        c->mtid = hdr_name2tid(h, tmp);
        if (c->mtid < 0) W("[W::sam_parse1] unrecognized mate reference name \"%s\"; treated as unmapped\n", tmp);
    }
    { const char *e; c->mpos = str2i64(f[7], &e) - 1; }
    { const char *e; c->isize = str2i64(f[8], &e); }
    /* seq */
    if (!(fl[9] == 1 && f[9][0] == '*')) {
        c->l_qseq = fl[9];
        if (c->n_cigar && qlen_cig != c->l_qseq) {
            W("[E::sam_parse1] CIGAR and query sequence are of different length\n"); free(d.s); return -2;
        }
        size_t off = d.l;
        int nb = (c->l_qseq + 1) >> 1;
        ks_grow(&d, nb);
        memset(d.s + off, 0, nb);
        for (int i = 0; i < c->l_qseq; i++)
            d.s[off + (i>>1)] |= seq_nt16_table[(uint8_t)f[9][i]] << ((~i & 1) << 2);
        d.l += nb;
    }
    /* qual */
    {
        size_t off = d.l;
        ks_grow(&d, c->l_qseq);
        if (fl[10] == 1 && f[10][0] == '*') {
            memset(d.s + off, 0xff, c->l_qseq);
        } else {
            if ((int64_t)fl[10] != c->l_qseq) {
                W("[E::sam_parse1] SEQ and QUAL are of different length\n"); free(d.s); return -2;
            }
            for (int i = 0; i < c->l_qseq; i++) d.s[off + i] = f[10][i] - 33;
        }
        d.l += c->l_qseq;
    }
    /* aux */
    if (aux) {
        const char *q = aux;
        while (q < end) {
            const char *qe = q;
            while (qe < end && *qe != '\t') qe++;
            size_t tl = qe - q;
            if (tl < 3 || q[2] != ':') {
                if (tl < 5 && tl >= 3 && q[2] == ':' ) {}
                W("[E::aux_parse] incomplete aux field\n"); free(d.s); return -2;
            }
            if (tl < 5) { W("[E::aux_parse] Incomplete aux field\n"); free(d.s); return -2; }
            char type = q[3];
            if (q[4] != ':') { W("[E::aux_parse] unrecognized type '%c'\n", q[4] == ':' ? type : q[4]); free(d.s); return -2; }
            ks_putc(&d, q[0]); ks_putc(&d, q[1]);
            const char *v = q + 5;
            size_t vl = qe - v;
            switch (type) {
            case 'A':
                if (vl < 1) { W("[E::aux_parse] incomplete aux field\n"); free(d.s); return -2; }
                ks_putc(&d, 'A'); ks_putc(&d, v[0]); break;
            case 'i': case 'I': {
                char *e; int64_t x;
                if (*v == '-') {
                    errno = 0; long long t = strtoll(v, &e, 10);
                    if (errno || t < INT32_MIN) { W("[E::aux_parse] numeric value out of allowed range\n"); free(d.s); return -2; }
                    x = t;
                } else {
                    errno = 0; unsigned long long t = strtoull(v, &e, 10);
                    if (errno || t > UINT32_MAX) { W("[E::aux_parse] numeric value out of allowed range\n"); free(d.s); return -2; }
                    x = (int64_t)t;
                }
                uint8_t buf[8]; int n = put_int(buf, x);
                ks_putsn(&d, (char*)buf, n);
                break;
            }
            case 'f': {
                char tb[64]; size_t l = vl < 63 ? vl : 63; memcpy(tb, v, l); tb[l] = 0;
                float x = strtof(tb, NULL);
                ks_putc(&d, 'f'); ks_putsn(&d, (char*)&x, 4); break;
            }
            case 'd': {
                char tb[64]; size_t l = vl < 63 ? vl : 63; memcpy(tb, v, l); tb[l] = 0;
                double x = strtod(tb, NULL);
                ks_putc(&d, 'd'); ks_putsn(&d, (char*)&x, 8); break;
            }
            case 'Z': ks_putc(&d, 'Z'); ks_putsn(&d, v, vl); ks_putc(&d, 0); break;
            case 'H':
                if (vl & 1) { W("[E::aux_parse] hex field does not have an even number of digits\n"); free(d.s); return -2; }
                ks_putc(&d, 'H'); ks_putsn(&d, v, vl); ks_putc(&d, 0); break;
            case 'B': {
                if (vl < 1) { W("[E::sam_parse_B_vals_r] Unrecognized type B:%c\n", ' '); free(d.s); return -2; }
                if (parse_B(&d, v, qe) < 0) { free(d.s); return -2; }
                break;
            }
            default:
                W("[E::aux_parse] unrecognized type '%c'\n", type); free(d.s); return -2;
            }
            q = qe < end ? qe + 1 : end;
        }
    }
    /* bin */
    {
        int64_t r = rlen;
        if (r == 0 || (c->flag & FUNMAP)) r = 1;
        c->bin = reg2bin(c->pos, c->pos + r, 14, 5);
    }
    free(b->data);
    b->data = (uint8_t*)d.s; b->m_data = d.m; b->l_data = d.l;
    return 0;
}

void rec_reverse_complement_seq(char *seq, int len) {
    static const char comp[256] = {
        ['A']='T',['C']='G',['G']='C',['T']='A',['N']='N',['a']='t',['c']='g',['g']='c',['t']='a',['n']='n',
        ['M']='K',['R']='Y',['W']='W',['S']='S',['Y']='R',['K']='M',['V']='B',['H']='D',['D']='H',['B']='V',['=']='=',
        ['m']='k',['r']='y',['w']='w',['s']='s',['y']='r',['k']='m',['v']='b',['h']='d',['d']='h',['b']='v'
    };
    for (int i = 0, j = len - 1; i <= j; i++, j--) {
        char a = seq[i], b2 = seq[j];
        seq[i] = comp[(uint8_t)b2] ? comp[(uint8_t)b2] : b2;
        seq[j] = comp[(uint8_t)a] ? comp[(uint8_t)a] : a;
    }
}
