{"command":"cd /workspace/src && cat > sam_io.c <<'EOF'
/* SAM/BAM file I/O */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "sam.h"

static int detect_from_bytes(const uint8_t *b, int n) {
    if (n >= 4 && memcmp(b, "BAM\1", 4) == 0) return FMT_BAM;
    if (n >= 4 && memcmp(b, "CRAM", 4) == 0) return FMT_CRAM;
    if (n >= 1 && b[0] == '>') return FMT_FASTA;
    if (n >= 1 && b[0] == '@') {
        /* SAM header or FASTQ: check */
        if (n >= 4 && (memcmp(b, "@HD\t", 4) == 0 || memcmp(b, "@SQ\t", 4) == 0 || memcmp(b, "@RG\t", 4) == 0 ||
                       memcmp(b, "@PG\t", 4) == 0 || memcmp(b, "@CO\t", 4) == 0)) return FMT_SAM;
        /* look for FASTQ: second line then '+' line */
        int i = 0, nl = 0;
        int line_starts[4] = {0};
        for (i = 0; i < n && nl < 3; i++) if (b[i] == '\n') { nl++; if (nl < 4) line_starts[nl] = i + 1; }
        if (nl >= 2 && line_starts[2] < n && b[line_starts[2]] == '+') return FMT_FASTQ;
        return FMT_SAM;
    }
    return FMT_SAM;
}

samfile_t *sf_open(const char *fn, const char *mode) {
    samfile_t *fp = xcalloc(1, sizeof(samfile_t));
    fp->fn = xstrdup(fn);
    if (mode[0] == 'r') {
        fp->bg = bg_open_read(fn);
        if (!fp->bg) { free(fp->fn); free(fp); return NULL; }
        fp->is_compressed = fp->bg->mode != BG_RAW;
        uint8_t buf[4096];
        int n = bg_peek(fp->bg, buf, sizeof buf);
        if (n < 0) n = 0;
        fp->fmt = detect_from_bytes(buf, n);
        if (n == 0) fp->fmt = FMT_SAM;
        return fp;
    }
    fp->is_write = 1;
    int bam = strchr(mode, 'b') != NULL;
    int level = -1;
    for (const char *p = mode; *p; p++) if (*p >= '0' && *p <= '9') level = *p - '0';
    if (strchr(mode, 'u')) level = 0;
    if (bam) {
        fp->fmt = FMT_BAM;
        fp->bg = bg_open_write(fn, BG_BGZF, level);
    } else if (strchr(mode, 'z')) {
        fp->fmt = FMT_SAM;
        fp->bg = bg_open_write(fn, BG_BGZF, level);
    } else {
        fp->fmt = FMT_SAM;
        fp->bg = bg_open_write(fn, BG_RAW, 0);
    }
    if (!fp->bg) { free(fp->fn); free(fp); return NULL; }
    fp->level = level;
    return fp;
}

static int read_exact(bgzf_t *bg, void *buf, int64_t n) {
    int64_t r = bg_read(bg, buf, n);
    return r == n ? 0 : -1;
}

hdr_t *sf_read_header(samfile_t *fp) {
    hdr_t *h = hdr_init();
    if (fp->fmt == FMT_BAM) {
        uint8_t magic[4];
        int32_t l_text, n_ref;
        if (read_exact(fp->bg, magic, 4) < 0 || memcmp(magic, "BAM\1", 4) != 0) goto err;
        if (read_exact(fp->bg, &l_text, 4) < 0 || l_text < 0) goto err;
        char *text = xmalloc(l_text + 1);
        if (read_exact(fp->bg, text, l_text) < 0) { free(text); goto err; }
        text[l_text] = 0;
        size_t tl = strlen(text);
        if (read_exact(fp->bg, &n_ref, 4) < 0 || n_ref < 0) { free(text); goto err; }
        for (int i = 0; i < n_ref; i++) {
            int32_t ln; uint32_t lr;
            if (read_exact(fp->bg, &ln, 4) < 0 || ln <= 0) { free(text); goto err; }
            char *name = xmalloc(ln + 1);
            if (read_exact(fp->bg, name, ln) < 0) { free(name); free(text); goto err; }
            name[ln] = 0;
            if (read_exact(fp->bg, &lr, 4) < 0) { free(name); free(text); goto err; }
            hdr_add_target(h, name, lr);
            free(name);
        }
        if (hdr_parse(h, text, tl) < 0) { free(text); goto err; }
        h->raw_text = text;
        hdr_sync_sq(h);
        fp->hdr = h;
        return h;
    } else if (fp->fmt == FMT_SAM) {
        int lineno = 0;
        for (;;) {
            int r = bg_getline(fp->bg, &fp->line);
            if (r < 0) break;
            lineno++;
            if (fp->line.l > 0 && fp->line.s[0] == '@') {
                if (hdr_parse_line(h, fp->line.s, fp->line.l, lineno) < 0) goto err;
            } else {
                fp->pending = 1;
                break;
            }
        }
        fp->lineno = lineno;
        if (hdr_build_targets(h) < 0) goto err;
        fp->hdr = h;
        return h;
    }
err:
    hdr_destroy(h);
    return NULL;
}

int bam_read_rec(bgzf_t *bg, rec_t *b) {
    int32_t bs;
    int64_t r = bg_read(bg, &bs, 4);
    if (r == 0) return -1;
    if (r != 4) return -3;
    if (bs < 32) return -4;
    uint8_t x[32];
    if (read_exact(bg, x, 32) < 0) return -3;
    core_t *c = &b->core;
    int32_t i32; uint16_t u16; uint32_t u32;
    memcpy(&i32, x, 4); c->tid = i32;
    memcpy(&i32, x + 4, 4); c->pos = i32;
    uint8_t l_rn = x[8];
    c->qual = x[9];
    memcpy(&u16, x + 10, 2); c->bin = u16;
    memcpy(&u16, x + 12, 2); c->n_cigar = u16;
    memcpy(&u16, x + 14, 2); c->flag = u16;
    memcpy(&u32, x + 16, 4); c->l_qseq = (int32_t)u32;
    memcpy(&i32, x + 20, 4); c->mtid = i32;
    memcpy(&i32, x + 24, 4); c->mpos = i32;
    memcpy(&i32, x + 28, 4); c->isize = i32;
    int extranul = (4 - (l_rn & 3)) & 3;
    c->l_extranul = extranul;
    c->l_qname = l_rn + extranul;
    int dlen = bs - 32;
    int total = dlen + extranul;
    rec_resize(b, total + 1);
    if (read_exact(bg, b->data, l_rn) < 0) return -3;
    for (int i = 0; i < extranul; i++) b->data[l_rn + i] = 0;
    if (read_exact(bg, b->data + l_rn + extranul, dlen - l_rn) < 0) return -3;
    b->l_data = total;
    return 0;
}

int sf_read(samfile_t *fp, rec_t *b) {
    if (fp->fmt == FMT_BAM) {
        fp->last_voff = bg_tell(fp->bg);
        int r = bam_read_rec(fp->bg, b);
        return r;
    }
    if (fp->fmt == FMT_SAM) {
        for (;;) {
            if (!fp->pending) {
                fp->last_voff = bg_tell(fp->bg);
                int r = bg_getline(fp->bg, &fp->line);
                if (r < 0) return fp->bg->err ? -2 : -1;
                fp->lineno++;
            }
            fp->pending = 0;
            if (fp->line.l == 0) continue;
            int r = sam_parse1(fp->line.s, fp->line.l, fp->hdr, b, fp->lineno);
            if (r < 0) {
                fprintf(stderr, "[W::sam_read1_sam] Parse error at line %d\n", fp->lineno);
                return -4;
            }
            return 0;
        }
    }
    return -2;
}

int sf_write_header(samfile_t *fp, const hdr_t *h) {
    kstr t = {0, 0, NULL};
    hdr_text(h, &t);
    if (fp->fmt == FMT_BAM) {
        bg_write(fp->bg, "BAM\1", 4);
        int32_t l = t.l;
        bg_write(fp->bg, &l, 4);
        bg_write(fp->bg, t.s, t.l);
        int32_t n = h->n_targets;
        bg_write(fp->bg, &n, 4);
        for (int i = 0; i < h->n_targets; i++) {
            int32_t ln = strlen(h->tname[i]) + 1;
            bg_write(fp->bg, &ln, 4);
            bg_write(fp->bg, h->tname[i], ln);
            uint32_t lr = (uint32_t)h->tlen[i];
            bg_write(fp->bg, &lr, 4);
        }
        bg_flush(fp->bg);
    } else {
        bg_write(fp->bg, t.s, t.l);
    }
    ks_free(&t);
    return 0;
}

int bam_write_rec(bgzf_t *bg, const rec_t *b) {
    const core_t *c = &b->core;
    int l_rn = c->l_qname - c->l_extranul;
    int dlen = b->l_data - c->l_extranul;
    int32_t bs = 32 + dlen;
    uint8_t x[36];
    int32_t i32; uint16_t u16; uint32_t u32;
    memcpy(x, &bs, 4);
    i32 = c->tid; memcpy(x + 4, &i32, 4);
    i32 = (int32_t)c->pos; memcpy(x + 8, &i32, 4);
    x[12] = l_rn; x[13] = c->qual;
    u16 = c->bin; memcpy(x + 14, &u16, 2);
    u16 = c->n_cigar; memcpy(x + 16, &u16, 2);
    u16 = c->flag; memcpy(x + 18, &u16, 2);
    u32 = c->l_qseq; memcpy(x + 20, &u32, 4);
    i32 = c->mtid; memcpy(x + 24, &i32, 4);
    i32 = (int32_t)c->mpos; memcpy(x + 28, &i32, 4);
    i32 = (int32_t)c->isize; memcpy(x + 32, &i32, 4);
    bg_flush_try(bg, 4 + bs);
    if (bg_write(bg, x, 36) < 0) return -1;
    if (bg_write(bg, b->data, l_rn) < 0) return -1;
    if (bg_write(bg, b->data + c->l_qname, b->l_data - c->l_qname) < 0) return -1;
    return 0;
}

int sf_write(samfile_t *fp, const hdr_t *h, const rec_t *b) {
    if (fp->fmt == FMT_BAM) return bam_write_rec(fp->bg, b);
    sam_format1(h, b, &fp->line);
    ks_putc(&fp->line, '\n');
    return bg_write(fp->bg, fp->line.s, fp->line.l);
}

int sf_close(samfile_t *fp) {
    if (!fp) return 0;
    int r = bg_close(fp->bg);
    ks_free(&fp->line);
    free(fp->fn);
    free(fp);
    return r;
}

const char *sf_ext(int fmt) {
    switch (fmt) {
    case FMT_BAM: return "bam";
    case FMT_CRAM: return "cram";
    default: return "sam";
    }
}

char *stringify_argv(int argc, char **argv) {
    kstr s = {0, 0, NULL};
    for (int i = 0; i < argc; i++) {
        if (i) ks_putc(&s, ' ');
        for (const char *p = argv[i]; *p; p++) {
            if (*p == '\t' || *p == '\n') ks_putc(&s, ' ');
            else ks_putc(&s, *p);
        }
    }
    return ks_release(&s);
}

void make_cmdline(int argc, char **argv) {
    free(g_cmdline);
    g_cmdline = stringify_argv(argc, argv);
}
EOF"}

