cat > idx.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include "idx.h"

#define MIN_MARKER_DIST 0x10000

static inline int bin_first(int l) { return ((1 << ((l << 1) + l)) - 1) / 7; }
static inline int bin_parent(int b) { return (b - 1) >> 3; }
static inline int bin_level(int bin) { int l, b; for (l = 0, b = bin; b; ++l, b = bin_parent(b)); return l; }
static inline int bin_bot(int bin, int n_lvls) { int l = bin_level(bin); return (bin - bin_first(l)) << (n_lvls - l) * 3; }

idx_t *idx_init(int n, int fmt, uint64_t offset0, int min_shift, int n_lvls) {
    idx_t *idx = xcalloc(1, sizeof(idx_t));
    idx->fmt = fmt; idx->min_shift = min_shift; idx->n_lvls = n_lvls;
    idx->n_bins = ((1 << (3 * n_lvls + 3)) - 1) / 7;
    idx->n = n;
    idx->bidx = xcalloc(n > 0 ? n : 1, sizeof(kh32_t*));
    idx->lidx = xcalloc(n > 0 ? n : 1, sizeof(lidx_t));
    idx->z.save_bin = idx->z.last_bin = 0xffffffffu;
    idx->z.save_tid = idx->z.last_tid = -1;
    idx->z.save_off = idx->z.last_off = idx->z.off_beg = idx->z.off_end = offset0;
    idx->z.last_coor = 0xffffffffu;
    return idx;
}

void idx_destroy(idx_t *idx) {
    if (!idx) return;
    for (int i = 0; i < idx->n; i++) { kh32_destroy(idx->bidx[i]); free(idx->lidx[i].offset); }
    free(idx->bidx); free(idx->lidx); free(idx);
}

static void insert_to_b(kh32_t *b, int bin, uint64_t beg, uint64_t end) {
    int absent;
    uint32_t k = kh32_put(b, bin, &absent);
    bins_t *l = &b->vals[k];
    if (absent) { l->m = 1; l->n = 0; l->list = calloc(1, sizeof(pair64_t)); l->loff = 0; }
    if (l->n == l->m) { l->m <<= 1; l->list = realloc(l->list, l->m * sizeof(pair64_t)); }
    l->list[l->n].u = beg;
    l->list[l->n++].v = end;
}

static void insert_to_l(lidx_t *l, int64_t _beg, int64_t _end, uint64_t offset, int min_shift) {
    int64_t beg = _beg >> min_shift, end = (_end - 1) >> min_shift;
    if (l->m < end + 1) {
        int64_t new_m = l->m * 2 > end + 1 ? l->m * 2 : end + 1;
        l->offset = realloc(l->offset, new_m * sizeof(uint64_t));
        memset(l->offset + l->m, 0xff, (new_m - l->m) * sizeof(uint64_t));
        l->m = new_m;
    }
    for (int64_t i = beg; i <= end; ++i)
        if (l->offset[i] == (uint64_t)-1) l->offset[i] = offset;
    if (l->n < end + 1) l->n = end + 1;
}

int idx_push(idx_t *idx, int tid, int64_t beg, int64_t end, uint64_t offset, int is_mapped) {
    int bin;
    if (tid < 0) beg = -1, end = 0;
    if (idx->z.finished) return 0;
    if (idx->z.last_tid != tid || (idx->z.last_tid >= 0 && tid < 0)) {
        if (tid >= 0 && idx->n_no_coor) {
            fprintf(stderr, "[E::hts_idx_push] NO_COOR reads not in a single block at the end %d %d\n", tid, idx->z.last_tid);
            return -1;
        }
        if (tid >= 0 && idx->bidx[tid] != 0) {
            fprintf(stderr, "[E::hts_idx_push] Chromosome blocks not continuous\n");
            return -1;
        }
        idx->z.last_tid = tid;
        idx->z.last_bin = 0xffffffffu;
    } else if (tid >= 0 && idx->z.last_coor > beg) {
        fprintf(stderr, "[E::hts_idx_push] Unsorted positions on sequence #%d: %lld followed by %lld\n",
                tid + 1, (long long)idx->z.last_coor + 1, (long long)beg + 1);
        return -1;
    }
    if (tid >= 0) {
        if (idx->bidx[tid] == 0) idx->bidx[tid] = kh32_init();
        if (beg < 0) beg = 0;
        if (end <= 0) end = 1;
        if (is_mapped) insert_to_l(&idx->lidx[tid], beg, end, idx->z.last_off, idx->min_shift);
    } else idx->n_no_coor++;
    bin = reg2bin(beg, end, idx->min_shift, idx->n_lvls);
    if ((int)idx->z.last_bin != bin) {
        if (idx->z.save_bin != 0xffffffffu) {
            if (idx->z.save_tid >= 0)
                insert_to_b(idx->bidx[idx->z.save_tid], idx->z.save_bin, idx->z.save_off, idx->z.last_off);
        }
        if (idx->z.last_bin == 0xffffffffu && idx->z.save_bin != 0xffffffffu) {
            idx->z.off_end = idx->z.last_off;
            if (idx->z.save_tid >= 0) {
                insert_to_b(idx->bidx[idx->z.save_tid], idx->n_bins + 1, idx->z.off_beg, idx->z.off_end);
                insert_to_b(idx->bidx[idx->z.save_tid], idx->n_bins + 1, idx->z.n_mapped, idx->z.n_unmapped);
            }
            idx->z.n_mapped = idx->z.n_unmapped = 0;
            idx->z.off_beg = idx->z.off_end;
        }
        idx->z.save_off = idx->z.last_off;
        idx->z.save_bin = idx->z.last_bin = bin;
        idx->z.save_tid = tid;
    }
    if (is_mapped) ++idx->z.n_mapped;
    else ++idx->z.n_unmapped;
    idx->z.last_off = offset;
    idx->z.last_coor = beg;
    return 0;
}

static int cmp_pair_u(const void *a, const void *b) {
    const pair64_t *x = a, *y = b;
    return x->u < y->u ? -1 : x->u > y->u ? 1 : 0;
}

static void update_loff(idx_t *idx, int i, int free_lidx) {
    kh32_t *bidx = idx->bidx[i];
    lidx_t *lidx = &idx->lidx[i];
    int64_t l;
    uint64_t offset0 = 0;
    if (bidx) {
        uint32_t k = kh32_get(bidx, idx->n_bins + 1);
        if (k != bidx->n_buckets) offset0 = bidx->vals[k].list[0].u;
        for (l = 0; l < lidx->n && lidx->offset[l] == (uint64_t)-1; ++l) lidx->offset[l] = offset0;
    } else l = 1;
    for (; l < lidx->n; ++l)
        if (lidx->offset[l] == (uint64_t)-1) lidx->offset[l] = lidx->offset[l-1];
    if (bidx == 0) return;
    for (uint32_t k = 0; k != bidx->n_buckets; ++k)
        if (kh_exist32(bidx, k)) {
            if ((int)bidx->keys[k] < idx->n_bins) {
                int bot = bin_bot(bidx->keys[k], idx->n_lvls);
                bidx->vals[k].loff = bot < lidx->n ? lidx->offset[bot] : 0;
            } else bidx->vals[k].loff = 0;
        }
    if (free_lidx) { free(lidx->offset); lidx->m = lidx->n = 0; lidx->offset = 0; }
}

static void compress_binning(idx_t *idx, int i) {
    kh32_t *bidx = idx->bidx[i];
    if (!bidx) return;
    for (int l = idx->n_lvls; l > 0; --l) {
        unsigned start = bin_first(l);
        for (uint32_t k = 0; k != bidx->n_buckets; ++k) {
            if (!kh_exist32(bidx, k) || (int)bidx->keys[k] >= idx->n_bins || bidx->keys[k] < start) continue;
            bins_t *p = &bidx->vals[k];
            if (l < idx->n_lvls && p->n > 1) qsort(p->list, p->n, sizeof(pair64_t), cmp_pair_u);
            if ((p->list[p->n - 1].v >> 16) - (p->list[0].u >> 16) < MIN_MARKER_DIST) {
                uint32_t kp = kh32_get(bidx, bin_parent(bidx->keys[k]));
                if (kp == bidx->n_buckets) continue;
                bins_t *q = &bidx->vals[kp];
                if (q->n + p->n > q->m) {
                    q->m = q->n + p->n;
                    q->m--; q->m |= q->m >> 1; q->m |= q->m >> 2; q->m |= q->m >> 4; q->m |= q->m >> 8; q->m |= q->m >> 16; q->m++;
                    q->list = realloc(q->list, q->m * sizeof(pair64_t));
                }
                memcpy(q->list + q->n, p->list, p->n * sizeof(pair64_t));
                q->n += p->n;
                free(p->list); p->list = NULL;
                kh32_del(bidx, k);
            }
        }
    }
    uint32_t k = kh32_get(bidx, 0);
    if (k != bidx->n_buckets) qsort(bidx->vals[k].list, bidx->vals[k].n, sizeof(pair64_t), cmp_pair_u);
    for (k = 0; k != bidx->n_buckets; ++k) {
        if (!kh_exist32(bidx, k) || (int)bidx->keys[k] >= idx->n_bins) continue;
        bins_t *p = &bidx->vals[k];
        int l, m;
        for (l = 1, m = 0; l < p->n; ++l) {
            if (p->list[m].v >> 16 >= p->list[l].u >> 16) {
                if (p->list[m].v < p->list[l].v) p->list[m].v = p->list[l].v;
            } else p->list[++m] = p->list[l];
        }
        p->n = m + 1;
    }
}

void idx_finish(idx_t *idx, uint64_t final_offset) {
    if (!idx || idx->z.finished) return;
    if (idx->z.save_tid >= 0) {
        insert_to_b(idx->bidx[idx->z.save_tid], idx->z.save_bin, idx->z.save_off, final_offset);
        insert_to_b(idx->bidx[idx->z.save_tid], idx->n_bins + 1, idx->z.off_beg, final_offset);
        insert_to_b(idx->bidx[idx->z.save_tid], idx->n_bins + 1, idx->z.n_mapped, idx->z.n_unmapped);
    }
    for (int i = 0; i < idx->n; ++i) {
        update_loff(idx, i, idx->fmt == IDX_CSI);
        compress_binning(idx, i);
    }
    idx->z.finished = 1;
    idx->has_no_coor = 1;
}

static void put32(kstr *s, int32_t v) { ks_putsn(s, (char*)&v, 4); }
static void put64(kstr *s, uint64_t v) { ks_putsn(s, (char*)&v, 8); }

int idx_save(const idx_t *idx, const char *fn) {
    kstr s = {0, 0, NULL};
    if (idx->fmt == IDX_CSI) {
        ks_putsn(&s, "CSI\1", 4);
        put32(&s, idx->min_shift); put32(&s, idx->n_lvls); put32(&s, 0);
    } else ks_putsn(&s, "BAI\1", 4);
    put32(&s, idx->n);
    for (int i = 0; i < idx->n; i++) {
        kh32_t *b = idx->bidx[i];
        put32(&s, b ? (int32_t)b->size : 0);
        if (b) for (uint32_t k = 0; k != b->n_buckets; ++k) if (kh_exist32(b, k)) {
            bins_t *p = &b->vals[k];
            put32(&s, b->keys[k]);
            if (idx->fmt == IDX_CSI) put64(&s, p->loff);
            put32(&s, p->n);
            for (int j = 0; j < p->n; j++) { put64(&s, p->list[j].u); put64(&s, p->list[j].v); }
        }
        if (idx->fmt != IDX_CSI) {
            put32(&s, (int32_t)idx->lidx[i].n);
            for (int64_t j = 0; j < idx->lidx[i].n; j++) put64(&s, idx->lidx[i].offset[j]);
        }
    }
    put64(&s, idx->n_no_coor);
    int ret = 0;
    if (idx->fmt == IDX_CSI) {
        bgzf_t *fp = bg_open_write(fn, BG_BGZF, -1);
        if (!fp) { ks_free(&s); return -1; }
        bg_write(fp, s.s, s.l);
        if (bg_close(fp) < 0) ret = -1;
    } else {
        FILE *f = fopen(fn, "wb");
        if (!f) { ks_free(&s); return -1; }
        if (fwrite(s.s, 1, s.l, f) != s.l) ret = -1;
        if (fclose(f) != 0) ret = -1;
    }
    ks_free(&s);
    return ret;
}

idx_t *idx_load(const char *fn) {
    bgzf_t *fp = bg_open_read(fn);
    if (!fp) return NULL;
    kstr s = {0, 0, NULL};
    uint8_t buf[65536];
    int64_t n;
    while ((n = bg_read(fp, buf, sizeof buf)) > 0) ks_putsn(&s, (char*)buf, n);
    bg_close(fp);
    if (s.l < 8) { ks_free(&s); return NULL; }
    const uint8_t *p = (uint8_t*)s.s, *e = p + s.l;
    idx_t *idx = NULL;
#define RD32(v) do { if (p + 4 > e) goto fail; memcpy(&(v), p, 4); p += 4; } while (0)
#define RD64(v) do { if (p + 8 > e) goto fail; memcpy(&(v), p, 8); p += 8; } while (0)
    int fmt, min_shift = 14, n_lvls = 5;
    if (memcmp(p, "BAI\1", 4) == 0) { fmt = IDX_BAI; p += 4; }
    else if (memcmp(p, "CSI\1", 4) == 0) {
        fmt = IDX_CSI; p += 4;
        int32_t laux;
        RD32(min_shift); RD32(n_lvls); RD32(laux);
        if (laux < 0 || p + laux > e) goto fail;
        p += laux;
    } else { ks_free(&s); return NULL; }
    int32_t nref; RD32(nref);
    idx = idx_init(nref, fmt, 0, min_shift, n_lvls);
    for (int i = 0; i < nref; i++) {
        int32_t nbin; RD32(nbin);
        if (nbin > 0) idx->bidx[i] = kh32_init();
        for (int j = 0; j < nbin; j++) {
            uint32_t bin; int32_t nch; uint64_t loff = 0;
            RD32(bin);
            if (fmt == IDX_CSI) RD64(loff);
            RD32(nch);
            int absent;
            uint32_t k = kh32_put(idx->bidx[i], bin, &absent);
            bins_t *b = &idx->bidx[i]->vals[k];
            b->m = b->n = nch; b->loff = loff;
            b->list = xmalloc((nch > 0 ? nch : 1) * sizeof(pair64_t));
            for (int c = 0; c < nch; c++) { RD64(b->list[c].u); RD64(b->list[c].v); }
        }
        if (fmt != IDX_CSI) {
            int32_t nint; RD32(nint);
            idx->lidx[i].n = idx->lidx[i].m = nint;
            idx->lidx[i].offset = xmalloc((nint > 0 ? nint : 1) * sizeof(uint64_t));
            for (int c = 0; c < nint; c++) RD64(idx->lidx[i].offset[c]);
        }
    }
    if (p + 8 <= e) { memcpy(&idx->n_no_coor, p, 8); idx->has_no_coor = 1; }
    idx->z.finished = 1;
    ks_free(&s);
    return idx;
fail:
    idx_destroy(idx);
    ks_free(&s);
    return NULL;
}

static int file_exists(const char *fn) { struct stat st; return stat(fn, &st) == 0; }

char *idx_find(const char *fn) {
    size_t l = strlen(fn);
    char *t = xmalloc(l + 8);
    const char *exts[] = { ".bai", ".csi", ".crai", NULL };
    for (int i = 0; exts[i]; i++) {
        sprintf(t, "%s%s", fn, exts[i]);
        if (file_exists(t)) return t;
    }
    /* replace extension */
    const char *dot = strrchr(fn, '.');
    const char *slash = strrchr(fn, '/');
    if (dot && (!slash || dot > slash)) {
        size_t b = dot - fn;
        for (int i = 0; exts[i]; i++) {
            memcpy(t, fn, b); strcpy(t + b, exts[i]);
            if (file_exists(t)) return t;
        }
    }
    free(t);
    return NULL;
}

idx_t *idx_load_for(const char *fn, const char *fnidx) {
    char *f = fnidx ? xstrdup(fnidx) : idx_find(fn);
    if (!f) return NULL;
    idx_t *idx = idx_load(f);
    free(f);
    return idx;
}

int idx_get_stat(const idx_t *idx, int tid, uint64_t *mapped, uint64_t *unmapped) {
    *mapped = *unmapped = 0;
    if (tid < 0 || tid >= idx->n || !idx->bidx[tid]) return -1;
    kh32_t *b = idx->bidx[tid];
    uint32_t k = kh32_get(b, idx->n_bins + 1);
    if (k == b->n_buckets || b->vals[k].n < 2) return -1;
    *mapped = b->vals[k].list[1].u;
    *unmapped = b->vals[k].list[1].v;
    return 0;
}

uint64_t idx_max_offset(const idx_t *idx) {
    uint64_t mx = 0;
    for (int i = 0; i < idx->n; i++) {
        kh32_t *b = idx->bidx[i];
        if (!b) continue;
        uint32_t k = kh32_get(b, idx->n_bins + 1);
        if (k != b->n_buckets && b->vals[k].n >= 1) {
            if (b->vals[k].list[0].v > mx) mx = b->vals[k].list[0].v;
        } else {
            for (uint32_t j = 0; j < b->n_buckets; j++) if (kh_exist32(b, j) && (int)b->keys[j] < idx->n_bins) {
                bins_t *p = &b->vals[j];
                for (int c = 0; c < p->n; c++) if (p->list[c].v > mx) mx = p->list[c].v;
            }
        }
    }
    return mx;
}

int bam_index_build(const char *fn, const char *fnidx, int min_shift) {
    samfile_t *fp = sf_open(fn, "r");
    if (!fp) return -2;
    if (fp->fmt != FMT_BAM || fp->bg->mode != BG_BGZF) { sf_close(fp); return -3; }
    hdr_t *h = sf_read_header(fp);
    if (!h) { sf_close(fp); return -2; }
    int fmt, n_lvls;
    if (min_shift > 0) {
        int64_t max_len = 0, s;
        for (int i = 0; i < h->n_targets; i++) if (h->tlen[i] > max_len) max_len = h->tlen[i];
        max_len += 256;
        for (n_lvls = 0, s = 1LL << min_shift; max_len > s; ++n_lvls, s <<= 3);
        fmt = IDX_CSI;
    } else { min_shift = 14; n_lvls = 5; fmt = IDX_BAI; }
    idx_t *idx = idx_init(h->n_targets, fmt, bg_tell(fp->bg), min_shift, n_lvls);
    rec_t *b = rec_init();
    int r;
    while ((r = bam_read_rec(fp->bg, b)) >= 0) {
        if (idx_push(idx, b->core.tid, b->core.pos, rec_endpos(b), bg_tell(fp->bg), !(b->core.flag & FUNMAP)) < 0) {
            fprintf(stderr, "[E::sam_index] Read '%s' with ref_name='%s', ref_length=%lld, flags=%d, pos=%lld cannot be indexed\n",
                    rec_qname(b), hdr_tname(h, b->core.tid), (long long)(b->core.tid >= 0 ? h->tlen[b->core.tid] : 0),
                    b->core.flag, (long long)b->core.pos + 1);
            rec_destroy(b); idx_destroy(idx); hdr_destroy(h); sf_close(fp);
            return -1;
        }
    }
    if (r < -1) { rec_destroy(b); idx_destroy(idx); hdr_destroy(h); sf_close(fp); return -4; }
    idx_finish(idx, bg_tell(fp->bg));
    char *out;
    if (fnidx) out = xstrdup(fnidx);
    else { out = xmalloc(strlen(fn) + 5); sprintf(out, "%s.%s", fn, fmt == IDX_CSI ? "csi" : "bai"); }
    int ret = idx_save(idx, out);
    free(out);
    rec_destroy(b); idx_destroy(idx); hdr_destroy(h); sf_close(fp);
    return ret < 0 ? -5 : 0;
}

/* ---------------- iterator ---------------- */
static int reg2bins(int64_t beg, int64_t end, int min_shift, int n_lvls, int **list, int *m) {
    int l, t, s = min_shift + (n_lvls << 1) + n_lvls, n = 0;
    if (beg >= end) return 0;
    if (end >= 1LL << s) end = 1LL << s;
    for (--end, l = 0, t = 0; l <= n_lvls; s -= 3, t += 1 << ((l << 1) + l), ++l) {
        int64_t b, e;
        b = t + (beg >> s); e = t + (end >> s);
        int need = n + (int)(e - b) + 1;
        if (need > *m) { *m = need * 2; *list = xrealloc(*list, *m * sizeof(int)); }
        for (int64_t i = b; i <= e; ++i) (*list)[n++] = (int)i;
    }
    return n;
}

iter_t *idx_query(const idx_t *idx, int tid, int64_t beg, int64_t end) {
    iter_t *it = xcalloc(1, sizeof(iter_t));
    it->tid = tid; it->beg = beg; it->end = end;
    if (tid == -1) { /* no coordinate reads */
        it->nocoor = 1;
        it->n_off = 1;
        it->off = xmalloc(sizeof(pair64_t));
        it->off[0].u = idx_max_offset(idx);
        it->off[0].v = (uint64_t)-1;
        return it;
    }
    if (tid == -3) { it->all = 1; return it; }
    if (tid < 0 || tid >= idx->n || !idx->bidx[tid]) { it->finished = 1; return it; }
    if (beg < 0) beg = 0;
    kh32_t *bidx = idx->bidx[tid];
    uint64_t min_off = 0;
    {
        int bin = bin_first(idx->n_lvls) + (int)(beg >> idx->min_shift);
        uint32_t k;
        do {
            k = kh32_get(bidx, bin);
            if (k != bidx->n_buckets) break;
            int first = (bin_parent(bin) << 3) + 1;
            if (bin > first) --bin; else bin = bin_parent(bin);
        } while (bin);
        if (bin == 0) k = kh32_get(bidx, bin);
        min_off = k != bidx->n_buckets ? bidx->vals[k].loff : 0;
        if (idx->lidx[tid].offset && (beg >> idx->min_shift) < idx->lidx[tid].n &&
            min_off < idx->lidx[tid].offset[beg >> idx->min_shift])
            min_off = idx->lidx[tid].offset[beg >> idx->min_shift];
    }
    int *bins = NULL, mb = 0;
    int nb = reg2bins(beg, end, idx->min_shift, idx->n_lvls, &bins, &mb);
    int n_off = 0, m_off = 0;
    pair64_t *off = NULL;
    for (int i = 0; i < nb; i++) {
        uint32_t k = kh32_get(bidx, bins[i]);
        if (k == bidx->n_buckets) continue;
        bins_t *p = &bidx->vals[k];
        for (int j = 0; j < p->n; j++) {
            if (p->list[j].v > min_off) {
                if (n_off == m_off) { m_off = m_off ? m_off * 2 : 16; off = xrealloc(off, m_off * sizeof(pair64_t)); }
                off[n_off].u = p->list[j].u > min_off ? p->list[j].u : min_off;
                off[n_off].v = p->list[j].v;
                n_off++;
            }
        }
    }
    free(bins);
    if (n_off) {
        qsort(off, n_off, sizeof(pair64_t), cmp_pair_u);
        int l = 0;
        for (int i = 1; i < n_off; ++i) {
            if (off[i].u <= off[l].v) { if (off[i].v > off[l].v) off[l].v = off[i].v; }
            else off[++l] = off[i];
        }
        n_off = l + 1;
    }
    it->off = off; it->n_off = n_off; it->i = -1;
    if (n_off == 0) it->finished = 1;
    return it;
}

void iter_destroy(iter_t *it) { if (it) { free(it->off); free(it); } }

int iter_next(samfile_t *fp, iter_t *it, rec_t *b) {
    if (it->finished) return -1;
    if (it->all) {
        return sf_read(fp, b);
    }
    for (;;) {
        if (it->i < 0 || (it->i < it->n_off && it->curr_off >= it->off[it->i].v)) {
            it->i++;
            if (it->i >= it->n_off) { it->finished = 1; return -1; }
            if (it->i == 0 || it->off[it->i].u != it->curr_off) {
                if (bg_seek(fp->bg, it->off[it->i].u) < 0) { it->finished = 1; return -2; }
            }
            it->curr_off = bg_tell(fp->bg);
        }
        int r = bam_read_rec(fp->bg, b);
        if (r < 0) { it->finished = 1; return r; }
        it->curr_off = bg_tell(fp->bg);
        if (it->nocoor) {
            if (b->core.tid >= 0) continue;
            return 0;
        }
        if (b->core.tid != it->tid || b->core.pos >= it->end) { it->finished = 1; return -1; }
        if (rec_endpos(b) > it->beg && it->end > b->core.pos) return 0;
    }
}
EOF

