#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <inttypes.h>
#include "bed.h"
#include "bgzf.h"

bed_t *bed_init(void) {
    bed_t *b = xcalloc(1, sizeof(bed_t));
    b->map = sm_init();
    return b;
}

void bed_destroy(bed_t *b) {
    if (!b) return;
    for (int i = 0; i < b->n; i++) { free(b->l[i].a); free(b->l[i].name); }
    free(b->l); sm_destroy(b->map); free(b);
}

bedlist_t *bed_get(const bed_t *b, const char *chr) {
    int64_t v;
    if (!b || !sm_get(b->map, chr, &v)) return NULL;
    return &b->l[v];
}

void bed_add(bed_t *b, const char *chr, int64_t beg, int64_t end) {
    int64_t v;
    if (!sm_get(b->map, chr, &v)) {
        if (b->n == b->m) { b->m = b->m ? b->m * 2 : 8; b->l = xrealloc(b->l, b->m * sizeof(bedlist_t)); }
        memset(&b->l[b->n], 0, sizeof(bedlist_t));
        b->l[b->n].name = xstrdup(chr);
        v = b->n++;
        sm_put(b->map, chr, v);
    }
    bedlist_t *p = &b->l[v];
    if (p->n == p->m) { p->m = p->m ? p->m * 2 : 8; p->a = xrealloc(p->a, p->m * sizeof(bedreg_t)); }
    p->a[p->n].beg = beg; p->a[p->n].end = end; p->n++;
}

bed_t *bed_read(const char *fn) {
    bgzf_t *fp = bg_open_read(fn);
    if (!fp) return NULL;
    bed_t *b = bed_init();
    kstr line = {0, 0, NULL};
    unsigned lineno = 0;
    while (bg_getline(fp, &line) >= 0) {
        lineno++;
        char *ref = line.s, *ref_end;
        if (line.l == 0 || *ref == '#') continue;
        if (strncmp(ref, "track", 5) == 0 && isspace((unsigned char)ref[5])) continue;
        if (strncmp(ref, "browser", 7) == 0 && isspace((unsigned char)ref[7])) continue;
        for (ref_end = ref; *ref_end && !isspace((unsigned char)*ref_end); ref_end++) {}
        if (ref_end == ref) {
            fprintf(stderr, "[bed_read] Parse error reading \"%s\" at line %u\n", fn, lineno);
            continue;
        }
        uint64_t beg = 0, end = 0;
        int num = sscanf(ref_end, "%" SCNu64 " %" SCNu64, &beg, &end);
        if (num == 1) { end = beg--; }
        if (num < 1 || end < beg) {
            char save = *ref_end; *ref_end = 0;
            if (strcmp(ref, "browser") == 0 || strcmp(ref, "track") == 0) { *ref_end = save; continue; }
            *ref_end = save;
            if (num < 1) fprintf(stderr, "[bed_read] Parse error reading \"%s\" at line %u\n", fn, lineno);
            else fprintf(stderr, "[bed_read] Parse error reading \"%s\" at line %u : end < start\n", fn, lineno);
            continue;
        }
        *ref_end = 0;
        bed_add(b, ref, (int64_t)beg, (int64_t)end);
    }
    ks_free(&line);
    bg_close(fp);
    bed_unify(b);
    return b;
}

static int cmp_reg(const void *a, const void *b) {
    const bedreg_t *x = a, *y = b;
    if (x->beg != y->beg) return x->beg < y->beg ? -1 : 1;
    if (x->end != y->end) return x->end < y->end ? -1 : 1;
    return 0;
}

void bed_unify(bed_t *b) {
    for (int i = 0; i < b->n; i++) {
        bedlist_t *p = &b->l[i];
        if (p->n < 2) continue;
        qsort(p->a, p->n, sizeof(bedreg_t), cmp_reg);
        int j = 0;
        for (int k = 1; k < p->n; k++) {
            if (p->a[k].beg <= p->a[j].end) { if (p->a[k].end > p->a[j].end) p->a[j].end = p->a[k].end; }
            else p->a[++j] = p->a[k];
        }
        p->n = j + 1;
    }
}

int bed_overlap(const bed_t *b, const char *chr, int64_t beg, int64_t end) {
    bedlist_t *p = bed_get(b, chr);
    if (!p || p->n == 0) return 0;
    /* binary search first region with end > beg */
    int lo = 0, hi = p->n;
    while (lo < hi) { int mid = (lo + hi) / 2; if (p->a[mid].end <= beg) lo = mid + 1; else hi = mid; }
    for (int i = lo; i < p->n; i++) {
        if (p->a[i].beg >= end) break;
        if (p->a[i].end > beg && p->a[i].beg < end) return 1;
    }
    return 0;
}
EOF"}

