            if (p->a[k].beg <= p->a[j].end) { if (p->a[k].end > p->a[j].end) p->a[j].end = p->a[k].end; }
            else p->a[++j] = p->a[k];
        }
        p->n = j + 1;
    }
}

int bed_overlap(const bed_t *b, const char *chr, int64_t beg, int64_t end) {
    bedlist_t *p = bed_get(b, chr);
    if (!p || p->n == 0) return 0;
    /* binary search first region with end > beg */
    int lo = 0, hi = p->n;
    while (lo < hi) { int mid = (lo + hi) / 2; if (p->a[mid].end <= beg) lo = mid + 1; else hi = mid; }
    for (int i = lo; i < p->n; i++) {
        if (p->a[i].beg >= end) break;
        if (p->a[i].end > beg && p->a[i].beg < end) return 1;
    }
    return 0;
}
