            fprintf(stderr, "[E::hts_parse_region] Coordinates must be > 0\n");
            return -1;
        }
        if (isdigit((unsigned char)*hyphen) || *hyphen == '\0' || *hyphen == ',') {
            *end = *beg == -1 ? POS_MAX : -(*beg + 1);
            *beg = 0;
            return 0;
        } else if (*beg < -1) {
            fprintf(stderr, "[E::hts_parse_region] Unexpected string \"%s\" after region\n", hyphen);
            return -1;
        }
    }
    if (*hyphen == '\0') {
        *end = POS_MAX;
    } else if (*hyphen == '-') {
        *end = parse_decimal(hyphen + 1, &hyphen, 0);
        if (*hyphen != '\0' && *hyphen != ',') {
            fprintf(stderr, "[E::hts_parse_region] Unexpected string \"%s\" after region\n", hyphen);
            return -1;
        }
    } else {
        fprintf(stderr, "[E::hts_parse_region] Unexpected string \"%s\" after region\n", hyphen);
        return -1;
    }
    if (*end == 0) *end = POS_MAX;
    if (*beg >= *end) return -1;
    return 0;
