cat > common.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include "common.h"

int g_verbosity = 3;

void gopts_init(gopts_t *g) { memset(g, 0, sizeof *g); g->out_level = -1; }

int parse_fmt_str(const char *s, int *fmt, int *compress, int *level) {
    char name[64]; size_t i = 0;
    while (s[i] && s[i] != ',' && i < sizeof name - 1) { name[i] = s[i]; i++; }
    name[i] = 0;
    *compress = 0;
    if (strcasecmp(name, "sam") == 0) *fmt = FMT_SAM;
    else if (strcasecmp(name, "bam") == 0) *fmt = FMT_BAM;
    else if (strcasecmp(name, "cram") == 0) *fmt = FMT_CRAM;
    else if (strcasecmp(name, "sam.gz") == 0) { *fmt = FMT_SAM; *compress = 1; }
    else if (strcasecmp(name, "fastq") == 0 || strcasecmp(name, "fq") == 0) *fmt = FMT_FASTQ;
    else if (strcasecmp(name, "fasta") == 0 || strcasecmp(name, "fa") == 0) *fmt = FMT_FASTA;
    else if (strcasecmp(name, "json") == 0) *fmt = 100;
    else if (strcasecmp(name, "tsv") == 0) *fmt = 101;
    else return -1;
    const char *p = s + i;
    while (*p == ',') {
        p++;
        if (strncmp(p, "level=", 6) == 0 && level) *level = atoi(p + 6);
        while (*p && *p != ',') p++;
    }
    return 0;
}

void gopts_init(gopts_t *g);
int gopts_parse(gopts_t *g, int c, const char *arg) {
    switch (c) {
    case GO_INPUT_FMT_OPTION: return 0;
    case GO_INPUT_FMT: return 0;
    case GO_OUTPUT_FMT: {
        int cmp, lvl = g->out_level;
        if (parse_fmt_str(arg, &g->out_fmt, &cmp, &lvl) < 0) return -1;
        g->out_compress = cmp; g->out_level = lvl;
        g->out_fmt_str = (char*)arg;
        return 0;
    }
    case GO_OUTPUT_FMT_OPTION:
        if (strncmp(arg, "level=", 6) == 0) g->out_level = atoi(arg + 6);
        return 0;
    case GO_REFERENCE: g->reference = (char*)arg; return 0;
    case GO_THREADS: g->nthreads = atoi(arg); return 0;
    case GO_WRITE_INDEX: g->write_index = 1; return 0;
    case GO_VERBOSITY: g->verbosity = atoi(arg); g_verbosity = g->verbosity; return 0;
    }
    return -1;
}

int fmt_from_fn(const char *fn, int *compress) {
    *compress = 0;
    if (!fn || strcmp(fn, "-") == 0) return 0;
    size_t l = strlen(fn);
    char *t = xstrdup(fn);
    const char *zext[] = { ".gz", ".bgz", ".bgzf", NULL };
    for (int i = 0; zext[i]; i++) {
        size_t el = strlen(zext[i]);
        if (l > el && strcasecmp(t + l - el, zext[i]) == 0) { *compress = 1; t[l - el] = 0; l -= el; break; }
    }
    int fmt = 0;
    const char *dot = strrchr(t, '.');
    if (dot) {
        if (strcasecmp(dot, ".bam") == 0) fmt = FMT_BAM;
        else if (strcasecmp(dot, ".cram") == 0) fmt = FMT_CRAM;
        else if (strcasecmp(dot, ".sam") == 0) fmt = FMT_SAM;
        else if (strcasecmp(dot, ".fq") == 0 || strcasecmp(dot, ".fastq") == 0) fmt = FMT_FASTQ;
        else if (strcasecmp(dot, ".fa") == 0 || strcasecmp(dot, ".fasta") == 0) fmt = FMT_FASTA;
    }
    free(t);
    return fmt;
}

/* fmt_flag: "b" for BAM, "c" cram, "" SAM, NULL use default from filename */
void out_mode(char *mode, const char *fn, const gopts_t *g, const char *fmt_flag, int level) {
    strcpy(mode, "w");
    int fmt = 0, cmp = 0;
    if (g && g->out_fmt) { fmt = g->out_fmt; cmp = g->out_compress; }
    else if (fmt_flag && *fmt_flag) { fmt = fmt_flag[0] == 'b' ? FMT_BAM : fmt_flag[0] == 'c' ? FMT_CRAM : FMT_SAM; }
    else {
        fmt = fmt_from_fn(fn, &cmp);
        if (fmt == 0 || fmt == FMT_FASTA || fmt == FMT_FASTQ) {
            if (fmt_flag) fmt = FMT_SAM, cmp = 0;
            else fmt = FMT_SAM;
        }
    }
    if (fmt == FMT_CRAM) fmt = FMT_BAM; /* CRAM unsupported: fall back */
    if (fmt == FMT_BAM) strcat(mode, "b");
    else if (cmp) strcat(mode, "z");
    int lv = level;
    if (g && g->out_level >= 0) lv = g->out_level;
    if (lv >= 0) { char t[3]; t[0] = '0' + (lv > 9 ? 9 : lv); t[1] = 0; strcat(mode, t); }
}

int write_index_for(const char *fn, int csi) {
    (void)csi;
    char *out = xmalloc(strlen(fn) + 5);
    sprintf(out, "%s.csi", fn);
    int r = bam_index_build(fn, out, 14);
    free(out);
    return r;
}

void add_pg(hdr_t *h, int no_pg) {
    if (no_pg) return;
    hdr_add_pg(h, "samtools", g_version, g_cmdline);
}
EOF"}

