/* fmt_flag: "b" for BAM, "c" cram, "" SAM, NULL use default from filename */
void out_mode(char *mode, const char *fn, const gopts_t *g, const char *fmt_flag, int level) {
    strcpy(mode, "w");
    int fmt = 0, cmp = 0;
    if (g && g->out_fmt) { fmt = g->out_fmt; cmp = g->out_compress; }
    else if (fmt_flag && *fmt_flag) { fmt = fmt_flag[0] == 'b' ? FMT_BAM : fmt_flag[0] == 'c' ? FMT_CRAM : FMT_SAM; }
    else {
