static int sanitize_parse(const char *s, int *flags) {
    /* keywords: unmap, pos, mqual, cigar, aux, cigdup?, off, on, all, none */
    *flags = 0;
    char *d = xstrdup(s), *save = NULL;
    for (char *t = strtok_r(d, ",", &save); t; t = strtok_r(NULL, ",", &save)) {
        if (strcmp(t, "unmap") == 0) *flags |= 1;
        else if (strcmp(t, "pos") == 0) *flags |= 2;
        else if (strcmp(t, "mqual") == 0) *flags |= 4;
        else if (strcmp(t, "cigar") == 0) *flags |= 8;
        else if (strcmp(t, "cigdup") == 0) *flags |= 16;
        else if (strcmp(t, "cigarx") == 0) *flags |= 32;
        else if (strcmp(t, "aux") == 0) *flags |= 64;
        else if (strcmp(t, "off") == 0 || strcmp(t, "none") == 0) *flags = 0;
        else if (strcmp(t, "on") == 0) *flags |= 1|2|4|8|16;
        else if (strcmp(t, "all") == 0) *flags |= 0xffff;
        else { fprintf(stderr, "samtools sanitize: Unrecognised keyword %s\n", t); free(d); return -1; }
    }
    free(d);
    return 0;
}

