        }
        case 'D': {
            if (strlen(optarg) < 4 || optarg[2] != ':') {
                fprintf(stderr, "samtools view: Invalid \"tag:file\" option: \"%s\"\n", optarg);
                ret = 1; goto view_end;
            }
            if (s.has_tag && (s.tag[0] != optarg[0] || s.tag[1] != optarg[1])) {
                fprintf(stderr, "samtools view: Different tag \"%c%c\" was specified before: \"%s\"\n", optarg[0], optarg[1], s.tag);
                ret = 1; goto view_end;
            }
            s.tag[0] = optarg[0]; s.tag[1] = optarg[1]; s.tag[2] = 0; s.has_tag = 1;
            int ok;
            strmap_t *m = read_word_file(optarg + 3, &ok);
            if (!ok) { print_error_errno("view", "failed to open \"%s\" for reading", optarg + 3); ret = 1; goto view_end; }
            if (!s.tvhash) s.tvhash = m;
            else { for (int i = 0; i < m->m; i++) if (m->keys[i]) sm_put(s.tvhash, m->keys[i], 1); sm_destroy(m); }
            break;
        }
        case 0x2002: view_usage(stdout, 1); ret = 0; goto view_end;
        case 'B': s.remove_B = 1; break;
        case 'x': case 0x2004: {
            int keep = (c == 0x2004);
            const char *p = optarg;
            if (*p == '^') { keep = 1; p++; }
            if (!s.rm_tags) s.rm_tags = sm_init();
            s.keep_tags = keep;
            const char *q = p;
            while (*q) {
                const char *e = q;
                while (*e && *e != ',') e++;
                if (e - q != 2) {
                    fprintf(stderr, "main_samview: Error parsing option, auxiliary tags should be exactly two characters long.\n");
                    view_usage(stderr, 0);
                    ret = 1; goto view_end;
                }
                char t[3] = { q[0], q[1], 0 };
                sm_put(s.rm_tags, t, 1);
                q = *e ? e + 1 : e;
            }
            break;
        }
        case 'M': s.multi_region = 1; break;
        case 0x2006: no_pg = 1; break;
        case 'e':
            if (!(s.filter = expr_parse(optarg))) {
                fprintf(stderr, "[E::sam_passes_filter] Couldn't process filter expression\n");
                s.filter = expr_bad();
            }
            break;
        case 'z':
            if (sanitize_parse(optarg, &s.sanitize) < 0) { fputc('\n', stderr); ret = 1; goto view_end; }
            break;
        case 0x200b: save_counts = optarg; break;
        case 'O':
            if (gopts_parse(&ga, GO_OUTPUT_FMT, optarg) < 0) { fmt_err = 1; }
            break;
        case 'T': ga.reference = optarg; break;
        case '@': {
            char *e; long v = strtol(optarg, &e, 10);
            if (e == optarg || *e || v < 0) {
                fprintf(stderr, "Invalid threads value.\n");
                view_usage(stderr, 0);
                ret = 1; goto view_end;
            }
            break;
        }
        case '?':
            if (optopt && optopt < 0x1000) fprintf(stderr, "samtools view: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "samtools view: unrecognised option '%s'\n", argv[optind - 1]);
            view_usage(stderr, 0);
            ret = 1; goto view_end;
        default:
            if (gopts_parse(&ga, c, optarg) != 0) { view_usage(stderr, 0); ret = 1; goto view_end; }
        }
    }
    if (fmt_err) { view_usage(stderr, 0); ret = 1; goto view_end; }
    if (subsam_frac > 0) { s.subsam_frac = subsam_frac; s.subsam_seed = (uint32_t)subsam_seed; }
    if (is_header_only) is_header = 1;
    if (compress_level >= 0 && !*out_format) strcpy(out_format, "b");
    if (argc == optind && isatty(STDIN_FILENO)) {
        view_usage(stdout, 0);
        ret = 0; goto view_end;
    }
    fn_in = optind < argc ? argv[optind] : "-";
    if (has_index_file) {
        if (optind + 1 >= argc) {
            fprintf(stderr, "Incorrect number of arguments for -X option. Aborting.\n");
            ret = 1; goto view_end;
        }
        fn_idx_in = argv[optind + 1];
        optind++;
    }
    if (!fn_list && ga.reference) {
        static char fai[4096];
        snprintf(fai, sizeof fai, "%s.fai", ga.reference);
        if (access(fai, R_OK) != 0) {
            extern int fai_build(const char *fn);
            fai_build(ga.reference);
        }
        fn_list = fai;
    }
    samfile_t *in = sf_open(fn_in, "r");
    if (!in) {
        fprintf(stderr, "[E::hts_open_format] Failed to open file \"%s\" : %s\n", fn_in, strerror(errno));
        print_error_errno("view", "failed to open \"%s\" for reading", fn_in);
        ret = 1; goto view_end;
    }
    hdr_t *h = NULL;
    samfile_t *out = NULL, *un_out = NULL;
    rec_t *b = NULL;
    if (in->fmt == FMT_CRAM) {
        fprintf(stderr, "[main_samview] fail to read the header from \"%s\".\n", fn_in);
        ret = 1; goto view_close;
    }
    h = sf_read_header(in);
    if (!h) {
        fprintf(stderr, "[main_samview] fail to read the header from \"%s\".\n", fn_in);
        ret = 1; goto view_close;
    }
    if (fn_list && h->n_targets == 0 && in->fmt == FMT_SAM) {
        hdr_add_fai(h, fn_list);
    }
    if (s.rghash && !s.rg_neg && s.no_rg) { /* nothing special */ }
    if (!is_count) {
        char mode[16];
        if (!fn_out) fn_out = "-";
        out_mode(mode, fn_out, &ga, out_format, compress_level);
        add_pg(h, no_pg);
        out = sf_open(fn_out, mode);
        if (!out) {
            print_error_errno("view", "failed to open \"%s\" for writing", fn_out);
            ret = 1; goto view_close;
        }
        if (fn_un_out) {
            un_out = sf_open(fn_un_out, mode);
            if (!un_out) {
                print_error_errno("view", "failed to open \"%s\" for writing", fn_un_out);
                ret = 1; goto view_close;
            }
        }
        if (out->fmt != FMT_SAM || is_header || out->bg->mode == BG_BGZF) {
            if (out->fmt != FMT_SAM || is_header) sf_write_header(out, h);
        }
        if (un_out && (un_out->fmt != FMT_SAM || is_header)) sf_write_header(un_out, h);
    }
    if (is_header_only) goto view_close;

    b = rec_init();
    int nregs = argc - (optind + 1);
    if (nregs <= 0 && !s.multi_region) {
        int r;
        while ((r = sf_read(in, b)) >= 0) {
            if (s.sanitize) sanitize_rec(h, b, s.sanitize);
            int f = process_aln(h, b, &s);
            if (f < 0) {
                fprintf(stderr, "samtools view: error reading file \"%s\"\n", fn_in);
                ret = 1; break;
            }
            if (!f) {
                if (!is_count) {
                    b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags;
                    if (sf_write(out, h, b) < 0) { ret = 1; break; }
                }
                count++;
            } else {
                fail_count++;
                if (s.unmap && out) {
                    b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags;
                    b->core.flag |= FUNMAP;
                    sf_write(out, h, b);
                } else if (un_out) sf_write(un_out, h, b);
            }
        }
        if (r < -1) {
            fprintf(stderr, "samtools view: error reading file \"%s\"\n", fn_in);
            ret = 1;
        }
    } else {
        idx_t *idx = NULL;
        if (in->fmt == FMT_BAM && in->bg->mode == BG_BGZF) idx = idx_load_for(fn_in, fn_idx_in);
        if (!idx) {
            fprintf(stderr, "[E::idx_find_and_load] Could not retrieve index file for '%s'\n", fn_in);
            fprintf(stderr, "samtools view: Random alignment retrieval only works for indexed SAM.gz, BAM or CRAM files.\n");
            ret = 1; goto view_close;
        }
        if (!s.multi_region) {
            for (int i = optind + 1; i < argc; i++) {
                int tid; int64_t beg, end;
                if (parse_region(h, argv[i], &tid, &beg, &end, 0) < 0) {
                    fprintf(stderr, "[main_samview] region \"%s\" specifies an invalid region or unknown reference. Continue anyway.\n", argv[i]);
                    continue;
                }
                iter_t *it;
                if (tid == -3) { bg_seek(in->bg, 0); sf_close(in); in = sf_open(fn_in, "r"); hdr_t *t = sf_read_header(in); hdr_destroy(t); it = idx_query(idx, -3, 0, 0); }
                else it = idx_query(idx, tid, beg, end);
                int r;
                while ((r = iter_next(in, it, b)) >= 0) {
                    if (s.sanitize) sanitize_rec(h, b, s.sanitize);
                    int f = process_aln(h, b, &s);
                    if (f < 0) { fprintf(stderr, "samtools view: error reading file \"%s\"\n", fn_in); ret = 1; break; }
                    if (!f) {
                        if (!is_count) {
                            b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags;
                            sf_write(out, h, b);
                        }
                        count++;
                    } else {
                        fail_count++;
                        if (s.unmap && out) { b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags; b->core.flag |= FUNMAP; sf_write(out, h, b); }
                        else if (un_out) sf_write(un_out, h, b);
                    }
                }
                iter_destroy(it);
                if (r < -1) {
                    fprintf(stderr, "[main_samview] retrieval of region \"%s\" failed due to truncated file or corrupt BAM index file\n", argv[i]);
                    ret = 1; break;
                }
            }
        } else {
            /* multi-region: collect regions */
            int nr = 0, mr = 16;
            vreg_t *regs = xmalloc(mr * sizeof(vreg_t));
            for (int i = optind + 1; i < argc; i++) {
                int tid; int64_t beg, end;
                if (parse_region(h, argv[i], &tid, &beg, &end, 0) < 0) {
                    fprintf(stderr, "[main_samview] region \"%s\" specifies an invalid region or unknown reference. Continue anyway.\n", argv[i]);
                    continue;
                }
                if (tid == -3) { for (int t = 0; t < h->n_targets; t++) { if (nr == mr) { mr *= 2; regs = xrealloc(regs, mr * sizeof(vreg_t)); } regs[nr].tid = t; regs[nr].beg = 0; regs[nr].end = INT64_MAX; nr++; } tid = -1; beg = 0; end = INT64_MAX; }
                if (nr == mr) { mr *= 2; regs = xrealloc(regs, mr * sizeof(vreg_t)); }
                regs[nr].tid = tid; regs[nr].beg = beg; regs[nr].end = end; nr++;
            }
            if (s.bed && nregs <= 0) {
                for (int i = 0; i < s.bed->n; i++) {
                    int tid = hdr_name2tid(h, s.bed->l[i].name);
                    if (tid < 0) continue;
                    for (int j = 0; j < s.bed->l[i].n; j++) {
                        if (nr == mr) { mr *= 2; regs = xrealloc(regs, mr * sizeof(vreg_t)); }
                        regs[nr].tid = tid; regs[nr].beg = s.bed->l[i].a[j].beg; regs[nr].end = s.bed->l[i].a[j].end; nr++;
                    }
                }
            } else if (s.bed && nregs > 0) {
                /* intersect: keep cmdline regions, bed used as filter */
                s.multi_region = 0;
            }
            if (nregs <= 0 && !s.bed) {
                /* whole file */
                for (int t = 0; t < h->n_targets; t++) {
                    if (nr == mr) { mr *= 2; regs = xrealloc(regs, mr * sizeof(vreg_t)); }
                    regs[nr].tid = t; regs[nr].beg = 0; regs[nr].end = INT64_MAX; nr++;
                }
            }
            qsort(regs, nr, sizeof(vreg_t), cmp_vreg);
            /* gather chunks */
            int n_off = 0, m_off = 0; pair64_t *off = NULL;
            for (int i = 0; i < nr; i++) {
                iter_t *it = idx_query(idx, regs[i].tid, regs[i].beg, regs[i].end);
                for (int j = 0; j < it->n_off; j++) {
                    if (n_off == m_off) { m_off = m_off ? m_off * 2 : 16; off = xrealloc(off, m_off * sizeof(pair64_t)); }
                    off[n_off++] = it->off[j];
                }
                iter_destroy(it);
            }
            /* sort & merge */
            for (int i = 1; i < n_off; i++) { pair64_t t = off[i]; int j = i - 1; while (j >= 0 && off[j].u > t.u) { off[j+1] = off[j]; j--; } off[j+1] = t; }
            int l = 0;
            for (int i = 1; i < n_off; i++) {
                if (off[i].u <= off[l].v) { if (off[i].v > off[l].v) off[l].v = off[i].v; }
                else off[++l] = off[i];
            }
            if (n_off) n_off = l + 1;
            /* fetch pairs: collect names of selected reads first */
            strmap_t *pairnames = NULL;
            if (fetch_pairs) {
                pairnames = sm_init();
                for (int ci = 0; ci < n_off; ci++) {
                    if (bg_seek(in->bg, off[ci].u) < 0) break;
                    while (bg_tell(in->bg) < off[ci].v) {
                        if (bam_read_rec(in->bg, b) < 0) break;
                        if (overlaps_regs(regs, nr, b)) {
                            rec_t *tmp = rec_dup(b);
                            if (!process_aln(h, tmp, &s)) sm_put(pairnames, rec_qname(b), 1);
                            rec_destroy(tmp);
                        }
                    }
                }
                /* scan entire file for mates */
                sf_close(in); in = sf_open(fn_in, "r"); { hdr_t *t = sf_read_header(in); hdr_destroy(t); }
                int r;
                while ((r = sf_read(in, b)) >= 0) {
                    if (!sm_has(pairnames, rec_qname(b))) continue;
                    int f = process_aln(h, b, &s);
                    if (!f) {
                        if (!is_count) { b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags; sf_write(out, h, b); }
                        count++;
                    }
                }
                sm_destroy(pairnames);
            } else {
                for (int ci = 0; ci < n_off; ci++) {
                    if (bg_seek(in->bg, off[ci].u) < 0) break;
                    while ((uint64_t)bg_tell(in->bg) < off[ci].v) {
                        int r = bam_read_rec(in->bg, b);
                        if (r < 0) break;
                        if (!overlaps_regs(regs, nr, b)) continue;
                        int f = process_aln(h, b, &s);
                        if (f < 0) { ret = 1; break; }
                        if (!f) {
                            if (!is_count) { b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags; sf_write(out, h, b); }
                            count++;
                        } else {
                            fail_count++;
                            if (s.unmap && out) { b->core.flag |= FUNMAP; sf_write(out, h, b); }
                            else if (un_out) sf_write(un_out, h, b);
                        }
                    }
                }
            }
            free(off); free(regs);
        }
        idx_destroy(idx);
    }

view_close:
    if (is_count && ret == 0) printf("%lld\n", (long long)count);
    if (save_counts) {
        FILE *f = fopen(save_counts, "w");
        if (f) { fprintf(f, "%lld\n%lld\n", (long long)count, (long long)fail_count); fclose(f); }
    }
    if (out && sf_close(out) < 0) { if (!ret) { print_error_errno("view", "error closing output file"); ret = 1; } }
    if (un_out) sf_close(un_out);
    if (ga.write_index && out && fn_out && strcmp(fn_out, "-") != 0) write_index_for(fn_out, 1);
    rec_destroy(b);
    hdr_destroy(h);
    sf_close(in);
view_end:
    bed_destroy(s.bed);
    sm_destroy(s.rghash); sm_destroy(s.rnhash); sm_destroy(s.tvhash); sm_destroy(s.rm_tags);
    expr_destroy(s.filter);
    (void)fn_list;
    return ret;
}
EOF"}

actions.command:
cd /workspace/src && cat > cmd_view.c <<'EOF'
/* samtools view */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <ctype.h>
#include <math.h>
#include "common.h"
#include "expr.h"

typedef struct {
    int flag_on, flag_off, flag_anyon, flag_alloff;
    int min_mapQ, min_qlen;
    char *library;
    bed_t *bed;
    strmap_t *rghash; int rg_neg;
    strmap_t *rnhash; int rn_neg;
    strmap_t *tvhash; char tag[3]; int has_tag;
    int no_rg;
    double subsam_frac; uint32_t subsam_seed;
    int remove_B;
    strmap_t *rm_tags; int keep_tags;
    int unmap;
    int multi_region;
    int add_flags, remove_flags;
    expr_t *filter;
    int sanitize;
} vsettings_t;

static void view_usage(FILE *fp, int is_long) {
    fputs(is_long ? usage_view_long : usage_view_short, fp);
}

static uint32_t x31_hash(const char *s) {
    uint32_t h = (uint8_t)*s;
    if (h) for (++s; *s; ++s) h = (h << 5) - h + (uint8_t)*s;
    return h;
}
static uint32_t wang_hash(uint32_t key) {
    key += ~(key << 15);
    key ^= (key >> 10);
    key += (key << 3);
    key ^= (key >> 6);
    key += ~(key << 11);
    key ^= (key >> 16);
    return key;
}

const char *rec_library(const hdr_t *h, const rec_t *b) {
    uint8_t *rg = aux_get(b, "RG");
    if (!rg || rg[0] != 'Z') return NULL;
    int i = hdr_find_line(h, "RG", "ID", (char*)rg + 1);
    if (i < 0) return NULL;
    return hline_get(&h->l[i], "LB");
}

static void remove_B(rec_t *b) {
    /* collapse backward cigar operator */
    int n = b->core.n_cigar;
    uint32_t *cig = rec_cigar(b);
    int has_b = 0;
    for (int i = 0; i < n; i++) if (cig_op(cig[i]) == C_BACK) { has_b = 1; break; }
    if (!has_b) return;
    /* implementation following the classic algorithm */
    uint32_t *nc = xmalloc(n * sizeof(uint32_t) + 4);
    int k = 0, j;
    int end_j = -1; (void)end_j;
    uint8_t *seq = rec_seq(b), *qual = rec_qual(b);
    int qlen = b->core.l_qseq;
    char *s = xmalloc(qlen + 1); uint8_t *q = xmalloc(qlen + 1);
    for (int i = 0; i < qlen; i++) { s[i] = seqi(seq, i); q[i] = qual[i]; }
    int l = 0; /* query position */
    int ql = 0; /* new query length */
    for (int i = 0; i < n; i++) {
        int op = cig_op(cig[i]), len = cig_len(cig[i]);
        if (op == C_BACK) {
            int t, u;
            if (k == 0) continue;
            /* back up len on reference */
            u = len;
            for (j = k - 1; j >= 0 && u > 0; j--) {
                int op2 = cig_op(nc[j]), len2 = cig_len(nc[j]);
                if (cigar_type(op2) & 2) {
                    if (len2 > u) { nc[j] = ((len2 - u) << 4) | op2; if (cigar_type(op2) & 1) ql -= u; u = 0; break; }
                    else { u -= len2; if (cigar_type(op2) & 1) ql -= len2; k--; }
                } else {
                    if (cigar_type(op2) & 1) ql -= len2;
                    k--;
                }
            }
            t = 0; (void)t;
            l = ql;
        } else {
            if (k > 0 && cig_op(nc[k-1]) == op) nc[k-1] += len << 4;
            else nc[k++] = (len << 4) | op;
            if (cigar_type(op) & 1) {
                for (int x = 0; x < len; x++) { s[ql + x] = s[l + x]; q[ql + x] = q[l + x]; }
                ql += len; l += len;
            }
        }
    }
    (void)l;
    /* rebuild record */
    int old_cig_bytes = n * 4, new_cig_bytes = k * 4;
    int seq_old = (qlen + 1) / 2, seq_new = (ql + 1) / 2;
    int auxl = rec_l_aux(b);
    uint8_t *aux = xmalloc(auxl + 1); memcpy(aux, rec_aux(b), auxl);
    int newl = b->core.l_qname + new_cig_bytes + seq_new + ql + auxl;
    rec_resize(b, newl);
    (void)old_cig_bytes; (void)seq_old;
    memcpy(b->data + b->core.l_qname, nc, new_cig_bytes);
    b->core.n_cigar = k;
    b->core.l_qseq = ql;
    uint8_t *ns = rec_seq(b);
    memset(ns, 0, seq_new);
    for (int i = 0; i < ql; i++) ns[i>>1] |= s[i] << ((~i & 1) << 2);
    memcpy(rec_qual(b), q, ql);
    memcpy(rec_aux(b), aux, auxl);
    b->l_data = newl;
    free(aux); free(nc); free(s); free(q);
}

static void strip_tags(rec_t *b, strmap_t *tags, int keep) {
    uint8_t *p = rec_aux(b), *end = b->data + b->l_data;
    while (p + 3 <= end) {
        char t[3] = { p[0], p[1], 0 };
        int sz = aux_size(p + 2);
        if (sz < 0) break;
        int in = sm_has(tags, t);
        if ((in && !keep) || (!in && keep)) {
            memmove(p, p + 2 + sz, end - (p + 2 + sz));
            b->l_data -= 2 + sz;
            end = b->data + b->l_data;
        } else p += 2 + sz;
    }
}

/* returns 1 if filtered out, 0 if kept, -1 on error */
static int process_aln(const hdr_t *h, rec_t *b, vsettings_t *s) {
    if (s->filter) {
        int r = expr_eval_rec(s->filter, h, b);
        if (r < 0) return -1;
        if (!r) return 1;
    }
    if (b->core.qual < s->min_mapQ || ((b->core.flag & s->flag_on) != s->flag_on) || (b->core.flag & s->flag_off))
        return 1;
    if (s->flag_alloff && ((b->core.flag & s->flag_alloff) == s->flag_alloff)) return 1;
    if (s->flag_anyon && ((b->core.flag & s->flag_anyon) == 0)) return 1;
    if (!s->multi_region && s->bed && (b->core.tid < 0 || !bed_overlap(s->bed, hdr_tname(h, b->core.tid), b->core.pos, rec_endpos(b))))
        return 1;
    if (s->subsam_frac > 0.) {
        uint32_t k = wang_hash(x31_hash(rec_qname(b)) ^ s->subsam_seed);
        if ((double)(k & 0xffffff) / 0x1000000 >= s->subsam_frac) return 1;
    }
    if (s->rghash) {
        uint8_t *r = aux_get(b, "RG");
        if (r && r[0] == 'Z') {
            int in = sm_has(s->rghash, (char*)r + 1);
            if (in == s->rg_neg) return 1;
        } else if (s->no_rg) return 1;
    } else if (s->no_rg) {
        uint8_t *r = aux_get(b, "RG");
        if (!r) return 1;
    }
    if (s->has_tag) {
        uint8_t *t = aux_get(b, s->tag);
        if (!t) return 1;
        if (s->tvhash) {
            char buf[64];
            const char *v = NULL;
            if (t[0] == 'Z' || t[0] == 'H') v = (char*)t + 1;
            else if (t[0] == 'A') { buf[0] = t[1]; buf[1] = 0; v = buf; }
            else if (strchr("cCsSiI", t[0])) { snprintf(buf, sizeof buf, "%lld", (long long)aux2i(t)); v = buf; }
            else return 1;
            if (!sm_has(s->tvhash, v)) return 1;
        }
    }
    if (s->rnhash) {
        int in = sm_has(s->rnhash, rec_qname(b));
        if (in == s->rn_neg) return 1;
    }
    if (s->library) {
        const char *p = rec_library(h, b);
        if (!p || strcmp(p, s->library) != 0) return 1;
    }
    if (s->min_qlen > 0) {
        int qlen = 0;
        uint32_t *cig = rec_cigar(b);
        for (uint32_t k = 0; k < b->core.n_cigar; k++)
            if ((cigar_type(cig_op(cig[k])) & 1) || cig_op(cig[k]) == C_HARD_CLIP) qlen += cig_len(cig[k]);
        if (qlen < s->min_qlen) return 1;
    }
    if (s->remove_B) remove_B(b);
    if (s->rm_tags) strip_tags(b, s->rm_tags, s->keep_tags);
    return 0;
}

static strmap_t *read_word_file(const char *fn, int *ok) {
    FILE *f = fopen(fn, "r");
    *ok = 0;
    if (!f) return NULL;
    strmap_t *m = sm_init();
    char *line = NULL; size_t cap = 0; ssize_t n;
    while ((n = getline(&line, &cap, f)) >= 0) {
        char *p = line;
        while (*p && isspace((unsigned char)*p)) p++;
        char *e = p;
        while (*e && !isspace((unsigned char)*e)) e++;
        *e = 0;
        if (*p) sm_put(m, p, 1);
    }
    free(line); fclose(f);
    *ok = 1;
    return m;
}

static int parse_flags_opt(const char *arg, int *out) {
    int ok;
    int64_t v = parse_flag_str(arg, &ok);
    if (!ok || v < 0) { fprintf(stderr, "samtools view: Unknown flag '%s'\n", arg); return -1; }
    *out = (int)v;
    return 0;
}

static int sanitize_parse(const char *s, int *flags) {
    /* keywords: unmap, pos, mqual, cigar, aux, cigdup?, off, on, all, none */
    *flags = 0;
    char *d = xstrdup(s), *save = NULL;
    for (char *t = strtok_r(d, ",", &save); t; t = strtok_r(NULL, ",", &save)) {
        if (strcmp(t, "unmap") == 0) *flags |= 1;
        else if (strcmp(t, "pos") == 0) *flags |= 2;
        else if (strcmp(t, "mqual") == 0) *flags |= 4;
        else if (strcmp(t, "cigar") == 0) *flags |= 8;
        else if (strcmp(t, "cigdup") == 0) *flags |= 16;
        else if (strcmp(t, "cigarx") == 0) *flags |= 32;
        else if (strcmp(t, "aux") == 0) *flags |= 64;
        else if (strcmp(t, "off") == 0 || strcmp(t, "none") == 0) *flags = 0;
        else if (strcmp(t, "on") == 0) *flags |= 1|2|4|8|16;
        else if (strcmp(t, "all") == 0) *flags |= 0xffff;
        else { fprintf(stderr, "samtools sanitize: Unrecognised keyword %s\n", t); free(d); return -1; }
    }
    free(d);
    return 0;
}

int sanitize_rec(const hdr_t *h, rec_t *b, int flags);

typedef struct { int tid; int64_t beg, end; } vreg_t;

static int cmp_vreg(const void *a, const void *b) {
    const vreg_t *x = a, *y = b;
    if (x->tid != y->tid) return x->tid < y->tid ? -1 : 1;
    if (x->beg != y->beg) return x->beg < y->beg ? -1 : 1;
    return x->end < y->end ? -1 : x->end > y->end;
}

static int overlaps_regs(const vreg_t *r, int n, const rec_t *b) {
    int64_t e = rec_endpos(b);
    for (int i = 0; i < n; i++) {
        if (r[i].tid == -1 && b->core.tid < 0) return 1;
        if (r[i].tid != b->core.tid) continue;
        if (b->core.pos < r[i].end && e > r[i].beg) return 1;
    }
    return 0;
}

int main_samview(int argc, char *argv[]) {
    int c, is_header = 0, is_header_only = 0, ret = 0, compress_level = -1, is_count = 0, has_index_file = 0, no_pg = 0;
    int fetch_pairs = 0;
    char out_format[8] = "";
    char *fn_in = NULL, *fn_out = NULL, *fn_list = NULL, *fn_un_out = NULL, *fn_idx_in = NULL;
    char *save_counts = NULL;
    int64_t count = 0, fail_count = 0;
    vsettings_t s; memset(&s, 0, sizeof s);
    gopts_t ga; gopts_init(&ga);
    int fmt_err = 0;

    static const struct option lopts[] = {
        {"add-flags", required_argument, NULL, 0x2001},
        {"bam", no_argument, NULL, 'b'},
        {"count", no_argument, NULL, 'c'},
        {"cram", no_argument, NULL, 'C'},
        {"customized-index", no_argument, NULL, 'X'},
        {"excl-flags", required_argument, NULL, 'F'},
        {"exclude-flags", required_argument, NULL, 'F'},
        {"exclude-no-read_group", no_argument, NULL, 'n'},
        {"expr", required_argument, NULL, 'e'},
        {"fai-reference", required_argument, NULL, 't'},
        {"fast", no_argument, NULL, '1'},
        {"fetch-pairs", no_argument, NULL, 'P'},
        {"header-only", no_argument, NULL, 'H'},
        {"help", no_argument, NULL, 0x2002},
        {"incl-flags", required_argument, NULL, 0x2003},
        {"include-flags", required_argument, NULL, 0x2003},
        {"rf", required_argument, NULL, 0x2003},
        {"keep-tag", required_argument, NULL, 0x2004},
        {"library", required_argument, NULL, 'l'},
        {"min-mapq", required_argument, NULL, 'q'},
        {"min-MQ", required_argument, NULL, 'q'},
        {"min-mq", required_argument, NULL, 'q'},
        {"min-qlen", required_argument, NULL, 'm'},
        {"no-header", no_argument, NULL, 0x2005},
        {"no-PG", no_argument, NULL, 0x2006},
        {"output", required_argument, NULL, 'o'},
        {"output-unselected", required_argument, NULL, 'U'},
        {"unoutput", required_argument, NULL, 'U'},
        {"qname-file", required_argument, NULL, 'N'},
        {"read-group", required_argument, NULL, 'r'},
        {"read-group-file", required_argument, NULL, 'R'},
        {"readgroup", required_argument, NULL, 'r'},
        {"readgroup-file", required_argument, NULL, 'R'},
        {"region-file", required_argument, NULL, 0x2007},
        {"regions-file", required_argument, NULL, 0x2007},
        {"remove-B", no_argument, NULL, 'B'},
        {"remove-flags", required_argument, NULL, 0x2008},
        {"remove-tag", required_argument, NULL, 'x'},
        {"require-flags", required_argument, NULL, 'f'},
        {"subsample", required_argument, NULL, 0x2009},
        {"subsample-seed", required_argument, NULL, 0x200a},
        {"tag", required_argument, NULL, 'd'},
        {"tag-file", required_argument, NULL, 'D'},
        {"target-file", required_argument, NULL, 'L'},
        {"targets-file", required_argument, NULL, 'L'},
        {"uncompressed", no_argument, NULL, 'u'},
        {"unmap", no_argument, NULL, 'p'},
        {"use-index", no_argument, NULL, 'M'},
        {"with-header", no_argument, NULL, 'h'},
        {"sanitize", required_argument, NULL, 'z'},
        {"save-counts", required_argument, NULL, 0x200b},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"output-fmt", required_argument, NULL, 'O'},
        {"output-fmt-option", required_argument, NULL, GO_OUTPUT_FMT_OPTION},
        {"reference", required_argument, NULL, 'T'},
        {"threads", required_argument, NULL, '@'},
        {"write-index", no_argument, NULL, GO_WRITE_INDEX},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    double subsam_frac = -1; int64_t subsam_seed = 0;
    opterr = 0;
    while ((c = getopt_long(argc, argv, "SbBcCt:h1Ho:O:q:f:F:G:ul:r:T:R:N:d:D:L:s:@:m:x:U:MXe:pPz:n", lopts, NULL)) >= 0) {
        switch (c) {
        case 's': {
            char *e;
            double v = strtod(optarg, &e);
            if (e == optarg || *e != '\0' || v < 0) {
                fprintf(stderr, "samtools view: Incorrect sampling argument \"%s\"\n", optarg);
                ret = 1; goto view_end;
            }
            subsam_seed = (int64_t)v;
            subsam_frac = v - (double)subsam_seed;
            if (subsam_frac == 0) subsam_frac = -1; 
            break;
        }
        case 0x2009: {
            char *e; double v = strtod(optarg, &e);
            if (e == optarg || *e || v < 0 || v > 1) {
                fprintf(stderr, "samtools view: Incorrect sampling argument \"%s\"\n", optarg);
                goto view_end;
            }
            subsam_frac = v; break;
        }
        case 0x200a: {
            char *e; long long v = strtoll(optarg, &e, 10);
            if (e == optarg || *e) { fprintf(stderr, "samtools view: Incorrect seed argument \"%s\"\n", optarg); goto view_end; }
            subsam_seed = v; break;
        }
        case 'm': {
            char *e; long v = strtol(optarg, &e, 10);
            if (e == optarg || *e) { fprintf(stderr, "samtools view: Incorrect min_qlen \"%s\"\n", optarg); goto view_end; }
            s.min_qlen = v; break;
        }
        case 'c': is_count = 1; break;
        case 'S': break;
        case 'b': strcpy(out_format, "b"); break;
        case 'C': strcpy(out_format, "c"); break;
        case 't': fn_list = optarg; break;
        case 'h': is_header = 1; break;
        case 'H': is_header_only = 1; break;
        case 0x2005: is_header = is_header_only = 0; break;
        case 'o': fn_out = optarg; break;
        case 'U': fn_un_out = optarg; break;
        case 'X': has_index_file = 1; break;
        case 'f': { int v; if (parse_flags_opt(optarg, &v) < 0) { ret = 1; goto view_end; } s.flag_on |= v; break; }
        case 'F': { int v; if (parse_flags_opt(optarg, &v) < 0) { ret = 1; goto view_end; } s.flag_off |= v; break; }
        case 0x2003: { int v; if (parse_flags_opt(optarg, &v) < 0) { ret = 1; goto view_end; } s.flag_anyon |= v; break; }
        case 'G': { int v; if (parse_flags_opt(optarg, &v) < 0) { ret = 1; goto view_end; } s.flag_alloff |= v; break; }
        case 0x2001: { int v; if (parse_flags_opt(optarg, &v) < 0) { ret = 1; goto view_end; } s.add_flags |= v; break; }
        case 0x2008: { int v; if (parse_flags_opt(optarg, &v) < 0) { ret = 1; goto view_end; } s.remove_flags |= v; break; }
        case 'q': {
            char *e; long v = strtol(optarg, &e, 10);
            if (e == optarg || *e) { fprintf(stderr, "samtools view: Incorrect min_mapQ \"%s\"\n", optarg); goto view_end; }
            s.min_mapQ = v; break;
        }
        case 'u': compress_level = 0; break;
        case '1': compress_level = 1; break;
        case 'l': s.library = optarg; break;
        case 'p': s.unmap = 1; break;
        case 'P': fetch_pairs = 1; s.multi_region = 1; break;
        case 0x2007: s.multi_region = 1; /* fall through */
        case 'L':
            if (s.bed) bed_destroy(s.bed);
            if (!(s.bed = bed_read(optarg))) {
                print_error_errno("view", "Could not read file \"%s\"", optarg);
                ret = 1; goto view_end;
            }
            break;
        case 'n': s.no_rg = 1; break;
        case 'r':
            if (!s.rghash) s.rghash = sm_init();
            sm_put(s.rghash, optarg, 1);
            break;
        case 'R': {
            const char *fn = optarg; int neg = 0;
            if (*fn == '^') { neg = 1; fn++; }
            int ok;
            strmap_t *m = read_word_file(fn, &ok);
            if (!ok) { print_error_errno("view", "failed to open \"%s\" for reading", fn); ret = 1; goto view_end; }
            if (s.rghash) { for (int i = 0; i < m->m; i++) if (m->keys[i]) sm_put(s.rghash, m->keys[i], 1); sm_destroy(m); }
            else s.rghash = m;
            s.rg_neg = neg;
            break;
        }
        case 'N': {
            const char *fn = optarg; int neg = 0;
            if (*fn == '^') { neg = 1; fn++; }
            int ok;
            strmap_t *m = read_word_file(fn, &ok);
            if (!ok) { print_error_errno("view", "failed to open \"%s\" for reading", fn); ret = 1; goto view_end; }
            if (s.rnhash) { for (int i = 0; i < m->m; i++) if (m->keys[i]) sm_put(s.rnhash, m->keys[i], 1); sm_destroy(m); }
            else s.rnhash = m;
            s.rn_neg = neg;
            break;
        }
        case 'd': {
            if (strlen(optarg) < 2 || (optarg[2] && optarg[2] != ':')) {
                fprintf(stderr, "samtools view: Invalid \"tag:value\" option: \"%s\"\n", optarg);
                ret = 1; goto view_end;
            }
            if (s.has_tag && (s.tag[0] != optarg[0] || s.tag[1] != optarg[1])) {
                fprintf(stderr, "samtools view: Different tag \"%c%c\" was specified before: \"%s\"\n", optarg[0], optarg[1], s.tag);
                ret = 1; goto view_end;
            }
            s.tag[0] = optarg[0]; s.tag[1] = optarg[1]; s.tag[2] = 0; s.has_tag = 1;
            if (optarg[2] == ':' ) {
                if (!s.tvhash) s.tvhash = sm_init();
                sm_put(s.tvhash, optarg + 3, 1);
            }
            break;
        }
        case 'D': {
            if (strlen(optarg) < 4 || optarg[2] != ':') {
                fprintf(stderr, "samtools view: Invalid \"tag:file\" option: \"%s\"\n", optarg);
                ret = 1; goto view_end;
            }
            if (s.has_tag && (s.tag[0] != optarg[0] || s.tag[1] != optarg[1])) {
                fprintf(stderr, "samtools view: Different tag \"%c%c\" was specified before: \"%s\"\n", optarg[0], optarg[1], s.tag);
                ret = 1; goto view_end;
            }
            s.tag[0] = optarg[0]; s.tag[1] = optarg[1]; s.tag[2] = 0; s.has_tag = 1;
            int ok;
            strmap_t *m = read_word_file(optarg + 3, &ok);
            if (!ok) { print_error_errno("view", "failed to open \"%s\" for reading", optarg + 3); ret = 1; goto view_end; }
            if (!s.tvhash) s.tvhash = m;
            else { for (int i = 0; i < m->m; i++) if (m->keys[i]) sm_put(s.tvhash, m->keys[i], 1); sm_destroy(m); }
            break;
        }
        case 0x2002: view_usage(stdout, 1); ret = 0; goto view_end;
        case 'B': s.remove_B = 1; break;
        case 'x': case 0x2004: {
            int keep = (c == 0x2004);
            const char *p = optarg;
            if (*p == '^') { keep = 1; p++; }
            if (!s.rm_tags) s.rm_tags = sm_init();
            s.keep_tags = keep;
            const char *q = p;
            while (*q) {
                const char *e = q;
                while (*e && *e != ',') e++;
                if (e - q != 2) {
                    fprintf(stderr, "main_samview: Error parsing option, auxiliary tags should be exactly two characters long.\n");
                    view_usage(stderr, 0);
                    ret = 1; goto view_end;
                }
                char t[3] = { q[0], q[1], 0 };
                sm_put(s.rm_tags, t, 1);
                q = *e ? e + 1 : e;
            }
            break;
        }
        case 'M': s.multi_region = 1; break;
        case 0x2006: no_pg = 1; break;
        case 'e':
            if (!(s.filter = expr_parse(optarg))) {
                fprintf(stderr, "[E::sam_passes_filter] Couldn't process filter expression\n");
                s.filter = expr_bad();
            }
            break;
        case 'z':
            if (sanitize_parse(optarg, &s.sanitize) < 0) { fputc('\n', stderr); ret = 1; goto view_end; }
            break;
        case 0x200b: save_counts = optarg; break;
        case 'O':
            if (gopts_parse(&ga, GO_OUTPUT_FMT, optarg) < 0) { fmt_err = 1; }
            break;
        case 'T': ga.reference = optarg; break;
        case '@': {
            char *e; long v = strtol(optarg, &e, 10);
            if (e == optarg || *e || v < 0) {
                fprintf(stderr, "Invalid threads value.\n");
                view_usage(stderr, 0);
                ret = 1; goto view_end;
            }
            break;
        }
        case '?':
            if (optopt && optopt < 0x1000) fprintf(stderr, "samtools view: invalid option -- '%c'\n", optopt);
            else fprintf(stderr, "samtools view: unrecognised option '%s'\n", argv[optind - 1]);
            view_usage(stderr, 0);
            ret = 1; goto view_end;
        default:
            if (gopts_parse(&ga, c, optarg) != 0) { view_usage(stderr, 0); ret = 1; goto view_end; }
        }
    }
    if (fmt_err) { view_usage(stderr, 0); ret = 1; goto view_end; }
    if (subsam_frac > 0) { s.subsam_frac = subsam_frac; s.subsam_seed = (uint32_t)subsam_seed; }
    if (is_header_only) is_header = 1;
    if (compress_level >= 0 && !*out_format) strcpy(out_format, "b");
    if (argc == optind && isatty(STDIN_FILENO)) {
        view_usage(stdout, 0);
        ret = 0; goto view_end;
    }
    fn_in = optind < argc ? argv[optind] : "-";
    if (has_index_file) {
        if (optind + 1 >= argc) {
            fprintf(stderr, "Incorrect number of arguments for -X option. Aborting.\n");
            ret = 1; goto view_end;
        }
        fn_idx_in = argv[optind + 1];
        optind++;
    }
    if (!fn_list && ga.reference) {
        static char fai[4096];
        snprintf(fai, sizeof fai, "%s.fai", ga.reference);
        if (access(fai, R_OK) != 0) {
            extern int fai_build(const char *fn);
            fai_build(ga.reference);
        }
        fn_list = fai;
    }
    samfile_t *in = sf_open(fn_in, "r");
    if (!in) {
        fprintf(stderr, "[E::hts_open_format] Failed to open file \"%s\" : %s\n", fn_in, strerror(errno));
        print_error_errno("view", "failed to open \"%s\" for reading", fn_in);
        ret = 1; goto view_end;
    }
    hdr_t *h = NULL;
    samfile_t *out = NULL, *un_out = NULL;
    rec_t *b = NULL;
    if (in->fmt == FMT_CRAM) {
        fprintf(stderr, "[main_samview] fail to read the header from \"%s\".\n", fn_in);
        ret = 1; goto view_close;
    }
    h = sf_read_header(in);
    if (!h) {
        fprintf(stderr, "[main_samview] fail to read the header from \"%s\".\n", fn_in);
        ret = 1; goto view_close;
    }
    if (fn_list && h->n_targets == 0 && in->fmt == FMT_SAM) {
        hdr_add_fai(h, fn_list);
    }
    if (s.rghash && !s.rg_neg && s.no_rg) { /* nothing special */ }
    if (!is_count) {
        char mode[16];
        if (!fn_out) fn_out = "-";
        out_mode(mode, fn_out, &ga, out_format, compress_level);
        add_pg(h, no_pg);
        out = sf_open(fn_out, mode);
        if (!out) {
            print_error_errno("view", "failed to open \"%s\" for writing", fn_out);
            ret = 1; goto view_close;
        }
        if (fn_un_out) {
            un_out = sf_open(fn_un_out, mode);
            if (!un_out) {
                print_error_errno("view", "failed to open \"%s\" for writing", fn_un_out);
                ret = 1; goto view_close;
            }
        }
        if (out->fmt != FMT_SAM || is_header || out->bg->mode == BG_BGZF) {
            if (out->fmt != FMT_SAM || is_header) sf_write_header(out, h);
        }
        if (un_out && (un_out->fmt != FMT_SAM || is_header)) sf_write_header(un_out, h);
    }
    if (is_header_only) goto view_close;

    b = rec_init();
    int nregs = argc - (optind + 1);
    if (nregs <= 0 && !s.multi_region) {
        int r;
        while ((r = sf_read(in, b)) >= 0) {
            if (s.sanitize) sanitize_rec(h, b, s.sanitize);
            int f = process_aln(h, b, &s);
            if (f < 0) {
                fprintf(stderr, "samtools view: error reading file \"%s\"\n", fn_in);
                ret = 1; break;
            }
            if (!f) {
                if (!is_count) {
                    b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags;
                    if (sf_write(out, h, b) < 0) { ret = 1; break; }
                }
                count++;
            } else {
                fail_count++;
                if (s.unmap && out) {
                    b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags;
                    b->core.flag |= FUNMAP;
                    sf_write(out, h, b);
                } else if (un_out) sf_write(un_out, h, b);
            }
        }
        if (r < -1) {
            fprintf(stderr, "samtools view: error reading file \"%s\"\n", fn_in);
            ret = 1;
        }
    } else {
        idx_t *idx = NULL;
        if (in->fmt == FMT_BAM && in->bg->mode == BG_BGZF) idx = idx_load_for(fn_in, fn_idx_in);
        if (!idx) {
            fprintf(stderr, "[E::idx_find_and_load] Could not retrieve index file for '%s'\n", fn_in);
            fprintf(stderr, "samtools view: Random alignment retrieval only works for indexed SAM.gz, BAM or CRAM files.\n");
            ret = 1; goto view_close;
        }
        if (!s.multi_region) {
            for (int i = optind + 1; i < argc; i++) {
                int tid; int64_t beg, end;
                if (parse_region(h, argv[i], &tid, &beg, &end, 0) < 0) {
                    fprintf(stderr, "[main_samview] region \"%s\" specifies an invalid region or unknown reference. Continue anyway.\n", argv[i]);
                    continue;
                }
                iter_t *it;
                if (tid == -3) { bg_seek(in->bg, 0); sf_close(in); in = sf_open(fn_in, "r"); hdr_t *t = sf_read_header(in); hdr_destroy(t); it = idx_query(idx, -3, 0, 0); }
                else it = idx_query(idx, tid, beg, end);
                int r;
                while ((r = iter_next(in, it, b)) >= 0) {
                    if (s.sanitize) sanitize_rec(h, b, s.sanitize);
                    int f = process_aln(h, b, &s);
                    if (f < 0) { fprintf(stderr, "samtools view: error reading file \"%s\"\n", fn_in); ret = 1; break; }
                    if (!f) {
                        if (!is_count) {
                            b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags;
                            sf_write(out, h, b);
                        }
                        count++;
                    } else {
                        fail_count++;
                        if (s.unmap && out) { b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags; b->core.flag |= FUNMAP; sf_write(out, h, b); }
                        else if (un_out) sf_write(un_out, h, b);
                    }
                }
                iter_destroy(it);
                if (r < -1) {
                    fprintf(stderr, "[main_samview] retrieval of region \"%s\" failed due to truncated file or corrupt BAM index file\n", argv[i]);
                    ret = 1; break;
                }
            }
        } else {
            /* multi-region: collect regions */
            int nr = 0, mr = 16;
            vreg_t *regs = xmalloc(mr * sizeof(vreg_t));
            for (int i = optind + 1; i < argc; i++) {
                int tid; int64_t beg, end;
                if (parse_region(h, argv[i], &tid, &beg, &end, 0) < 0) {
                    fprintf(stderr, "[main_samview] region \"%s\" specifies an invalid region or unknown reference. Continue anyway.\n", argv[i]);
                    continue;
                }
                if (tid == -3) { for (int t = 0; t < h->n_targets; t++) { if (nr == mr) { mr *= 2; regs = xrealloc(regs, mr * sizeof(vreg_t)); } regs[nr].tid = t; regs[nr].beg = 0; regs[nr].end = INT64_MAX; nr++; } tid = -1; beg = 0; end = INT64_MAX; }
                if (nr == mr) { mr *= 2; regs = xrealloc(regs, mr * sizeof(vreg_t)); }
                regs[nr].tid = tid; regs[nr].beg = beg; regs[nr].end = end; nr++;
            }
            if (s.bed && nregs <= 0) {
                for (int i = 0; i < s.bed->n; i++) {
                    int tid = hdr_name2tid(h, s.bed->l[i].name);
                    if (tid < 0) continue;
                    for (int j = 0; j < s.bed->l[i].n; j++) {
                        if (nr == mr) { mr *= 2; regs = xrealloc(regs, mr * sizeof(vreg_t)); }
                        regs[nr].tid = tid; regs[nr].beg = s.bed->l[i].a[j].beg; regs[nr].end = s.bed->l[i].a[j].end; nr++;
                    }
                }
            } else if (s.bed && nregs > 0) {
                /* intersect: keep cmdline regions, bed used as filter */
                s.multi_region = 0;
            }
            if (nregs <= 0 && !s.bed) {
                /* whole file */
                for (int t = 0; t < h->n_targets; t++) {
                    if (nr == mr) { mr *= 2; regs = xrealloc(regs, mr * sizeof(vreg_t)); }
                    regs[nr].tid = t; regs[nr].beg = 0; regs[nr].end = INT64_MAX; nr++;
                }
            }
            qsort(regs, nr, sizeof(vreg_t), cmp_vreg);
            /* gather chunks */
            int n_off = 0, m_off = 0; pair64_t *off = NULL;
            for (int i = 0; i < nr; i++) {
                iter_t *it = idx_query(idx, regs[i].tid, regs[i].beg, regs[i].end);
                for (int j = 0; j < it->n_off; j++) {
                    if (n_off == m_off) { m_off = m_off ? m_off * 2 : 16; off = xrealloc(off, m_off * sizeof(pair64_t)); }
                    off[n_off++] = it->off[j];
                }
                iter_destroy(it);
            }
            /* sort & merge */
            for (int i = 1; i < n_off; i++) { pair64_t t = off[i]; int j = i - 1; while (j >= 0 && off[j].u > t.u) { off[j+1] = off[j]; j--; } off[j+1] = t; }
            int l = 0;
            for (int i = 1; i < n_off; i++) {
                if (off[i].u <= off[l].v) { if (off[i].v > off[l].v) off[l].v = off[i].v; }
                else off[++l] = off[i];
            }
            if (n_off) n_off = l + 1;
            /* fetch pairs: collect names of selected reads first */
            strmap_t *pairnames = NULL;
            if (fetch_pairs) {
                pairnames = sm_init();
                for (int ci = 0; ci < n_off; ci++) {
                    if (bg_seek(in->bg, off[ci].u) < 0) break;
                    while (bg_tell(in->bg) < off[ci].v) {
                        if (bam_read_rec(in->bg, b) < 0) break;
                        if (overlaps_regs(regs, nr, b)) {
                            rec_t *tmp = rec_dup(b);
                            if (!process_aln(h, tmp, &s)) sm_put(pairnames, rec_qname(b), 1);
                            rec_destroy(tmp);
                        }
                    }
                }
                /* scan entire file for mates */
                sf_close(in); in = sf_open(fn_in, "r"); { hdr_t *t = sf_read_header(in); hdr_destroy(t); }
                int r;
                while ((r = sf_read(in, b)) >= 0) {
                    if (!sm_has(pairnames, rec_qname(b))) continue;
                    int f = process_aln(h, b, &s);
                    if (!f) {
                        if (!is_count) { b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags; sf_write(out, h, b); }
                        count++;
                    }
                }
                sm_destroy(pairnames);
            } else {
                for (int ci = 0; ci < n_off; ci++) {
                    if (bg_seek(in->bg, off[ci].u) < 0) break;
                    while ((uint64_t)bg_tell(in->bg) < off[ci].v) {
                        int r = bam_read_rec(in->bg, b);
                        if (r < 0) break;
                        if (!overlaps_regs(regs, nr, b)) continue;
                        int f = process_aln(h, b, &s);
                        if (f < 0) { ret = 1; break; }
                        if (!f) {
                            if (!is_count) { b->core.flag = (b->core.flag | s.add_flags) & ~s.remove_flags; sf_write(out, h, b); }
                            count++;
                        } else {
                            fail_count++;
                            if (s.unmap && out) { b->core.flag |= FUNMAP; sf_write(out, h, b); }
                            else if (un_out) sf_write(un_out, h, b);
                        }
                    }
                }
            }
            free(off); free(regs);
        }
        idx_destroy(idx);
    }

view_close:
    if (is_count && ret == 0) printf("%lld\n", (long long)count);
    if (save_counts) {
        FILE *f = fopen(save_counts, "w");
        if (f) { fprintf(f, "%lld\n%lld\n", (long long)count, (long long)fail_count); fclose(f); }
    }
    if (out && sf_close(out) < 0) { if (!ret) { print_error_errno("view", "error closing output file"); ret = 1; } }
    if (un_out) sf_close(un_out);
    if (ga.write_index && out && fn_out && strcmp(fn_out, "-") != 0) write_index_for(fn_out, 1);
    rec_destroy(b);
    hdr_destroy(h);
    sf_close(in);
view_end:
    bed_destroy(s.bed);
    sm_destroy(s.rghash); sm_destroy(s.rnhash); sm_destroy(s.tvhash); sm_destroy(s.rm_tags);
    expr_destroy(s.filter);
    (void)fn_list;
    return ret;
}
