#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>
#include <unistd.h>
#include "fai.h"
#include "bgzf.h"
#include "ks.h"

static void fai_add(fai_t *f, const char *name, int64_t len, int64_t lb, int64_t ll, int64_t off, int64_t qoff, int warn) {
    if (sm_has(f->map, name)) {
        if (warn) fprintf(stderr, "[W::fai_insert_index] Ignoring duplicate sequence \"%s\" at byte offset %lld\n", name, (long long)off);
        return;
    }
    if (f->n == f->m) { f->m = f->m ? f->m * 2 : 16; f->e = xrealloc(f->e, f->m * sizeof(faient_t)); }
    faient_t *e = &f->e[f->n];
    e->name = xstrdup(name); e->len = len; e->line_blen = lb; e->line_len = ll; e->offset = off; e->qual_offset = qoff;
    sm_put(f->map, name, f->n);
    f->n++;
}

static fai_t *fai_new(void) { fai_t *f = xcalloc(1, sizeof(fai_t)); f->map = sm_init(); return f; }

void fai_destroy(fai_t *f) {
    if (!f) return;
    for (int i = 0; i < f->n; i++) free(f->e[i].name);
    free(f->e); sm_destroy(f->map); free(f->fn); free(f->data);
    if (f->fp) fclose(f->fp);
    free(f);
}

/* build core: returns fai or NULL */
static fai_t *fai_build_core(bgzf_t *bg) {
    fai_t *idx = fai_new();
    enum { OUT_READ, IN_NAME, IN_SEQ, SEQ_END, IN_QUAL } state = OUT_READ;
    int format = 0; /* 1 fasta, 2 fastq */
    int read_done = 0, line_num = 1, c;
    int64_t seq_offset = 0, qual_offset = 0, seq_len = 0, qual_len = 0, char_len = 0, cl = 0, line_len = 0, ll = 0;
    kstr name = {0, 0, NULL};
    ks_putsn(&name, "", 0);
    int64_t upos = 0;
#define GETC() (c = bg_getc(bg), (c >= 0 ? upos++ : 0), c)
    while (GETC() >= 0) {
        switch (state) {
        case OUT_READ:
            switch (c) {
            case '>':
                if (format == 2) { fprintf(stderr, "[E::fai_build_core] Found '>' in a FASTQ file, error at line %d\n", line_num); goto fail; }
                format = 1; state = IN_NAME; break;
            case '@':
                if (format == 1) { fprintf(stderr, "[E::fai_build_core] Found '@' in a FASTA file, error at line %d\n", line_num); goto fail; }
                format = 2; state = IN_NAME; break;
            case '\r':
                if (GETC() == '\n') line_num++;
                else { fprintf(stderr, "[E::fai_build_core] Format error, carriage return not followed by new line at line %d\n", line_num); goto fail; }
                break;
            case '\n': line_num++; break;
            default:
                if (isprint(c)) fprintf(stderr, "[E::fai_build_core] Format error, unexpected \"%c\" at line %d\n", c, line_num);
                else fprintf(stderr, "[E::fai_build_core] Format error, unexpected character at line %d\n", line_num);
                goto fail;
            }
            break;
        case IN_NAME:
            if (read_done) {
                fai_add(idx, name.s, seq_len, char_len, line_len, seq_offset, qual_offset, 1);
                read_done = 0;
            }
            name.l = 0; name.s[0] = 0;
            do {
                if (!isspace(c)) ks_putc(&name, c);
                else if (name.l > 0 || c == '\n') break;
            } while (GETC() >= 0);
            if (c < 0) { fprintf(stderr, "[E::fai_build_core] The last entry '%s' has no sequence at line %d\n", name.s, line_num); goto fail; }
            if (c != '\n') while (GETC() >= 0 && c != '\n');
            state = IN_SEQ; seq_len = qual_len = char_len = line_len = 0;
            seq_offset = upos;
            line_num++;
            break;
        case IN_SEQ:
            if (format == 1) {
                if (c == '\n') { state = OUT_READ; line_num++; continue; }
                else if (c == '>') { state = IN_NAME; continue; }
            } else if (format == 2) {
                if (c == '+') {
                    state = IN_QUAL;
                    if (c != '\n') while (GETC() >= 0 && c != '\n');
                    qual_offset = upos;
                    line_num++;
                    continue;
                } else if (c == '\n') {
                    fprintf(stderr, "[E::fai_build_core] Inlined empty line is not allowed in sequence '%s' at line %d\n", name.s, line_num);
                    goto fail;
                }
            }
            ll = cl = 0;
            if (format == 1) read_done = 1;
            do {
                ll++;
                if (isgraph(c)) cl++;
            } while (GETC() >= 0 && c != '\n');
            ll++; seq_len += cl;
            if (line_len == 0) { line_len = ll; char_len = cl; }
            else if (line_len < ll || char_len < cl) {
                fprintf(stderr, "[E::fai_build_core] Different line length in sequence '%s' at line %d\n", name.s, line_num);
                goto fail;
            } else if (line_len > ll || char_len > cl) {
                if (format == 1) state = OUT_READ;
                else state = SEQ_END;
            }
            line_num++;
            break;
        case SEQ_END:
            if (c == '+') {
                state = IN_QUAL;
                while (GETC() >= 0 && c != '\n');
                qual_offset = upos;
                line_num++;
            } else {
                fprintf(stderr, "[E::fai_build_core] Format error, expecting '+', got '%c' at line %d\n", c, line_num);
                goto fail;
            }
            break;
        case IN_QUAL:
            if (c == '\n') {
                if (!read_done) { fprintf(stderr, "[E::fai_build_core] Inlined empty line is not allowed in quality of sequence '%s'\n", name.s); goto fail; }
                state = OUT_READ; line_num++; continue;
            } else if (c == '@' && read_done) { state = IN_NAME; continue; }
            ll = cl = 0;
            do { ll++; if (isgraph(c)) cl++; } while (GETC() >= 0 && c != '\n');
            ll++; qual_len += cl;
            if (line_len < ll) { fprintf(stderr, "[E::fai_build_core] Quality line length too long in '%s' at line %d\n", name.s, line_num); goto fail; }
            else if (qual_len == seq_len) { read_done = 1; }
            else if (qual_len > seq_len) { fprintf(stderr, "[E::fai_build_core] Quality length longer than sequence in '%s' at line %d\n", name.s, line_num); goto fail; }
            line_num++;
            break;
        }
    }
    if (read_done) {
        fai_add(idx, name.s, seq_len, char_len, line_len, seq_offset, qual_offset, 1);
    } else if (state != OUT_READ || format == 0) {
        if (!(state == OUT_READ)) { fprintf(stderr, "[E::fai_build_core] File truncated at line %d\n", line_num); goto fail; }
    }
    idx->is_fastq = format == 2;
    ks_free(&name);
    return idx;
fail:
    ks_free(&name);
    fai_destroy(idx);
    return NULL;
#undef GETC
}

static int write_fai(const fai_t *f, const char *fn) {
    FILE *o = fopen(fn, "w");
    if (!o) return -1;
    for (int i = 0; i < f->n; i++) {
        faient_t *e = &f->e[i];
        if (f->is_fastq)
            fprintf(o, "%s\t%lld\t%lld\t%lld\t%lld\t%lld\n", e->name, (long long)e->len, (long long)e->offset, (long long)e->line_blen, (long long)e->line_len, (long long)e->qual_offset);
        else
            fprintf(o, "%s\t%lld\t%lld\t%lld\t%lld\n", e->name, (long long)e->len, (long long)e->offset, (long long)e->line_blen, (long long)e->line_len);
    }
    return fclose(o);
}

static int write_gzi(const char *fn, const char *gzi) {
    FILE *f = fopen(fn, "rb");
    if (!f) return -1;
    uint64_t caddr = 0, uaddr = 0;
    uint64_t *ent = NULL; size_t n = 0, m = 0;
    uint8_t h[18];
    int first = 1;
    while (fread(h, 1, 18, f) == 18) {
        int bsize = (h[16] | (h[17] << 8)) + 1;
        if (fseek(f, bsize - 18 - 4, SEEK_CUR) < 0) break;
        uint8_t is[4];
        if (fread(is, 1, 4, f) != 4) break;
        uint32_t isize = is[0] | (is[1] << 8) | (is[2] << 16) | ((uint32_t)is[3] << 24);
        if (isize > 0) {
            if (!first) {
                if (n + 2 > m) { m = m ? m * 2 : 32; ent = xrealloc(ent, m * sizeof(uint64_t)); }
                ent[n++] = caddr; ent[n++] = uaddr;
            }
            first = 0;
        }
        caddr += bsize; uaddr += isize;
    }
    fclose(f);
    FILE *o = fopen(gzi, "wb");
    if (!o) { free(ent); return -1; }
    uint64_t cnt = n / 2;
    fwrite(&cnt, 8, 1, o);
    if (n) fwrite(ent, 8, n, o);
    free(ent);
    return fclose(o);
}

int fai_build2(const char *fn, const char *fnfai, const char *fngzi, int quiet) {
    (void)quiet;
    bgzf_t *bg = bg_open_read(fn);
    if (!bg) {
        fprintf(stderr, "[E::fai_build3_core] Failed to open the file %s : %s\n", fn, strerror(errno));
        return -1;
    }
    int mode = bg->mode;
    fai_t *f = NULL;
    if (mode == BG_GZIP) {
        /* htslib attempts and fails */
        fprintf(stderr, "[E::fai_build_core] File truncated at line 1\n");
        fprintf(stderr, "[E::fai_build3_core] Cannot index files compressed with gzip, please use bgzip\n");
        bg_close(bg);
        return -1;
    }
    f = fai_build_core(bg);
    bg_close(bg);
    if (!f) return -1;
    char *fai = fnfai ? xstrdup(fnfai) : NULL;
    if (!fai) { fai = xmalloc(strlen(fn) + 5); sprintf(fai, "%s.fai", fn); }
    if (write_fai(f, fai) < 0) {
        fprintf(stderr, "[E::fai_build3_core] Failed to open the FASTA index %s : %s\n", fai, strerror(errno));
        free(fai); fai_destroy(f); return -1;
    }
    free(fai);
    if (mode == BG_BGZF) {
        char *gzi = fngzi ? xstrdup(fngzi) : NULL;
        if (!gzi) { gzi = xmalloc(strlen(fn) + 5); sprintf(gzi, "%s.gzi", fn); }
        write_gzi(fn, gzi);
        free(gzi);
    }
    fai_destroy(f);
    return 0;
}

int fai_build(const char *fn) { return fai_build2(fn, NULL, NULL, 0); }

static fai_t *fai_read_index(const char *fnfai) {
    FILE *f = fopen(fnfai, "r");
    if (!f) return NULL;
    fai_t *idx = fai_new();
    char *line = NULL; size_t cap = 0; ssize_t n;
    while ((n = getline(&line, &cap, f)) >= 0) {
        while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r')) line[--n] = 0;
        if (n == 0) continue;
        char *tab = strchr(line, '\t');
        if (!tab) continue;
        *tab = 0;
        long long len, off, lb, ll, qo = 0;
        int k = sscanf(tab + 1, "%lld%lld%lld%lld%lld", &len, &off, &lb, &ll, &qo);
        if (k < 4) continue;
        if (k == 5) idx->is_fastq = 1;
        fai_add(idx, line, len, lb, ll, off, qo, 0);
    }
    free(line); fclose(f);
    return idx;
}

fai_t *fai_load3(const char *fn, const char *fnfai, const char *fngzi, int build) {
    char *fai = fnfai ? xstrdup(fnfai) : NULL;
    if (!fai) { fai = xmalloc(strlen(fn) + 5); sprintf(fai, "%s.fai", fn); }
    fai_t *idx = NULL;
    if (access(fai, R_OK) != 0 && build) {
        if (fai_build2(fn, fai, fngzi, 0) < 0) { free(fai); return NULL; }
    }
    idx = fai_read_index(fai);
    if (!idx) {
        fprintf(stderr, "[E::fai_load3_core] Failed to open FASTA index %s: %s\n", fai, strerror(errno));
        free(fai); return NULL;
    }
    free(fai);
    idx->fn = xstrdup(fn);
    int r = bg_is_bgzf_file(fn);
    if (r == 1) {
        idx->is_bgzf = 1;
        bgzf_t *bg = bg_open_read(fn);
        if (!bg) { fai_destroy(idx); return NULL; }
        kstr d = {0, 0, NULL};
        uint8_t buf[65536]; int64_t k;
        while ((k = bg_read(bg, buf, sizeof buf)) > 0) ks_putsn(&d, (char*)buf, k);
        bg_close(bg);
        idx->data = d.s ? d.s : xstrdup(""); idx->data_len = d.l;
    } else {
        idx->fp = fopen(fn, "rb");
        if (!idx->fp) { fprintf(stderr, "[E::fai_load3_core] Failed to open FASTA file %s\n", fn); fai_destroy(idx); return NULL; }
    }
    return idx;
}

fai_t *fai_load(const char *fn) { return fai_load3(fn, NULL, NULL, 1); }

int fai_tid(const fai_t *fai, const char *name) {
    int64_t v;
    if (sm_get(fai->map, name, &v)) return (int)v;
    return -1;
}

static char *fetch_core(fai_t *fai, int64_t offset, int64_t lb, int64_t ll, int64_t beg, int64_t end, int64_t *len) {
    int64_t n = end - beg;
    if (n <= 0) { *len = 0; return xstrdup(""); }
    char *s = xmalloc(n + 1);
    int64_t pos = offset + beg / lb * ll + beg % lb;
    int64_t l = 0;
    if (fai->data) {
        int64_t p = pos;
        while (l < n && p < fai->data_len) {
            char c = fai->data[p++];
            if (isgraph((unsigned char)c)) s[l++] = c;
            else if (c == '>' || c == '@') break;
        }
    } else {
        if (fseeko(fai->fp, pos, SEEK_SET) < 0) { free(s); *len = -1; return NULL; }
        int c;
        while (l < n && (c = getc(fai->fp)) != EOF) {
            if (isgraph(c)) s[l++] = c;
        }
    }
    s[l] = 0;
    *len = l;
    return s;
}

char *fai_fetch_seq(fai_t *fai, int id, int64_t beg, int64_t end, int64_t *len) {
    faient_t *e = &fai->e[id];
    if (end > e->len) end = e->len;
    if (beg < 0) beg = 0;
    if (beg >= end) { *len = 0; return xstrdup(""); }
    return fetch_core(fai, e->offset, e->line_blen, e->line_len, beg, end, len);
}

char *fai_fetch_qual(fai_t *fai, int id, int64_t beg, int64_t end, int64_t *len) {
    faient_t *e = &fai->e[id];
    if (end > e->len) end = e->len;
    if (beg < 0) beg = 0;
    if (beg >= end) { *len = 0; return xstrdup(""); }
    return fetch_core(fai, e->qual_offset, e->line_blen, e->line_len, beg, end, len);
}

extern int64_t parse_decimal(const char *str, char **end, int flags);

/* parse region against fai names. returns 0 ok, -1 not found */
int fai_parse_reg(const fai_t *fai, const char *s, int *id, int64_t *beg, int64_t *end) {
    size_t s_len = strlen(s);
    const char *colon = NULL;
    int quoted = 0;
    char *buf = xmalloc(s_len + 1);
    if (*s == '{') {
        const char *close = memchr(s, '}', s_len);
        if (!close) { free(buf); return -1; }
        s++; s_len--;
        if (close[1] == ':') colon = close + 1;
        quoted = 1;
    }
    if (!colon) for (size_t i = s_len; i > 0; i--) if (s[i-1] == ':') { colon = s + i - 1; break; }
    *beg = 0; *end = INT64_MAX;
    if (!colon) {
        memcpy(buf, s, s_len - quoted); buf[s_len - quoted] = 0;
        *id = fai_tid(fai, buf); free(buf);
        return *id >= 0 ? 0 : -1;
    }
    if (!quoted) {
        memcpy(buf, s, s_len); buf[s_len] = 0;
        if ((*id = fai_tid(fai, buf)) >= 0) {
            memcpy(buf, s, colon - s); buf[colon - s] = 0;
            if (fai_tid(fai, buf) >= 0) {
                fprintf(stderr, "[E::fai_get_val] Range is ambiguous. Use {%s} or {%.*s}%s instead\n", s, (int)(colon - s), s, colon);
                free(buf); *id = -1; return -1;
            }
            free(buf); return 0;
        }
    }
    memcpy(buf, s, colon - s - quoted); buf[colon - s - quoted] = 0;
    *id = fai_tid(fai, buf);
    free(buf);
    if (*id < 0) return -1;
    char *hyphen;
    *beg = parse_decimal(colon + 1, &hyphen, 0) - 1;
    if (*beg < 0) {
        if (isdigit((unsigned char)*hyphen) || *hyphen == '\0' || *hyphen == ',') {
            *end = *beg == -1 ? INT64_MAX : -(*beg + 1);
            *beg = 0;
            return 0;
        } else if (*beg < -1) { *id = -1; return -1; }
    }
    if (*hyphen == '\0') *end = INT64_MAX;
    else if (*hyphen == '-') {
        *end = parse_decimal(hyphen + 1, &hyphen, 0);
        if (*hyphen != '\0' && *hyphen != ',') { *id = -1; return -1; }
    } else { *id = -1; return -1; }
    if (*end == 0) *end = INT64_MAX;
    if (*beg >= *end) { *id = -1; return -1; }
    return 0;
}

char *fai_fetch_reg(fai_t *fai, const char *reg, int64_t *len, int qual) {
    int id; int64_t beg, end;
    if (fai_parse_reg(fai, reg, &id, &beg, &end) < 0) {
        fprintf(stderr, "[W::fai_get_val] Reference %s not found in %s file, returning empty sequence\n", reg, fai->is_fastq ? "FASTQ" : "FASTA");
        *len = -2;
        return NULL;
    }
    return qual ? fai_fetch_qual(fai, id, beg, end, len) : fai_fetch_seq(fai, id, beg, end, len);
}
