{"command":"cd /workspace/src && cat > cmd_faidx.c <<'EOF'
/* samtools faidx / fqidx */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <getopt.h>
#include "fai.h"
#include "usage.h"
#include "ks.h"
#include "bgzf.h"

static void revcomp(char *s, int64_t n) {
    static char comp[256];
    static int init = 0;
    if (!init) {
        for (int i = 0; i < 256; i++) comp[i] = i;
        const char *a = "ACGTUMRWSYKVHDBNacgtumrwsykvhdbn", *b = "TGCAAKYWSRMBDHVNtgcaakywsrmbdhvn";
        for (int i = 0; a[i]; i++) comp[(uint8_t)a[i]] = b[i];
        init = 1;
    }
    for (int64_t i = 0, j = n - 1; i <= j; i++, j--) {
        char x = s[i], y = s[j];
        s[i] = comp[(uint8_t)y]; s[j] = comp[(uint8_t)x];
    }
}
static void reverse(char *s, int64_t n) {
    for (int64_t i = 0, j = n - 1; i < j; i++, j--) { char t = s[i]; s[i] = s[j]; s[j] = t; }
}

static int write_line(bgzf_t *out, const char *seq, int64_t len, int64_t wrap) {
    if (wrap <= 0) wrap = len > 0 ? len : 1;
    for (int64_t i = 0; i < len; i += wrap) {
        int64_t n = len - i < wrap ? len - i : wrap;
        bg_write(out, seq + i, n);
        bg_write(out, "\n", 1);
    }
    return 0;
}

static int parse_reg_simple(const char *s, int64_t *beg, int64_t *end) {
    /* returns 1 if region has coordinates */
    const char *c = strrchr(s, ':');
    if (!c) return 0;
    extern int64_t parse_decimal(const char *str, char **end, int flags);
    char *h;
    int64_t b = parse_decimal(c + 1, &h, 0);
    if (h == c + 1) return 0;
    *beg = b - 1;
    if (*h == '-') { *end = parse_decimal(h + 1, &h, 0); if (*end == 0) *end = INT64_MAX; }
    else *end = INT64_MAX;
    return 1;
}

static int write_output(fai_t *fai, bgzf_t *out, const char *name, int ignore, int64_t line_len_opt,
                        int rev, const char *pos_s, const char *neg_s, int fastq) {
    int64_t len;
    char *seq = fai_fetch_reg(fai, name, &len, 0);
    kstr h = {0, 0, NULL};
    ks_putc(&h, fastq ? '@' : '>'); ks_puts(&h, name); ks_puts(&h, rev ? neg_s : pos_s); ks_putc(&h, '\n');
    bg_write(out, h.s, h.l);
    ks_free(&h);
    if (len < 0) {
        /* second lookup, as for line length */
        fprintf(stderr, "[W::fai_get_val] Reference %s not found in %s file, returning empty sequence\n", name, fai->is_fastq ? "FASTQ" : "FASTA");
        bg_flush(out);
        fprintf(stderr, "[faidx] Failed to fetch sequence in %s\n", name);
        free(seq);
        if (ignore && len == -2) return 0;
        return 1;
    }
    int64_t beg, end;
    if (len == 0) fprintf(stderr, "[faidx] Zero length sequence: %s\n", name);
    else if (parse_reg_simple(name, &beg, &end) && end < INT32_MAX && len != end - beg)
        fprintf(stderr, "[faidx] Truncated sequence: %s\n", name);
    int64_t wrap = line_len_opt;
    if (wrap < 0) {
        int id; int64_t b2, e2;
        if (fai_parse_reg(fai, name, &id, &b2, &e2) == 0) wrap = fai->e[id].line_blen; else wrap = 60;
    }
    if (rev) revcomp(seq, len);
    write_line(out, seq, len, wrap);
    free(seq);
    if (fastq) {
        bg_write(out, "+\n", 2);
        int64_t ql;
        char *q = fai_fetch_reg(fai, name, &ql, 1);
        if (q) {
            if (rev) reverse(q, ql);
            write_line(out, q, ql, wrap);
            free(q);
        }
    }
    return 0;
}

static int faidx_core(int argc, char *argv[], int is_fqidx) {
    int c, ignore = 0, rev = 0, fastq = is_fqidx;
    int64_t line_len = -1;
    char *out_fn = NULL, *region_file = NULL, *fai_fn = NULL, *gzi_fn = NULL;
    const char *pos_s = "", *neg_s = "/rc";
    char *custom = NULL;
    const char *usage = is_fqidx ? usage_fqidx : usage_faidx;
    static const struct option lopts[] = {
        {"output", required_argument, NULL, 'o'},
        {"help", no_argument, NULL, 'h'},
        {"length", required_argument, NULL, 'n'},
        {"continue", no_argument, NULL, 'c'},
        {"region-file", required_argument, NULL, 'r'},
        {"fastq", no_argument, NULL, 'f'},
        {"reverse-complement", no_argument, NULL, 'i'},
        {"mark-strand", required_argument, NULL, 1000},
        {"fai-idx", required_argument, NULL, 1001},
        {"gzi-idx", required_argument, NULL, 1002},
        {"output-fmt-option", required_argument, NULL, 1003},
        {"threads", required_argument, NULL, '@'},
        {"write-index", no_argument, NULL, 1004},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, is_fqidx ? "ho:n:cr:i@:" : "ho:n:cr:fi@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'o': out_fn = optarg; break;
        case 'n': {
            long v = strtol(optarg, NULL, 10);
            if (v < 0) { fprintf(stderr, "[faidx] bad line length '%s', using default:60\n", optarg); v = 60; }
            line_len = v; break;
        }
        case 'c': ignore = 1; break;
        case 'r': region_file = optarg; break;
        case 'f': fastq = 1; break;
        case 'i': rev = 1; break;
        case 1000:
            if (strcmp(optarg, "on") == 0 || strcmp(optarg, "rc") == 0) { pos_s = ""; neg_s = "/rc"; }
            else if (strcmp(optarg, "no") == 0 || strcmp(optarg, "off") == 0) { pos_s = ""; neg_s = ""; }
            else if (strcmp(optarg, "sign") == 0) { pos_s = "(+)"; neg_s = "(-)"; }
            else if (strncmp(optarg, "custom,", 7) == 0) {
                free(custom); custom = xstrdup(optarg + 7);
                char *comma = strchr(custom, ',');
                if (comma) { *comma = 0; neg_s = comma + 1; } else neg_s = "";
                pos_s = custom;
            } else {
                fprintf(stderr, "[faidx] Unknown --mark-strand option \"%s\"\n", optarg);
                fputs(usage, stderr);
                free(custom);
                return 1;
            }
            break;
        case 1001: fai_fn = optarg; break;
        case 1002: gzi_fn = optarg; break;
        case 1003: case '@': case 1004: break;
        case 'h': fputs(usage, stdout); free(custom); return 0;
        default: fputs(usage, stderr); free(custom); return 1;
        }
    }
    if (argc == optind) { fputs(usage, stdout); free(custom); return 0; }
    const char *fn = argv[optind];
    if (optind + 1 == argc && !region_file) {
        if (fai_build2(fn, fai_fn, gzi_fn, 0) != 0) {
            char *t = fai_fn ? xstrdup(fai_fn) : NULL;
            if (!t) { t = xmalloc(strlen(fn) + 5); sprintf(t, "%s.fai", fn); }
            fprintf(stderr, "[faidx] Could not build fai index %s\n", t);
            free(t); free(custom);
            return 1;
        }
        free(custom);
        return 0;
    }
    fai_t *fai = fai_load3(fn, fai_fn, gzi_fn, 1);
    if (!fai) {
        char *t = fai_fn ? xstrdup(fai_fn) : NULL;
        if (!t) { t = xmalloc(strlen(fn) + 5); sprintf(t, "%s.fai", fn); }
        fprintf(stderr, "[faidx] Could not load fai index %s\n", t);
        free(t); free(custom);
        return 1;
    }
    if (fastq && !fai->is_fastq) {
        /* treat as fasta-only index */
    }
    bgzf_t *out = NULL;
    if (out_fn) {
        out = bg_open_write(out_fn, BG_RAW, 0);
        if (!out) {
            fprintf(stderr, "[faidx] Cannot open \"%s\" for writing :%s.\n", out_fn, strerror(errno));
            fai_destroy(fai); free(custom);
            return 1;
        }
    } else out = bg_open_write("-", BG_RAW, 0);
    int ret = 0;
    if (region_file) {
        bgzf_t *rf = bg_open_read(region_file);
        if (!rf) {
            fprintf(stderr, "[faidx] Failed to open \"%s\" for reading.\n", region_file);
            ret = 1;
        } else {
            kstr line = {0, 0, NULL};
            while (bg_getline(rf, &line) >= 0) {
                if (write_output(fai, out, line.s, ignore, line_len, rev, pos_s, neg_s, fastq)) { ret = 1; break; }
            }
            ks_free(&line);
            bg_close(rf);
        }
    }
    if (!ret) {
        for (int i = optind + 1; i < argc; i++) {
            if (write_output(fai, out, argv[i], ignore, line_len, rev, pos_s, neg_s, fastq)) { ret = 1; break; }
        }
    }
    if (bg_close(out) < 0 && !ret) {
        fprintf(stderr, "[faidx] Error closing output\n");
        ret = 1;
    }
    fai_destroy(fai);
    free(custom);
    return ret;
}

int main_faidx(int argc, char *argv[]) { return faidx_core(argc, argv, 0); }
int main_fqidx(int argc, char *argv[]) { return faidx_core(argc, argv, 1); }
EOF"}

