            fai_destroy(fai); free(custom);
            return 1;
        }
    } else out = bg_open_write("-", BG_RAW, 0);
    int ret = 0;
    if (region_file) {
        bgzf_t *rf = bg_open_read(region_file);
        if (!rf) {
            fprintf(stderr, "[faidx] Failed to open \"%s\" for reading.\n", region_file);
            ret = 1;
        } else {
            kstr line = {0, 0, NULL};
            while (bg_getline(rf, &line) >= 0) {
                if (write_output(fai, out, line.s, ignore, line_len, rev, pos_s, neg_s, fastq)) { ret = 1; break; }
            }
            ks_free(&line);
            bg_close(rf);
        }
    }
    if (!ret) {
        for (int i = optind + 1; i < argc; i++) {
            if (write_output(fai, out, argv[i], ignore, line_len, rev, pos_s, neg_s, fastq)) { ret = 1; break; }
        }
    }
    if (bg_close(out) < 0 && !ret) {
        fprintf(stderr, "[faidx] Error closing output\n");
        ret = 1;
    }
    fai_destroy(fai);
    free(custom);
    return ret;
}

int main_faidx(int argc, char *argv[]) { return faidx_core(argc, argv, 0); }
int main_fqidx(int argc, char *argv[]) { return faidx_core(argc, argv, 1); }
