/* samtools index, idxstats, flagstat */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include "common.h"

static int is_index_name(const char *s) {
    size_t l = strlen(s);
    const char *ex[] = { ".bai", ".csi", ".crai", NULL };
    for (int i = 0; ex[i]; i++) { size_t el = strlen(ex[i]); if (l >= el && strcmp(s + l - el, ex[i]) == 0) return 1; }
    return 0;
}

int main_index(int argc, char *argv[]) {
    int csi = 0, min_shift = 14, multiple = 0, c;
    const char *fn_idx = NULL;
    static const struct option lopts[] = {
        {"bai", no_argument, NULL, 'b'}, {"csi", no_argument, NULL, 'c'},
        {"min-shift", required_argument, NULL, 'm'}, {"output", required_argument, NULL, 'o'},
        {"output-file", required_argument, NULL, 'o'},
        {"threads", required_argument, NULL, '@'}, {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "bcm:Mo:@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'b': csi = 0; break;
        case 'c': csi = 1; break;
        case 'm': csi = 1; min_shift = atoi(optarg); break;
        case 'M': multiple = 1; break;
        case 'o': fn_idx = optarg; break;
        case '@': break;
        default: fputs(usage_index, stderr); return 1;
        }
    }
    int n_files = argc - optind;
    if (n_files == 0) { fputs(usage_index, stdout); return 0; }
    if (n_files == 2 && !multiple && !fn_idx) {
        if (is_index_name(argv[optind + 1]) || 1) { fn_idx = argv[optind + 1]; n_files = 1; }
    }
    if (n_files > 1 && fn_idx) {
        print_error("index", "can't use -o with multiple input alignment files");
        return 1;
    }
    for (int i = optind; i < optind + n_files; i++) {
        errno = 0;
        int ret = bam_index_build(argv[i], fn_idx, csi ? min_shift : 0);
        if (ret < 0) {
            if (ret == -2) print_error_errno("index", "failed to open \"%s\"", argv[i]);
            else if (ret == -3) print_error("index", "\"%s\" is in a format that cannot be usefully indexed", argv[i]);
            else if (ret == -5 && fn_idx) print_error("index", "failed to create or write index \"%s\"", fn_idx);
            else if (ret == -5) print_error("index", "failed to create or write index");
            else { errno = 0; print_error_errno("index", "failed to create index for \"%s\"", argv[i]); }
            return 1;
        }
    }
    return 0;
}

int main_idxstats(int argc, char *argv[]) {
    int c, has_idx_file = 0;
    static const struct option lopts[] = {
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"threads", required_argument, NULL, '@'},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "@:X", lopts, NULL)) >= 0) {
        switch (c) {
        case 'X': has_idx_file = 1; break;
        case '@': case GO_INPUT_FMT_OPTION: case GO_VERBOSITY: break;
        default: fputs(usage_idxstats, stderr); return 1;
        }
    }
    if (argc == optind) { fputs(usage_idxstats, stdout); return 0; }
    const char *fn = argv[optind];
    const char *fnidx = has_idx_file && optind + 1 < argc ? argv[optind + 1] : NULL;
    samfile_t *fp = sf_open(fn, "r");
    if (!fp) { print_error_errno("idxstats", "failed to open \"%s\"", fn); return 1; }
    hdr_t *h = sf_read_header(fp);
    if (!h) { print_error("idxstats", "failed to read header for \"%s\"", fn); sf_close(fp); return 1; }
    idx_t *idx = NULL;
    if (fp->fmt == FMT_BAM && fp->bg->mode == BG_BGZF) idx = idx_load_for(fn, fnidx);
    if (idx) {
        for (int i = 0; i < h->n_targets; i++) {
            uint64_t m, u;
            idx_get_stat(idx, i, &m, &u);
            printf("%s\t%lld\t%llu\t%llu\n", h->tname[i], (long long)h->tlen[i], (unsigned long long)m, (unsigned long long)u);
        }
        printf("*\t0\t0\t%llu\n", (unsigned long long)idx->n_no_coor);
        idx_destroy(idx);
    } else {
        uint64_t *cnt = xcalloc(2 * (h->n_targets + 1), sizeof(uint64_t));
        rec_t *b = rec_init();
        int r;
        while ((r = sf_read(fp, b)) >= 0) {
            int t = b->core.tid;
            if (t < -1 || t >= h->n_targets) continue;
            int k = t + 1;
            if (b->core.flag & FUNMAP) cnt[2*k+1]++; else cnt[2*k]++;
        }
        if (r < -1) {
            print_error("idxstats", "failed to process \"%s\"", fn);
            rec_destroy(b); free(cnt); hdr_destroy(h); sf_close(fp);
            return 1;
        }
        for (int i = 0; i < h->n_targets; i++)
            printf("%s\t%lld\t%llu\t%llu\n", h->tname[i], (long long)h->tlen[i], (unsigned long long)cnt[2*(i+1)], (unsigned long long)cnt[2*(i+1)+1]);
        printf("*\t0\t%llu\t%llu\n", (unsigned long long)cnt[0], (unsigned long long)cnt[1]);
        rec_destroy(b); free(cnt);
    }
    hdr_destroy(h);
    sf_close(fp);
    return 0;
}

