{"command":"cd /workspace/src && cat > cmd_sort.c <<'EOF'
/* samtools sort */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include "common.h"

enum { ORD_COORD = 0, ORD_NAME, ORD_TAG, ORD_TEMPLATE };

int strnum_cmp(const char *_a, const char *_b) {
    const unsigned char *pa = (const unsigned char*)_a, *pb = (const unsigned char*)_b;
    while (*pa && *pb) {
        if (!isdigit(*pa) || !isdigit(*pb)) {
            if (*pa != *pb) return (int)*pa - (int)*pb;
            ++pa; ++pb;
        } else {
            while (*pa == '0') ++pa;
            while (*pb == '0') ++pb;
            while (isdigit(*pa) && *pa == *pb) ++pa, ++pb;
            int diff = (int)*pa - (int)*pb;
            while (isdigit(*pa) && isdigit(*pb)) ++pa, ++pb;
            if (isdigit(*pa)) return 1;
            else if (isdigit(*pb)) return -1;
            else if (diff) return diff;
        }
    }
    if (*pa || *pb) return *pa ? 1 : -1;
    return 0;
}

typedef struct {
    rec_t *b;
    uint8_t *tag;
    uint64_t idx;
} srec_t;

static int g_order, g_natural, g_by_tag;
static char g_tag[3];

static int cmp_coord(const rec_t *a, const rec_t *b) {
    uint64_t pa = ((uint64_t)(uint32_t)a->core.tid << 32) | ((uint64_t)(a->core.pos + 1) << 1) | ((a->core.flag & FREVERSE) ? 1 : 0);
    uint64_t pb = ((uint64_t)(uint32_t)b->core.tid << 32) | ((uint64_t)(b->core.pos + 1) << 1) | ((b->core.flag & FREVERSE) ? 1 : 0);
    return pa < pb ? -1 : (pa > pb ? 1 : 0);
}

static int cmp_name(const rec_t *a, const rec_t *b) {
    int t = g_natural ? strnum_cmp(rec_qname(a), rec_qname(b)) : strcmp(rec_qname(a), rec_qname(b));
    if (t != 0) return t;
    t = (int)(a->core.flag & 0xc0) - (int)(b->core.flag & 0xc0);
    return t;
}

static int cmp_tagv(const uint8_t *ta, const uint8_t *tb) {
    if (!ta || !tb) return ta ? 1 : (tb ? -1 : 0);
    int sa = (ta[0] == 'Z' || ta[0] == 'H'), sb = (tb[0] == 'Z' || tb[0] == 'H');
    if (sa && sb) return strcmp((char*)ta + 1, (char*)tb + 1);
    if (sa) return 1;
    if (sb) return -1;
    if (ta[0] == 'A' && tb[0] == 'A') return (int)ta[1] - (int)tb[1];
    double va = (ta[0] == 'f' || ta[0] == 'd') ? aux2f(ta) : (double)aux2i(ta);
    double vb = (tb[0] == 'f' || tb[0] == 'd') ? aux2f(tb) : (double)aux2i(tb);
    if (ta[0] == 'A') va = ta[1];
    if (tb[0] == 'A') vb = tb[1];
    return va < vb ? -1 : (va > vb ? 1 : 0);
}

static int cmp_srec(const srec_t *a, const srec_t *b) {
    int t;
    if (g_by_tag) {
        t = cmp_tagv(a->tag, b->tag);
        if (t) return t;
    }
    if (g_order == ORD_NAME) return cmp_name(a->b, b->b);
    return cmp_coord(a->b, b->b);
}

static void merge_sort(srec_t *a, srec_t *tmp, size_t n) {
    if (n < 2) return;
    if (n < 16) {
        for (size_t i = 1; i < n; i++) {
            srec_t t = a[i]; size_t j = i;
            while (j > 0 && cmp_srec(&a[j-1], &t) > 0) { a[j] = a[j-1]; j--; }
            a[j] = t;
        }
        return;
    }
    size_t m = n / 2;
    merge_sort(a, tmp, m);
    merge_sort(a + m, tmp, n - m);
    size_t i = 0, j = m, k = 0;
    while (i < m && j < n) {
