seqreader_t *sr_open(const char *fn) {
    bgzf_t *bg = bg_open_read(fn);
    if (!bg) return NULL;
    seqreader_t *r = xcalloc(1, sizeof(seqreader_t));
    r->bg = bg;
    return r;
}
void sr_close(seqreader_t *r) {
    if (!r) return;
    bg_close(r->bg);
    ks_free(&r->name); ks_free(&r->comment); ks_free(&r->seq); ks_free(&r->qual);
    free(r);
}

int sr_read(seqreader_t *r) {
    int c;
    ks_clear(&r->name); ks_clear(&r->comment); ks_clear(&r->seq); ks_clear(&r->qual);
    ks_putsn(&r->name, "", 0); ks_putsn(&r->comment, "", 0); ks_putsn(&r->seq, "", 0); ks_putsn(&r->qual, "", 0);
    if (r->last_char == 0) {
        while ((c = bg_getc(r->bg)) >= 0 && c != '>' && c != '@');
        if (c < 0) return -1;
        r->last_char = c;
    }
    if (r->last_char < 0) return -1;
    r->is_fastq = (r->last_char == '@');
    /* name */
    while ((c = bg_getc(r->bg)) >= 0 && !isspace(c)) ks_putc(&r->name, c);
    if (c >= 0 && c != '\n') {
        while (c == ' ' || c == '\t') c = bg_getc(r->bg);
        if (c >= 0 && c != '\n') {
            ks_putc(&r->comment, c);
            while ((c = bg_getc(r->bg)) >= 0 && c != '\n') ks_putc(&r->comment, c);
        }
        if (r->comment.l && r->comment.s[r->comment.l-1] == '\r') r->comment.s[--r->comment.l] = 0;
    }
    if (c < 0) { r->last_char = -1; return 0; }
    /* sequence */
    while ((c = bg_getc(r->bg)) >= 0 && c != '>' && c != '+' && c != '@') {
        if (c == '\n') continue;
        ks_putc(&r->seq, c);
        while ((c = bg_getc(r->bg)) >= 0 && c != '\n') ks_putc(&r->seq, c);
        if (r->seq.l && r->seq.s[r->seq.l-1] == '\r') r->seq.s[--r->seq.l] = 0;
        if (c < 0) break;
    }
    if (c == '>' || c == '@') r->last_char = c;
    else if (c < 0) r->last_char = -1;
    if (c != '+') return (int)r->seq.l;
    /* fastq quality */
    r->is_fastq = 1;
    while ((c = bg_getc(r->bg)) >= 0 && c != '\n');
    if (c < 0) { r->last_char = -1; return -2; }
    while (r->qual.l < r->seq.l) {
        c = bg_getc(r->bg);
        if (c < 0) break;
        if (c == '\n' || c == '\r') continue;
        ks_putc(&r->qual, c);
    }
    /* skip to next record start */
    r->last_char = 0;
    if (r->qual.l != r->seq.l) { r->last_char = -1; return -2; }
    return (int)r->seq.l;
