/* samtools dict */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>
#include <getopt.h>
#include "seqio.h"
#include "md5.h"
#include "usage.h"
#include "util.h"

int main_dict(int argc, char *argv[]) {
    static const struct option lopts[] = {
        {"assembly", required_argument, NULL, 'a'}, {"alias", no_argument, NULL, 'A'},
        {"alternative-name", no_argument, NULL, 'A'}, {"no-header", no_argument, NULL, 'H'},
        {"alt", required_argument, NULL, 'l'}, {"output", required_argument, NULL, 'o'},
        {"species", required_argument, NULL, 's'}, {"uri", required_argument, NULL, 'u'},
        {"help", no_argument, NULL, 'h'}, {NULL, 0, NULL, 0}
    };
    char *assembly = NULL, *species = NULL, *uri = NULL, *out_fn = NULL, *alt_fn = NULL;
    int alias = 0, header = 1, c;
    while ((c = getopt_long(argc, argv, "?AhHa:s:u:o:l:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'a': assembly = optarg; break;
        case 'A': alias = 1; break;
        case 's': species = optarg; break;
        case 'u': uri = optarg; break;
        case 'o': out_fn = optarg; break;
        case 'H': header = 0; break;
        case 'l': alt_fn = optarg; break;
        case 'h': case '?': fputs(usage_dict, stderr); return 1;
        default: fputs(usage_dict, stderr); return 1;
        }
    }
    const char *fn = optind < argc ? argv[optind] : "-";
    if (optind >= argc && 0) { fputs(usage_dict, stderr); return 1; }
    strmap_t *alt = NULL;
    if (alt_fn) {
        FILE *af = fopen(alt_fn, "r");
        if (!af) { fprintf(stderr, "dict: %s: No such file or directory\n", alt_fn); return 1; }
        alt = sm_init();
        char *line = NULL; size_t cap = 0; ssize_t n;
        while ((n = getline(&line, &cap, af)) >= 0) {
            if (line[0] == '@') continue;
            char *e = line; while (*e && !isspace((unsigned char)*e)) e++;
            *e = 0;
            if (*line) sm_put(alt, line, 1);
        }
        free(line); fclose(af);
    }
    seqreader_t *r = sr_open(fn);
    if (!r) { fprintf(stderr, "dict: %s: No such file or directory\n", fn); return 1; }
    FILE *out = stdout;
    if (out_fn) {
        out = fopen(out_fn, "w");
        if (!out) { fprintf(stderr, "dict: %s: Cannot open file for writing\n", out_fn); sr_close(r); return 1; }
    }
    if (header) fprintf(out, "@HD\tVN:1.0\tSO:unsorted\n");
    char *real = NULL;
    if (!uri && strcmp(fn, "-") != 0) real = realpath(fn, NULL);
    while (sr_read(r) >= 0) {
        int k = 0;
        char *s = r->seq.s;
        for (size_t i = 0; i < r->seq.l; i++) if (s[i] >= '!' && s[i] <= '~') s[k++] = toupper((unsigned char)s[i]);
        md5_ctx m; md5_init(&m); md5_update(&m, s, k);
        uint8_t dg[16]; char hex[33]; md5_final(&m, dg); md5_hex(hex, dg);
        fprintf(out, "@SQ\tSN:%s\tLN:%d\tM5:%s", r->name.s, k, hex);
        if (alias) {
            const char *nm = r->name.s;
            if (strncmp(nm, "chr", 3) == 0) {
                if (strcmp(nm + 3, "M") == 0) fprintf(out, "\tAN:MT");
                else fprintf(out, "\tAN:%s", nm + 3);
            } else {
                if (strcmp(nm, "MT") == 0) fprintf(out, "\tAN:chrM");
                else fprintf(out, "\tAN:chr%s", nm);
            }
        }
        if (uri) fprintf(out, "\tUR:%s", uri);
        else if (strcmp(fn, "-") != 0) fprintf(out, "\tUR:file://%s", real ? real : fn);
        if (assembly) fprintf(out, "\tAS:%s", assembly);
        if (species) fprintf(out, "\tSP:%s", species);
        if (alt && sm_has(alt, r->name.s)) fprintf(out, "\tAH:*");
        fprintf(out, "\n");
    }
    free(real);
    sr_close(r);
    sm_destroy(alt);
    if (out != stdout) fclose(out);
    return 0;
}
