#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include "common.h"

int main_head(int argc, char *argv[]) {
    static const struct option lopts[] = {
        {"headers", required_argument, NULL, 'h'}, {"records", required_argument, NULL, 'n'},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"reference", required_argument, NULL, 'T'}, {"threads", required_argument, NULL, '@'},
        {"verbosity", required_argument, NULL, GO_VERBOSITY}, {NULL, 0, NULL, 0}
    };
    int64_t nhdr = -1, nrec = 0;
    int c;
    while ((c = getopt_long(argc, argv, "h:n:T:@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'h': nhdr = strtoll(optarg, NULL, 10); break;
        case 'n': nrec = strtoll(optarg, NULL, 10); break;
        case 'T': case '@': case GO_INPUT_FMT_OPTION: case GO_VERBOSITY: break;
        default: fputs(usage_head, stderr); return 1;
        }
    }
    const char *fn = optind < argc ? argv[optind] : "-";
    if (optind >= argc && isatty(STDIN_FILENO)) { fputs(usage_head, stdout); return 0; }
    samfile_t *fp = sf_open(fn, "r");
    if (!fp) { print_error_errno("head", "failed to open \"%s\" for reading", fn); return 1; }
    hdr_t *h = sf_read_header(fp);
    if (!h) { print_error("head", "failed to read the header"); sf_close(fp); return 1; }
    kstr t = {0, 0, NULL};
    hdr_text(h, &t);
    if (nhdr < 0) fwrite(t.s, 1, t.l, stdout);
    else {
        size_t p = 0; int64_t k = 0;
        while (p < t.l && k < nhdr) {
            char *e = memchr(t.s + p, '\n', t.l - p);
            size_t q = e ? (size_t)(e - t.s) + 1 : t.l;
            fwrite(t.s + p, 1, q - p, stdout);
            p = q; k++;
        }
    }
    ks_free(&t);
    int ret = 0;
    if (nrec > 0) {
        rec_t *b = rec_init();
        kstr s = {0, 0, NULL};
        int64_t k = 0, r;
        while (k < nrec && (r = sf_read(fp, b)) >= 0) {
            sam_format1(h, b, &s);
            fwrite(s.s, 1, s.l, stdout); fputc('\n', stdout);
            k++;
        }
        if (k < nrec && r < -1) { print_error("head", "failed to read record"); ret = 1; }
        ks_free(&s); rec_destroy(b);
    }
    hdr_destroy(h);
    sf_close(fp);
    return ret;
}

int main_quickcheck(int argc, char *argv[]) {
    int verbose = 0, quiet = 0, unmapped = 0, opt;
    while ((opt = getopt(argc, argv, "qvu")) != -1) {
        switch (opt) {
        case 'u': unmapped = 1; break;
        case 'v': verbose++; break;
        case 'q': quiet = 1; break;
        default: fputs(usage_quickcheck, stderr); return 1;
        }
    }
    (void)quiet;
    argc -= optind; argv += optind;
    if (argc < 1) { fputs(usage_quickcheck, stdout); return 1; }
    if (verbose >= 2) fprintf(stderr, "verbosity set to %d\n", verbose);
    int ret = 0;
    for (int i = 0; i < argc; i++) {
        int st = 0;
        if (verbose >= 3) fprintf(stderr, "checking %s\n", argv[i]);
        samfile_t *fp = sf_open(argv[i], "r");
        if (!fp) {
            if (verbose >= 2) fprintf(stderr, "%s could not be opened for reading.\n", argv[i]);
            st |= 2;
        } else {
            if (verbose >= 3) fprintf(stderr, "opened %s\n", argv[i]);
            int is_seq = (fp->fmt == FMT_SAM || fp->fmt == FMT_BAM || fp->fmt == FMT_CRAM);
            if (!is_seq) {
                if (verbose >= 2) fprintf(stderr, "%s was not identified as sequence data.\n", argv[i]);
                st |= 4;
            } else {
                if (verbose >= 3) fprintf(stderr, "%s is sequence data\n", argv[i]);
                hdr_t *h = fp->fmt == FMT_CRAM ? NULL : sf_read_header(fp);
                if (!h) {
                    if (verbose >= 2) fprintf(stderr, "%s caused an error whilst reading its header.\n", argv[i]);
                    st |= 8;
                } else {
                    if (!unmapped && h->n_targets <= 0) {
                        if (verbose >= 2) fprintf(stderr, "%s had no targets in header.\n", argv[i]);
                        st |= 8;
                    } else if (verbose >= 3) fprintf(stderr, "%s has %d targets in header.\n", argv[i], h->n_targets);
                    hdr_destroy(h);
                }
            }
            int r;
            if (fp->bg->mode == BG_BGZF) r = bg_check_eof(fp->bg);
            else r = 3;
            if (r < 0) {
                if (verbose >= 2) fprintf(stderr, "%s caused an error whilst checking for EOF block.\n", argv[i]);
                st |= 16;
            } else switch (r) {
                case 0:
                    if (verbose >= 2) fprintf(stderr, "%s was missing EOF block when one should be present.\n", argv[i]);
                    st |= 16; break;
                case 1: if (verbose >= 3) fprintf(stderr, "%s has good EOF block.\n", argv[i]); break;
                case 2: if (verbose >= 3) fprintf(stderr, "%s cannot be checked for EOF block as it is not seekable.\n", argv[i]); break;
                case 3: if (verbose >= 3) fprintf(stderr, "%s cannot be checked for EOF block because its filetype does not contain one.\n", argv[i]); break;
            }
            sf_close(fp);
        }
        if (st > 0 && verbose >= 1) fprintf(stdout, "%s\n", argv[i]);
        ret |= st;
    }
    return ret;
}
EOF
