/* pileup engine */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "plp.h"

static lbnode_t *node_alloc(plp_t *it) {
    lbnode_t *n;
    if (it->freelist) { n = it->freelist; it->freelist = n->next; }
    else n = xcalloc(1, sizeof(lbnode_t));
    n->next = NULL;
    it->cnt++;
    return n;
}
static void node_free(plp_t *it, lbnode_t *n) {
    it->cnt--;
    n->next = it->freelist; it->freelist = n;
}

plp_t *plp_init(plp_read_f func, void *data) {
    plp_t *it = xcalloc(1, sizeof(plp_t));
    it->head = it->tail = node_alloc(it);
    it->max_tid = it->max_pos = -1;
    it->flag_mask = FUNMAP | FSECONDARY | FQCFAIL | FDUP;
    it->maxcnt = 8000;
    if (func) { it->func = func; it->data = data; it->b = rec_init(); }
    return it;
}

void plp_set_maxcnt(plp_t *it, int maxcnt) { it->maxcnt = maxcnt; }

void plp_init_overlaps(plp_t *it) { it->do_overlaps = 1; it->overlaps = sm_init(); }

void plp_destroy(plp_t *it) {
    lbnode_t *p = it->head;
    while (p) { lbnode_t *q = p->next; free(p->b.data); free(p); p = q; }
    p = it->freelist;
    while (p) { lbnode_t *q = p->next; free(p->b.data); free(p); p = q; }
    free(it->plp);
    rec_destroy(it->b);
    sm_destroy(it->overlaps);
    free(it->ov_nodes);
    free(it);
}

/* ---- overlap handling ---- */
static int cigar_iref2iseq_set(const uint32_t **cigar, const uint32_t *cigar_max, int64_t *icig, int64_t *iseq, int64_t *iref) {
    int64_t pos = *iref;
    if (pos < 0) return -1;
    *icig = 0; *iseq = 0; *iref = 0;
    while (*cigar < cigar_max) {
        int cig = (**cigar) & 0xf, ncig = (**cigar) >> 4;
        if (cig == C_SOFT_CLIP) { (*cigar)++; *iseq += ncig; *icig = 0; continue; }
        if (cig == C_HARD_CLIP || cig == C_PAD) { (*cigar)++; *icig = 0; continue; }
        if (cig == C_MATCH || cig == C_EQUAL || cig == C_DIFF) {
            pos -= ncig;
            if (pos < 0) { *icig = ncig + pos; *iseq += *icig; *iref += *icig; return C_MATCH; }
            (*cigar)++; *iseq += ncig; *icig = 0; *iref += ncig;
            continue;
        }
        if (cig == C_INS) { (*cigar)++; *iseq += ncig; *icig = 0; continue; }
        if (cig == C_DEL || cig == C_REF_SKIP) {
            pos -= ncig;
            if (pos < 0) pos = 0;
            (*cigar)++; *icig = 0; *iref += ncig;
            continue;
        }
        return -2;
    }
    *iseq = -1;
    return -1;
}

static int cigar_iref2iseq_next(const uint32_t **cigar, const uint32_t *cigar_max, int64_t *icig, int64_t *iseq, int64_t *iref) {
    while (*cigar < cigar_max) {
        int cig = (**cigar) & 0xf, ncig = (**cigar) >> 4;
        if (cig == C_MATCH || cig == C_EQUAL || cig == C_DIFF) {
            if (*icig >= ncig - 1) { *icig = 0; (*cigar)++; continue; }
            (*iseq)++; (*icig)++; (*iref)++;
            return C_MATCH;
        }
        if (cig == C_DEL || cig == C_REF_SKIP) { (*cigar)++; (*iref) += ncig; *icig = 0; continue; }
        if (cig == C_INS) { (*cigar)++; *iseq += ncig; *icig = 0; continue; }
        if (cig == C_SOFT_CLIP) { (*cigar)++; *iseq += ncig; *icig = 0; continue; }
        if (cig == C_HARD_CLIP || cig == C_PAD) { (*cigar)++; *icig = 0; continue; }
        return -2;
    }
    *iseq = -1; *iref = -1;
    return -1;
}

static void tweak_overlap_quality(rec_t *a, rec_t *b) {
    const uint32_t *a_cigar = rec_cigar(a), *b_cigar = rec_cigar(b);
    const uint32_t *a_max = a_cigar + a->core.n_cigar, *b_max = b_cigar + b->core.n_cigar;
    uint8_t *a_qual = rec_qual(a), *b_qual = rec_qual(b);
    uint8_t *a_seq = rec_seq(a), *b_seq = rec_seq(b);
    int64_t iref = b->core.pos;
    int64_t a_iref = iref - a->core.pos;
    int64_t b_iref = iref - b->core.pos;
    int64_t a_icig, a_iseq, b_icig, b_iseq;
    int a_ret = cigar_iref2iseq_set(&a_cigar, a_max, &a_icig, &a_iseq, &a_iref);
    if (a_ret < 0) return;
    int b_ret = cigar_iref2iseq_set(&b_cigar, b_max, &b_icig, &b_iseq, &b_iref);
    if (b_ret < 0) return;
    while (1) {
        while (a_ret >= 0 && a_iref >= 0 && a_iref < iref - a->core.pos)
            a_ret = cigar_iref2iseq_next(&a_cigar, a_max, &a_icig, &a_iseq, &a_iref);
        if (a_ret < 0) break;
        if (iref < a_iref + a->core.pos) iref = a_iref + a->core.pos;
        while (b_ret >= 0 && b_iref >= 0 && b_iref < iref - b->core.pos)
            b_ret = cigar_iref2iseq_next(&b_cigar, b_max, &b_icig, &b_iseq, &b_iref);
        if (b_ret < 0) break;
        if (iref < b_iref + b->core.pos) iref = b_iref + b->core.pos;
        iref++;
        if (a_iref + a->core.pos != b_iref + b->core.pos) continue;
        if (seqi(a_seq, a_iseq) == seqi(b_seq, b_iseq)) {
            int qual = a_qual[a_iseq] + b_qual[b_iseq];
            a_qual[a_iseq] = qual > 200 ? 200 : qual;
            b_qual[b_iseq] = 0;
        } else {
            if (a_qual[a_iseq] >= b_qual[b_iseq]) {
                a_qual[a_iseq] = 0.8 * a_qual[a_iseq];
                b_qual[b_iseq] = 0;
            } else {
                b_qual[b_iseq] = 0.8 * b_qual[b_iseq];
                a_qual[a_iseq] = 0;
            }
        }
    }
}

static void overlap_push(plp_t *it, lbnode_t *node) {
    if (!it->do_overlaps) return;
    if ((node->b.core.flag & FMUNMAP) || !(node->b.core.flag & FPROPER_PAIR)) return;
    if ((node->b.core.mtid >= 0 && node->b.core.tid != node->b.core.mtid)
        || (llabs(node->b.core.isize) >= 2 * node->b.core.l_qseq && node->b.core.mpos >= node->end))
        return;
    int64_t v;
    const char *qn = rec_qname(&node->b);
    if (!sm_get(it->overlaps, qn, &v) || v < 0) {
        if (node->b.core.mpos >= node->b.core.pos || ((node->b.core.flag & FPAIRED) && node->b.core.mpos == -1)) {
            /* store pointer */
            if (it->ov_n == it->ov_m) { it->ov_m = it->ov_m ? it->ov_m * 2 : 64; it->ov_nodes = xrealloc(it->ov_nodes, it->ov_m * sizeof(lbnode_t*)); }
            int slot = -1;
            for (int i = 0; i < it->ov_n; i++) if (!it->ov_nodes[i]) { slot = i; break; }
            if (slot < 0) slot = it->ov_n++;
            it->ov_nodes[slot] = node;
            sm_put(it->overlaps, qn, slot);
        }
    } else {
        lbnode_t *a = it->ov_nodes[v];
        tweak_overlap_quality(&a->b, &node->b);
        it->ov_nodes[v] = NULL;
        sm_put(it->overlaps, qn, -1);
    }
}

static void overlap_remove(plp_t *it, const rec_t *b) {
    if (!it->do_overlaps || !b) return;
    int64_t v;
    if (sm_get(it->overlaps, rec_qname(b), &v) && v >= 0) {
        lbnode_t *n = it->ov_nodes[v];
        if (n && &n->b == b) { it->ov_nodes[v] = NULL; sm_put(it->overlaps, rec_qname(b), -1); }
        else if (n && n->b.core.pos == b->core.pos && n->b.core.flag == b->core.flag) {}
    }
}

/* remove by node (when node is freed) */
static void overlap_remove_node(plp_t *it, lbnode_t *node) {
    if (!it->do_overlaps) return;
    int64_t v;
    if (sm_get(it->overlaps, rec_qname(&node->b), &v) && v >= 0 && it->ov_nodes[v] == node) {
        it->ov_nodes[v] = NULL;
        sm_put(it->overlaps, rec_qname(&node->b), -1);
    }
}

int plp_push(plp_t *it, const rec_t *b) {
    if (it->error) return -1;
    if (b) {
        if (b->core.tid < 0) { overlap_remove(it, b); return 0; }
        if (b->core.flag & it->flag_mask) { overlap_remove(it, b); return 0; }
        if (it->tid == b->core.tid && it->pos == b->core.pos && it->cnt > it->maxcnt) { overlap_remove(it, b); return 0; }
        rec_copy(&it->tail->b, b);
        it->tail->b.id = it->id++;
        it->tail->beg = b->core.pos;
        it->tail->end = b->core.pos + cigar2rlen(b->core.n_cigar, rec_cigar(b));
        it->tail->s.k = -1; it->tail->s.x = -1; it->tail->s.y = -1;
        it->tail->s.end = it->tail->end - 1;
        overlap_push(it, it->tail);
        if (b->core.tid < it->max_tid) {
            fprintf(stderr, "[E::bam_plp_push] The input is not sorted (chromosomes out of order)\n");
            it->error = 1; return -1;
        }
        if (b->core.tid == it->max_tid && it->tail->beg < it->max_pos) {
            fprintf(stderr, "[E::bam_plp_push] The input is not sorted (reads out of order)\n");
            it->error = 1; return -1;
        }
        it->max_tid = b->core.tid; it->max_pos = it->tail->beg;
        if (it->tail->end > it->pos || it->tail->b.core.tid > it->tid) {
            it->tail->next = node_alloc(it);
            it->tail = it->tail->next;
        } else {
            overlap_remove_node(it, it->tail);
        }
    } else it->is_eof = 1;
    return 0;
}

static int resolve_cigar2(pileup1_t *p, int64_t pos, cstate_t *s) {
    rec_t *b = p->b;
    core_t *c = &b->core;
    uint32_t *cigar = rec_cigar(b);
    int k;
    if (s->k == -1) {
        p->qpos = 0;
        if (c->n_cigar == 1) {
            int op = cig_op(cigar[0]);
            if (op == C_MATCH || op == C_EQUAL || op == C_DIFF) s->k = 0, s->x = c->pos, s->y = 0;
        } else {
            for (k = 0, s->x = c->pos, s->y = 0; k < (int)c->n_cigar; ++k) {
                int op = cig_op(cigar[k]), l = cig_len(cigar[k]);
                if (op == C_MATCH || op == C_DEL || op == C_REF_SKIP || op == C_EQUAL || op == C_DIFF) break;
                else if (op == C_INS || op == C_SOFT_CLIP) s->y += l;
            }
            s->k = k;
        }
    } else {
        int op, l = cig_len(cigar[s->k]);
        if (pos - s->x >= l) {
            op = cig_op(cigar[s->k + 1]);
            int cur = cig_op(cigar[s->k]);
            if (op == C_MATCH || op == C_DEL || op == C_REF_SKIP || op == C_EQUAL || op == C_DIFF) {
                if (cur == C_MATCH || cur == C_EQUAL || cur == C_DIFF) s->y += l;
                s->x += l;
                ++s->k;
            } else {
                if (cur == C_MATCH || cur == C_EQUAL || cur == C_DIFF) s->y += l;
                s->x += l;
                for (k = s->k + 1; k < (int)c->n_cigar; ++k) {
                    op = cig_op(cigar[k]), l = cig_len(cigar[k]);
                    if (op == C_MATCH || op == C_DEL || op == C_REF_SKIP || op == C_EQUAL || op == C_DIFF) break;
                    else if (op == C_INS || op == C_SOFT_CLIP) s->y += l;
                }
                s->k = k;
            }
        }
    }
    {
        int op = cig_op(cigar[s->k]), l = cig_len(cigar[s->k]);
        p->is_del = p->indel = p->is_refskip = 0;
        if (s->x + l - 1 == pos && s->k + 1 < (int)c->n_cigar) {
            int op2 = cig_op(cigar[s->k + 1]);
            int l2 = cig_len(cigar[s->k + 1]);
            if (op2 == C_DEL && op != C_DEL) {
                p->indel = -(int)l2;
                for (k = s->k + 2; k < (int)c->n_cigar; ++k) {
                    op2 = cig_op(cigar[k]); l2 = cig_len(cigar[k]);
                    if (op2 == C_DEL) p->indel -= l2;
                    else break;
                }
            } else if (op2 == C_INS) {
                p->indel = l2;
                for (k = s->k + 2; k < (int)c->n_cigar; ++k) {
                    op2 = cig_op(cigar[k]); l2 = cig_len(cigar[k]);
                    if (op2 == C_INS) p->indel += l2;
                    else if (op2 != C_PAD) break;
                }
            } else if (op2 == C_PAD && s->k + 2 < (int)c->n_cigar) {
                int l3 = 0;
                for (k = s->k + 2; k < (int)c->n_cigar; ++k) {
                    op2 = cig_op(cigar[k]); l2 = cig_len(cigar[k]);
                    if (op2 == C_INS) l3 += l2;
                    else if (op2 == C_DEL || op2 == C_MATCH || op2 == C_REF_SKIP || op2 == C_EQUAL || op2 == C_DIFF) break;
                }
                if (l3 > 0) p->indel = l3;
            }
        }
        if (op == C_MATCH || op == C_EQUAL || op == C_DIFF) {
            p->qpos = s->y + (pos - s->x);
        } else if (op == C_DEL || op == C_REF_SKIP) {
            p->is_del = 1; p->qpos = s->y;
            p->is_refskip = (op == C_REF_SKIP);
        }
        p->is_head = (pos == c->pos); p->is_tail = (pos == s->end);
    }
    p->cigar_ind = s->k;
    return 1;
}

const pileup1_t *plp_next(plp_t *it, int *_tid, int64_t *_pos, int *_n_plp) {
    if (it->error) { *_n_plp = -1; return NULL; }
    *_n_plp = 0;
    if (it->is_eof && it->head == it->tail) return NULL;
    while (it->is_eof || it->max_tid > it->tid || (it->max_tid == it->tid && it->max_pos > it->pos)) {
        int n_plp = 0;
        lbnode_t **pptr = &it->head;
        while (*pptr != it->tail) {
            lbnode_t *p = *pptr;
            if (p->b.core.tid < it->tid || (p->b.core.tid == it->tid && p->end <= it->pos)) {
                overlap_remove_node(it, p);
                *pptr = p->next; node_free(it, p);
            } else {
                if (p->b.core.tid == it->tid && p->beg <= it->pos) {
                    if (n_plp == it->max_plp) {
                        it->max_plp = it->max_plp ? it->max_plp << 1 : 256;
                        it->plp = xrealloc(it->plp, sizeof(pileup1_t) * it->max_plp);
                    }
                    it->plp[n_plp].b = &p->b;
                    it->plp[n_plp].cd = p->cd;
                    if (resolve_cigar2(it->plp + n_plp, it->pos, &p->s)) ++n_plp;
                }
                pptr = &(*pptr)->next;
            }
        }
        *_n_plp = n_plp; *_tid = it->tid; *_pos = it->pos;
        if (it->head != it->tail) {
            if (it->tid > it->head->b.core.tid) {
                fprintf(stderr, "[E::bam_plp_next] Unsorted input. Pileup aborts\n");
                it->error = 1; *_n_plp = -1; return NULL;
            }
        }
        if (it->tid < it->head->b.core.tid) {
            it->tid = it->head->b.core.tid; it->pos = it->head->beg;
        } else if (it->pos < it->head->beg) {
            it->pos = it->head->beg;
        } else ++it->pos;
        if (n_plp) return it->plp;
        if (it->is_eof && it->head == it->tail) break;
    }
    return NULL;
}

const pileup1_t *plp_auto(plp_t *it, int *_tid, int64_t *_pos, int *_n_plp) {
    const pileup1_t *plp;
    if (it->func == 0 || it->error) { *_n_plp = -1; return 0; }
    if ((plp = plp_next(it, _tid, _pos, _n_plp)) != 0) return plp;
    else {
        *_n_plp = 0;
        if (it->is_eof) return 0;
        int ret;
        while ((ret = it->func(it->data, it->b)) >= 0) {
            if (plp_push(it, it->b) < 0) { *_n_plp = -1; return 0; }
            if ((plp = plp_next(it, _tid, _pos, _n_plp)) != 0) return plp;
        }
        if (ret < -1) { it->error = ret; *_n_plp = -1; return 0; }
        plp_push(it, 0);
        if ((plp = plp_next(it, _tid, _pos, _n_plp)) != 0) return plp;
        return 0;
    }
}

int plp_insertion(const pileup1_t *p, kstr *ins, int *del_len) {
    int j, k, indel, nb = 0;
    uint32_t *cigar;
    if (p->indel <= 0) {
        ins->l = 0; ks_grow(ins, 0); ins->s[0] = 0;
        if (del_len) *del_len = -p->indel;
        return 0;
    }
    if (del_len) *del_len = 0;
    ins->l = 0;
    cigar = rec_cigar(p->b);
    indel = 0;
    for (k = p->cigar_ind + 1; k < (int)p->b->core.n_cigar; k++) {
        switch (cig_op(cigar[k])) {
        case C_INS: case C_PAD: indel += cig_len(cigar[k]); break;
        case C_SOFT_CLIP: case C_HARD_CLIP: break;
        default: k = p->b->core.n_cigar; break;
        }
    }
    nb = indel;
    ks_grow(ins, indel + 1);
    indel = 0;
    j = p->qpos + 1;
    uint8_t *seq = rec_seq(p->b);
    for (k = p->cigar_ind + 1; k < (int)p->b->core.n_cigar; k++) {
        int l;
        switch (cig_op(cigar[k])) {
        case C_INS:
            for (l = 0; l < (int)cig_len(cigar[k]); l++, j++)
                ins->s[indel++] = seq_nt16_str[j < p->b->core.l_qseq ? seqi(seq, j) : 15];
            break;
        case C_PAD:
            for (l = 0; l < (int)cig_len(cigar[k]); l++) ins->s[indel++] = '*';
            break;
        case C_SOFT_CLIP: case C_HARD_CLIP: break;
        case C_DEL:
            if (del_len) {
                int d = 0, kk;
                for (kk = k; kk < (int)p->b->core.n_cigar && cig_op(cigar[kk]) == C_DEL; kk++) d += cig_len(cigar[kk]);
                *del_len = d;
            }
            k = p->b->core.n_cigar; break;
        default: k = p->b->core.n_cigar; break;
        }
    }
    ins->s[indel] = 0;
    ins->l = indel;
    (void)nb;
    return indel;
}

/* ---- multi pileup ---- */
mplp_t *mplp_init(int n, plp_read_f func, void **data) {
    mplp_t *m = xcalloc(1, sizeof(mplp_t));
    m->n = n;
    m->pos = xcalloc(n, sizeof(int64_t));
    m->n_plp = xcalloc(n, sizeof(int));
    m->plp = xcalloc(n, sizeof(pileup1_t*));
    m->iter = xcalloc(n, sizeof(plp_t*));
    m->min_pos = INT64_MAX;
    for (int i = 0; i < n; i++) {
        m->iter[i] = plp_init(func, data[i]);
        m->pos[i] = INT64_MAX;
    }
    return m;
}
void mplp_destroy(mplp_t *m) {
    for (int i = 0; i < m->n; i++) plp_destroy(m->iter[i]);
    free(m->iter); free(m->pos); free(m->n_plp); free(m->plp); free(m);
}
void mplp_init_overlaps(mplp_t *m) { for (int i = 0; i < m->n; i++) plp_init_overlaps(m->iter[i]); }
void mplp_set_maxcnt(mplp_t *m, int maxcnt) { for (int i = 0; i < m->n; i++) m->iter[i]->maxcnt = maxcnt; }

int mplp_auto(mplp_t *m, int *_tid, int64_t *_pos, int *n_plp, const pileup1_t **plp) {
    int i, ret = 0;
    int64_t new_min = INT64_MAX;
    for (i = 0; i < m->n; ++i) {
        if (m->pos[i] == m->min_pos) {
            int tid; int64_t pos;
            m->plp[i] = plp_auto(m->iter[i], &tid, &pos, &m->n_plp[i]);
            if (m->iter[i]->error) return -1;
            if (m->plp[i]) m->pos[i] = ((int64_t)tid << 32) | pos;
            else m->pos[i] = INT64_MAX;
        }
        if (m->plp[i] && m->pos[i] < new_min) new_min = m->pos[i];
    }
    m->min_pos = new_min;
    if (new_min == INT64_MAX) return 0;
    *_tid = (int)(new_min >> 32); *_pos = (int32_t)(new_min & 0xffffffff);
    for (i = 0; i < m->n; ++i) {
        if (m->pos[i] == m->min_pos) { n_plp[i] = m->n_plp[i]; plp[i] = m->plp[i]; ++ret; }
        else { n_plp[i] = 0; plp[i] = 0; }
    }
    return ret;
}
