int sam_prob_realn(rec_t *b, const char *ref, int64_t ref_len, int flag);
int sam_cap_mapq(rec_t *b, const char *ref, int64_t ref_len, int thres);

enum { EX_FLAG = 1, EX_RNAME, EX_POS, EX_MAPQ, EX_RNEXT, EX_PNEXT, EX_TLEN, EX_QNAME_E, EX_TAG };
typedef struct { int type; char tag[3]; } extra_t;

typedef struct {
