cd /workspace/src && cat > cmd_mpileup.c <<'EOF'
/* samtools mpileup */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include "common.h"
#include "plp.h"
#include "fai.h"

#define MPLP_NO_ORPHAN 0x40
#define MPLP_REALN 0x80
#define MPLP_ILLUMINA13 0x200
#define MPLP_IGNORE_RG 0x400
#define MPLP_PRINT_QPOS 0x800
#define MPLP_PRINT_MAPQ 0x1000
#define MPLP_REDO_BAQ 0x2000
#define MPLP_PRINT_QPOS5 0x4000
#define MPLP_PRINT_QNAME 0x8000
#define MPLP_NO_INS 0x10000

int sam_prob_realn(rec_t *b, const char *ref, int64_t ref_len, int flag);
int sam_cap_mapq(rec_t *b, const char *ref, int64_t ref_len, int thres);

enum { EX_FLAG = 1, EX_RNAME, EX_POS, EX_MAPQ, EX_RNEXT, EX_PNEXT, EX_TLEN, EX_QNAME_E, EX_TAG };
typedef struct { int type; char tag[3]; } extra_t;

typedef struct {
    int min_mq, flag, min_baseQ, capQ_thres, max_depth, all, rev_del;
    int rflag_require, rflag_filter;
    char *reg, *fai_fname, *output_fname;
    fai_t *fai;
    bed_t *bed;
    strmap_t *rghash;
    int no_ins, no_del, no_ends;
    char sep, empty;
    extra_t *extra; int n_extra;
} mplp_conf_t;

typedef struct {
    char *ref; int ref_id; int64_t ref_len;
} mplp_ref_t;

typedef struct {
    samfile_t *fp;
    iter_t *iter;
    hdr_t *h;
    mplp_ref_t *ref;
    const mplp_conf_t *conf;
} mplp_aux_t;

static int mplp_get_ref(mplp_aux_t *ma, int tid, char **ref, int64_t *ref_len) {
    mplp_ref_t *r = ma->ref;
    if (!r || !ma->conf->fai) { *ref = NULL; return 0; }
    if (tid == r->ref_id) { *ref = r->ref; *ref_len = r->ref_len; return 1; }
    free(r->ref); r->ref = NULL; r->ref_id = -1;
    int id = fai_tid(ma->conf->fai, hdr_tname(ma->h, tid));
    if (id < 0) { *ref = NULL; return 0; }
    int64_t len;
    r->ref = fai_fetch_seq(ma->conf->fai, id, 0, INT64_MAX, &len);
    r->ref_len = len; r->ref_id = tid;
    *ref = r->ref; *ref_len = r->ref_len;
    return r->ref != NULL;
}

static int mplp_func(void *data, rec_t *b) {
    mplp_aux_t *ma = data;
    int ret, skip = 0;
    do {
        char *ref; int64_t ref_len; int has_ref;
        ret = ma->iter ? iter_next(ma->fp, ma->iter, b) : sf_read(ma->fp, b);
        if (ret < 0) break;
        if (b->core.tid < 0 || (b->core.flag & FUNMAP)) { skip = 1; continue; }
        if (ma->conf->rflag_require && !(ma->conf->rflag_require & b->core.flag)) { skip = 1; continue; }
        if (ma->conf->rflag_filter && (ma->conf->rflag_filter & b->core.flag)) { skip = 1; continue; }
        if (ma->conf->bed && ma->conf->all == 0) {
            skip = !bed_overlap(ma->conf->bed, hdr_tname(ma->h, b->core.tid), b->core.pos, rec_endpos(b));
            if (skip) continue;
        }
        if (ma->conf->rghash) {
            uint8_t *rg = aux_get(b, "RG");
            skip = (rg && sm_has(ma->conf->rghash, (char*)rg + 1));
            if (skip) continue;
        }
        if (ma->conf->flag & MPLP_ILLUMINA13) {
            uint8_t *q = rec_qual(b);
            for (int i = 0; i < b->core.l_qseq; i++) q[i] = q[i] > 31 ? q[i] - 31 : 0;
        }
        if (ma->conf->fai && b->core.tid >= 0) {
            has_ref = mplp_get_ref(ma, b->core.tid, &ref, &ref_len);
            if (has_ref && ref_len <= b->core.pos) {
                fprintf(stderr, "[%s] Skipping because %lld is outside of %lld [ref:%d]\n", "mplp_func",
                        (long long)b->core.pos, (long long)ref_len, b->core.tid);
                skip = 1; continue;
            }
        } else has_ref = 0;
        skip = 0;
        if (has_ref && (ma->conf->flag & MPLP_REALN)) sam_prob_realn(b, ref, ref_len, (ma->conf->flag & MPLP_REDO_BAQ) ? 7 : 3);
        if (has_ref && ma->conf->capQ_thres > 10) {
            int q = sam_cap_mapq(b, ref, ref_len, ma->conf->capQ_thres);
            if (q < 0) skip = 1;
            else if (b->core.qual > q) b->core.qual = q;
        }
        if (b->core.qual < ma->conf->min_mq) skip = 1;
        else if ((ma->conf->flag & MPLP_NO_ORPHAN) && (b->core.flag & FPAIRED) && !(b->core.flag & FPROPER_PAIR)) skip = 1;
    } while (skip);
    return ret;
}

static void print_empty(kstr *o, const mplp_conf_t *conf, const char *tname, int64_t pos, int n, const char *ref, int64_t len) {
    ks_puts(o, tname); ks_putc(o, '\t'); ks_puti(o, pos + 1); ks_putc(o, '\t');
    ks_putc(o, (ref && pos < len) ? ref[pos] : 'N');
    for (int i = 0; i < n; i++) {
        ks_puts(o, "\t0\t*\t*");
        if (conf->flag & MPLP_PRINT_MAPQ) ks_puts(o, "\t*");
        if (conf->flag & MPLP_PRINT_QPOS) ks_puts(o, "\t*");
        if (conf->flag & MPLP_PRINT_QPOS5) ks_puts(o, "\t*");
        if (conf->flag & MPLP_PRINT_QNAME) ks_puts(o, "\t*");
        for (int k = 0; k < conf->n_extra; k++) ks_puts(o, "\t*");
    }
    ks_putc(o, '\n');
}

static void pileup_seq(kstr *o, const pileup1_t *p, int64_t pos, int64_t ref_len, const char *ref, kstr *ks, const mplp_conf_t *conf) {
    int rev = (p->b->core.flag & FREVERSE) != 0;
    if (!conf->no_ends && p->is_head) {
        ks_putc(o, '^');
        ks_putc(o, p->b->core.qual > 93 ? 126 : p->b->core.qual + 33);
    }
    if (!p->is_del) {
        int c = p->qpos < p->b->core.l_qseq ? seq_nt16_str[seqi(rec_seq(p->b), p->qpos)] : 'N';
        if (ref) {
            int rb = pos < ref_len ? ref[pos] : 'N';
            if (c == '=' || seq_nt16_table[c] == seq_nt16_table[rb]) c = rev ? ',' : '.';
            else c = rev ? tolower(c) : toupper(c);
        } else {
            if (c == '=') c = rev ? ',' : '.';
            else c = rev ? tolower(c) : toupper(c);
        }
        ks_putc(o, c);
    } else ks_putc(o, p->is_refskip ? (rev ? '<' : '>') : ((rev && conf->rev_del) ? '#' : '*'));
    int del_len = -p->indel;
    if (p->indel > 0) {
        int len = plp_insertion(p, ks, &del_len);
        if (conf->no_ins < 2) {
            ks_putc(o, '+');
            ks_puti(o, len);
            if (!conf->no_ins) {
                for (int j = 0; j < len; j++) {
                    int c = ks->s[j];
                    ks_putc(o, rev ? tolower(c) : toupper(c));
                }
            }
        }
    }
    if (del_len > 0) {
        if (conf->no_del < 2) { ks_putc(o, '-'); ks_puti(o, del_len); }
        if (!conf->no_del) {
            for (int j = 1; j <= del_len; ++j) {
                int c = (ref && pos + j < ref_len) ? ref[pos + j] : 'N';
                ks_putc(o, rev ? tolower(c) : toupper(c));
            }
        }
    }
    if (!conf->no_ends && p->is_tail) ks_putc(o, '$');
}

static void mpileup_usage(FILE *fp) { fputs(usage_mpileup, fp); }

static int count_samples(hdr_t **h, int n, char **fn, int ignore_rg) {
    strmap_t *sm = sm_init();
    int ns = 0;
    for (int i = 0; i < n; i++) {
        int found = 0;
        if (!ignore_rg) {
            for (int j = 0; j < h[i]->nl; j++) {
                hline_t *l = &h[i]->l[j];
                if (l->type[0] != 'R' || l->type[1] != 'G') continue;
                const char *s = hline_get(l, "SM");
                if (!s) continue;
                found = 1;
                if (!sm_has(sm, s)) { sm_put(sm, s, ns++); }
            }
        }
        if (!found) { if (!sm_has(sm, fn[i])) sm_put(sm, fn[i], ns++); }
    }
    sm_destroy(sm);
    return ns;
}

static int parse_extra(mplp_conf_t *conf, const char *s) {
    char *d = xstrdup(s), *save = NULL;
    for (char *t = strtok_r(d, ",", &save); t; t = strtok_r(NULL, ",", &save)) {
        extra_t e; memset(&e, 0, sizeof e);
        if (strcmp(t, "FLAG") == 0) e.type = EX_FLAG;
        else if (strcmp(t, "RNAME") == 0) e.type = EX_RNAME;
        else if (strcmp(t, "POS") == 0) e.type = EX_POS;
        else if (strcmp(t, "MAPQ") == 0) e.type = EX_MAPQ;
        else if (strcmp(t, "RNEXT") == 0) e.type = EX_RNEXT;
        else if (strcmp(t, "PNEXT") == 0) e.type = EX_PNEXT;
        else if (strcmp(t, "TLEN") == 0) e.type = EX_TLEN;
        else if (strcmp(t, "QNAME") == 0) e.type = EX_QNAME_E;
        else if (strlen(t) == 2) { e.type = EX_TAG; e.tag[0] = t[0]; e.tag[1] = t[1]; }
        else { fprintf(stderr, "[%s] Error: Unrecognised column \"%s\"\n", "parse_output_extra", t); free(d); return -1; }
        conf->extra = xrealloc(conf->extra, (conf->n_extra + 1) * sizeof(extra_t));
        conf->extra[conf->n_extra++] = e;
    }
    free(d);
    /* order: fixed-field columns first in canonical order, then tags */
    return 0;
}

int main_mpileup(int argc, char *argv[]) {
    mplp_conf_t conf; memset(&conf, 0, sizeof conf);
    conf.min_baseQ = 13; conf.capQ_thres = 0; conf.max_depth = 8000;
    conf.flag = MPLP_NO_ORPHAN | MPLP_REALN;
    conf.rflag_filter = FUNMAP | FSECONDARY | FQCFAIL | FDUP;
    conf.sep = ','; conf.empty = '*';
    char *file_list = NULL, *positions = NULL, *exclude_rg = NULL;
    int nfiles = 0, c, no_overlaps = 0, has_idx = 0;
    char **fn = NULL;
    static const struct option lopts[] = {
        {"rf", required_argument, NULL, 1}, {"ff", required_argument, NULL, 2},
        {"incl-flags", required_argument, NULL, 1}, {"excl-flags", required_argument, NULL, 2},
        {"output", required_argument, NULL, 3}, {"output-QNAME", no_argument, NULL, 5},
        {"output-qname", no_argument, NULL, 5}, {"illumina1.3+", no_argument, NULL, '6'},
        {"count-orphans", no_argument, NULL, 'A'}, {"bam-list", required_argument, NULL, 'b'},
        {"no-BAQ", no_argument, NULL, 'B'}, {"no-baq", no_argument, NULL, 'B'},
        {"adjust-MQ", required_argument, NULL, 'C'}, {"adjust-mq", required_argument, NULL, 'C'},
        {"max-depth", required_argument, NULL, 'd'}, {"redo-BAQ", no_argument, NULL, 'E'},
        {"redo-baq", no_argument, NULL, 'E'}, {"fasta-ref", required_argument, NULL, 'f'},
        {"exclude-RG", required_argument, NULL, 'G'}, {"exclude-rg", required_argument, NULL, 'G'},
        {"positions", required_argument, NULL, 'l'}, {"region", required_argument, NULL, 'r'},
        {"ignore-RG", no_argument, NULL, 'R'}, {"ignore-rg", no_argument, NULL, 'R'},
        {"min-MQ", required_argument, NULL, 'q'}, {"min-mq", required_argument, NULL, 'q'},
        {"min-BQ", required_argument, NULL, 'Q'}, {"min-bq", required_argument, NULL, 'Q'},
        {"ignore-overlaps", no_argument, NULL, 'x'}, {"ignore-overlaps-removal", no_argument, NULL, 'x'},
        {"disable-overlap-removal", no_argument, NULL, 'x'},
        {"output-BP", no_argument, NULL, 'O'}, {"output-bp", no_argument, NULL, 'O'},
        {"output-BP-5", no_argument, NULL, 14}, {"output-bp-5", no_argument, NULL, 14},
        {"output-MQ", no_argument, NULL, 's'}, {"output-mq", no_argument, NULL, 's'},
        {"output-mods", no_argument, NULL, 'M'},
        {"output-extra", required_argument, NULL, 15}, {"output-sep", required_argument, NULL, 16},
        {"output-empty", required_argument, NULL, 17}, {"no-output-ins", no_argument, NULL, 18},
        {"no-output-ins-mods", no_argument, NULL, 22},
        {"no-output-del", no_argument, NULL, 19}, {"no-output-ends", no_argument, NULL, 20},
        {"reverse-del", no_argument, NULL, 21},
        {"customized-index", no_argument, NULL, 'X'},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"reference", required_argument, NULL, GO_REFERENCE},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "Agf:r:l:q:Q:uRC:BDSd:L:b:P:po:e:h:Im:F:EG:6OsVvxXt:a:M", lopts, NULL)) >= 0) {
        switch (c) {
        case 1: { int ok; int64_t v = parse_flag_str(optarg, &ok); if (!ok || v < 0) { fprintf(stderr, "Could not parse --rf %s\n", optarg); return 1; } conf.rflag_require = v; break; }
        case 2: { int ok; int64_t v = parse_flag_str(optarg, &ok); if (!ok || v < 0) { fprintf(stderr, "Could not parse --ff %s\n", optarg); return 1; } conf.rflag_filter = v; break; }
        case 3: conf.output_fname = optarg; break;
        case 5: conf.flag |= MPLP_PRINT_QNAME; break;
        case 14: conf.flag |= MPLP_PRINT_QPOS5; break;
        case 15: if (parse_extra(&conf, optarg) < 0) return 1; break;
        case 16: conf.sep = optarg[0]; break;
        case 17: conf.empty = optarg[0]; break;
        case 18: conf.no_ins++; break;
        case 22: break;
        case 19: conf.no_del++; break;
        case 20: conf.no_ends = 1; break;
        case 21: conf.rev_del = 1; break;
        case 'f':
            conf.fai = fai_load(optarg);
            if (!conf.fai) return 1;
            conf.fai_fname = optarg;
            break;
        case 'd': conf.max_depth = atoi(optarg); break;
        case 'r': conf.reg = optarg; break;
        case 'l': positions = optarg; break;
        case 'b': file_list = optarg; break;
        case 'o': conf.output_fname = optarg; break;
        case 'B': conf.flag &= ~MPLP_REALN; break;
        case 'E': conf.flag |= MPLP_REDO_BAQ; break;
        case '6': conf.flag |= MPLP_ILLUMINA13; break;
        case 'R': conf.flag |= MPLP_IGNORE_RG; break;
        case 's': conf.flag |= MPLP_PRINT_MAPQ; break;
        case 'O': conf.flag |= MPLP_PRINT_QPOS; break;
        case 'C': conf.capQ_thres = atoi(optarg); break;
        case 'q': conf.min_mq = atoi(optarg); break;
        case 'Q': conf.min_baseQ = atoi(optarg); break;
        case 'A': conf.flag &= ~MPLP_NO_ORPHAN; break;
        case 'a': if (optarg[0] == 'a') conf.all = 2; else conf.all++; break;
        case 'x': no_overlaps = 1; break;
        case 'X': has_idx = 1; break;
        case 'G': exclude_rg = optarg; break;
        case 'M': break;
        case GO_INPUT_FMT_OPTION: case GO_VERBOSITY: break;
        case GO_REFERENCE: break;
        case 'g': case 'v': case 'u': case 'D': case 'S': case 'V': case 'I': case 'P': case 'p':
        case 'L': case 'e': case 'h': case 'm': case 'F': case 't':
            fprintf(stderr, "[%s] Error: option -%c is no longer supported by samtools mpileup.\n", "bam_mpileup", c);
            fprintf(stderr, "Please use \"bcftools mpileup\" instead.\n");
            return 1;
        default:
            if (optopt == 'a' && optind > 0 && argv[optind-1][0] == '-' ) {}
            mpileup_usage(stderr); return 1;
        }
    }
    (void)has_idx;
    if (exclude_rg) {
        FILE *f = fopen(exclude_rg, "r");
        if (f) {
            conf.rghash = sm_init();
            char buf[4096];
            while (fscanf(f, "%4095s", buf) == 1) sm_put(conf.rghash, buf, 1);
            fclose(f);
        }
    }
    if (positions) {
        conf.bed = bed_read(positions);
        if (!conf.bed) { print_error_errno("mpileup", "Could not read file \"%s\"", positions); return 1; }
    }
    if (file_list) {
        FILE *f = fopen(file_list, "r");
        if (!f) { print_error_errno("mpileup", "Could not read file list \"%s\"", file_list); return 1; }
        char *line = NULL; size_t cap = 0; ssize_t n;
        while ((n = getline(&line, &cap, f)) >= 0) {
            while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r')) line[--n] = 0;
            if (n == 0) continue;
            fn = xrealloc(fn, (nfiles + 1) * sizeof(char*)); fn[nfiles++] = xstrdup(line);
        }
        free(line); fclose(f);
    } else {
        if (argc == optind) {
            if (isatty(STDIN_FILENO)) { mpileup_usage(stdout); return 0; }
            fn = xmalloc(sizeof(char*)); fn[0] = xstrdup("-"); nfiles = 1;
        } else {
            nfiles = argc - optind;
            fn = xmalloc(nfiles * sizeof(char*));
            for (int i = 0; i < nfiles; i++) fn[i] = xstrdup(argv[optind + i]);
        }
    }
    int ret = 0;
    mplp_aux_t **data = xcalloc(nfiles, sizeof(mplp_aux_t*));
    hdr_t **hs = xcalloc(nfiles, sizeof(hdr_t*));
    hdr_t *h = NULL;
    mplp_ref_t mref = { NULL, -1, 0 };
    int tid0 = -1; int64_t beg0 = 0, end0 = INT64_MAX;
    for (int i = 0; i < nfiles; i++) {
        data[i] = xcalloc(1, sizeof(mplp_aux_t));
        data[i]->fp = sf_open(fn[i], "r");
        if (!data[i]->fp) {
            fprintf(stderr, "[%s] failed to open %s: %s\n", "mpileup", fn[i], strerror(errno));
            ret = 1; goto cleanup;
        }
        data[i]->conf = &conf;
        data[i]->ref = &mref;
        hs[i] = sf_read_header(data[i]->fp);
        if (!hs[i]) {
            fprintf(stderr, "[%s] fail to read the header of %s\n", "mpileup", fn[i]);
            ret = 1; goto cleanup;
        }
        data[i]->h = i ? h : hs[i];
        if (i == 0) h = hs[i];
        if (conf.reg) {
            idx_t *idx = NULL;
            if (data[i]->fp->fmt == FMT_BAM) idx = idx_load_for(fn[i], NULL);
            if (!idx) {
                fprintf(stderr, "[%s] fail to load index for %s\n", "mpileup", fn[i]);
                ret = 1; goto cleanup;
            }
            int tid; int64_t beg, end;
            if (parse_region(hs[i], conf.reg, &tid, &beg, &end, 0) < 0 || tid < 0) {
                fprintf(stderr, "[%s] malformatted region or wrong seqname for %s\n", "mpileup", fn[i]);
                idx_destroy(idx);
                ret = 1; goto cleanup;
            }
            data[i]->iter = idx_query(idx, tid, beg, end);
            if (i == 0) { tid0 = tid; beg0 = beg; end0 = end; }
            idx_destroy(idx);
        }
    }
    fprintf(stderr, "[%s] %d samples in %d input files\n", "mpileup", count_samples(hs, nfiles, fn, conf.flag & MPLP_IGNORE_RG), nfiles);
    {
        FILE *out = stdout;
        if (conf.output_fname) {
            out = fopen(conf.output_fname, "w");
            if (!out) { print_error_errno("mpileup", "failed to write to %s", conf.output_fname); ret = 1; goto cleanup; }
        }
        mplp_t *iter = mplp_init(nfiles, mplp_func, (void**)data);
        if (!no_overlaps) mplp_init_overlaps(iter);
        if (conf.max_depth <= 0) conf.max_depth = INT32_MAX;
        if ((double)conf.max_depth * nfiles > 1 << 20)
            fprintf(stderr, "Max depth is above 1M. Potential memory hog!\n");
        mplp_set_maxcnt(iter, conf.max_depth);
        int *n_plp = xcalloc(nfiles, sizeof(int));
        const pileup1_t **plp = xcalloc(nfiles, sizeof(pileup1_t*));
        int tid, last_tid = -1; int64_t pos, last_pos = -1;
        char *ref = NULL; int64_t ref_len = 0;
        kstr o = {0, 0, NULL}, ks = {0, 0, NULL};
        int r;
        while ((r = mplp_auto(iter, &tid, &pos, n_plp, plp)) > 0) {
            if (conf.reg && (pos < beg0 || pos >= end0)) continue;
            if (!mplp_get_ref(data[0], tid, &ref, &ref_len)) ref = NULL;
            if (conf.all) {
                while (tid > last_tid) {
                    if (last_tid >= 0 && !conf.reg) {
                        char *lref = NULL; int64_t llen = 0;
                        if (!mplp_get_ref(data[0], last_tid, &lref, &llen)) lref = NULL;
                        while (++last_pos < h->tlen[last_tid]) {
                            if (conf.bed && !bed_overlap(conf.bed, hdr_tname(h, last_tid), last_pos, last_pos + 1)) continue;
                            print_empty(&o, &conf, hdr_tname(h, last_tid), last_pos, nfiles, lref, llen);
                            if (o.l > 65536) { fwrite(o.s, 1, o.l, out); o.l = 0; }
                        }
                        if (!mplp_get_ref(data[0], tid, &ref, &ref_len)) ref = NULL;
                    }
                    last_tid++;
                    last_pos = -1;
                    if (conf.all < 2) break;
                }
                while (++last_pos < pos) {
                    if (conf.reg && last_pos < beg0) continue;
                    if (conf.bed && !bed_overlap(conf.bed, hdr_tname(h, tid), last_pos, last_pos + 1)) continue;
                    print_empty(&o, &conf, hdr_tname(h, tid), last_pos, nfiles, ref, ref_len);
                }
                last_tid = tid;
                last_pos = pos;
            }
            if (conf.bed && tid >= 0 && !bed_overlap(conf.bed, hdr_tname(h, tid), pos, pos + 1)) continue;
            ks_puts(&o, hdr_tname(h, tid)); ks_putc(&o, '\t'); ks_puti(&o, pos + 1); ks_putc(&o, '\t');
            ks_putc(&o, (ref && pos < ref_len) ? ref[pos] : 'N');
            for (int i = 0; i < nfiles; i++) {
                int cnt = 0;
                for (int j = 0; j < n_plp[i]; j++) {
                    const pileup1_t *p = plp[i] + j;
                    int q = p->qpos < p->b->core.l_qseq ? rec_qual(p->b)[p->qpos] : 0;
                    if (q >= conf.min_baseQ) ++cnt;
                }
                ks_putc(&o, '\t'); ks_puti(&o, cnt); ks_putc(&o, '\t');
                if (n_plp[i] == 0) {
                    ks_puts(&o, "*\t*");
                    if (conf.flag & MPLP_PRINT_MAPQ) ks_puts(&o, "\t*");
                    if (conf.flag & MPLP_PRINT_QPOS) ks_puts(&o, "\t*");
                    if (conf.flag & MPLP_PRINT_QPOS5) ks_puts(&o, "\t*");
                    if (conf.flag & MPLP_PRINT_QNAME) ks_puts(&o, "\t*");
                    for (int k = 0; k < conf.n_extra; k++) ks_puts(&o, "\t*");
                } else {
                    int n = 0;
                    for (int j = 0; j < n_plp[i]; j++) {
                        const pileup1_t *p = plp[i] + j;
                        int q = p->qpos < p->b->core.l_qseq ? rec_qual(p->b)[p->qpos] : 0;
                        if (q >= conf.min_baseQ) { n++; pileup_seq(&o, p, pos, ref_len, ref, &ks, &conf); }
                    }
                    if (!n) ks_putc(&o, '*');
                    n = 0;
                    ks_putc(&o, '\t');
                    for (int j = 0; j < n_plp[i]; j++) {
                        const pileup1_t *p = plp[i] + j;
                        int q = p->qpos < p->b->core.l_qseq ? rec_qual(p->b)[p->qpos] : 0;
                        if (q >= conf.min_baseQ) {
                            q = q + 33 < 126 ? q + 33 : 126;
                            ks_putc(&o, q); n++;
                        }
                    }
                    if (!n) ks_putc(&o, '*');
                    if (conf.flag & MPLP_PRINT_MAPQ) {
                        n = 0; ks_putc(&o, '\t');
                        for (int j = 0; j < n_plp[i]; j++) {
                            const pileup1_t *p = plp[i] + j;
                            int q = p->qpos < p->b->core.l_qseq ? rec_qual(p->b)[p->qpos] : 0;
                            if (q < conf.min_baseQ) continue;
                            int mq = p->b->core.qual + 33; if (mq > 126) mq = 126;
                            ks_putc(&o, mq); n++;
                        }
                        if (!n) ks_putc(&o, '*');
                    }
                    if (conf.flag & (MPLP_PRINT_QPOS | MPLP_PRINT_QPOS5)) {
                        for (int which = 0; which < 2; which++) {
                            if (which == 0 && !(conf.flag & MPLP_PRINT_QPOS)) continue;
                            if (which == 1 && !(conf.flag & MPLP_PRINT_QPOS5)) continue;
                            n = 0; ks_putc(&o, '\t');
                            for (int j = 0; j < n_plp[i]; j++) {
                                const pileup1_t *p = plp[i] + j;
                                int q = p->qpos < p->b->core.l_qseq ? rec_qual(p->b)[p->qpos] : 0;
                                if (q < conf.min_baseQ) continue;
                                if (n > 0) ks_putc(&o, conf.sep);
                                int v = p->qpos + 1;
                                if (which == 1 && (p->b->core.flag & FREVERSE)) v = p->b->core.l_qseq - p->qpos;
                                ks_puti(&o, v); n++;
                            }
                            if (!n) ks_putc(&o, '*');
                        }
                    }
                    if (conf.flag & MPLP_PRINT_QNAME) {
                        n = 0; ks_putc(&o, '\t');
                        for (int j = 0; j < n_plp[i]; j++) {
                            const pileup1_t *p = plp[i] + j;
                            int q = p->qpos < p->b->core.l_qseq ? rec_qual(p->b)[p->qpos] : 0;
                            if (q < conf.min_baseQ) continue;
                            if (n > 0) ks_putc(&o, conf.sep);
                            ks_puts(&o, rec_qname(p->b)); n++;
                        }
                        if (!n) ks_putc(&o, '*');
                    }
                    for (int k = 0; k < conf.n_extra; k++) {
                        n = 0; ks_putc(&o, '\t');
                        for (int j = 0; j < n_plp[i]; j++) {
                            const pileup1_t *p = plp[i] + j;
                            int q = p->qpos < p->b->core.l_qseq ? rec_qual(p->b)[p->qpos] : 0;
                            if (q < conf.min_baseQ) continue;
                            if (n > 0) ks_putc(&o, conf.sep);
                            n++;
                            const core_t *cc = &p->b->core;
                            switch (conf.extra[k].type) {
                            case EX_FLAG: ks_puti(&o, cc->flag); break;
                            case EX_RNAME: ks_puts(&o, hdr_tname(h, cc->tid)); break;
                            case EX_POS: ks_puti(&o, cc->pos + 1); break;
                            case EX_MAPQ: ks_puti(&o, cc->qual); break;
                            case EX_RNEXT: ks_puts(&o, cc->mtid < 0 ? "*" : hdr_tname(h, cc->mtid)); break;
                            case EX_PNEXT: ks_puti(&o, cc->mpos + 1); break;
                            case EX_TLEN: ks_puti(&o, cc->isize); break;
                            case EX_QNAME_E: ks_puts(&o, rec_qname(p->b)); break;
                            case EX_TAG: {
                                uint8_t *t = aux_get(p->b, conf.extra[k].tag);
                                if (!t) { ks_putc(&o, conf.empty); break; }
                                switch (t[0]) {
                                case 'A': ks_putc(&o, t[1]); break;
                                case 'Z': case 'H': ks_puts(&o, (char*)t + 1); break;
                                case 'f': case 'd': ks_printf(&o, "%g", aux2f(t)); break;
                                default: ks_puti(&o, aux2i(t)); break;
                                }
                                break;
                            }
                            }
                        }
                        if (!n) ks_putc(&o, '*');
                    }
                }
            }
            ks_putc(&o, '\n');
            if (o.l > 65536) { fwrite(o.s, 1, o.l, out); o.l = 0; }
        }
        if (r < 0) ret = 1;
        if (conf.all) {
            if (last_tid < 0 && conf.reg && conf.all > 1) {
                last_tid = tid0; last_pos = beg0 - 1;
            }
            while (last_tid >= 0 && last_tid < h->n_targets) {
                char *lref = NULL; int64_t llen = 0;
                if (!mplp_get_ref(data[0], last_tid, &lref, &llen)) lref = NULL;
                while (++last_pos < h->tlen[last_tid]) {
                    if (last_pos >= end0) break;
                    if (conf.bed && !bed_overlap(conf.bed, hdr_tname(h, last_tid), last_pos, last_pos + 1)) continue;
                    print_empty(&o, &conf, hdr_tname(h, last_tid), last_pos, nfiles, lref, llen);
                    if (o.l > 65536) { fwrite(o.s, 1, o.l, out); o.l = 0; }
                }
                last_tid++;
                last_pos = -1;
                if (conf.all < 2 || conf.reg) break;
            }
        }
        fwrite(o.s, 1, o.l, out);
        ks_free(&o); ks_free(&ks);
        free(n_plp); free(plp);
        mplp_destroy(iter);
        if (out != stdout) fclose(out);
    }
cleanup:
    for (int i = 0; i < nfiles; i++) {
        if (data[i]) { if (data[i]->fp) sf_close(data[i]->fp); iter_destroy(data[i]->iter); free(data[i]); }
        hdr_destroy(hs[i]);
        free(fn[i]);
    }
    free(data); free(hs); free(fn); free(mref.ref);
    fai_destroy(conf.fai);
    bed_destroy(conf.bed);
    sm_destroy(conf.rghash);
    free(conf.extra);
    return ret;
}
