{"command":"cd /workspace/src && cat > cmd_depth.c <<'EOF'
/* samtools depth */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include "common.h"

typedef struct {
    samfile_t *fp; hdr_t *h; iter_t *iter;
    rec_t *b; int has; /* buffered record */
    int eof;
} dfile_t;

typedef struct {
    int min_qual, min_mqual, min_len, skip_del, all_pos, remove_overlaps, header;
    int required, excl, incl;
} dopt_t;

static int dfile_next(dfile_t *f, const dopt_t *o) {
    for (;;) {
        int r = f->iter ? iter_next(f->fp, f->iter, f->b) : sf_read(f->fp, f->b);
        if (r < 0) { f->eof = 1; f->has = 0; return r; }
        core_t *c = &f->b->core;
        if (c->tid < 0) continue;
        if (c->flag & o->excl) continue;
        if (o->incl && !(c->flag & o->incl)) continue;
        if (o->required && (c->flag & o->required) != o->required) continue;
        if (c->qual < o->min_mqual) continue;
        if (o->min_len) {
            int64_t ql = 0; uint32_t *cg = rec_cigar(f->b);
            for (uint32_t k = 0; k < c->n_cigar; k++) {
                int op = cig_op(cg[k]);
                if (op == C_MATCH || op == C_INS || op == C_EQUAL || op == C_DIFF) ql += cig_len(cg[k]);
            }
            if (ql < o->min_len) continue;
        }
        f->has = 1;
        return 0;
    }
}

typedef struct { int64_t start, end; } ovl_t;

static void depth_usage(FILE *fp) { fputs(usage_depth, fp); }

int main_depth(int argc, char *argv[]) {
    dopt_t o; memset(&o, 0, sizeof o);
    o.excl = FUNMAP | FSECONDARY | FQCFAIL | FDUP;
    char *reg = NULL, *bedfn = NULL, *listfn = NULL, *outfn = NULL;
    int c, has_idx = 0;
    static const struct option lopts[] = {
        {"min-MQ", required_argument, NULL, 'Q'}, {"min-mq", required_argument, NULL, 'Q'},
        {"min-BQ", required_argument, NULL, 'q'}, {"min-bq", required_argument, NULL, 'q'},
        {"excl-flags", required_argument, NULL, 'G'}, {"exclude-flags", required_argument, NULL, 'G'},
        {"incl-flags", required_argument, NULL, 1}, {"include-flags", required_argument, NULL, 1},
        {"require-flags", required_argument, NULL, 2},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"reference", required_argument, NULL, GO_REFERENCE},
        {"threads", required_argument, NULL, '@'},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "@:q:Q:r:b:Xf:aml:d:Jo:HG:g:s", lopts, NULL)) >= 0) {
        switch (c) {
        case 'a': o.all_pos++; break;
        case 'b': bedfn = optarg; break;
        case 'X': has_idx = 1; break;
        case 'q': o.min_qual = atoi(optarg); break;
        case 'Q': o.min_mqual = atoi(optarg); break;
        case 'r': reg = optarg; break;
        case 'f': listfn = optarg; break;
        case 'l': o.min_len = atoi(optarg); break;
        case 'm': case 'd': break;
        case 'J': o.skip_del = 0; o.skip_del = -1; break;
        case 'o': outfn = optarg; break;
        case 'H': o.header = 1; break;
        case 's': o.remove_overlaps = 1; break;
        case 'g': case 'G': case 1: case 2: {
            int ok; int64_t v = parse_flag_str(optarg, &ok);
            if (!ok || v < 0) { fprintf(stderr, "[%s] Error: Invalid flag string \"%s\"\n", "main_depth", optarg); return 1; }
            if (c == 'g') o.excl &= ~v; else if (c == 'G') o.excl |= v; else if (c == 1) o.incl |= v; else o.required |= v;
            break;
        }
        case '@': case GO_INPUT_FMT_OPTION: case GO_REFERENCE: case GO_VERBOSITY: break;
        default: depth_usage(stderr); return 1;
        }
    }
    int include_del = (o.skip_del == -1);
    char **fns = NULL; int nf = 0;
    if (listfn) {
        FILE *f = fopen(listfn, "r");
        if (!f) { print_error_errno("depth", "Cannot open file list \"%s\"", listfn); return 1; }
        char *line = NULL; size_t cap = 0; ssize_t n;
        while ((n = getline(&line, &cap, f)) >= 0) {
            while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r')) line[--n] = 0;
            if (!n) continue;
            fns = xrealloc(fns, (nf + 1) * sizeof(char*)); fns[nf++] = xstrdup(line);
        }
        free(line); fclose(f);
    } else {
        if (optind == argc && isatty(STDIN_FILENO)) { depth_usage(stdout); return 0; }
        if (optind == argc) { fns = xmalloc(sizeof(char*)); fns[0] = xstrdup("-"); nf = 1; }
        else {
            int n = argc - optind;
            if (has_idx) n /= 2;
            for (int i = 0; i < n; i++) { fns = xrealloc(fns, (nf + 1) * sizeof(char*)); fns[nf++] = xstrdup(argv[optind + i]); }
        }
    }
    bed_t *bed = NULL;
    if (bedfn) {
        bed = bed_read(bedfn);
        if (!bed) { print_error_errno("depth", "Could not read file \"%s\"", bedfn); return 1; }
    }
    dfile_t *df = xcalloc(nf, sizeof(dfile_t));
    int ret = 0;
    hdr_t *h = NULL;
    int rtid = -1; int64_t rbeg = 0, rend = INT64_MAX;
    for (int i = 0; i < nf; i++) {
        df[i].fp = sf_open(fns[i], "r");
        if (!df[i].fp) { print_error_errno("depth", "Could not open \"%s\"", fns[i]); ret = 1; goto done; }
        df[i].h = sf_read_header(df[i].fp);
        if (!df[i].h) { print_error("depth", "Couldn't read header for \"%s\"", fns[i]); ret = 1; goto done; }
        if (!h) h = df[i].h;
        df[i].b = rec_init();
        if (reg) {
            idx_t *idx = (df[i].fp->fmt == FMT_BAM) ? idx_load_for(fns[i], has_idx ? argv[optind + nf + i] : NULL) : NULL;
            if (!idx) { print_error("depth", "cannot find index for \"%s\"", fns[i]); ret = 1; goto done; }
            if (parse_region(df[i].h, reg, &rtid, &rbeg, &rend, 0) < 0 || rtid < 0) {
                print_error("depth", "cannot parse region \"%s\"", reg); idx_destroy(idx); ret = 1; goto done;
            }
            df[i].iter = idx_query(idx, rtid, rbeg, rend);
            idx_destroy(idx);
        }
    }
    FILE *out = stdout;
    if (outfn) {
        out = fopen(outfn, "w");
        if (!out) { print_error_errno("depth", "Cannot open \"%s\" for writing.", outfn); ret = 1; goto done; }
    }
    if (o.header) {
        fputs("#CHROM\tPOS", out);
        for (int i = 0; i < nf; i++) fprintf(out, "\t%s", fns[i]);
        fputc('\n', out);
    }
    for (int i = 0; i < nf; i++) dfile_next(&df[i], &o);
    /* process tid by tid */
    int last_tid = -1;
    int32_t **cov = xcalloc(nf, sizeof(int32_t*));
    int64_t cov_m = 0;
    kstr ob = {0, 0, NULL};
    strmap_t *ov = o.remove_overlaps ? sm_init() : NULL;
    ovl_t *ovs = NULL; int nov = 0, mov = 0;
    for (;;) {
        int tid = INT32_MAX;
        for (int i = 0; i < nf; i++) if (df[i].has && df[i].b->core.tid < tid) tid = df[i].b->core.tid;
        int done_all = (tid == INT32_MAX);
        /* print intermediate empty references for -aa */
        if (o.all_pos > 1 && !reg) {
            int upto = done_all ? h->n_targets : tid;
            for (int t = last_tid + 1; t < upto; t++) {
                int64_t len = h->tlen[t];
                for (int64_t p = 0; p < len; p++) {
                    if (bed && !bed_overlap(bed, h->tname[t], p, p + 1)) continue;
                    ks_puts(&ob, h->tname[t]); ks_putc(&ob, '\t'); ks_puti(&ob, p + 1);
                    for (int i = 0; i < nf; i++) ks_puts(&ob, "\t0");
                    ks_putc(&ob, '\n');
                    if (ob.l > 65536) { fwrite(ob.s, 1, ob.l, out); ob.l = 0; }
                }
            }
        }
        if (done_all) break;
        last_tid = tid;
        int64_t len = h->tlen[tid];
        if (len + 1 > cov_m) {
            for (int i = 0; i < nf; i++) cov[i] = xrealloc(cov[i], (len + 1) * sizeof(int32_t));
            cov_m = len + 1;
        }
        for (int i = 0; i < nf; i++) memset(cov[i], 0, (len + 1) * sizeof(int32_t));
        int64_t maxend = 0;
        for (int i = 0; i < nf; i++) {
            if (ov) { sm_destroy(ov); ov = sm_init(); nov = 0; }
            while (df[i].has && df[i].b->core.tid == tid) {
                rec_t *b = df[i].b;
                int64_t pos = b->core.pos;
                int64_t ostart = -1, oend = -1;
                if (ov && (b->core.flag & FPAIRED) && !(b->core.flag & FMUNMAP) && b->core.mtid == b->core.tid) {
                    int64_t v;
                    if (sm_get(ov, rec_qname(b), &v)) { ostart = ovs[v].start; oend = ovs[v].end; }
                    else if (b->core.mpos >= b->core.pos) {
                        if (nov == mov) { mov = mov ? mov * 2 : 64; ovs = xrealloc(ovs, mov * sizeof(ovl_t)); }
                        ovs[nov].start = b->core.pos; ovs[nov].end = rec_endpos(b);
                        sm_put(ov, rec_qname(b), nov); nov++;
                    }
                }
                uint32_t *cg = rec_cigar(b);
                uint8_t *q = rec_qual(b);
                int64_t qp = 0;
                for (uint32_t k = 0; k < b->core.n_cigar; k++) {
                    int op = cig_op(cg[k]); int64_t l = cig_len(cg[k]);
                    if (op == C_MATCH || op == C_EQUAL || op == C_DIFF) {
                        for (int64_t j = 0; j < l; j++) {
                            int64_t rp = pos + j;
                            if (rp < 0 || rp >= len) continue;
                            if (o.min_qual && b->core.l_qseq && q[qp + j] < o.min_qual) continue;
                            if (rp >= ostart && rp < oend) continue;
                            cov[i][rp]++;
                        }
                        pos += l; qp += l;
                    } else if (op == C_DEL) {
                        if (include_del) {
                            for (int64_t j = 0; j < l; j++) {
                                int64_t rp = pos + j;
                                if (rp < 0 || rp >= len) continue;
                                if (rp >= ostart && rp < oend) continue;
                                cov[i][rp]++;
                            }
                        }
                        pos += l;
                    } else if (op == C_REF_SKIP) pos += l;
                    else if (op == C_INS || op == C_SOFT_CLIP) qp += l;
                }
                if (pos > maxend) maxend = pos;
                dfile_next(&df[i], &o);
            }
        }
        int64_t from = 0, to = len;
        if (reg) { from = rbeg; to = rend < len ? rend : len; }
        if (!o.all_pos && maxend < to) to = maxend;
        for (int64_t p = from; p < to; p++) {
            if (bed && !bed_overlap(bed, h->tname[tid], p, p + 1)) continue;
            if (!o.all_pos) {
                int any = 0;
                for (int i = 0; i < nf; i++) if (cov[i][p]) { any = 1; break; }
                if (!any) continue;
            }
            ks_puts(&ob, h->tname[tid]); ks_putc(&ob, '\t'); ks_puti(&ob, p + 1);
            for (int i = 0; i < nf; i++) { ks_putc(&ob, '\t'); ks_puti(&ob, cov[i][p]); }
            ks_putc(&ob, '\n');
            if (ob.l > 65536) { fwrite(ob.s, 1, ob.l, out); ob.l = 0; }
        }
    }
    if (o.all_pos > 1 && reg && last_tid < 0 && rtid >= 0) {
        int64_t len = h->tlen[rtid];
        int64_t to = rend < len ? rend : len;
        for (int64_t p = rbeg; p < to; p++) {
            if (bed && !bed_overlap(bed, h->tname[rtid], p, p + 1)) continue;
            ks_puts(&ob, h->tname[rtid]); ks_putc(&ob, '\t'); ks_puti(&ob, p + 1);
            for (int i = 0; i < nf; i++) ks_puts(&ob, "\t0");
            ks_putc(&ob, '\n');
        }
    }
    fwrite(ob.s, 1, ob.l, out);
    ks_free(&ob);
    for (int i = 0; i < nf; i++) free(cov[i]);
    free(cov); free(ovs); sm_destroy(ov);
    if (out != stdout) fclose(out);
done:
    for (int i = 0; i < nf; i++) {
        if (df[i].fp) sf_close(df[i].fp);
        hdr_destroy(df[i].h);
        rec_destroy(df[i].b);
        iter_destroy(df[i].iter);
        free(fns[i]);
    }
    free(df); free(fns);
    bed_destroy(bed);
    return ret;
}
