/* samtools coverage */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <limits.h>
#include <sys/ioctl.h>
#include "common.h"
#include "plp.h"

typedef struct {
    int64_t beg, end;
    unsigned n_selected_reads;
    unsigned long long n_covered_bases;
    double summed_coverage, summed_baseQ, summed_mapQ;
    int covered;
} cstats_t;

typedef struct {
    samfile_t *fp; hdr_t *h; iter_t *iter;
    int min_mapQ, min_len, fail_flags, required_flags;
    cstats_t *stats;
} caux_t;

static int cov_read(void *data, rec_t *b) {
    caux_t *a = data;
    int ret;
    for (;;) {
        ret = a->iter ? iter_next(a->fp, a->iter, b) : sf_read(a->fp, b);
        if (ret < 0) break;
        if (a->fail_flags && (b->core.flag & a->fail_flags)) continue;
        if (a->required_flags && (b->core.flag & a->required_flags) != a->required_flags) continue;
        if (b->core.qual < a->min_mapQ) continue;
        if (a->min_len && cigar2qlen(b->core.n_cigar, rec_cigar(b)) < a->min_len) continue;
        if (b->core.tid >= 0 && b->core.tid < a->h->n_targets) {
            a->stats[b->core.tid].n_selected_reads++;
            a->stats[b->core.tid].summed_mapQ += b->core.qual;
        }
        break;
    }
    return ret;
}

static void print_tab_line(FILE *f, const hdr_t *h, const cstats_t *s, int tid) {
    fputs(h->tname[tid], f);
    double rl = (double)s[tid].end - s[tid].beg;
    fprintf(f, "\t%lld\t%lld\t%u\t%llu\t%g\t%g\t%.3g\t%.3g\n",
            (long long)s[tid].beg + 1, (long long)s[tid].end, s[tid].n_selected_reads, s[tid].n_covered_bases,
            100.0 * s[tid].n_covered_bases / rl, s[tid].summed_coverage / rl,
            s[tid].summed_coverage > 0 ? s[tid].summed_baseQ / s[tid].summed_coverage : 0,
            s[tid].n_selected_reads > 0 ? s[tid].summed_mapQ / s[tid].n_selected_reads : 0);
}

static const char *const BLOCK_CHARS2[] = {".", ":"};
static const char *const BLOCK_CHARS8[] = {"\u2581", "\u2582", "\u2583", "\u2584", "\u2585", "\u2586", "\u2587", "\u2588"};

static char *readable_bps(double bp, char *buf) {
    const char *units[] = {"", "K", "M", "G", "T"};
    int i = 0;
    while (bp >= 1000 && i < 4) { bp /= 1000; i++; }
    sprintf(buf, "%0.*f%sbp", i == 0 ? 0 : 2, bp, units[i]);
    return buf;
}

static void set_read_counts_hist(double *hist, int n_bins) { (void)hist; (void)n_bins; }

static void print_hist(FILE *f, const hdr_t *h, const cstats_t *stats, int tid, const uint32_t *hist,
                       int hist_size, int full_utf) {
    int i, col;
    int n_rows = 10;
    const char *const *BLOCK_CHARS = full_utf ? BLOCK_CHARS8 : BLOCK_CHARS2;
    int blockchar_len = full_utf ? 8 : 2;
    double hist_max = 0, hist_data[hist_size];
    for (i = 0; i < hist_size; i++) {
        hist_data[i] = 100.0 * hist[i] / (stats[tid].end - stats[tid].beg) * hist_size;
        if (hist_data[i] > hist_max) hist_max = hist_data[i];
    }
    char buf[32];
    double region_len = stats[tid].end - stats[tid].beg;
    fprintf(f, "%s (%sbp)\n", h->tname[tid], readable_bps(h->tlen[tid], buf));
    (void)set_read_counts_hist;
    double row_bin_size = hist_max / (double)n_rows;
    for (i = n_rows - 1; i >= 0; --i) {
        double current_bin = row_bin_size * i;
        if (i == n_rows - 1) fprintf(f, ">%7.2f%% ", current_bin);
        else fprintf(f, "%7.2f%% ", current_bin);
        fprintf(f, full_utf ? "\u2502" : "|");
        for (col = 0; col < hist_size; ++col) {
            if (hist_data[col] > current_bin) {
                double rem = hist_data[col] - current_bin;
                if (rem >= row_bin_size) fprintf(f, "%s", BLOCK_CHARS[blockchar_len - 1]);
                else {
                    int ci = (int)(rem / row_bin_size * blockchar_len);
                    if (ci >= blockchar_len) ci = blockchar_len - 1;
                    fprintf(f, "%s", BLOCK_CHARS[ci]);
                }
            } else fprintf(f, " ");
        }
        fprintf(f, full_utf ? "\u2502" : "|");
        fputc(' ', f);
        switch (i) {
        case 9: fprintf(f, "Number of reads: %i", stats[tid].n_selected_reads); break;
        case 8: if (stats[tid].n_selected_reads > 0) fprintf(f, "    (%i filtered)", 0); break;
        case 7: fprintf(f, "Covered bases:   %sbp", readable_bps(stats[tid].n_covered_bases, buf)); break;
        case 6: fprintf(f, "Percent covered: %.4g%%", 100.0 * stats[tid].n_covered_bases / region_len); break;
        case 5: fprintf(f, "Mean coverage:   %.3gx", stats[tid].summed_coverage / region_len); break;
        case 4: fprintf(f, "Mean baseQ:      %.3g", stats[tid].summed_coverage ? stats[tid].summed_baseQ / stats[tid].summed_coverage : 0); break;
        case 3: fprintf(f, "Mean mapQ:       %.3g", stats[tid].n_selected_reads ? stats[tid].summed_mapQ / stats[tid].n_selected_reads : 0); break;
        case 1: fprintf(f, "Histo bin width: %sbp", readable_bps((double)(stats[tid].end - stats[tid].beg) / hist_size, buf)); break;
        case 0: fprintf(f, "Histo max bin:   %.5g%%", hist_max); break;
        }
        fputc('\n', f);
    }
    fprintf(f, "%8s ", " ");
    fprintf(f, full_utf ? "\u2514" : "+");
    for (col = 0; col < hist_size; ++col) fprintf(f, full_utf ? "\u2500" : "-");
    fprintf(f, full_utf ? "\u2518" : "+");
    fputc('\n', f);
    fprintf(f, "%8s %-12s", " ", readable_bps(stats[tid].beg + 1, buf));
    for (col = 0; col < hist_size - 24; ++col) fputc(' ', f);
    fprintf(f, "%12s\n", readable_bps(stats[tid].end, buf));
}

