    case 'a': return 't'; case 'c': return 'g'; case 'g': return 'c'; case 't': return 'a';
    case 'M': return 'K'; case 'R': return 'Y'; case 'W': return 'W'; case 'S': return 'S';
    case 'Y': return 'R'; case 'K': return 'M'; case 'V': return 'B'; case 'H': return 'D';
    case 'D': return 'H'; case 'B': return 'V'; case 'N': return 'N'; case '=': return '=';
    }
    return c;
}

static bgzf_t *open_out(const char *fn, int level) {
    size_t l = strlen(fn);
    int gz = (l > 3 && strcmp(fn + l - 3, ".gz") == 0) || (l > 5 && strcmp(fn + l - 5, ".bgzf") == 0);
    return bg_open_write(fn, gz ? BG_BGZF : BG_RAW, gz ? level : 0);
}

static void append_tag_str(kstr *s, const uint8_t *p) {
    /* p points at tag name; format TAG:T:VAL */
    const uint8_t *nx;
    aux_format1(s, p, &nx);
}

static int make_line(const hdr_t *h, rec_t *b, kstr *out, const fqopts_t *o, int which) {
    (void)h;
    core_t *c = &b->core;
    int len = c->l_qseq;
    uint8_t *seq = rec_seq(b), *qual = rec_qual(b);
    int qs = 0, qe = len;
    if (o->no_sc && c->n_cigar) {
        uint32_t *cg = rec_cigar(b);
        if (cig_op(cg[0]) == C_SOFT_CLIP) qs = cig_len(cg[0]);
        else if (c->n_cigar > 1 && cig_op(cg[0]) == C_HARD_CLIP && cig_op(cg[1]) == C_SOFT_CLIP) qs = cig_len(cg[1]);
        int k = c->n_cigar - 1;
        if (cig_op(cg[k]) == C_SOFT_CLIP) qe = len - cig_len(cg[k]);
        else if (k > 0 && cig_op(cg[k]) == C_HARD_CLIP && cig_op(cg[k-1]) == C_SOFT_CLIP) qe = len - cig_len(cg[k-1]);
        if (qe < qs) qe = qs;
    }
    int n = qe - qs;
    char *s = xmalloc(n + 1), *q = xmalloc(n + 1);
    for (int i = 0; i < n; i++) s[i] = seq_nt16_str[seqi(seq, qs + i)];
    s[n] = 0;
    uint8_t *oq = o->use_oq ? aux_get(b, "OQ") : NULL;
    if (oq && oq[0] == 'Z' && (int)strlen((char*)oq + 1) == len) {
        for (int i = 0; i < n; i++) q[i] = oq[1 + qs + i];
    } else if (len && qual[0] == 0xff) {
        for (int i = 0; i < n; i++) q[i] = 33 + o->def_qual;
    } else {
        for (int i = 0; i < n; i++) q[i] = qual[qs + i] + 33;
    }
    q[n] = 0;
    if (c->flag & FREVERSE) {
        for (int i = 0, j = n - 1; i < j; i++, j--) {
            char t = s[i]; s[i] = compl(s[j]); s[j] = compl(t);
            t = q[i]; q[i] = q[j]; q[j] = t;
        }
        if (n & 1) s[n/2] = compl(s[n/2]);
    }
    out->l = 0;
    ks_putc(out, o->is_fasta ? '>' : '@');
    ks_puts(out, rec_qname(b));
    if (o->umi) {
        for (int i = 0; i < o->n_umi_tags; i++) {
            uint8_t *u = aux_get(b, o->umi_tags[i]);
            if (u && u[0] == 'Z') { ks_putc(out, '_'); ks_puts(out, (char*)u + 1); break; }
        }
    }
    if (o->has12) {
        if ((c->flag & FREAD1) && !(c->flag & FREAD2)) ks_puts(out, "/1");
        else if ((c->flag & FREAD2) && !(c->flag & FREAD1)) ks_puts(out, "/2");
    }
    if (o->illumina) {
        ks_putc(out, ' ');
        ks_putc(out, (c->flag & FREAD2) && !(c->flag & FREAD1) ? '2' : '1');
        ks_puts(out, (c->flag & FQCFAIL) ? ":Y:0:" : ":N:0:");
        uint8_t *bc = aux_get(b, o->barcode_tag);
        if (bc && bc[0] == 'Z') {
            for (const char *p = (char*)bc + 1; *p; p++) ks_putc(out, isalpha((unsigned char)*p) ? toupper((unsigned char)*p) : (*p == '-' ? '+' : *p));
        }
    }
    if (o->copy_tags) {
        if (o->all_tags) {
            uint8_t *p = rec_aux(b), *e = b->data + b->l_data;
            while (p + 3 <= e) {
                ks_putc(out, '\t');
                const uint8_t *nx;
                aux_format1(out, p, &nx);
                p = (uint8_t*)nx;
            }
        } else {
            for (int i = 0; i < o->ntags; i++) {
                uint8_t *t = aux_get(b, o->tags[i]);
                if (t) { ks_putc(out, '\t'); append_tag_str(out, t - 2); }
            }
        }
    }
    ks_putc(out, '\n');
    ks_puts(out, s);
    ks_putc(out, '\n');
    if (!o->is_fasta) {
        ks_puts(out, "+\n");
        ks_puts(out, q);
        ks_putc(out, '\n');
    }
    free(s); free(q);
    (void)which;
    return 0;
}

static int fq_main(int argc, char *argv[], int is_fasta) {
    fqopts_t o; memset(&o, 0, sizeof o);
    o.is_fasta = is_fasta;
    o.flag_off = FSECONDARY | FSUPPLEMENTARY;
    o.has12 = 1; o.def_qual = 1; o.level = 1;
    strcpy(o.sc_aux, "s0");
    o.barcode_tag = "BC"; o.quality_tag = "QT";
    char *umitags = "RX,OX";
    int c;
    const char *usage = is_fasta ? usage_fasta : usage_fastq;
    static const struct option lopts[] = {
        {"tag", required_argument, NULL, 'd'}, {"tag-file", required_argument, NULL, 'D'},
        {"require-flags", required_argument, NULL, 'f'}, {"excl-flags", required_argument, NULL, 'F'},
        {"exclude-flags", required_argument, NULL, 'F'}, {"rf", required_argument, NULL, 1},
        {"incl-flags", required_argument, NULL, 1}, {"include-flags", required_argument, NULL, 1},
        {"i1", required_argument, NULL, 2}, {"i2", required_argument, NULL, 3},
        {"barcode-tag", required_argument, NULL, 4}, {"quality-tag", required_argument, NULL, 5},
        {"index-format", required_argument, NULL, 6}, {"no-sc", no_argument, NULL, 7},
        {"sc-aux", required_argument, NULL, 8}, {"no-sc-bkp", no_argument, NULL, 9},
        {"UMI", no_argument, NULL, 'U'}, {"umi", no_argument, NULL, 'U'},
        {"UMI-tag", required_argument, NULL, 10}, {"umi-tag", required_argument, NULL, 10},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"reference", required_argument, NULL, GO_REFERENCE},
        {"threads", required_argument, NULL, '@'},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "0:1:2:o:f:F:G:niNOs:c:tT:v:@:d:D:U", lopts, NULL)) >= 0) {
        switch (c) {
        case '0': o.fnr[0] = optarg; break;
        case '1': o.fnr[1] = optarg; break;
        case '2': o.fnr[2] = optarg; break;
        case 'o': o.fn_o = optarg; break;
        case 'f': case 'F': case 'G': case 1: {
            int ok; int64_t v = parse_flag_str(optarg, &ok);
            if (!ok || v < 0) { fprintf(stderr, "Invalid flag \"%s\"\n", optarg); fputs(usage, stderr); return 1; }
            if (c == 'f') o.flag_on |= v; else if (c == 'F') o.flag_off = v; else if (c == 'G') o.flag_alloff |= v; else o.flag_anyon |= v;
            break;
        }
        case 'n': o.has12 = 0; break;
        case 'N': o.has12always = 1; break;
        case 'i': o.illumina = 1; break;
        case 'O': o.use_oq = 1; break;
        case 's': o.fnse = optarg; break;
        case 'c': o.level = atoi(optarg); if (o.level < 0) o.level = 0; if (o.level > 9) o.level = 9; break;
        case 't': {
            o.copy_tags = 1;
            const char *t3[] = { "RG", "BC", "QT" };
            for (int i = 0; i < 3; i++) { o.tags = xrealloc(o.tags, (o.ntags + 1) * sizeof(char*)); o.tags[o.ntags++] = xstrdup(t3[i]); }
            break;
        }
        case 'T': {
            o.copy_tags = 1;
            if (strcmp(optarg, "*") == 0) { o.all_tags = 1; break; }
            char *d = xstrdup(optarg), *save = NULL;
            for (char *t = strtok_r(d, ",", &save); t; t = strtok_r(NULL, ",", &save)) {
                o.tags = xrealloc(o.tags, (o.ntags + 1) * sizeof(char*)); o.tags[o.ntags++] = xstrdup(t);
            }
            free(d);
            break;
        }
        case 'v': o.def_qual = atoi(optarg); break;
        case 'd': {
            o.has_tag = 1;
            o.tag_name = xstrdup(optarg);
            char *col = strchr(o.tag_name, ':');
            if (col) { *col = 0; if (!o.tag_vals) o.tag_vals = sm_init(); sm_put(o.tag_vals, col + 1, 1); }
            break;
        }
        case 'D': {
            o.has_tag = 1;
            o.tag_name = xstrdup(optarg);
            char *col = strchr(o.tag_name, ':');
            if (!col) { fputs(usage, stderr); return 1; }
            *col = 0;
            FILE *f = fopen(col + 1, "r");
            if (!f) { print_error_errno(is_fasta ? "fasta" : "fastq", "failed to open \"%s\"", col + 1); return 1; }
            if (!o.tag_vals) o.tag_vals = sm_init();
            char buf[4096];
            while (fscanf(f, "%4095s", buf) == 1) sm_put(o.tag_vals, buf, 1);
            fclose(f);
            break;
        }
        case 'U': o.umi = 1; break;
        case 2: o.fni1 = optarg; break;
        case 3: o.fni2 = optarg; break;
        case 4: o.barcode_tag = optarg; break;
        case 5: o.quality_tag = optarg; break;
        case 6: o.index_format = optarg; break;
        case 7: o.no_sc = 1; break;
        case 8: strncpy(o.sc_aux, optarg, 2); o.sc_aux[2] = 0; break;
        case 9: o.no_sc_bkp = 1; break;
        case 10: umitags = optarg; break;
        case '@': case GO_INPUT_FMT_OPTION: case GO_REFERENCE: case GO_VERBOSITY: break;
        default: fputs(usage, stderr); return 1;
        }
    }
    {
        char *d = xstrdup(umitags), *save = NULL;
        for (char *t = strtok_r(d, ",", &save); t; t = strtok_r(NULL, ",", &save)) {
            o.umi_tags = xrealloc(o.umi_tags, (o.n_umi_tags + 1) * sizeof(char*)); o.umi_tags[o.n_umi_tags++] = xstrdup(t);
        }
        free(d);
    }
    if (o.fn_o) { if (!o.fnr[1]) o.fnr[1] = o.fn_o; if (!o.fnr[2]) o.fnr[2] = o.fn_o; }
    if (o.has12always) o.has12 = 1;
    else if (o.has12 && o.fnr[1] && o.fnr[2] && strcmp(o.fnr[1], o.fnr[2]) != 0) o.has12 = 0;
    const char *fn = optind < argc ? argv[optind] : "-";
    if (optind == argc && isatty(STDIN_FILENO)) { fputs(usage, stdout); return 0; }
    if (argc - optind > 1) { fputs(usage, stderr); return 1; }
    samfile_t *fp = sf_open(fn, "r");
    if (!fp) { print_error_errno(is_fasta ? "fasta" : "fastq", "Cannot read file \"%s\"", fn); return 1; }
    hdr_t *h = sf_read_header(fp);
    if (!h) { fprintf(stderr, "Failed to read header for \"%s\"\n", fn); sf_close(fp); return 1; }
    /* outputs */
    bgzf_t *outs[3] = {0}, *sing = NULL, *stdo = NULL;
    const char *names[3];
    for (int i = 0; i < 3; i++) names[i] = o.fnr[i];
    int ret = 0;
    for (int i = 0; i < 3; i++) {
        if (!names[i]) {
            if (!stdo) stdo = bg_open_write("-", BG_RAW, 0);
            outs[i] = stdo;
            continue;
        }
        int dup = -1;
        for (int j = 0; j < i; j++) if (names[j] && strcmp(names[j], names[i]) == 0) dup = j;
        if (dup >= 0) { outs[i] = outs[dup]; continue; }
        outs[i] = open_out(names[i], o.level);
        if (!outs[i]) { print_error_errno(is_fasta ? "fasta" : "fastq", "Cannot write to \"%s\"", names[i]); ret = 1; goto done; }
    }
    if (o.fnse) {
        for (int i = 0; i < 3; i++) if (names[i] && strcmp(names[i], o.fnse) == 0) sing = outs[i];
        if (!sing) sing = open_out(o.fnse, o.level);
    }
    {
        rec_t *b = rec_init(), *prev = NULL;
        kstr line = {0, 0, NULL}, line2 = {0, 0, NULL};
        int64_t n_reads = 0, n_single = 0;
        int r;
        while ((r = sf_read(fp, b)) >= 0) {
            core_t *cc = &b->core;
            if (cc->flag & o.flag_off) continue;
            if ((cc->flag & o.flag_on) != o.flag_on) continue;
            if (o.flag_anyon && !(cc->flag & o.flag_anyon)) continue;
            if (o.flag_alloff && (cc->flag & o.flag_alloff) == o.flag_alloff) continue;
            if (o.has_tag) {
                uint8_t *t = aux_get(b, o.tag_name);
                if (!t) continue;
                if (o.tag_vals) {
                    char buf[64]; const char *v = NULL;
                    if (t[0] == 'Z' || t[0] == 'H') v = (char*)t + 1;
                    else if (t[0] == 'A') { buf[0] = t[1]; buf[1] = 0; v = buf; }
                    else if (strchr("cCsSiI", t[0])) { snprintf(buf, sizeof buf, "%lld", (long long)aux2i(t)); v = buf; }
                    if (!v || !sm_has(o.tag_vals, v)) continue;
                }
            }
            ++n_reads;
            int which = ((cc->flag & FREAD1) ? 1 : 0) | ((cc->flag & FREAD2) ? 2 : 0);
            if (which == 3) which = 0;
            if (!sing) {
                make_line(h, b, &line, &o, which);
                bg_write(outs[which], line.s, line.l);
            } else {
                if (prev) {
                    if (strcmp(rec_qname(prev), rec_qname(b)) == 0) {
                        int wp = ((prev->core.flag & FREAD1) ? 1 : 0) | ((prev->core.flag & FREAD2) ? 2 : 0);
                        if (wp == 3) wp = 0;
                        make_line(h, prev, &line, &o, wp);
                        make_line(h, b, &line2, &o, which);
                        if (wp == 1 && which == 2) { bg_write(outs[1], line.s, line.l); bg_write(outs[2], line2.s, line2.l); }
                        else if (wp == 2 && which == 1) { bg_write(outs[1], line2.s, line2.l); bg_write(outs[2], line.s, line.l); }
                        else { bg_write(outs[wp], line.s, line.l); bg_write(outs[which], line2.s, line2.l); }
                        rec_destroy(prev); prev = NULL;
                        continue;
                    } else {
                        int wp = ((prev->core.flag & FREAD1) ? 1 : 0) | ((prev->core.flag & FREAD2) ? 2 : 0);
                        if (wp == 3) wp = 0;
                        make_line(h, prev, &line, &o, wp);
                        if (wp == 0) bg_write(outs[0], line.s, line.l);
                        else { bg_write(sing, line.s, line.l); n_single++; }
                        rec_destroy(prev); prev = NULL;
                    }
                }
                prev = rec_dup(b);
            }
        }
        if (prev) {
            int wp = ((prev->core.flag & FREAD1) ? 1 : 0) | ((prev->core.flag & FREAD2) ? 2 : 0);
            if (wp == 3) wp = 0;
            make_line(h, prev, &line, &o, wp);
            if (wp == 0) bg_write(outs[0], line.s, line.l);
            else { bg_write(sing, line.s, line.l); n_single++; }
            rec_destroy(prev);
        }
        if (r < -1) { fprintf(stderr, "[%s] Failed to read file\n", "bam2fq_mainloop"); ret = 1; }
        fprintf(stderr, "[M::%s] discarded %lld singletons\n", "bam2fq_mainloop", (long long)n_single);
        fprintf(stderr, "[M::%s] processed %lld reads\n", "bam2fq_mainloop", (long long)n_reads);
        ks_free(&line); ks_free(&line2);
        rec_destroy(b);
    }
done:
    for (int i = 0; i < 3; i++) {
        if (!outs[i]) continue;
        bgzf_t *x = outs[i];
        for (int j = i + 1; j < 3; j++) if (outs[j] == x) outs[j] = NULL;
        if (sing == x) sing = NULL;
        bg_close(x);
    }
    if (sing) bg_close(sing);
    hdr_destroy(h);
    sf_close(fp);
    (void)comp_tab;
    return ret;
}

int main_fastq(int argc, char *argv[]) { return fq_main(argc, argv, 0); }
int main_fasta(int argc, char *argv[]) { return fq_main(argc, argv, 1); }
