        if (!ga.out_fmt && (f == 0 || strcmp(fnout, "-") == 0)) { strcpy(mode, "wb"); if (level >= 0) { char t[3] = { '0' + (level > 9 ? 9 : level), 0 }; strcat(mode, t); } }
