        if (!out) { print_error_errno("merge", "failed to create \"%s\"", fnout); ret = 1; goto done; }
        sf_write_header(out, hout);
        for (int i = 0; i < nf; i++) m_next(&in[i]);
        for (;;) {
            int best = -1;
            for (int i = 0; i < nf; i++) {
                if (!in[i].has) continue;
                if (best < 0 || m_cmp_core(in[i].b, in[best].b) < 0) best = i;
            }
            if (best < 0) break;
            sf_write(out, hout, in[best].b);
