/* ---------------- cat ---------------- */
static int raw_copy_bam(bgzf_t *out, const char *fn) {
    bgzf_t *in = bg_open_read(fn);
    if (!in) return -1;
    samfile_t tmp; memset(&tmp, 0, sizeof tmp);
    /* skip header */
    uint8_t magic[4]; int32_t l_text, n_ref;
    if (bg_read(in, magic, 4) != 4 || memcmp(magic, "BAM\1", 4)) { bg_close(in); return -2; }
    bg_read(in, &l_text, 4);
    char *t = xmalloc(l_text + 1); bg_read(in, t, l_text); free(t);
    bg_read(in, &n_ref, 4);
    for (int i = 0; i < n_ref; i++) {
        int32_t ln; bg_read(in, &ln, 4);
        char *nm = xmalloc(ln + 1); bg_read(in, nm, ln); free(nm);
        uint32_t lr; bg_read(in, &lr, 4);
    }
    if (in->upos < in->ulen) {
        bg_write(out, in->ubuf + in->upos, in->ulen - in->upos);
        bg_flush(out);
    }
    /* raw copy remaining compressed data, skipping a trailing EOF block */
    int64_t off = bg_raw_tell(in);
    int fd = in->fd;
    lseek(fd, off, SEEK_SET);
    kstr data = {0, 0, NULL};
    uint8_t buf[65536]; ssize_t n;
    while ((n = read(fd, buf, sizeof buf)) > 0) ks_putsn(&data, (char*)buf, n);
    static const uint8_t eofm[28] = "\037\213\010\4\0\0\0\0\0\377\6\0\102\103\2\0\033\0\3\0\0\0\0\0\0\0\0\0";
    size_t len = data.l;
    int warn = 0;
    if (len >= 28) {
        const uint8_t *e = (uint8_t*)data.s + len - 28;
        uint32_t isize; memcpy(&isize, e + 24, 4);
        if (e[0] == 0x1f && e[1] == 0x8b && isize == 0) len -= 28;
        else warn = 1;
    }
    if (warn) {
        fprintf(stderr, "[%s] WARNING: Unexpected block structure in file '%s'. Possible output corruption.\n", "bam_cat", fn);
    }
    (void)eofm;
    if (len) {
        bg_flush(out);
        ssize_t w = 0; size_t p = 0;
        while (p < len && (w = write(out->fd, data.s + p, len - p)) > 0) p += w;
        out->out_addr += len;
    }
    ks_free(&data);
    bg_close(in);
    return 0;
}

int main_cat(int argc, char *argv[]) {
    int c, no_pg = 0;
    char *outfn = "-", *hfn = NULL, *listfn = NULL;
    static const struct option lopts[] = {
        {"no-PG", no_argument, NULL, 1},
        {"output-fmt-option", required_argument, NULL, GO_OUTPUT_FMT_OPTION},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "h:o:b:r:p:fq@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'h': hfn = optarg; break;
        case 'o': outfn = optarg; break;
        case 'b': listfn = optarg; break;
        case 1: no_pg = 1; break;
        case 'r': case 'p': case 'f': case 'q': case '@': case GO_OUTPUT_FMT_OPTION: case GO_VERBOSITY: break;
        default: fputs(usage_cat, stderr); return 1;
        }
    }
    char **fns = NULL; int nf = 0;
    if (listfn) {
        FILE *f = fopen(listfn, "r");
        if (!f) { print_error_errno("cat", "Couldn't open file of input filenames \"%s\"", listfn); return 1; }
        char *line = NULL; size_t cap = 0; ssize_t n;
        while ((n = getline(&line, &cap, f)) >= 0) {
            while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r')) line[--n] = 0;
            if (!n) continue;
            fns = xrealloc(fns, (nf + 1) * sizeof(char*)); fns[nf++] = xstrdup(line);
        }
        free(line); fclose(f);
    }
    for (int i = optind; i < argc; i++) { fns = xrealloc(fns, (nf + 1) * sizeof(char*)); fns[nf++] = xstrdup(argv[i]); }
    if (nf == 0) { fputs(usage_cat, stderr); return 1; }
    hdr_t *h = NULL;
    if (hfn) {
        samfile_t *hf = sf_open(hfn, "r");
        if (!hf || !(h = sf_read_header(hf))) { fprintf(stderr, "[%s] ERROR: couldn't read header from '%s'.\n", "main_cat", hfn); if (hf) sf_close(hf); return 1; }
        sf_close(hf);
    } else {
        samfile_t *f0 = sf_open(fns[0], "r");
        if (!f0) { print_error_errno("cat", "failed to open file '%s'", fns[0]); return 1; }
        if (f0->fmt != FMT_BAM) {
            fprintf(stderr, "[%s] ERROR: input is not BAM or CRAM\n", "main_cat");
            sf_close(f0); return 1;
        }
        h = sf_read_header(f0);
        sf_close(f0);
        if (!h) { fprintf(stderr, "[%s] ERROR: couldn't read header from '%s'.\n", "main_cat", fns[0]); return 1; }
    }
    add_pg(h, no_pg);
    samfile_t *out = sf_open(outfn, "wb");
    if (!out) { print_error_errno("cat", "fail to open output file '%s'", outfn); hdr_destroy(h); return 1; }
    sf_write_header(out, h);
