    for (int i = 0; i < nf; i++) {
        int r = raw_copy_bam(out->bg, fns[i]);
        if (r < 0) { fprintf(stderr, "[%s] ERROR: fail to open file '%s'.\n", "bam_cat", fns[i]); ret = 1; break; }
    }
    sf_close(out);
    hdr_destroy(h);
    for (int i = 0; i < nf; i++) free(fns[i]);
    free(fns);
    return ret;
}
