static int m_cmp_core(const rec_t *a, const rec_t *b) {
    if (m_by_tag) {
        uint8_t *ta = aux_get(a, m_tag), *tb = aux_get(b, m_tag);
        int t;
        if (!ta || !tb) t = ta ? 1 : (tb ? -1 : 0);
