    int c, no_pg = 0;
    char *outfn = "-", *hfn = NULL, *listfn = NULL;
    static const struct option lopts[] = {
        {"no-PG", no_argument, NULL, 1},
        {"output-fmt-option", required_argument, NULL, GO_OUTPUT_FMT_OPTION},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "h:o:b:r:p:fq@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'h': hfn = optarg; break;
        case 'o': outfn = optarg; break;
        case 'b': listfn = optarg; break;
        case 1: no_pg = 1; break;
        case 'r': case 'p': case 'f': case 'q': case '@': case GO_OUTPUT_FMT_OPTION: case GO_VERBOSITY: break;
        default: fputs(usage_cat, stderr); return 1;
        }
    }
    char **fns = NULL; int nf = 0;
    if (listfn) {
        FILE *f = fopen(listfn, "r");
        if (!f) { print_error_errno("cat", "Couldn't open file of input filenames \"%s\"", listfn); return 1; }
        char *line = NULL; size_t cap = 0; ssize_t n;
        while ((n = getline(&line, &cap, f)) >= 0) {
            while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r')) line[--n] = 0;
            if (!n) continue;
            fns = xrealloc(fns, (nf + 1) * sizeof(char*)); fns[nf++] = xstrdup(line);
        }
        free(line); fclose(f);
    }
    for (int i = optind; i < argc; i++) { fns = xrealloc(fns, (nf + 1) * sizeof(char*)); fns[nf++] = xstrdup(argv[i]); }
    if (nf == 0) { fputs(usage_cat, stderr); return 1; }
    hdr_t *h = NULL;
    if (hfn) {
        samfile_t *hf = sf_open(hfn, "r");
        if (!hf || !(h = sf_read_header(hf))) { fprintf(stderr, "[%s] ERROR: couldn't read header from '%s'.\n", "main_cat", hfn); if (hf) sf_close(hf); return 1; }
        sf_close(hf);
    } else {
        samfile_t *f0 = sf_open(fns[0], "r");
        if (!f0) { print_error_errno("cat", "failed to open file '%s'", fns[0]); return 1; }
        if (f0->fmt != FMT_BAM) {
            fprintf(stderr, "[%s] ERROR: input is not BAM or CRAM\n", "main_cat");
            sf_close(f0); return 1;
        }
        h = sf_read_header(f0);
        sf_close(f0);
        if (!h) { fprintf(stderr, "[%s] ERROR: couldn't read header from '%s'.\n", "main_cat", fns[0]); return 1; }
    }
    add_pg(h, no_pg);
    samfile_t *out = sf_open(outfn, "wb");
    if (!out) { print_error_errno("cat", "fail to open output file '%s'", outfn); hdr_destroy(h); return 1; }
    sf_write_header(out, h);
    int ret = 0;
    for (int i = 0; i < nf; i++) {
        int r = raw_copy_bam(out->bg, fns[i]);
        if (r < 0) { fprintf(stderr, "[%s] ERROR: fail to open file '%s'.\n", "bam_cat", fns[i]); ret = 1; break; }
    }
    sf_close(out);
    hdr_destroy(h);
    for (int i = 0; i < nf; i++) free(fns[i]);
    free(fns);
    return ret;
}
