int sam_cap_mapq(rec_t *b, const char *ref, int64_t ref_len, int thres) {
    uint8_t *seq = rec_seq(b), *qual = rec_qual(b);
    uint32_t *cigar = rec_cigar(b);
    core_t *c = &b->core;
    int i, y, mm, q, len, clip_l, clip_q;
    int64_t x;
    double t;
    if (thres < 0) thres = 40;
    mm = q = len = clip_l = clip_q = 0;
    for (i = y = 0, x = c->pos; i < (int)c->n_cigar; ++i) {
        int j, l = cigar[i] >> 4, op = cigar[i] & 0xf;
        if (op == C_MATCH || op == C_EQUAL || op == C_DIFF) {
            for (j = 0; j < l; ++j) {
                int c1, c2;
                if (x + j >= ref_len || ref[x+j] == '\0') break;
                c1 = seqi(seq, y + j); c2 = seq_nt16_table[(unsigned char)ref[x+j]];
                if (c2 != 15 && c1 != 15 && qual[y+j] >= 13) {
                    ++len;
                    if (c1 && c1 != c2 && qual[y+j] >= 13) {
                        ++mm;
                        q += qual[y+j] > 33 ? 33 : qual[y+j];
                    }
                }
            }
            if (j < l) break;
            x += l; y += l; len += l;
        } else if (op == C_DEL) {
            for (j = 0; j < l; ++j) if (x + j >= ref_len || ref[x+j] == '\0') break;
            if (j < l) break;
            x += l;
        } else if (op == C_SOFT_CLIP) {
            for (j = 0; j < l; ++j) clip_q += qual[y+j];
            clip_l += l;
            y += l;
        } else if (op == C_HARD_CLIP) {
            clip_q += 13 * l;
            clip_l += l;
        } else if (op == C_INS) y += l;
        else if (op == C_REF_SKIP) x += l;
    }
    for (i = 0, t = 1; i < mm; ++i) t *= (double)len / (i + 1);
    t = q - 4.343 * log(t) + clip_q / 5.;
    if (t > thres) return -1;
    if (t < 0) t = 0;
    t = sqrt((thres - t) / thres) * thres;
    return (int)(t + .499);
}
