/* Base alignment quality (BAQ) via banded glocal HMM, and mapping-quality capping */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "sam.h"

typedef struct { float d, e; int bw; } probaln_par_t;

#define EI .25
#define EM .33333333333
static float g_qual2prob[256];
#define set_u(u, b, i, k) { int x=(i)-(b); x=x>0?x:0; (u)=((k)-x+1)*3; }

int probaln_glocal(const uint8_t *_ref, int l_ref, const uint8_t *_query, int l_query, const uint8_t *iqual,
                   const probaln_par_t *c, int *state, uint8_t *q) {
    double **f, **b = 0, *s, m[9], sI, sM, bI, bM, pb;
    float *qual, *_qual;
    const uint8_t *ref, *query;
    int bw, bw2, i, k, is_backward = 1, Pr;
    if (l_ref <= 0 || l_query <= 0) return 0;
    is_backward = state && q ? 1 : 0;
    ref = _ref - 1; query = _query - 1;
    bw = l_ref > l_query ? l_ref : l_query;
    if (bw > c->bw) bw = c->bw;
    if (bw < abs(l_ref - l_query)) bw = abs(l_ref - l_query);
    bw2 = bw * 2 + 1;
    f = calloc(l_query + 1, sizeof(double*));
    if (is_backward) b = calloc(l_query + 1, sizeof(double*));
    for (i = 0; i <= l_query; ++i) {
        f[i] = calloc(bw2 * 3 + 6, sizeof(double));
        if (is_backward) b[i] = calloc(bw2 * 3 + 6, sizeof(double));
    }
    s = calloc(l_query + 2, sizeof(double));
    _qual = calloc(l_query, sizeof(float));
    if (g_qual2prob[0] == 0)
        for (i = 0; i < 256; ++i) g_qual2prob[i] = pow(10, -i / 10.);
    for (i = 0; i < l_query; ++i) _qual[i] = g_qual2prob[iqual ? iqual[i] : 30];
    qual = _qual - 1;
    sM = sI = 1. / (2 * l_query + 2);
    m[0*3+0] = (1 - c->d - c->d) * (1 - sM); m[0*3+1] = m[0*3+2] = c->d * (1 - sM);
    m[1*3+0] = (1 - c->e) * (1 - sI); m[1*3+1] = c->e * (1 - sI); m[1*3+2] = 0.;
    m[2*3+0] = 1 - c->e; m[2*3+1] = 0.; m[2*3+2] = c->e;
    bM = (1 - c->d) / l_ref; bI = c->d / l_ref;
    set_u(k, bw, 0, 0);
    f[0][k] = s[0] = 1.;
    {
        double *fi = f[1], sum;
        int beg = 1, end = l_ref < bw + 1 ? l_ref : bw + 1, _beg, _end;
        for (k = beg, sum = 0.; k <= end; ++k) {
            int u;
            double e = (ref[k] > 3 || query[1] > 3) ? 1. : ref[k] == query[1] ? 1. - qual[1] : qual[1] * EM;
            set_u(u, bw, 1, k);
            fi[u+0] = e * bM; fi[u+1] = EI * bI;
            sum += fi[u] + fi[u+1];
        }
        s[1] = sum;
        set_u(_beg, bw, 1, beg); set_u(_end, bw, 1, end); _end += 2;
        for (k = _beg; k <= _end; ++k) fi[k] /= sum;
    }
    for (i = 2; i <= l_query; ++i) {
        double *fi = f[i], *fi1 = f[i-1], sum, qli = qual[i];
        int beg = 1, end = l_ref, x, _beg, _end;
        uint8_t qyi = query[i];
        x = i - bw; beg = beg > x ? beg : x;
        x = i + bw; end = end < x ? end : x;
        for (k = beg, sum = 0.; k <= end; ++k) {
            int u, v11, v01, v10;
            double e;
            e = (ref[k] > 3 || qyi > 3) ? 1. : ref[k] == qyi ? 1. - qli : qli * EM;
            set_u(u, bw, i, k); set_u(v11, bw, i-1, k-1); set_u(v10, bw, i-1, k); set_u(v01, bw, i, k-1);
            fi[u+0] = e * (m[0] * fi1[v11+0] + m[3] * fi1[v11+1] + m[6] * fi1[v11+2]);
            fi[u+1] = EI * (m[1] * fi1[v10+0] + m[4] * fi1[v10+1]);
            fi[u+2] = m[2] * fi[v01+0] + m[8] * fi[v01+2];
            sum += fi[u] + fi[u+1] + fi[u+2];
        }
        s[i] = sum;
        set_u(_beg, bw, i, beg); set_u(_end, bw, i, end); _end += 2;
        for (k = _beg, sum = 1./sum; k <= _end; ++k) fi[k] *= sum;
    }
    {
        double sum;
        for (k = 1, sum = 0.; k <= l_ref; ++k) {
            int u;
            set_u(u, bw, l_query, k);
            if (u < 3 || u >= bw2 * 3 + 3) continue;
            sum += f[l_query][u+0] * sM + f[l_query][u+1] * sI;
        }
        s[l_query+1] = sum;
    }
    {
        double p = 1., Pr1 = 0.;
        for (i = 0; i <= l_query + 1; ++i) {
            p *= s[i];
            if (p < 1e-100) Pr1 += -4.343 * log(p), p = 1.;
        }
        Pr1 += -4.343 * log(p * l_ref * l_query);
        Pr = (int)(Pr1 + .499);
        if (!is_backward) {
            for (i = 0; i <= l_query; ++i) free(f[i]);
            free(f); free(s); free(_qual);
            return Pr;
        }
    }
    for (k = 1; k <= l_ref; ++k) {
        int u;
        double *bi = b[l_query];
        set_u(u, bw, l_query, k);
        if (u < 3 || u >= bw2 * 3 + 3) continue;
        bi[u+0] = sM / s[l_query] / s[l_query+1]; bi[u+1] = sI / s[l_query] / s[l_query+1];
    }
    for (i = l_query - 1; i >= 1; --i) {
        int beg = 1, end = l_ref, x, _beg, _end;
        double *bi = b[i], *bi1 = b[i+1], y = (i > 1), qli1 = qual[i+1];
        uint8_t qyi1 = query[i+1];
        x = i - bw; beg = beg > x ? beg : x;
        x = i + bw; end = end < x ? end : x;
        for (k = end; k >= beg; --k) {
            int u, v11, v01, v10;
            double e;
            set_u(u, bw, i, k); set_u(v11, bw, i+1, k+1); set_u(v10, bw, i+1, k); set_u(v01, bw, i, k+1);
            e = (k >= l_ref ? 0 : (ref[k+1] > 3 || qyi1 > 3) ? 1. : ref[k+1] == qyi1 ? 1. - qli1 : qli1 * EM) * bi1[v11];
            bi[u+0] = e * m[0] + EI * m[1] * bi1[v10+1] + m[2] * bi[v01+2];
            bi[u+1] = e * m[3] + EI * m[4] * bi1[v10+1];
            bi[u+2] = (e * m[6] + m[8] * bi[v01+2]) * y;
        }
        set_u(_beg, bw, i, beg); set_u(_end, bw, i, end); _end += 2;
        for (k = _beg, y = 1./s[i]; k <= _end; ++k) bi[k] *= y;
    }
    {
        int beg = 1, end = l_ref < bw + 1 ? l_ref : bw + 1;
        double sum = 0.;
        for (k = end; k >= beg; --k) {
            int u;
            double e = (ref[k] > 3 || query[1] > 3) ? 1. : ref[k] == query[1] ? 1. - qual[1] : qual[1] * EM;
            set_u(u, bw, 1, k);
            if (u < 3 || u >= bw2 * 3 + 3) continue;
            sum += e * b[1][u+0] * bM + EI * b[1][u+1] * bI;
        }
        set_u(k, bw, 0, 0);
        pb = b[0][k] = sum / s[0];
    }
    (void)pb;
    for (i = 1; i <= l_query; ++i) {
        double sum = 0., *fi = f[i], *bi = b[i], max = 0.;
        int beg = 1, end = l_ref, x, max_k = -1;
        x = i - bw; beg = beg > x ? beg : x;
        x = i + bw; end = end < x ? end : x;
        for (k = beg; k <= end; ++k) {
            int u;
            double z;
            set_u(u, bw, i, k);
            z = fi[u+0] * bi[u+0]; if (z > max) max = z, max_k = (k-1)<<2 | 0; sum += z;
            z = fi[u+1] * bi[u+1]; if (z > max) max = z, max_k = (k-1)<<2 | 1; sum += z;
        }
        max /= sum; sum *= s[i];
        if (state) state[i-1] = max_k;
        if (q) k = (int)(-4.343 * log(1. - max) + .499), q[i-1] = k > 100 ? 99 : k;
    }
    for (i = 0; i <= l_query; ++i) { free(f[i]); free(b[i]); }
    free(f); free(b); free(s); free(_qual);
    return Pr;
}

int sam_prob_realn(rec_t *b, const char *ref, int64_t ref_len, int flag) {
    int k, bw, yb, ye, apply_baq = flag & 1, extend_baq = flag & 2, redo_baq = flag & 4;
    int64_t i, x, y, xb, xe;
    uint32_t *cigar = rec_cigar(b);
    core_t *c = &b->core;
    probaln_par_t conf = { 0.001, 0.1, 10 };
    uint8_t *bq = 0, *zq = 0, *qual = rec_qual(b);
    if ((c->flag & FUNMAP) || c->l_qseq == 0 || qual[0] == (uint8_t)-1) return -1;
    if ((bq = aux_get(b, "BQ")) != 0) ++bq;
    if ((zq = aux_get(b, "ZQ")) != 0 && *zq == 'Z') ++zq;
    if (bq && redo_baq) { aux_del(b, bq - 1); bq = 0; zq = aux_get(b, "ZQ"); if (zq) ++zq; qual = rec_qual(b); }
    if (bq && zq) { aux_del(b, zq - 1); zq = 0; bq = aux_get(b, "BQ"); if (bq) ++bq; }
    if (bq || zq) {
        if ((apply_baq && zq) || (!apply_baq && bq)) return -3;
        if (bq && apply_baq) {
            for (i = 0; i < c->l_qseq; ++i) qual[i] = qual[i] + 64 < bq[i] ? 0 : qual[i] - ((int)bq[i] - 64);
            *(bq - 3) = 'Z';
        } else if (zq && !apply_baq) {
            for (i = 0; i < c->l_qseq; ++i) qual[i] += (int)zq[i] - 64;
            *(zq - 3) = 'B';
        }
        return 0;
    }
    x = c->pos; y = 0; yb = ye = -1; xb = xe = -1;
    for (k = 0; k < (int)c->n_cigar; ++k) {
        int op = cigar[k] & 0xf, l = cigar[k] >> 4;
        if (op == C_MATCH || op == C_EQUAL || op == C_DIFF) {
            if (yb < 0) yb = y;
            if (xb < 0) xb = x;
            ye = y + l; xe = x + l;
            x += l; y += l;
        } else if (op == C_SOFT_CLIP || op == C_INS) y += l;
        else if (op == C_DEL) x += l;
        else if (op == C_REF_SKIP) return -1;
    }
    if (xb == -1) return -1;
    bw = 7;
    if (llabs((xe - xb) - (ye - yb)) > bw) bw = llabs((xe - xb) - (ye - yb)) + 3;
    conf.bw = bw;
    xb -= yb + bw/2; if (xb < 0) xb = 0;
    xe += c->l_qseq - ye + bw/2;
    if (xe - xb - c->l_qseq > bw)
        xb += (xe - xb - c->l_qseq - bw) / 2, xe -= (xe - xb - c->l_qseq - bw) / 2;
    {
        uint8_t *seq = rec_seq(b);
        int64_t lref = xe > ref_len ? ref_len - xb : xe - xb;
        if (lref <= 0) return -1;
        uint8_t *tref = malloc(lref), *tseq = malloc(c->l_qseq), *q = malloc(c->l_qseq);
        int *state = malloc(c->l_qseq * sizeof(int));
        bq = malloc(c->l_qseq + 1);
        memcpy(bq, qual, c->l_qseq); bq[c->l_qseq] = 0;
        for (i = xb; i < xb + lref; ++i) tref[i - xb] = seq_nt16_int[seq_nt16_table[(unsigned char)ref[i]]];
        for (i = 0; i < c->l_qseq; ++i) tseq[i] = seq_nt16_int[seqi(seq, i)];
        probaln_glocal(tref, lref, tseq, c->l_qseq, qual, &conf, state, q);
        if (!extend_baq) {
            for (k = 0, x = c->pos, y = 0; k < (int)c->n_cigar; ++k) {
                int op = cigar[k] & 0xf, l = cigar[k] >> 4;
