                if (op == C_MATCH || op == C_EQUAL || op == C_DIFF) {
                    for (i = y; i < y + l; ++i)
                        bq[i] = ((state[i] & 3) != 0 || state[i] >> 2 != x - xb + (i - y)) ? 0 : q[i];
                    for (left[y] = bq[y], i = y + 1; i < y + l; ++i)
                        left[i] = bq[i] > left[i-1] ? bq[i] : left[i-1];
                    for (rght[y+l-1] = bq[y+l-1], i = y + l - 2; i >= y; --i)
