                    x += l; y += l;
                } else if (op == C_SOFT_CLIP || op == C_INS) y += l;
                else if (op == C_DEL) x += l;
            }
            for (i = 0; i < c->l_qseq; ++i) bq[i] = 64 + (qual[i] <= bq[i] ? 0 : qual[i] - bq[i]);
