    int c, flt_flag = UPDATE_NM | UPDATE_MD, is_bam_out = 0, is_uncompressed = 0, max_nm = 0, is_realn = 0;
    int capQ = 0, baq_flag = 0, quiet = 0, no_pg = 0;
    gopts_t ga; gopts_init(&ga);
    static const struct option lopts[] = {
        {"no-PG", no_argument, NULL, 1},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"output-fmt", required_argument, NULL, GO_OUTPUT_FMT},
        {"output-fmt-option", required_argument, NULL, GO_OUTPUT_FMT_OPTION},
        {"reference", required_argument, NULL, GO_REFERENCE},
        {"threads", required_argument, NULL, '@'},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "EqQreuNhbSC:n:Ad@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'r': is_realn = 1; break;
        case 'e': flt_flag |= USE_EQUAL; break;
        case 'd': flt_flag |= DROP_TAG; break;
        case 'q': flt_flag |= BIN_QUAL; break;
        case 'h': flt_flag |= HASH_QNM; break;
        case 'N': flt_flag &= ~(UPDATE_MD | UPDATE_NM); break;
        case 'b': is_bam_out = 1; break;
        case 'u': is_uncompressed = is_bam_out = 1; break;
        case 'S': break;
        case 'n': max_nm = atoi(optarg); break;
        case 'C': capQ = atoi(optarg); break;
        case 'A': baq_flag |= 1; break;
        case 'E': baq_flag |= 2; break;
        case 'Q': quiet = 1; break;
        case 1: no_pg = 1; break;
        case '@': break;
        default:
            if (gopts_parse(&ga, c, optarg) != 0) { fputs(usage_calmd, stderr); return 1; }
        }
    }
    if (optind + (ga.reference == NULL) >= argc + (ga.reference == NULL ? 0 : 0) && optind + (ga.reference == NULL ? 2 : 1) > argc) {
        fputs(usage_calmd, stderr); return 1;
    }
    samfile_t *fp = sf_open(argv[optind], "r");
    if (!fp) { print_error_errno("calmd", "Failed to open input file '%s'", argv[optind]); return 1; }
    hdr_t *h = sf_read_header(fp);
    if (!h || h->n_targets == 0) {
        fprintf(stderr, "[bam_fillmd] input SAM does not have header. Abort!\n");
        hdr_destroy(h); sf_close(fp); return 1;
    }
    char mode[16] = "w";
    if (ga.out_fmt == FMT_BAM) is_bam_out = 1;
    if (is_bam_out) strcat(mode, "b");
    if (is_uncompressed) strcat(mode, "0");
    samfile_t *out = sf_open("-", mode);
    add_pg(h, no_pg);
    sf_write_header(out, h);
    const char *ref_file = argc > optind + 1 ? argv[optind + 1] : ga.reference;
    fai_t *fai = fai_load(ref_file);
    int ret = 0;
    if (!fai) {
        print_error_errno("calmd", "Failed to open reference file '%s'", ref_file);
        sf_close(out); hdr_destroy(h); sf_close(fp); return 1;
    }
    rec_t *b = rec_init();
    int tid = -2; char *ref = NULL; int64_t len = 0;
    uint32_t skipped = 0;
    int r;
    while ((r = sf_read(fp, b)) >= 0) {
        if (b->core.tid >= 0) {
            if (tid != b->core.tid) {
                free(ref); ref = NULL; len = 0;
                int id = fai_tid(fai, hdr_tname(h, b->core.tid));
                if (id >= 0) ref = fai_fetch_seq(fai, id, 0, INT64_MAX, &len);
                tid = b->core.tid;
                if (!ref) {
                    fprintf(stderr, "[bam_fillmd] fail to find sequence '%s' in the reference.\n", hdr_tname(h, tid));
                    if (is_realn || capQ > 10) { ret = 1; break; }
                }
            }
            if (is_realn && ref) sam_prob_realn(b, ref, len, baq_flag);
            if (capQ > 10 && ref) {
                int q = sam_cap_mapq(b, ref, len, capQ);
                if (b->core.qual > q) b->core.qual = q;
            }
            if (ref) fillmd1_core(hdr_tname(h, tid), b, ref, len, flt_flag, max_nm, quiet, &skipped);
        }
        if (sf_write(out, h, b) < 0) { ret = 1; break; }
    }
    if (r < -1) { fprintf(stderr, "[bam_fillmd] Error reading input.\n"); ret = 1; }
    if (skipped) fprintf(stderr, "[calmd] Warning: %d records skipped due to no query sequence\n", skipped);
    free(ref);
    rec_destroy(b);
    fai_destroy(fai);
    if (sf_close(out) < 0) ret = 1;
    hdr_destroy(h);
    sf_close(fp);
    return ret;
}
