static void sync_mate_inner(rec_t *src, rec_t *dest) {
    dest->core.mtid = src->core.tid;
    dest->core.mpos = src->core.pos;
    if (src->core.flag & FREVERSE) dest->core.flag |= FMREVERSE; else dest->core.flag &= ~FMREVERSE;
    if (src->core.flag & FUNMAP) dest->core.flag |= FMUNMAP; else dest->core.flag &= ~FMUNMAP;
}
static bool plausibly_properly_paired(rec_t *a, rec_t *b) {
    if ((a->core.flag & FUNMAP) || (b->core.flag & FUNMAP)) return false;
    if (a->core.tid != b->core.tid) return false;
    rec_t *first, *second;
    int64_t a_pos = (a->core.flag & FREVERSE) ? rec_endpos(a) : a->core.pos;
    int64_t b_pos = (b->core.flag & FREVERSE) ? rec_endpos(b) : b->core.pos;
    if (a_pos > b_pos) { first = b; second = a; } else { first = a; second = b; }
