        uint8_t *d = aux_get(dest, "MC");
        if (d) aux_del(dest, d);
        kstr mc = {0, 0, NULL};
        format_cigar(src, &mc);
        aux_append(dest, "MC", 'Z', mc.l + 1, mc.s);
        free(mc.s);
    }
}
static void sync_mate(rec_t *a, rec_t *b) {
    sync_unmapped_pos_inner(a, b);
