/* ---------------- bedcov ---------------- */
typedef struct { samfile_t *fp; hdr_t *h; iter_t *iter; int min_mapQ; uint32_t flags; int64_t rcnt; int64_t beg, end; } bcaux_t;

static int bc_read(void *data, rec_t *b) {
    bcaux_t *a = data;
    int ret;
    for (;;) {
        ret = a->iter ? iter_next(a->fp, a->iter, b) : sf_read(a->fp, b);
        if (ret < 0) break;
        if (b->core.flag & a->flags) continue;
        if ((int)b->core.qual < a->min_mapQ) continue;
        a->rcnt++;
        break;
    }
    return ret;
}

int main_bedcov(int argc, char *argv[]) {
    int c, min_mapQ = 0, skip_DN = 0, do_rcount = 0, print_header = 0, max_depth = 0, has_idx = 0;
    int64_t min_depth = -1;
    uint32_t flags = FUNMAP | FSECONDARY | FQCFAIL | FDUP;
    static const struct option lopts[] = {
        {"min-MQ", required_argument, NULL, 'Q'}, {"min-mq", required_argument, NULL, 'Q'},
        {"max-depth", required_argument, NULL, 1},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"reference", required_argument, NULL, GO_REFERENCE},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "Q:Xg:G:jd:cH", lopts, NULL)) >= 0) {
        switch (c) {
        case 'Q': min_mapQ = atoi(optarg); break;
        case 'X': has_idx = 1; break;
        case 'c': do_rcount = 1; break;
        case 'H': print_header = 1; break;
        case 'g': case 'G': {
            int ok; int64_t v = parse_flag_str(optarg, &ok);
            if (!ok || v < 0) { fprintf(stderr, "Could not parse flags %s\n", optarg); return 1; }
            if (c == 'g') flags &= ~v; else flags |= v;
            break;
        }
        case 'j': skip_DN = 1; break;
        case 'd': min_depth = atoll(optarg); break;
        case 1: max_depth = atoi(optarg); break;
        case GO_INPUT_FMT_OPTION: case GO_REFERENCE: case GO_VERBOSITY: break;
        default: fputs(usage_bedcov, stderr); return 1;
        }
    }
    if (optind + 2 > argc) { fputs(usage_bedcov, stderr); return 1; }
    int n = argc - optind - 1;
    if (has_idx) n /= 2;
    bcaux_t *aux = xcalloc(n, sizeof(bcaux_t));
    idx_t **idx = xcalloc(n, sizeof(idx_t*));
    int ret = 0;
    for (int i = 0; i < n; i++) {
        const char *fn = argv[optind + 1 + i];
        aux[i].fp = sf_open(fn, "r");
        if (!aux[i].fp) { print_error_errno("bedcov", "can't open \"%s\"", fn); ret = 1; goto done; }
        aux[i].h = sf_read_header(aux[i].fp);
