        idx[i] = aux[i].fp->fmt == FMT_BAM ? idx_load_for(fn, has_idx ? argv[optind + 1 + n + i] : NULL) : NULL;
        if (!idx[i]) { print_error("bedcov", "can't load index for \"%s\"", fn); ret = 1; goto done; }
        aux[i].min_mapQ = min_mapQ; aux[i].flags = flags;
    }
