/* bedcov, addreplacerg, reheader, samples, split */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>
#include <errno.h>
#include <inttypes.h>
#include <limits.h>
#include "common.h"
#include "plp.h"
#include "fai.h"

/* ---------------- bedcov ---------------- */
typedef struct { samfile_t *fp; hdr_t *h; iter_t *iter; int min_mapQ; uint32_t flags; int64_t rcnt; int64_t beg, end; } bcaux_t;

static int bc_read(void *data, rec_t *b) {
    bcaux_t *a = data;
    int ret;
    for (;;) {
        ret = a->iter ? iter_next(a->fp, a->iter, b) : sf_read(a->fp, b);
        if (ret < 0) break;
        if (b->core.flag & a->flags) continue;
        if ((int)b->core.qual < a->min_mapQ) continue;
        a->rcnt++;
        break;
    }
    return ret;
}

int main_bedcov(int argc, char *argv[]) {
    int c, min_mapQ = 0, skip_DN = 0, do_rcount = 0, print_header = 0, max_depth = 0, has_idx = 0;
    int64_t min_depth = -1;
    uint32_t flags = FUNMAP | FSECONDARY | FQCFAIL | FDUP;
    static const struct option lopts[] = {
        {"min-MQ", required_argument, NULL, 'Q'}, {"min-mq", required_argument, NULL, 'Q'},
        {"max-depth", required_argument, NULL, 1},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"reference", required_argument, NULL, GO_REFERENCE},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "Q:Xg:G:jd:cH", lopts, NULL)) >= 0) {
        switch (c) {
        case 'Q': min_mapQ = atoi(optarg); break;
        case 'X': has_idx = 1; break;
        case 'c': do_rcount = 1; break;
        case 'H': print_header = 1; break;
        case 'g': case 'G': {
            int ok; int64_t v = parse_flag_str(optarg, &ok);
            if (!ok || v < 0) { fprintf(stderr, "Could not parse flags %s\n", optarg); return 1; }
            if (c == 'g') flags &= ~v; else flags |= v;
            break;
        }
        case 'j': skip_DN = 1; break;
        case 'd': min_depth = atoll(optarg); break;
        case 1: max_depth = atoi(optarg); break;
        case GO_INPUT_FMT_OPTION: case GO_REFERENCE: case GO_VERBOSITY: break;
        default: fputs(usage_bedcov, stderr); return 1;
        }
    }
    if (optind + 2 > argc) { fputs(usage_bedcov, stderr); return 1; }
    int n = argc - optind - 1;
    if (has_idx) n /= 2;
    bcaux_t *aux = xcalloc(n, sizeof(bcaux_t));
    idx_t **idx = xcalloc(n, sizeof(idx_t*));
    int ret = 0;
    for (int i = 0; i < n; i++) {
        const char *fn = argv[optind + 1 + i];
        aux[i].fp = sf_open(fn, "r");
        if (!aux[i].fp) { print_error_errno("bedcov", "can't open \"%s\"", fn); ret = 1; goto done; }
        aux[i].h = sf_read_header(aux[i].fp);
        if (!aux[i].h) { print_error("bedcov", "failed to read header for \"%s\"", fn); ret = 1; goto done; }
        idx[i] = aux[i].fp->fmt == FMT_BAM ? idx_load_for(fn, has_idx ? argv[optind + 1 + n + i] : NULL) : NULL;
        if (!idx[i]) { print_error("bedcov", "can't load index for \"%s\"", fn); ret = 1; goto done; }
        aux[i].min_mapQ = min_mapQ; aux[i].flags = flags;
    }
    bgzf_t *bf = bg_open_read(argv[optind]);
    if (!bf) { print_error_errno("bedcov", "can't open BED file '%s'", argv[optind]); ret = 1; goto done; }
    if (print_header) {
        printf("#chrom\tstart\tend");
        for (int i = 0; i < n; i++) printf("\t%s_cov", argv[optind + 1 + i]);
        if (min_depth >= 0) for (int i = 0; i < n; i++) printf("\t%s_depth", argv[optind + 1 + i]);
        if (do_rcount) for (int i = 0; i < n; i++) printf("\t%s_count", argv[optind + 1 + i]);
        printf("\n");
    }
    kstr line = {0, 0, NULL}, o = {0, 0, NULL};
    uint64_t *cnt = xcalloc(n, sizeof(uint64_t));
    int64_t *pcov = xcalloc(n, sizeof(int64_t));
    int *n_plp = xcalloc(n, sizeof(int));
    const pileup1_t **plp = xcalloc(n, sizeof(pileup1_t*));
    void **dp = xcalloc(n, sizeof(void*));
    for (int i = 0; i < n; i++) dp[i] = &aux[i];
    while (bg_getline(bf, &line) >= 0) {
        if (line.l == 0 || line.s[0] == '#') continue;
        if (strncmp(line.s, "track ", 6) == 0 || strncmp(line.s, "browser ", 8) == 0) continue;
        char *p = line.s;
        while (*p && !isspace((unsigned char)*p)) p++;
        if (!*p) { fprintf(stderr, "[%s] Error: invalid BED file line \"%s\".\n", "main_bedcov", line.s); ret = 1; break; }
        char save = *p; *p = 0;
        int tid = hdr_name2tid(aux[0].h, line.s);
        *p = save;
        int64_t beg = 0, end = 0;
        int num = sscanf(p + 1, "%" SCNd64 " %" SCNd64, &beg, &end);
        if (tid < 0 || num < 2 || end < beg) {
            fprintf(stderr, "[%s] Error: invalid BED file line \"%s\".\n", "main_bedcov", line.s);
            continue;
        }
        for (int i = 0; i < n; i++) {
            iter_destroy(aux[i].iter);
            aux[i].iter = idx_query(idx[i], tid, beg, end);
            aux[i].rcnt = 0;
        }
        mplp_t *mp = mplp_init(n, bc_read, dp);
        mplp_set_maxcnt(mp, max_depth > 0 ? max_depth : INT_MAX);
        memset(cnt, 0, n * sizeof(uint64_t));
        memset(pcov, 0, n * sizeof(int64_t));
        int t2; int64_t pos;
        while (mplp_auto(mp, &t2, &pos, n_plp, plp) > 0) {
            if (pos >= beg && pos < end) {
                for (int i = 0; i < n; i++) {
                    int m = 0;
                    if (skip_DN || min_depth >= 0) {
                        for (int j = 0; j < n_plp[i]; j++) {
                            const pileup1_t *pi = plp[i] + j;
                            if (pi->is_del || pi->is_refskip) ++m;
                        }
                    }
                    cnt[i] += skip_DN ? n_plp[i] - m : n_plp[i];
                    if (min_depth >= 0 && n_plp[i] - m >= min_depth) pcov[i]++;
                }
            }
        }
        mplp_destroy(mp);
        o.l = 0;
        ks_puts(&o, line.s);
        for (int i = 0; i < n; i++) { ks_putc(&o, '\t'); ks_puti(&o, (int64_t)cnt[i]); }
        if (min_depth >= 0) for (int i = 0; i < n; i++) { ks_putc(&o, '\t'); ks_puti(&o, pcov[i]); }
        if (do_rcount) for (int i = 0; i < n; i++) { ks_putc(&o, '\t'); ks_puti(&o, aux[i].rcnt); }
        ks_putc(&o, '\n');
        fwrite(o.s, 1, o.l, stdout);
    }
    ks_free(&line); ks_free(&o);
    free(cnt); free(pcov); free(n_plp); free(plp); free(dp);
    bg_close(bf);
done:
    for (int i = 0; i < n; i++) {
        if (aux[i].fp) sf_close(aux[i].fp);
        hdr_destroy(aux[i].h); iter_destroy(aux[i].iter); idx_destroy(idx[i]);
    }
    free(aux); free(idx);
    return ret;
}

/* ---------------- addreplacerg ---------------- */
static char *basic_unescape(const char *in) {
    char *out = xmalloc(strlen(in) + 1), *p = out;
    for (; *in; in++) {
        if (*in == '\\' && in[1]) {
            in++;
            switch (*in) {
            case 't': *p++ = '\t'; break;
            case 'n': *p++ = '\n'; break;
            case '\\': *p++ = '\\'; break;
            default: *p++ = '\\'; *p++ = *in; break;
            }
        } else *p++ = *in;
    }
    *p = 0;
    return out;
}

int main_addreplacerg(int argc, char *argv[]) {
    if (argc == 1) { fputs(usage_addreplacerg, stdout); return 1; }
    int c, mode = 0, no_pg = 0, uncompressed = 0, overwrite_hdr = 0;
    char *rg_id = NULL, *outfn = NULL;
    kstr rgline = {0, 0, NULL};
    gopts_t ga; gopts_init(&ga);
    static const struct option lopts[] = {
        {"no-PG", no_argument, NULL, 1},
        {"input-fmt", required_argument, NULL, GO_INPUT_FMT},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"output-fmt", required_argument, NULL, 'O'},
        {"output-fmt-option", required_argument, NULL, GO_OUTPUT_FMT_OPTION},
        {"reference", required_argument, NULL, GO_REFERENCE},
        {"threads", required_argument, NULL, '@'},
        {"write-index", no_argument, NULL, GO_WRITE_INDEX},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "r:R:m:o:O:l:h@:uw", lopts, NULL)) >= 0) {
        switch (c) {
        case 'r':
            if (rgline.l == 0) {
                if (strlen(optarg) < 3 || (optarg[0] != '@' && optarg[1] != 'R' && optarg[2] != 'G')) ks_puts(&rgline, "@RG\t");
            } else ks_puts(&rgline, "\t");
            ks_puts(&rgline, optarg);
            break;
        case 'R': rg_id = optarg; break;
        case 'm':
            if (strcmp(optarg, "overwrite_all") == 0) mode = 0;
            else if (strcmp(optarg, "orphan_only") == 0) mode = 1;
            else { fputs(usage_addreplacerg, stderr); return 1; }
            break;
        case 'o': outfn = optarg; break;
        case 'h': fputs(usage_addreplacerg, stdout); return 0;
        case 1: no_pg = 1; break;
        case 'u': uncompressed = 1; break;
        case 'w': overwrite_hdr = 1; break;
        case 'l': break;
        case '@': break;
        case '?': fputs(usage_addreplacerg, stderr); return 1;
        case 'O': if (gopts_parse(&ga, GO_OUTPUT_FMT, optarg) < 0) { fputs(usage_addreplacerg, stderr); return 1; } break;
        default: if (gopts_parse(&ga, c, optarg) == 0) break; fputs(usage_addreplacerg, stderr); return 1;
        }
    }
    if (argc - optind < 1) { fprintf(stderr, "You must specify an input file.\n"); fputs(usage_addreplacerg, stderr); return 1; }
    if (rg_id && rgline.l) { fprintf(stderr, "The options -r and -R are mutually exclusive.\n"); return 1; }
    char *line = NULL;
    char *id = NULL;
    if (rgline.l) {
        line = basic_unescape(rgline.s);
        char *p = strstr(line, "\tID:");
        if (!p) { fprintf(stderr, "[%s] The supplied RG line lacks an ID tag.\n", "parse_args"); free(line); return 1; }
        p += 4;
        char *e = p; while (*e && *e != '\t' && *e != '\n') e++;
        id = xmalloc(e - p + 1); memcpy(id, p, e - p); id[e - p] = 0;
    }
    ks_free(&rgline);
    const char *fn = argv[optind];
    samfile_t *in = sf_open(fn, "r");
    if (!in) { print_error_errno("addreplacerg", "could not open \"%s\"", fn); free(line); free(id); return 1; }
    hdr_t *h = sf_read_header(in);
    if (!h) { fprintf(stderr, "[init] Could not read header from \"%s\"\n", fn); sf_close(in); return 1; }
    char omode[16] = "w";
    if (uncompressed) strcat(omode, "b0");
    if (outfn) {
        int cmp; int f = fmt_from_fn(outfn, &cmp);
        if (f == FMT_BAM) { strcpy(omode, uncompressed ? "wb0" : "wb"); }
        else if (f == FMT_SAM) strcpy(omode, cmp ? "wz" : "w");
    }
    if (ga.out_fmt == FMT_BAM) strcpy(omode, uncompressed ? "wb0" : "wb");
    else if (ga.out_fmt == FMT_SAM) strcpy(omode, "w");
    int ret = 0;
    if (line) {
        int ex = hdr_find_line(h, "RG", "ID", id);
        if (ex >= 0) {
            if (overwrite_hdr) hdr_remove_line(h, ex);
            else {
                fprintf(stderr, "[init] ID of new RG line specified conflicts with that of an existing header RG line. Overwrite not specified.\n");
                ret = 1; goto done;
            }
        }
        char *s = line;
        while (*s) {
            char *e = strchr(s, '\n');
            size_t l = e ? (size_t)(e - s) : strlen(s);
            if (l > 0) {
                hdr_t *tmp = hdr_init();
                if (hdr_parse_line(tmp, s, l, 1) < 0) { hdr_destroy(tmp); fprintf(stderr, "[init] Error adding RG line with ID:%s to the output header.\n", id); ret = 1; goto done; }
                hline_t *nl = hdr_add_line_empty(h, tmp->l[0].type);
                for (int q = 0; q < tmp->l[0].ntag; q++) hline_set(nl, tmp->l[0].key[q], tmp->l[0].val[q]);
                hdr_destroy(tmp);
            }
            s += l; if (*s) s++;
        }
        if (mode == 0) {
            for (int i = h->nl - 1; i >= 0; i--) {
                if (h->l[i].type[0] != 'R' || h->l[i].type[1] != 'G') continue;
                const char *v = hline_get(&h->l[i], "ID");
                if (!v || strcmp(v, id) != 0) hdr_remove_line(h, i);
            }
        }
    } else {
        if (rg_id) {
            if (hdr_find_line(h, "RG", "ID", rg_id) < 0) {
                fprintf(stderr, "RG ID supplied does not exist in header. Supplied ID: %s\n", rg_id);
                ret = 1; goto done;
            }
            id = xstrdup(rg_id);
        } else {
            for (int i = 0; i < h->nl; i++) if (h->l[i].type[0] == 'R' && h->l[i].type[1] == 'G') {
                const char *v = hline_get(&h->l[i], "ID");
                if (v) { id = xstrdup(v); break; }
            }
            if (!id) { fprintf(stderr, "No RG specified on command line or in existing header.\n"); ret = 1; goto done; }
        }
    }
    add_pg(h, no_pg);
    {
        samfile_t *out = sf_open(outfn ? outfn : "-", omode);
        if (!out) { print_error_errno("addreplacerg", "could not open output file \"%s\"", outfn ? outfn : "-"); ret = 1; goto done; }
        sf_write_header(out, h);
        rec_t *b = rec_init();
        int r;
        while ((r = sf_read(in, b)) >= 0) {
            uint8_t *d = aux_get(b, "RG");
            if (mode == 0) {
                if (d) aux_del(b, d);
                aux_append(b, "RG", 'Z', strlen(id) + 1, id);
            } else if (!d) aux_append(b, "RG", 'Z', strlen(id) + 1, id);
            sf_write(out, h, b);
        }
        if (r < -1) { fprintf(stderr, "[addreplacerg] Error reading input\n"); ret = 1; }
        rec_destroy(b);
        sf_close(out);
        if (ga.write_index && outfn) write_index_for(outfn, 1);
    }
done:
    free(line); free(id);
    hdr_destroy(h);
    sf_close(in);
    return ret;
}

/* ---------------- reheader ---------------- */
int main_reheader(int argc, char *argv[]) {
    int c, no_pg = 0, inplace = 0;
    char *cmd = NULL;
    static const struct option lopts[] = {
        {"help", no_argument, NULL, 'h'}, {"in-place", no_argument, NULL, 'i'},
        {"no-PG", no_argument, NULL, 'P'}, {"command", required_argument, NULL, 'c'},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "hiPc:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'P': no_pg = 1; break;
        case 'i': inplace = 1; break;
        case 'c': cmd = optarg; break;
        case 'h': fputs(usage_reheader, stdout); return 0;
        default: fputs(usage_reheader, stderr); return 1;
        }
    }
    (void)inplace;
    if ((cmd && argc - optind != 1) || (!cmd && argc - optind != 2)) { fputs(usage_reheader, stderr); return 1; }
    const char *fn = cmd ? argv[optind] : argv[optind + 1];
    hdr_t *h = NULL;
    samfile_t *in = sf_open(fn, "r");
    if (!in) { print_error_errno("reheader", "fail to open file '%s'", fn); return 1; }
    hdr_t *oh = sf_read_header(in);
    if (!oh) { print_error("reheader", "Couldn't read header for '%s'", fn); sf_close(in); return 1; }
    if (cmd) {
        /* pass header text through external command */
        char tin[] = "/tmp/samtools_rh_XXXXXX";
        int tfd = mkstemp(tin);
        kstr t = {0, 0, NULL}; hdr_text(oh, &t);
        if (tfd >= 0) { ssize_t w = write(tfd, t.s, t.l); (void)w; close(tfd); }
        ks_free(&t);
        kstr full = {0, 0, NULL};
        ks_printf(&full, "%s < %s", cmd, tin);
        FILE *p = popen(full.s, "r");
        kstr ht = {0, 0, NULL};
        if (p) { char buf[4096]; size_t k; while ((k = fread(buf, 1, sizeof buf, p)) > 0) ks_putsn(&ht, buf, k); pclose(p); }
        unlink(tin);
        ks_free(&full);
        h = hdr_init();
        if (hdr_parse(h, ht.s ? ht.s : "", ht.l) < 0 || hdr_build_targets(h) < 0) { hdr_destroy(h); h = NULL; }
        ks_free(&ht);
    } else {
        samfile_t *hf = sf_open(argv[optind], "r");
        if (!hf) { print_error_errno("reheader", "fail to open file '%s'", argv[optind]); hdr_destroy(oh); sf_close(in); return 1; }
        h = sf_read_header(hf);
        sf_close(hf);
    }
    if (!h) { fprintf(stderr, "[%s] fail to read the header from '%s'\n", "main_reheader", cmd ? "command" : argv[optind]); hdr_destroy(oh); sf_close(in); return 1; }
    int ret = 0;
    add_pg(h, no_pg);
    if (in->fmt == FMT_BAM && in->bg->mode == BG_BGZF) {
        bgzf_t *out = bg_open_write("-", BG_BGZF, -1);
        samfile_t so; memset(&so, 0, sizeof so); so.bg = out; so.fmt = FMT_BAM;
        sf_write_header(&so, h);
        if (in->bg->upos < in->bg->ulen) { bg_write(out, in->bg->ubuf + in->bg->upos, in->bg->ulen - in->bg->upos); bg_flush(out); }
        int64_t off = bg_raw_tell(in->bg);
        lseek(in->bg->fd, off, SEEK_SET);
        uint8_t buf[65536]; ssize_t n;
        while ((n = read(in->bg->fd, buf, sizeof buf)) > 0) {
            ssize_t p = 0;
            while (p < n) { ssize_t w = write(out->fd, buf + p, n - p); if (w <= 0) break; p += w; }
        }
        bg_close(out);
    } else {
        samfile_t *out = sf_open("-", "w");
        sf_write_header(out, h);
        rec_t *b = rec_init();
        int r;
        while ((r = sf_read(in, b)) >= 0) sf_write(out, h, b);
        if (r < -1) ret = 1;
        rec_destroy(b);
        sf_close(out);
    }
    hdr_destroy(h); hdr_destroy(oh);
    sf_close(in);
    return ret;
}

/* ---------------- samples ---------------- */
int main_samples(int argc, char *argv[]) {
    int c, print_header = 0, test_index = 0, has_idx = 0;
    char *tag = "SM", *outfn = NULL;
    char **refs = NULL; int nrefs = 0;
    while ((c = getopt(argc, argv, "?hiT:o:f:F:X")) >= 0) {
        switch (c) {
        case 'h': print_header = 1; break;
        case 'i': test_index = 1; break;
        case 'T': tag = optarg; break;
        case 'o': outfn = optarg; break;
        case 'f': refs = xrealloc(refs, (nrefs + 1) * sizeof(char*)); refs[nrefs++] = xstrdup(optarg); break;
        case 'F': {
            FILE *f = fopen(optarg, "r");
            if (!f) { print_error_errno("samples", "Cannot read %s", optarg); return 1; }
            char *line = NULL; size_t cap = 0; ssize_t n;
            while ((n = getline(&line, &cap, f)) >= 0) {
                while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r')) line[--n] = 0;
                if (!n || line[0] == '#') continue;
                refs = xrealloc(refs, (nrefs + 1) * sizeof(char*)); refs[nrefs++] = xstrdup(line);
            }
            free(line); fclose(f);
            break;
        }
        case 'X': has_idx = 1; break;
        case '?': fputs(usage_samples, stdout); return 0;
        default: fputs(usage_samples, stderr); return 1;
        }
    }
    FILE *out = outfn ? fopen(outfn, "w") : stdout;
    if (!out) { print_error_errno("samples", "Cannot write to %s", outfn); return 1; }
    fai_t **fais = xcalloc(nrefs + 1, sizeof(fai_t*));
    for (int i = 0; i < nrefs; i++) fais[i] = fai_load3(refs[i], NULL, NULL, 0);
    if (print_header) {
        fprintf(out, "#%s\tPATH", tag);
        if (test_index) fprintf(out, "\tINDEX");
        if (nrefs) fprintf(out, "\tREFERENCE");
        fprintf(out, "\n");
    }
    char **files = NULL; int nfiles = 0;
    if (optind < argc) { for (int i = optind; i < argc; i++) { files = xrealloc(files, (nfiles + 1) * sizeof(char*)); files[nfiles++] = xstrdup(argv[i]); } }
    else if (!isatty(STDIN_FILENO)) {
        char *line = NULL; size_t cap = 0; ssize_t n;
        while ((n = getline(&line, &cap, stdin)) >= 0) {
            while (n > 0 && (line[n-1] == '\n' || line[n-1] == '\r')) line[--n] = 0;
            if (!n) continue;
            files = xrealloc(files, (nfiles + 1) * sizeof(char*)); files[nfiles++] = xstrdup(line);
        }
        free(line);
    } else { fputs(usage_samples, stdout); return 0; }
    int ret = 0;
    int step = 1;
    for (int i = 0; i < nfiles; i += step) {
        char *fn = files[i], *idxfn = NULL;
        if (has_idx) {
            char *tab = strchr(fn, '\t');
            if (tab) { *tab = 0; idxfn = tab + 1; }
            else if (optind < argc) { int half = nfiles / 2; if (i >= half) break; idxfn = files[i + half]; }
        }
        samfile_t *fp = sf_open(fn, "r");
        if (!fp) { print_error_errno("samples", "Cannot open %s", fn); ret = 1; continue; }
        hdr_t *h = sf_read_header(fp);
        if (!h) { print_error("samples", "Cannot read header for %s", fn); sf_close(fp); ret = 1; continue; }
        const char *ref_path = ".";
        if (nrefs) {
            for (int r = 0; r < nrefs; r++) {
                if (!fais[r]) continue;
                int ok = h->n_targets > 0;
                for (int t = 0; t < h->n_targets && ok; t++) {
                    int id = fai_tid(fais[r], h->tname[t]);
                    if (id < 0 || fais[r]->e[id].len != h->tlen[t]) ok = 0;
                }
                if (ok) { ref_path = refs[r]; break; }
            }
        }
        int idx_ok = 0;
        if (test_index) {
            char *f = idxfn ? xstrdup(idxfn) : idx_find(fn);
            if (f) { idx_ok = access(f, R_OK) == 0; free(f); }
        }
        strmap_t *seen = sm_init();
        int nfound = 0;
        for (int k = 0; k < h->nl; k++) {
            hline_t *l = &h->l[k];
            if (l->type[0] != 'R' || l->type[1] != 'G') continue;
            const char *s = hline_get(l, tag);
            if (!s || sm_has(seen, s)) continue;
            sm_put(seen, s, 1); nfound++;
            fprintf(out, "%s\t%s", s, fn);
            if (test_index) fprintf(out, "\t%c", idx_ok ? 'Y' : 'N');
            if (nrefs) fprintf(out, "\t%s", ref_path);
            fprintf(out, "\n");
        }
        if (!nfound) {
            fprintf(out, ".\t%s", fn);
            if (test_index) fprintf(out, "\t%c", idx_ok ? 'Y' : 'N');
            if (nrefs) fprintf(out, "\t%s", ref_path);
            fprintf(out, "\n");
        }
        sm_destroy(seen);
        hdr_destroy(h);
        sf_close(fp);
    }
    for (int i = 0; i < nfiles; i++) free(files[i]);
    free(files);
    for (int i = 0; i < nrefs; i++) { fai_destroy(fais[i]); free(refs[i]); }
    free(fais); free(refs);
    if (out != stdout) fclose(out);
    return ret;
}
