    while ((n = strchr(p, '%')) != NULL) {
        ks_putsn(&s, p, n - p);
        ++n;
        switch (*n) {
        case '%': ks_putc(&s, '%'); break;
        case '*': ks_puts(&s, base); break;
        case '#': ks_printf(&s, "%0*i", pad, idx); break;
        case '!': ks_puts(&s, id); break;
        case '.': ks_puts(&s, ext); break;
        default: free(s.s); return NULL;
        }
        p = n + 1;
    }
    ks_puts(&s, p);
    return ks_release(&s);
}

int main_split(int argc, char *argv[]) {
    int c, verbose = 0, no_pg = 0, pad = 0, max_split = 100;
    char *fmt = "%*_%#.%.", *un_fn = NULL, *un_hdr = NULL, *tag = NULL;
    gopts_t ga; gopts_init(&ga);
    static const struct option lopts[] = {
        {"no-PG", no_argument, NULL, 1}, {"max-split", required_argument, NULL, 'M'},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"output-fmt", required_argument, NULL, GO_OUTPUT_FMT},
        {"output-fmt-option", required_argument, NULL, GO_OUTPUT_FMT_OPTION},
        {"reference", required_argument, NULL, GO_REFERENCE},
        {"threads", required_argument, NULL, '@'},
        {"write-index", no_argument, NULL, GO_WRITE_INDEX},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    if (argc == 1) { fputs(usage_split, stdout); return 1; }
    while ((c = getopt_long(argc, argv, "vf:h:u:d:p:M:@:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'f': fmt = optarg; break;
        case 'h': un_hdr = optarg; break;
        case 'v': verbose = 1; break;
        case 'u': un_fn = optarg; break;
        case 'd': tag = optarg; break;
        case 'p': pad = atoi(optarg); break;
        case 'M': max_split = atoi(optarg); break;
        case 1: no_pg = 1; break;
        case '@': break;
        default:
            if (c != '?' && gopts_parse(&ga, c, optarg) == 0) break;
            fputs(usage_split, stdout); return 1;
        }
    }
    (void)verbose;
    if (argc - optind < 1) { fputs(usage_split, stdout); return 1; }
    const char *fn = argv[optind];
    samfile_t *in = sf_open(fn, "r");
    if (!in) { print_error_errno("split", "Could not open \"%s\"", fn); return 1; }
    hdr_t *h = sf_read_header(in);
    if (!h) { fprintf(stderr, "Could not read header from \"%s\"\n", fn); sf_close(in); return 1; }
    const char *slash = strrchr(fn, '/');
    char *base = xstrdup(slash ? slash + 1 : fn);
    char *dot = strrchr(base, '.'); if (dot) *dot = 0;
    int ofmt = ga.out_fmt ? ga.out_fmt : FMT_BAM;
    const char *ext = ofmt == FMT_SAM ? "sam" : (ofmt == FMT_CRAM ? "cram" : "bam");
    char omode[8]; strcpy(omode, ofmt == FMT_SAM ? "w" : "wb");
    int ret = 0;
    hdr_t *base_hdr = hdr_dup(h);
    add_pg(base_hdr, no_pg);
    samfile_t *un = NULL; hdr_t *uh = NULL;
    if (un_fn) {
        if (un_hdr) {
            samfile_t *hf = sf_open(un_hdr, "r");
            if (hf) { uh = sf_read_header(hf); sf_close(hf); }
            if (!uh) { fprintf(stderr, "Could not read header from \"%s\"\n", un_hdr); ret = 1; goto done0; }
            add_pg(uh, no_pg);
        } else uh = hdr_dup(base_hdr);
        un = sf_open(un_fn, omode);
        if (!un) { print_error_errno("split", "Could not open \"%s\"", un_fn); ret = 1; goto done0; }
        sf_write_header(un, uh);
    }
    {
        int nout = 0, mout = 0;
        samfile_t **outs = NULL; hdr_t **ohs = NULL;
        strmap_t *map = sm_init();
        if (!tag) {
            for (int i = 0; i < h->nl; i++) {
                if (h->l[i].type[0] != 'R' || h->l[i].type[1] != 'G') continue;
                const char *id = hline_get(&h->l[i], "ID");
                if (!id) continue;
                char *ofn = expand_fmt(fmt, base, id, nout, pad, ext);
                if (!ofn) { fprintf(stderr, "[%s] Output format string error\n", "split"); ret = 1; break; }
                hdr_t *oh = hdr_dup(base_hdr);
                for (int k = oh->nl - 1; k >= 0; k--) {
                    if (oh->l[k].type[0] != 'R' || oh->l[k].type[1] != 'G') continue;
                    const char *v = hline_get(&oh->l[k], "ID");
                    if (!v || strcmp(v, id)) hdr_remove_line(oh, k);
                }
                samfile_t *o = sf_open(ofn, omode);
                if (!o) { print_error_errno("split", "Could not open \"%s\"", ofn); free(ofn); hdr_destroy(oh); ret = 1; break; }
                sf_write_header(o, oh);
                if (nout == mout) { mout = mout ? mout * 2 : 8; outs = xrealloc(outs, mout * sizeof(*outs)); ohs = xrealloc(ohs, mout * sizeof(*ohs)); }
                outs[nout] = o; ohs[nout] = oh;
                sm_put(map, id, nout);
                nout++;
                free(ofn);
            }
        }
        rec_t *b = rec_init();
        int r;
        while (!ret && (r = sf_read(in, b)) >= 0) {
            const char *val = NULL; char buf[64];
            uint8_t *t = aux_get(b, tag ? tag : "RG");
            if (t) {
                if (t[0] == 'Z' || t[0] == 'H') val = (char*)t + 1;
                else if (tag && strchr("cCsSiI", t[0])) { snprintf(buf, sizeof buf, "%lld", (long long)aux2i(t)); val = buf; }
                else if (tag && t[0] == 'A') { buf[0] = t[1]; buf[1] = 0; val = buf; }
            }
            int64_t k;
            if (val && sm_get(map, val, &k)) { sf_write(outs[k], ohs[k], b); continue; }
            if (val && tag && nout < max_split) {
                char *ofn = expand_fmt(fmt, base, val, nout, pad, ext);
                if (!ofn) { ret = 1; break; }
                hdr_t *oh = hdr_dup(base_hdr);
                samfile_t *o = sf_open(ofn, omode);
                if (!o) { print_error_errno("split", "Could not open \"%s\"", ofn); free(ofn); hdr_destroy(oh); ret = 1; break; }
                sf_write_header(o, oh);
                if (nout == mout) { mout = mout ? mout * 2 : 8; outs = xrealloc(outs, mout * sizeof(*outs)); ohs = xrealloc(ohs, mout * sizeof(*ohs)); }
                outs[nout] = o; ohs[nout] = oh;
                sm_put(map, val, nout);
                sf_write(o, oh, b);
                nout++;
                free(ofn);
                continue;
            }
            if (un) sf_write(un, uh, b);
        }
        rec_destroy(b);
        for (int i = 0; i < nout; i++) { sf_close(outs[i]); hdr_destroy(ohs[i]); }
        free(outs); free(ohs);
        sm_destroy(map);
    }
    if (un) sf_close(un);
done0:
    hdr_destroy(uh);
    hdr_destroy(base_hdr);
    hdr_destroy(h);
    sf_close(in);
    free(base);
    return ret;
}

/* ---------------- reset ---------------- */
static char comp1(char c) {
    switch (c) {
    case 'A': return 'T'; case 'C': return 'G'; case 'G': return 'C'; case 'T': return 'A';
    case 'M': return 'K'; case 'R': return 'Y'; case 'Y': return 'R'; case 'K': return 'M';
    case 'V': return 'B'; case 'H': return 'D'; case 'D': return 'H'; case 'B': return 'V';
    }
    return c;
}

int main_reset(int argc, char *argv[]) {
    int c, no_pg = 0, no_rg = 0, keep_dup = 0;
    char *outfn = "-", *reject_pg = NULL;
    strmap_t *tags = NULL; int keep = 0;
    gopts_t ga; gopts_init(&ga);
    static const struct option lopts[] = {
        {"output", required_argument, NULL, 'o'}, {"remove-tag", required_argument, NULL, 'x'},
        {"keep-tag", required_argument, NULL, 1}, {"reject-PG", required_argument, NULL, 2},
        {"no-RG", no_argument, NULL, 3}, {"no-PG", no_argument, NULL, 4}, {"dupflag", no_argument, NULL, 5},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"output-fmt", required_argument, NULL, 'O'},
        {"output-fmt-option", required_argument, NULL, GO_OUTPUT_FMT_OPTION},
        {"reference", required_argument, NULL, 'T'},
        {"threads", required_argument, NULL, '@'},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "o:@:x:O:T:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'o': outfn = optarg; break;
        case 'x': case 1: {
            const char *p = optarg;
            if (*p == '^') { keep = 1; p++; }
            if (c == 1) keep = 1;
            if (!tags) tags = sm_init();
            char *d = xstrdup(p), *save = NULL;
            for (char *t = strtok_r(d, ",", &save); t; t = strtok_r(NULL, ",", &save)) sm_put(tags, t, 1);
            free(d);
            break;
        }
        case 2: reject_pg = optarg; break;
        case 3: no_rg = 1; break;
        case 4: no_pg = 1; break;
        case 5: keep_dup = 1; break;
        case '@': case 'T': break;
        case 'O': if (gopts_parse(&ga, GO_OUTPUT_FMT, optarg) < 0) { fputs(usage_reset, stderr); return 1; } break;
        default: if (c != '?' && gopts_parse(&ga, c, optarg) == 0) break; fputs(usage_reset, stderr); return 1;
        }
    }
    const char *fn = optind < argc ? argv[optind] : "-";
    samfile_t *in = sf_open(fn, "r");
    if (!in) { fprintf(stderr, "Could not open input file!\n"); return 1; }
    hdr_t *h = sf_read_header(in);
    if (!h) { fprintf(stderr, "Failed to read header from file!\n"); sf_close(in); return 1; }
    /* build output header */
    hdr_t *oh = hdr_init();
    int reject = 0;
    for (int i = 0; i < h->nl; i++) {
        hline_t *l = &h->l[i];
        if (l->type[0] == 'S' && l->type[1] == 'Q') continue;
        if (no_rg && l->type[0] == 'R' && l->type[1] == 'G') continue;
        if (l->type[0] == 'P' && l->type[1] == 'G') {
            const char *id = hline_get(l, "ID");
            if (reject_pg && id && strcmp(id, reject_pg) == 0) reject = 1;
            if (reject) continue;
        }
        hline_t *nl = hdr_add_line_empty(oh, l->type);
        for (int k = 0; k < l->ntag; k++) hline_set(nl, l->key[k], l->val[k]);
        if (l->co) nl->co = xstrdup(l->co);
    }
    for (int i = 0; i < oh->nl; i++) if (oh->l[i].type[0] == 'H' && oh->l[i].type[1] == 'D') {
        hline_set(&oh->l[i], "SO", "unsorted");
    }
    add_pg(oh, no_pg);
    char mode[8];
    out_mode(mode, outfn, &ga, NULL, -1);
    {
        int cmp; int f = fmt_from_fn(outfn, &cmp);
        if (!ga.out_fmt && f == 0) strcpy(mode, "wb");
    }
    samfile_t *out = sf_open(outfn, mode);
    if (!out) { fprintf(stderr, "Could not open output file!\n"); hdr_destroy(oh); hdr_destroy(h); sf_close(in); return 1; }
    sf_write_header(out, oh);
    rec_t *b = rec_init(), *nb = rec_init();
    int r, ret = 0;
    while ((r = sf_read(in, b)) >= 0) {
        core_t *cc = &b->core;
        if (cc->flag & (FSECONDARY | FSUPPLEMENTARY)) continue;
        int len = cc->l_qseq;
        char *s = xmalloc(len + 1); uint8_t *q = xmalloc(len + 1);
        uint8_t *sq = rec_seq(b), *qq = rec_qual(b);
        for (int i = 0; i < len; i++) { s[i] = seq_nt16_str[seqi(sq, i)]; q[i] = qq[i]; }
        if (cc->flag & FREVERSE) {
            for (int i = 0, j = len - 1; i < j; i++, j--) {
                char t = s[i]; s[i] = comp1(s[j]); s[j] = comp1(t);
                uint8_t u = q[i]; q[i] = q[j]; q[j] = u;
            }
            if (len & 1) s[len/2] = comp1(s[len/2]);
        }
        /* rebuild record */
        core_t *n = &nb->core;
        memset(n, 0, sizeof *n);
        int flag = cc->flag & (FPAIRED | FREAD1 | FREAD2 | FQCFAIL | (keep_dup ? FDUP : 0));
        flag |= FUNMAP;
        if (flag & FPAIRED) flag |= FMUNMAP;
        n->flag = flag; n->tid = n->mtid = -1; n->pos = n->mpos = -1; n->isize = 0; n->qual = 0;
        n->l_qseq = len; n->n_cigar = 0;
        n->l_qname = cc->l_qname; n->l_extranul = cc->l_extranul;
        int auxl = rec_l_aux(b);
        int nl = cc->l_qname + (len + 1) / 2 + len + auxl;
        rec_resize(nb, nl);
        memcpy(nb->data, b->data, cc->l_qname);
        uint8_t *ns = nb->data + cc->l_qname;
        memset(ns, 0, (len + 1) / 2);
        for (int i = 0; i < len; i++) ns[i>>1] |= seq_nt16_table[(uint8_t)s[i]] << ((~i & 1) << 2);
        memcpy(ns + (len + 1) / 2, q, len);
        memcpy(ns + (len + 1) / 2 + len, rec_aux(b), auxl);
        nb->l_data = nl;
        n->bin = 4680;
        /* tag removal */
        if (tags) {
            uint8_t *p = rec_aux(nb), *e = nb->data + nb->l_data;
            while (p + 3 <= e) {
                char t[3] = { p[0], p[1], 0 };
                int sz = aux_size(p + 2);
                int in_list = sm_has(tags, t);
                if ((in_list && !keep) || (!in_list && keep)) {
                    memmove(p, p + 2 + sz, e - (p + 2 + sz));
                    nb->l_data -= 2 + sz; e = nb->data + nb->l_data;
                } else p += 2 + sz;
            }
        } else {
            const char *def[] = { "AS", "CC", "CG", "CP", "H0", "H1", "H2", "HI", "IH", "MC", "MD", "MQ", "NM", "SA", "TS", NULL };
            for (int i = 0; def[i]; i++) { uint8_t *t = aux_get(nb, def[i]); if (t) aux_del(nb, t); }
        }
        if (no_rg) { uint8_t *t = aux_get(nb, "RG"); if (t) aux_del(nb, t); }
        free(s); free(q);
        sf_write(out, oh, nb);
    }
    if (r < -1) ret = 1;
    rec_destroy(b); rec_destroy(nb);
    sf_close(out);
    hdr_destroy(oh); hdr_destroy(h);
    sf_close(in);
    sm_destroy(tags);
    return ret;
}

/* ---------------- import ---------------- */
static void make_unmapped(rec_t *b, const char *name, int flag, const char *seq, const char *qual, int len) {
    core_t *c = &b->core;
    memset(c, 0, sizeof *c);
    int nl = strlen(name) + 1;
    int extranul = (4 - (nl & 3)) & 3;
    c->l_qname = nl + extranul; c->l_extranul = extranul;
    c->flag = flag; c->tid = c->mtid = -1; c->pos = c->mpos = -1; c->l_qseq = len; c->bin = 4680;
    int total = c->l_qname + (len + 1) / 2 + len;
    rec_resize(b, total);
    memcpy(b->data, name, nl);
    memset(b->data + nl, 0, extranul);
    uint8_t *s = b->data + c->l_qname;
    memset(s, 0, (len + 1) / 2);
    for (int i = 0; i < len; i++) s[i>>1] |= seq_nt16_table[(uint8_t)seq[i]] << ((~i & 1) << 2);
    uint8_t *q = s + (len + 1) / 2;
    if (qual && *qual) for (int i = 0; i < len; i++) q[i] = qual[i] - 33;
    else memset(q, 0xff, len);
    b->l_data = total;
}

int sam_parse_aux_str(rec_t *b, const char *s);

int main_import(int argc, char *argv[]) {
    int c, no_pg = 0, uncompressed = 0, casava = 0, name2 = 0, umi = 0;
    char *fn_s = NULL, *fn0 = NULL, *fn1 = NULL, *fn2 = NULL, *outfn = NULL, *rgline = NULL, *rgid = NULL, *taglist = NULL;
    char *bc_tag = "BC", *qt_tag = "QT", *umi_tag = "RX", *order_tag = NULL;
    gopts_t ga; gopts_init(&ga);
    static const struct option lopts[] = {
        {"i1", required_argument, NULL, 1}, {"i2", required_argument, NULL, 2},
        {"no-PG", no_argument, NULL, 3}, {"barcode-tag", required_argument, NULL, 4},
        {"quality-tag", required_argument, NULL, 5}, {"name2", no_argument, NULL, 'N'},
        {"UMI", no_argument, NULL, 'U'}, {"umi", no_argument, NULL, 'U'},
        {"UMI-tag", required_argument, NULL, 6}, {"umi-tag", required_argument, NULL, 6},
        {"order", required_argument, NULL, 7},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"output-fmt", required_argument, NULL, 'O'},
        {"output-fmt-option", required_argument, NULL, GO_OUTPUT_FMT_OPTION},
        {"threads", required_argument, NULL, '@'},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "s:0:1:2:o:O:u@:iNUr:R:T:", lopts, NULL)) >= 0) {
        switch (c) {
        case 's': fn_s = optarg; break;
        case '0': fn0 = optarg; break;
        case '1': fn1 = optarg; break;
        case '2': fn2 = optarg; break;
        case 'o': outfn = optarg; break;
        case 'u': uncompressed = 1; break;
        case 'i': casava = 1; break;
        case 'N': name2 = 1; break;
        case 'U': umi = 1; break;
        case 'r': {
            if (!rgline) { rgline = xmalloc(strlen(optarg) + 8); strcpy(rgline, strncmp(optarg, "@RG", 3) ? "@RG\t" : ""); strcat(rgline, optarg); }
            else { rgline = xrealloc(rgline, strlen(rgline) + strlen(optarg) + 2); strcat(rgline, "\t"); strcat(rgline, optarg); }
            break;
        }
        case 'R': rgid = optarg; break;
        case 'T': taglist = optarg; break;
        case 1: case 2: break;
        case 3: no_pg = 1; break;
        case 4: bc_tag = optarg; break;
        case 5: qt_tag = optarg; break;
        case 6: umi_tag = optarg; break;
        case 7: order_tag = optarg; break;
        case '@': break;
        case 'O': if (gopts_parse(&ga, GO_OUTPUT_FMT, optarg) < 0) { fputs(usage_import, stderr); return 1; } break;
        default: if (c != '?' && gopts_parse(&ga, c, optarg) == 0) break; fputs(usage_import, stderr); return 1;
        }
    }
    (void)qt_tag;
    if (!fn_s && !fn0 && !fn1 && !fn2) {
        int n = argc - optind;
        if (n == 0) { fputs(usage_import, stdout); return 0; }
        if (n == 1) fn_s = argv[optind];
        else if (n >= 2) { fn1 = argv[optind]; fn2 = argv[optind + 1]; }
    }
    hdr_t *h = hdr_init();
    hdr_add_line(h, "HD", "VN", "1.6", "SO", "unsorted", "GO", "query", NULL);
    if (rgline) {
        /* unescape \t */
        char *u = xmalloc(strlen(rgline) + 1), *p = u;
        for (const char *q = rgline; *q; q++) { if (q[0] == '\\' && q[1] == 't') { *p++ = '\t'; q++; } else *p++ = *q; }
        *p = 0;
        hdr_parse_line(h, u, strlen(u), 1);
        hline_t *l = &h->l[h->nl - 1];
        const char *id = hline_get(l, "ID");
        rgid = id ? xstrdup(id) : NULL;
        free(u);
    } else if (rgid) {
        hdr_add_line(h, "RG", "ID", rgid, NULL);
    }
    add_pg(h, no_pg);
    char mode[8] = "w";
    if (outfn) {
        int cmp; int f = fmt_from_fn(outfn, &cmp);
        if (f == FMT_BAM) strcpy(mode, "wb"); else if (cmp) strcpy(mode, "wz");
    }
    if (ga.out_fmt == FMT_BAM) strcpy(mode, "wb"); else if (ga.out_fmt == FMT_SAM) strcpy(mode, "w");
    if (uncompressed && mode[1] == 'b') strcat(mode, "0");
    samfile_t *out = sf_open(outfn ? outfn : "-", mode);
    if (!out) { print_error_errno("import", "Couldn't open output \"%s\"", outfn ? outfn : "-"); hdr_destroy(h); return 1; }
    sf_write_header(out, h);
    rec_t *b = rec_init();
    int ret = 0;
    int64_t order = 0;
    /* determine mode */
    seqreader_t *r1 = NULL, *r2 = NULL;
    int interleaved = 0, single = 0;
    if (fn_s) { r1 = sr_open(fn_s); interleaved = 1; }
    else if (fn0) { r1 = sr_open(fn0); single = 1; }
    else { if (fn1) r1 = sr_open(fn1); if (fn2) r2 = sr_open(fn2); if (fn1 && !fn2) single = 2; }
    if ((fn_s || fn0 || fn1) && !r1) { print_error_errno("import", "Couldn't open \"%s\"", fn_s ? fn_s : fn0 ? fn0 : fn1); ret = 1; goto done; }
    for (int recno = 0;; recno++) {
        seqreader_t *rd = r1;
        int which = 0;
        if (interleaved) which = (recno & 1) ? 2 : 1;
        else if (single == 1) which = 0;
        else if (single == 2) which = 1;
        else { rd = (recno & 1) ? r2 : r1; which = (recno & 1) ? 2 : 1; }
        if (!rd) break;
        int l = sr_read(rd);
        if (l < 0) break;
        char *name = rd->name.s;
        char *comment = rd->comment.s;
        char *nm2 = NULL;
        if (name2 && comment && *comment) {
            char *e = comment; while (*e && !isspace((unsigned char)*e)) e++;
            nm2 = xmalloc(e - comment + 1); memcpy(nm2, comment, e - comment); nm2[e - comment] = 0;
            name = nm2;
        }
        size_t nlen = strlen(name);
        if (which && nlen > 2 && name[nlen-2] == '/' && (name[nlen-1] == '1' || name[nlen-1] == '2')) name[nlen-2] = 0;
        int flag = FUNMAP;
        if (which == 1 && single != 2) flag |= FPAIRED | FMUNMAP | FREAD1;
        else if (which == 2) flag |= FPAIRED | FMUNMAP | FREAD2;
        if (interleaved && single == 0) {}
        char *bc = NULL;
        if (casava && comment && *comment) {
            /* format: 1:N:0:BARCODE */
            char *p = comment;
            if (isdigit((unsigned char)p[0]) && p[1] == ':' && (p[2] == 'Y' || p[2] == 'N') && p[3] == ':') {
                if (p[2] == 'Y') flag |= FQCFAIL;
                char *q = strchr(p + 4, ':');
                if (q) { q++; char *e = q; while (*e && !isspace((unsigned char)*e)) e++; bc = xmalloc(e - q + 1); memcpy(bc, q, e - q); bc[e - q] = 0; }
            }
        }
        make_unmapped(b, name, flag, rd->seq.s, rd->is_fastq ? rd->qual.s : NULL, l);
        if (bc && *bc) aux_append(b, bc_tag, 'Z', strlen(bc) + 1, bc);
        free(bc);
        if (umi) {
            char *colon = strrchr(rec_qname(b), ':');
            if (colon) aux_append(b, umi_tag, 'Z', strlen(colon + 1) + 1, colon + 1);
        }
        if (taglist && comment && *comment) {
            int all = strcmp(taglist, "*") == 0;
            char *d = xstrdup(comment), *save = NULL;
            for (char *t = strtok_r(d, " \t", &save); t; t = strtok_r(NULL, " \t", &save)) {
                if (strlen(t) < 5 || t[2] != ':' || t[4] != ':') continue;
                if (!all) {
                    char tg[3] = { t[0], t[1], 0 };
                    if (!strstr(taglist, tg)) continue;
                }
                sam_parse_aux_str(b, t);
            }
            free(d);
        }
        if (rgid) aux_append(b, "RG", 'Z', strlen(rgid) + 1, rgid);
        if (order_tag) aux_update_int(b, order_tag, order);
        order++;
        free(nm2);
        sf_write(out, h, b);
    }
done:
    sr_close(r1); sr_close(r2);
    rec_destroy(b);
    sf_close(out);
    hdr_destroy(h);
    free(rgline);
    return ret;
}

/* parse a single SAM aux "TG:T:VAL" and append */
int sam_parse_aux_str(rec_t *b, const char *s) {
    /* reuse SAM parser via a fake line */
    kstr l = {0, 0, NULL};
    ks_puts(&l, "x\t4\t*\t0\t0\t*\t*\t0\t0\t*\t*\t");
    ks_puts(&l, s);
    hdr_t *h = hdr_init();
    rec_t *t = rec_init();
    int r = sam_parse1(l.s, l.l, h, t, 0);
    if (r == 0) {
        int al = rec_l_aux(t);
        rec_resize(b, b->l_data + al);
        memcpy(b->data + b->l_data, rec_aux(t), al);
        b->l_data += al;
    }
    rec_destroy(t); hdr_destroy(h); ks_free(&l);
    return r;
}

/* ---------------- collate ---------------- */
static uint32_t hash_wang(uint32_t key) {
    key += ~(key << 15); key ^= (key >> 10); key += (key << 3);
    key ^= (key >> 6); key += ~(key << 11); key ^= (key >> 16);
    return key;
}
static uint32_t hash_x31_wang(const char *s) {
    uint32_t h = (uint8_t)*s;
    if (h) {
        for (++s; *s; ++s) h = (h << 5) - h + (uint8_t)*s;
        return hash_wang(h);
    }
    return 0;
}

typedef struct { uint32_t key; rec_t *b; } celem_t;
static int celem_cmp(const void *pa, const void *pb) {
    const celem_t *x = pa, *y = pb;
    if (x->key != y->key) return x->key < y->key ? -1 : 1;
    int t = strcmp(rec_qname(x->b), rec_qname(y->b));
    if (t) return t;
    int fx = (x->b->core.flag >> 6) & 3, fy = (y->b->core.flag >> 6) & 3;
    return fx - fy;
}

static void stable_sort(celem_t *a, size_t n, celem_t *tmp) {
    if (n < 2) return;
    size_t m = n / 2;
    stable_sort(a, m, tmp); stable_sort(a + m, n - m, tmp);
    size_t i = 0, j = m, k = 0;
    while (i < m && j < n) { if (celem_cmp(&a[j], &a[i]) < 0) tmp[k++] = a[j++]; else tmp[k++] = a[i++]; }
    while (i < m) tmp[k++] = a[i++];
    while (j < n) tmp[k++] = a[j++];
    memcpy(a, tmp, n * sizeof(celem_t));
}

int main_collate(int argc, char *argv[]) {
    int c, to_stdout = 0, uncompressed = 0, fast = 0, level = 1, n_files = 64, no_pg = 0;
    char *outfn = NULL, *tmpprefix = NULL;
    gopts_t ga; gopts_init(&ga);
    static const struct option lopts[] = {
        {"no-PG", no_argument, NULL, 1},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"output-fmt", required_argument, NULL, GO_OUTPUT_FMT},
        {"output-fmt-option", required_argument, NULL, GO_OUTPUT_FMT_OPTION},
        {"reference", required_argument, NULL, GO_REFERENCE},
        {"threads", required_argument, NULL, '@'},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "n:l:uOo:@:fr:T:", lopts, NULL)) >= 0) {
        switch (c) {
        case 'n': n_files = atoi(optarg); break;
        case 'l': level = atoi(optarg); break;
        case 'u': uncompressed = 1; break;
        case 'O': to_stdout = 1; break;
        case 'o': outfn = optarg; break;
        case 'f': fast = 1; break;
        case 'r': break;
        case 'T': tmpprefix = optarg; break;
        case 1: no_pg = 1; break;
        case '@': break;
        default: if (c != '?' && gopts_parse(&ga, c, optarg) == 0) break; fputs(usage_collate, stderr); return 1;
        }
    }
    (void)tmpprefix;
    if (uncompressed) level = 0;
    if (optind >= argc) {
        fprintf(stderr, "collate: no input filename specified.\n");
        fputs(usage_collate, stderr); return 1;
    }
    char *prefix = NULL;
    if (!outfn && !to_stdout) {
        if (optind + 1 >= argc) {
            fprintf(stderr, "collate: no output prefix specified.\n");
            fputs(usage_collate, stderr); return 1;
        }
        prefix = argv[optind + 1];
    }
    const char *fn = argv[optind];
    samfile_t *in = sf_open(fn, "r");
    if (!in) { print_error_errno("collate", "Cannot open input file \"%s\"", fn); return 1; }
    hdr_t *h = sf_read_header(in);
    if (!h) { print_error("collate", "Couldn't read header for '%s'", fn); sf_close(in); return 1; }
    for (int i = 0; i < h->nl; i++) if (h->l[i].type[0] == 'H' && h->l[i].type[1] == 'D') { hline_set(&h->l[i], "SO", "unsorted"); hline_set(&h->l[i], "GO", "query"); break; }
    if (hdr_count_type(h, "HD") == 0) hdr_add_line(h, "HD", "VN", "1.6", "SO", "unsorted", "GO", "query", NULL);
    add_pg(h, no_pg);
    char *ofn = NULL;
    if (to_stdout) ofn = xstrdup("-");
    else if (outfn) ofn = xstrdup(outfn);
    else { ofn = xmalloc(strlen(prefix) + 5); sprintf(ofn, "%s.bam", prefix); }
    char mode[8];
    {
        int cmp; int f = fmt_from_fn(ofn, &cmp);
        if (ga.out_fmt == FMT_SAM || (!ga.out_fmt && f == FMT_SAM)) strcpy(mode, cmp ? "wz" : "w");
        else sprintf(mode, "wb%d", level < 0 ? 1 : (level > 9 ? 9 : level));
    }
    samfile_t *out = sf_open(ofn, mode);
    if (!out) { print_error_errno("collate", "Cannot open output file \"%s\"", ofn); free(ofn); hdr_destroy(h); sf_close(in); return 1; }
    sf_write_header(out, h);
    int ret = 0;
    if (fast) {
        strmap_t *m = sm_init();
        rec_t **store = NULL; int ns = 0, ms = 0;
        rec_t *b = rec_init();
        int r;
        while ((r = sf_read(in, b)) >= 0) {
            if (b->core.flag & (FSECONDARY | FSUPPLEMENTARY)) continue;
            int64_t v;
            if (sm_get(m, rec_qname(b), &v) && v >= 0) {
                sf_write(out, h, store[v]);
                sf_write(out, h, b);
                rec_destroy(store[v]); store[v] = NULL;
                sm_put(m, rec_qname(b), -1);
            } else if (!(b->core.flag & FPAIRED)) {
                sf_write(out, h, b);
            } else {
                if (ns == ms) { ms = ms ? ms * 2 : 1024; store = xrealloc(store, ms * sizeof(rec_t*)); }
                store[ns] = rec_dup(b);
                sm_put(m, rec_qname(b), ns);
                ns++;
            }
        }
        for (int i = 0; i < ns; i++) if (store[i]) { sf_write(out, h, store[i]); rec_destroy(store[i]); }
        free(store); sm_destroy(m); rec_destroy(b);
    } else {
        if (n_files < 1) n_files = 1;
        celem_t **bins = xcalloc(n_files, sizeof(celem_t*));
        size_t *nb = xcalloc(n_files, sizeof(size_t)), *mb = xcalloc(n_files, sizeof(size_t));
        rec_t *b = rec_init();
        int r;
        while ((r = sf_read(in, b)) >= 0) {
            uint32_t k = hash_x31_wang(rec_qname(b));
            uint32_t l = k % n_files;
            if (nb[l] == mb[l]) { mb[l] = mb[l] ? mb[l] * 2 : 64; bins[l] = xrealloc(bins[l], mb[l] * sizeof(celem_t)); }
            bins[l][nb[l]].key = k; bins[l][nb[l]].b = rec_dup(b); nb[l]++;
        }
        if (r < -1) ret = 1;
        rec_destroy(b);
        for (int i = 0; i < n_files; i++) {
            if (!nb[i]) continue;
            celem_t *tmp = xmalloc(nb[i] * sizeof(celem_t));
            stable_sort(bins[i], nb[i], tmp);
            free(tmp);
            for (size_t j = 0; j < nb[i]; j++) { sf_write(out, h, bins[i][j].b); rec_destroy(bins[i][j].b); }
            free(bins[i]);
        }
        free(bins); free(nb); free(mb);
    }
    if (sf_close(out) < 0) ret = 1;
    free(ofn);
    hdr_destroy(h);
    sf_close(in);
    return ret;
}
