    c->flag = flag; c->tid = c->mtid = -1; c->pos = c->mpos = -1; c->l_qseq = len; c->bin = 4680;
    int total = c->l_qname + (len + 1) / 2 + len;
    rec_resize(b, total);
    memcpy(b->data, name, nl);
    memset(b->data + nl, 0, extranul);
    uint8_t *s = b->data + c->l_qname;
    memset(s, 0, (len + 1) / 2);
    for (int i = 0; i < len; i++) s[i>>1] |= seq_nt16_table[(uint8_t)seq[i]] << ((~i & 1) << 2);
