/* ---------------- collate ---------------- */
static uint32_t hash_wang(uint32_t key) {
    key += ~(key << 15); key ^= (key >> 10); key += (key << 3);
    key ^= (key >> 6); key += ~(key << 11); key ^= (key >> 16);
    return key;
}
static uint32_t hash_x31_wang(const char *s) {
    uint32_t h = (uint8_t)*s;
    if (h) {
        for (++s; *s; ++s) h = (h << 5) - h + (uint8_t)*s;
        return hash_wang(h);
    }
    return 0;
}

typedef struct { uint32_t key; rec_t *b; } celem_t;
static int celem_cmp(const void *pa, const void *pb) {
    const celem_t *x = pa, *y = pb;
    if (x->key != y->key) return x->key < y->key ? -1 : 1;
    int t = strcmp(rec_qname(x->b), rec_qname(y->b));
    if (t) return t;
    int fx = (x->b->core.flag >> 6) & 3, fy = (y->b->core.flag >> 6) & 3;
    return fx - fy;
}

static void stable_sort(celem_t *a, size_t n, celem_t *tmp) {
    if (n < 2) return;
    size_t m = n / 2;
    stable_sort(a, m, tmp); stable_sort(a + m, n - m, tmp);
    size_t i = 0, j = m, k = 0;
    while (i < m && j < n) { if (celem_cmp(&a[j], &a[i]) < 0) tmp[k++] = a[j++]; else tmp[k++] = a[i++]; }
    while (i < m) tmp[k++] = a[i++];
    while (j < n) tmp[k++] = a[j++];
    memcpy(a, tmp, n * sizeof(celem_t));
}

