        char *e;
        if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) l->num = (double)strtoll(p, &e, 16);
        else l->num = strtod(p, &e);
        l->p = e; l->tok = T_NUM; return;
    }
    if (*p == '"' || *p == '\'') {
        char q = *p++;
        while (*p && *p != q) {
            if (*p == '\\' && p[1]) { p++; switch (*p) { case 't': ks_putc(&l->str, '\t'); break; case 'n': ks_putc(&l->str, '\n'); break; default: ks_putc(&l->str, *p); } p++; }
            else ks_putc(&l->str, *p++);
        }
        if (*p != q) { l->tok = T_ERR; return; }
        l->p = p + 1; l->tok = T_STR; ks_putsn(&l->str, "", 0); return;
    }
    if (*p == '[') {
        if (p[1] && p[2] && p[3] == ']') { ks_putsn(&l->str, p + 1, 2); l->p = p + 4; l->tok = T_TAG; return; }
        l->tok = T_ERR; return;
    }
    if (isalpha((unsigned char)*p) || *p == '_') {
        while (isalnum((unsigned char)*p) || *p == '_' || *p == '.') ks_putc(&l->str, *p++);
        l->p = p; l->tok = T_ID; return;
    }
    l->p = p + 1;
    switch (*p) {
    case '(': l->tok = T_LP; return;
    case ')': l->tok = T_RP; return;
    case ',': l->tok = T_COMMA; return;
    case '+': l->tok = T_PLUS; return;
    case '-': l->tok = T_MINUS; return;
    case '*': l->tok = T_MUL; return;
    case '/': l->tok = T_DIV; return;
    case '%': l->tok = T_MOD; return;
    case '~': l->tok = T_BNOT; return;
    case '^': l->tok = T_BXOR; return;
    case '|': if (p[1] == '|') { l->p++; l->tok = T_OR; } else l->tok = T_BOR; return;
    case '&': if (p[1] == '&') { l->p++; l->tok = T_AND; } else l->tok = T_BAND; return;
    case '=': if (p[1] == '=') { l->p++; l->tok = T_EQ; } else if (p[1] == '~') { l->p++; l->tok = T_MATCH; } else l->tok = T_ERR; return;
    case '!': if (p[1] == '=') { l->p++; l->tok = T_NE; } else if (p[1] == '~') { l->p++; l->tok = T_NMATCH; } else l->tok = T_NOT; return;
    case '<': if (p[1] == '=') { l->p++; l->tok = T_LE; } else l->tok = T_LT; return;
    case '>': if (p[1] == '=') { l->p++; l->tok = T_GE; } else l->tok = T_GT; return;
    }
    l->tok = T_ERR;
}

static node_t *mk(int type) { return calloc(1, sizeof(node_t)); }
static void node_free(node_t *n) {
    if (!n) return;
    node_free(n->a); node_free(n->b); free(n->str);
    if (n->re) { regfree(n->re); free(n->re); }
    free(n);
}

enum { F_QNAME = 1, F_FLAG, F_RNAME, F_POS, F_ENDPOS, F_MAPQ, F_CIGAR, F_RNEXT, F_PNEXT, F_TLEN, F_SEQ, F_QUAL,
       F_QLEN, F_RLEN, F_SCLEN, F_HCLEN, F_LIBRARY, F_NCIGAR, F_TID, F_MTID, F_FLAGBIT };

static struct { const char *name; int id; int bit; } fields[] = {
    {"qname", F_QNAME, 0}, {"flag", F_FLAG, 0}, {"rname", F_RNAME, 0}, {"pos", F_POS, 0}, {"endpos", F_ENDPOS, 0},
    {"mapq", F_MAPQ, 0}, {"cigar", F_CIGAR, 0}, {"rnext", F_RNEXT, 0}, {"mrname", F_RNEXT, 0}, {"pnext", F_PNEXT, 0},
    {"mpos", F_PNEXT, 0}, {"tlen", F_TLEN, 0}, {"seq", F_SEQ, 0}, {"qual", F_QUAL, 0}, {"qlen", F_QLEN, 0},
    {"rlen", F_RLEN, 0}, {"sclen", F_SCLEN, 0}, {"hclen", F_HCLEN, 0}, {"library", F_LIBRARY, 0}, {"ncigar", F_NCIGAR, 0},
    {"tid", F_TID, 0}, {"mtid", F_MTID, 0},
    {"flag.paired", F_FLAGBIT, 1}, {"flag.proper_pair", F_FLAGBIT, 2}, {"flag.unmap", F_FLAGBIT, 4},
    {"flag.munmap", F_FLAGBIT, 8}, {"flag.reverse", F_FLAGBIT, 16}, {"flag.mreverse", F_FLAGBIT, 32},
    {"flag.read1", F_FLAGBIT, 64}, {"flag.read2", F_FLAGBIT, 128}, {"flag.secondary", F_FLAGBIT, 256},
    {"flag.qcfail", F_FLAGBIT, 512}, {"flag.dup", F_FLAGBIT, 1024}, {"flag.supplementary", F_FLAGBIT, 2048},
    {NULL, 0, 0}
};

static node_t *p_expr(lex_t *l);

static node_t *p_simple(lex_t *l) {
    node_t *n;
    switch (l->tok) {
    case T_NUM: n = mk(0); n->type = N_NUM; n->d = l->num; next(l); return n;
    case T_STR: n = mk(0); n->type = N_STR; n->str = strdup(l->str.s ? l->str.s : ""); next(l); return n;
    case T_TAG: n = mk(0); n->type = N_TAG; n->tag[0] = l->str.s[0]; n->tag[1] = l->str.s[1]; next(l); return n;
    case T_LP:
        next(l);
        n = p_expr(l);
        if (!n || l->tok != T_RP) { node_free(n); return NULL; }
        next(l);
        return n;
    case T_ID: {
        char *id = strdup(l->str.s);
        next(l);
        if (l->tok == T_LP) {
            next(l);
            n = mk(0); n->type = N_FUNC; n->str = id;
            n->a = p_expr(l);
            if (!n->a) { node_free(n); return NULL; }
            if (l->tok == T_COMMA) { next(l); n->b = p_expr(l); if (!n->b) { node_free(n); return NULL; } }
            if (l->tok != T_RP) { node_free(n); return NULL; }
            next(l);
            const char *fn[] = {"length", "min", "max", "avg", "exists", "default", "sqrt", "log", "exp", "pow", "abs", NULL};
            int ok = 0;
            for (int i = 0; fn[i]; i++) if (strcmp(id, fn[i]) == 0) ok = 1;
            if (!ok) { node_free(n); return NULL; }
            return n;
        }
        for (int i = 0; fields[i].name; i++) if (strcmp(fields[i].name, id) == 0) {
            n = mk(0); n->type = N_FIELD; n->op = fields[i].id; n->d = fields[i].bit;
            free(id);
            return n;
        }
        free(id);
        return NULL;
    }
    }
    return NULL;
}

static node_t *p_unary(lex_t *l) {
    if (l->tok == T_PLUS || l->tok == T_MINUS || l->tok == T_NOT || l->tok == T_BNOT) {
        int op = l->tok; next(l);
        node_t *a = p_unary(l);
        if (!a) return NULL;
        node_t *n = mk(0); n->type = N_UNARY; n->op = op; n->a = a;
        return n;
    }
    return p_simple(l);
}

static node_t *bin(int op, node_t *a, node_t *b) {
    if (!a || !b) { node_free(a); node_free(b); return NULL; }
    node_t *n = mk(0); n->type = N_BINARY; n->op = op; n->a = a; n->b = b;
    return n;
}

#define LEVEL(name, sub, cond) \
static node_t *name(lex_t *l) { \
    node_t *a = sub(l); \
    while (a && (cond)) { int op = l->tok; next(l); a = bin(op, a, sub(l)); } \
    return a; }

LEVEL(p_mul, p_unary, l->tok == T_MUL || l->tok == T_DIV || l->tok == T_MOD)
LEVEL(p_plus, p_mul, l->tok == T_PLUS || l->tok == T_MINUS)
LEVEL(p_cmp, p_plus, l->tok == T_LT || l->tok == T_LE || l->tok == T_GT || l->tok == T_GE)
LEVEL(p_eq, p_cmp, l->tok == T_EQ || l->tok == T_NE || l->tok == T_MATCH || l->tok == T_NMATCH)
LEVEL(p_band, p_eq, l->tok == T_BAND)
LEVEL(p_bxor, p_band, l->tok == T_BXOR)
LEVEL(p_bor, p_bxor, l->tok == T_BOR)
LEVEL(p_and, p_bor, l->tok == T_AND)
LEVEL(p_or, p_and, l->tok == T_OR)

static node_t *p_expr(lex_t *l) { return p_or(l); }

expr_t *expr_parse(const char *s) {
    lex_t l; memset(&l, 0, sizeof l);
    l.p = s;
    next(&l);
    node_t *n = p_expr(&l);
    if (!n || l.tok != T_EOF) { node_free(n); ks_free(&l.str); return NULL; }
    ks_free(&l.str);
    expr_t *e = calloc(1, sizeof(expr_t));
    e->root = n;
    return e;
}
expr_t *expr_bad(void) { expr_t *e = calloc(1, sizeof(expr_t)); e->bad = 1; return e; }
void expr_destroy(expr_t *e) { if (!e) return; node_free(e->root); free(e); }

static void vset_num(val_t *v, double d) { v->is_str = 0; v->is_null = 0; v->d = d; }
static void vset_str(val_t *v, const char *s) { v->is_str = 1; v->is_null = 0; v->s.l = 0; ks_puts(&v->s, s); }
static void vset_null(val_t *v) { v->is_str = 0; v->is_null = 1; v->d = 0; }
static int vtrue(const val_t *v) { if (v->is_null) return 0; if (v->is_str) return 1; return v->d != 0; }

const char *rec_library(const hdr_t *h, const rec_t *b);

static int eval(node_t *n, const hdr_t *h, const rec_t *b, val_t *r);

static int eval_field(node_t *n, const hdr_t *h, const rec_t *b, val_t *r) {
    const core_t *c = &b->core;
    switch (n->op) {
    case F_QNAME: vset_str(r, rec_qname(b)); break;
    case F_FLAG: vset_num(r, c->flag); break;
    case F_FLAGBIT: vset_num(r, (c->flag & (int)n->d) ? 1 : 0); break;
    case F_RNAME: vset_str(r, c->tid >= 0 ? hdr_tname(h, c->tid) : "*"); break;
    case F_TID: vset_num(r, c->tid); break;
    case F_MTID: vset_num(r, c->mtid); break;
    case F_POS: vset_num(r, c->pos + 1); break;
    case F_ENDPOS: vset_num(r, rec_endpos(b)); break;
    case F_MAPQ: vset_num(r, c->qual); break;
    case F_CIGAR: {
        kstr s = {0, 0, NULL};
        if (!c->n_cigar) ks_putc(&s, '*');
        for (uint32_t i = 0; i < c->n_cigar; i++) { uint32_t v = rec_cigar(b)[i]; ks_puti(&s, cig_len(v)); ks_putc(&s, CIGAR_STR[cig_op(v)]); }
        vset_str(r, s.s); ks_free(&s); break;
    }
    case F_NCIGAR: vset_num(r, c->n_cigar); break;
    case F_RNEXT: vset_str(r, c->mtid >= 0 ? hdr_tname(h, c->mtid) : "*"); break;
    case F_PNEXT: vset_num(r, c->mpos + 1); break;
    case F_TLEN: vset_num(r, c->isize); break;
    case F_SEQ: {
        kstr s = {0, 0, NULL};
        for (int i = 0; i < c->l_qseq; i++) ks_putc(&s, seq_nt16_str[seqi(rec_seq(b), i)]);
        if (!c->l_qseq) ks_putsn(&s, "", 0);
        vset_str(r, s.s); ks_free(&s); break;
    }
    case F_QUAL: {
        kstr s = {0, 0, NULL};
        const uint8_t *q = rec_qual(b);
        if (c->l_qseq && q[0] != 0xff) for (int i = 0; i < c->l_qseq; i++) ks_putc(&s, q[i] + 33);
        ks_putsn(&s, "", 0);
        vset_str(r, s.s); ks_free(&s); break;
    }
    case F_QLEN: vset_num(r, c->l_qseq); break;
    case F_RLEN: vset_num(r, cigar2rlen(c->n_cigar, rec_cigar(b))); break;
    case F_SCLEN: case F_HCLEN: {
        int want = n->op == F_SCLEN ? C_SOFT_CLIP : C_HARD_CLIP; int64_t t = 0;
        for (uint32_t i = 0; i < c->n_cigar; i++) if ((int)cig_op(rec_cigar(b)[i]) == want) t += cig_len(rec_cigar(b)[i]);
        vset_num(r, t); break;
    }
    case F_LIBRARY: { const char *lb = rec_library(h, b); if (lb) vset_str(r, lb); else vset_null(r); break; }
    default: return -1;
    }
    return 0;
}

static int eval(node_t *n, const hdr_t *h, const rec_t *b, val_t *r) {
    switch (n->type) {
    case N_NUM: vset_num(r, n->d); return 0;
    case N_STR: vset_str(r, n->str); return 0;
    case N_FIELD: return eval_field(n, h, b, r);
    case N_TAG: {
        uint8_t *t = aux_get(b, n->tag);
        if (!t) { vset_null(r); return 0; }
        switch (t[0]) {
        case 'A': { char s[2] = { t[1], 0 }; vset_str(r, s); break; }
        case 'Z': case 'H': vset_str(r, (char*)t + 1); break;
        case 'f': case 'd': vset_num(r, aux2f(t)); break;
        case 'B': vset_num(r, aux_B_len(t)); break;
        default: vset_num(r, (double)aux2i(t)); break;
        }
        return 0;
    }
    case N_UNARY: {
        if (eval(n->a, h, b, r) < 0) return -1;
        switch (n->op) {
        case T_NOT: { int t = vtrue(r); vset_num(r, !t); break; }
        case T_MINUS: if (r->is_str || r->is_null) { vset_null(r); } else r->d = -r->d; break;
        case T_PLUS: break;
        case T_BNOT: if (r->is_str || r->is_null) vset_null(r); else r->d = (double)(~(int64_t)r->d); break;
        }
        return 0;
    }
    case N_FUNC: {
        val_t a = {0}, bb = {0};
        if (eval(n->a, h, b, &a) < 0) return -1;
        const char *f = n->str;
        if (strcmp(f, "length") == 0) { if (a.is_null) vset_null(r); else vset_num(r, a.is_str ? (double)a.s.l : 0); }
        else if (strcmp(f, "exists") == 0) vset_num(r, a.is_null ? 0 : 1);
        else if (strcmp(f, "default") == 0) {
            if (a.is_null) { if (n->b && eval(n->b, h, b, &bb) < 0) return -1; *r = bb; bb.s.s = NULL; if (r->is_str) { val_t t = {0}; vset_str(&t, r->s.s); } }
            else { if (a.is_str) vset_str(r, a.s.s); else vset_num(r, a.d); }
        }
        else if (strcmp(f, "min") == 0 || strcmp(f, "max") == 0 || strcmp(f, "avg") == 0) {
            if (a.is_null) vset_null(r);
            else if (a.is_str) {
                if (!a.s.l) vset_null(r);
                else {
                    double mn = 1e300, mx = -1e300, sum = 0;
                    for (size_t i = 0; i < a.s.l; i++) { double v = (uint8_t)a.s.s[i]; if (v < mn) mn = v; if (v > mx) mx = v; sum += v; }
                    if (f[1] == 'i') vset_num(r, mn); else if (f[1] == 'a') vset_num(r, mx); else vset_num(r, sum / a.s.l);
                }
            } else vset_num(r, a.d);
        }
        else if (strcmp(f, "sqrt") == 0) vset_num(r, sqrt(a.d));
        else if (strcmp(f, "log") == 0) vset_num(r, log(a.d));
        else if (strcmp(f, "exp") == 0) vset_num(r, exp(a.d));
        else if (strcmp(f, "abs") == 0) vset_num(r, fabs(a.d));
        else if (strcmp(f, "pow") == 0) { if (n->b && eval(n->b, h, b, &bb) < 0) return -1; vset_num(r, pow(a.d, bb.d)); }
        ks_free(&a.s); ks_free(&bb.s);
        return 0;
    }
    case N_BINARY: {
        val_t a = {0}, c = {0};
        if (n->op == T_AND) {
            if (eval(n->a, h, b, &a) < 0) return -1;
            if (!vtrue(&a)) { vset_num(r, 0); ks_free(&a.s); return 0; }
            if (eval(n->b, h, b, &c) < 0) return -1;
            vset_num(r, vtrue(&c)); ks_free(&a.s); ks_free(&c.s); return 0;
        }
        if (n->op == T_OR) {
            if (eval(n->a, h, b, &a) < 0) return -1;
            if (vtrue(&a)) { vset_num(r, 1); ks_free(&a.s); return 0; }
            if (eval(n->b, h, b, &c) < 0) return -1;
            vset_num(r, vtrue(&c)); ks_free(&a.s); ks_free(&c.s); return 0;
        }
        if (eval(n->a, h, b, &a) < 0 || eval(n->b, h, b, &c) < 0) return -1;
        int op = n->op;
        if (op == T_MATCH || op == T_NMATCH) {
            if (a.is_null || c.is_null || !a.is_str || !c.is_str) vset_num(r, 0);
            else {
                if (!n->re) {
                    n->re = malloc(sizeof(regex_t));
                    if (regcomp(n->re, c.s.s, REG_EXTENDED | REG_NOSUB) != 0) { free(n->re); n->re = NULL; ks_free(&a.s); ks_free(&c.s); return -1; }
                }
                int m = regexec(n->re, a.s.s, 0, NULL, 0) == 0;
                vset_num(r, op == T_MATCH ? m : !m);
            }
        } else if (a.is_null || c.is_null) {
            if (op == T_EQ) vset_num(r, a.is_null && c.is_null);
            else if (op == T_NE) vset_num(r, !(a.is_null && c.is_null));
            else vset_null(r);
        } else if (a.is_str && c.is_str) {
            int t = strcmp(a.s.s, c.s.s);
            switch (op) {
            case T_EQ: vset_num(r, t == 0); break;
            case T_NE: vset_num(r, t != 0); break;
            case T_LT: vset_num(r, t < 0); break;
            case T_LE: vset_num(r, t <= 0); break;
            case T_GT: vset_num(r, t > 0); break;
            case T_GE: vset_num(r, t >= 0); break;
            default: vset_null(r);
            }
        } else if (a.is_str || c.is_str) {
            if (op == T_EQ) vset_num(r, 0); else if (op == T_NE) vset_num(r, 1); else vset_null(r);
        } else {
            double x = a.d, y = c.d;
            switch (op) {
            case T_EQ: vset_num(r, x == y); break;
            case T_NE: vset_num(r, x != y); break;
            case T_LT: vset_num(r, x < y); break;
            case T_LE: vset_num(r, x <= y); break;
            case T_GT: vset_num(r, x > y); break;
            case T_GE: vset_num(r, x >= y); break;
            case T_PLUS: vset_num(r, x + y); break;
            case T_MINUS: vset_num(r, x - y); break;
            case T_MUL: vset_num(r, x * y); break;
            case T_DIV: vset_num(r, x / y); break;
            case T_MOD: vset_num(r, (double)((int64_t)x % ((int64_t)y ? (int64_t)y : 1))); break;
            case T_BAND: vset_num(r, (double)((int64_t)x & (int64_t)y)); break;
            case T_BOR: vset_num(r, (double)((int64_t)x | (int64_t)y)); break;
            case T_BXOR: vset_num(r, (double)((int64_t)x ^ (int64_t)y)); break;
            }
        }
        ks_free(&a.s); ks_free(&c.s);
        return 0;
    }
    }
    return -1;
}

int expr_eval_rec(expr_t *e, const hdr_t *h, const rec_t *b) {
    if (e->bad) return -1;
    val_t v = {0};
    if (eval(e->root, h, b, &v) < 0) { ks_free(&v.s); return -1; }
    int t = vtrue(&v);
    ks_free(&v.s);
    return t;
}
