cd /workspace && git add -A && git commit -qm "split, reset, import, collate" -q; cd src && cat > expr.c <<'EOF'
/* Filter expression language for view -e */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
#include <regex.h>
#include "expr.h"
#include "ks.h"

typedef struct { int is_str, is_null; double d; kstr s; } val_t;

enum { N_NUM, N_STR, N_FIELD, N_TAG, N_UNARY, N_BINARY, N_FUNC, N_REGEX };
typedef struct node_s {
    int type;
    int op; /* for unary/binary: token code; for field: field id */
    double d;
    char *str;
    char tag[3];
    struct node_s *a, *b;
    regex_t *re;
} node_t;

struct expr_s { node_t *root; int bad; };

/* tokens */
enum { T_EOF = 0, T_NUM, T_STR, T_ID, T_TAG, T_LP, T_RP, T_COMMA,
       T_OR, T_AND, T_BOR, T_BXOR, T_BAND, T_EQ, T_NE, T_MATCH, T_NMATCH,
       T_LT, T_LE, T_GT, T_GE, T_PLUS, T_MINUS, T_MUL, T_DIV, T_MOD, T_NOT, T_BNOT, T_ERR };

typedef struct { const char *p; int tok; double num; kstr str; } lex_t;

static void next(lex_t *l) {
    while (isspace((unsigned char)*l->p)) l->p++;
    const char *p = l->p;
    l->str.l = 0;
    if (!*p) { l->tok = T_EOF; return; }
    if (isdigit((unsigned char)*p) || (*p == '.' && isdigit((unsigned char)p[1]))) {
        char *e;
        if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X')) l->num = (double)strtoll(p, &e, 16);
        else l->num = strtod(p, &e);
        l->p = e; l->tok = T_NUM; return;
    }
    if (*p == '"' || *p == '\'') {
        char q = *p++;
        while (*p && *p != q) {
            if (*p == '\\' && p[1]) { p++; switch (*p) { case 't': ks_putc(&l->str, '\t'); break; case 'n': ks_putc(&l->str, '\n'); break; default: ks_putc(&l->str, *p); } p++; }
            else ks_putc(&l->str, *p++);
        }
        if (*p != q) { l->tok = T_ERR; return; }
        l->p = p + 1; l->tok = T_STR; ks_putsn(&l->str, "", 0); return;
    }
    if (*p == '[') {
        if (p[1] && p[2] && p[3] == ']') { ks_putsn(&l->str, p + 1, 2); l->p = p + 4; l->tok = T_TAG; return; }
        l->tok = T_ERR; return;
    }
    if (isalpha((unsigned char)*p) || *p == '_') {
        while (isalnum((unsigned char)*p) || *p == '_' || *p == '.') ks_putc(&l->str, *p++);
        l->p = p; l->tok = T_ID; return;
    }
    l->p = p + 1;
    switch (*p) {
    case '(': l->tok = T_LP; return;
    case ')': l->tok = T_RP; return;
    case ',': l->tok = T_COMMA; return;
    case '+': l->tok = T_PLUS; return;
    case '-': l->tok = T_MINUS; return;
    case '*': l->tok = T_MUL; return;
    case '/': l->tok = T_DIV; return;
    case '%': l->tok = T_MOD; return;
    case '~': l->tok = T_BNOT; return;
    case '^': l->tok = T_BXOR; return;
    case '|': if (p[1] == '|') { l->p++; l->tok = T_OR; } else l->tok = T_BOR; return;
    case '&': if (p[1] == '&') { l->p++; l->tok = T_AND; } else l->tok = T_BAND; return;
    case '=': if (p[1] == '=') { l->p++; l->tok = T_EQ; } else if (p[1] == '~') { l->p++; l->tok = T_MATCH; } else l->tok = T_ERR; return;
    case '!': if (p[1] == '=') { l->p++; l->tok = T_NE; } else if (p[1] == '~') { l->p++; l->tok = T_NMATCH; } else l->tok = T_NOT; return;
    case '<': if (p[1] == '=') { l->p++; l->tok = T_LE; } else l->tok = T_LT; return;
    case '>': if (p[1] == '=') { l->p++; l->tok = T_GE; } else l->tok = T_GT; return;
    }
    l->tok = T_ERR;
}

static node_t *mk(int type) { return calloc(1, sizeof(node_t)); }
static void node_free(node_t *n) {
    if (!n) return;
    node_free(n->a); node_free(n->b); free(n->str);
    if (n->re) { regfree(n->re); free(n->re); }
    free(n);
}

enum { F_QNAME = 1, F_FLAG, F_RNAME, F_POS, F_ENDPOS, F_MAPQ, F_CIGAR, F_RNEXT, F_PNEXT, F_TLEN, F_SEQ, F_QUAL,
       F_QLEN, F_RLEN, F_SCLEN, F_HCLEN, F_LIBRARY, F_NCIGAR, F_TID, F_MTID, F_FLAGBIT };

static struct { const char *name; int id; int bit; } fields[] = {
    {"qname", F_QNAME, 0}, {"flag", F_FLAG, 0}, {"rname", F_RNAME, 0}, {"pos", F_POS, 0}, {"endpos", F_ENDPOS, 0},
    {"mapq", F_MAPQ, 0}, {"cigar", F_CIGAR, 0}, {"rnext", F_RNEXT, 0}, {"mrname", F_RNEXT, 0}, {"pnext", F_PNEXT, 0},
    {"mpos", F_PNEXT, 0}, {"tlen", F_TLEN, 0}, {"seq", F_SEQ, 0}, {"qual", F_QUAL, 0}, {"qlen", F_QLEN, 0},
    {"rlen", F_RLEN, 0}, {"sclen", F_SCLEN, 0}, {"hclen", F_HCLEN, 0}, {"library", F_LIBRARY, 0}, {"ncigar", F_NCIGAR, 0},
    {"tid", F_TID, 0}, {"mtid", F_MTID, 0},
