            break;
        case 'u': uncompressed = 1; break;
        case 1001: include_fails = 1; break;
        case 1002: no_pg = 1; break;
        case 1003: case 1004: case 1005: case 1007: case 1008: break;
        case 1006: barcode_tag = optarg; break;
        case 1009: use_rg = 1; break;
        case 1010: json = 1; report = 1; break;
        case 1011: dup_count = 1; break;
