        if (barcode_tag) { uint8_t *t = aux_get(rb, barcode_tag); if (t && t[0] == 'Z') { strncat(xbuf, (char*)t + 1, 500); } }
        if (use_rg) { uint8_t *t = aux_get(rb, "RG"); if (t && t[0] == 'Z') { strcat(xbuf, ":"); strncat(xbuf, (char*)t + 1, 500); } }
        extra = xbuf;
        if (is_pair(rb)) {
