                if (new_s + tie > old_s) { dupi = v; keepi = i; sm_put(pair, key.s, i); }
                else { dupi = i; keepi = v; }
                if (!(recs[dupi]->core.flag & FDUP)) {
                    recs[dupi]->core.flag |= FDUP;
                    dup_pair++;
