                    fprintf(f, "WRITTEN: %lld\n", (long long)written);
                    fprintf(f, "EXCLUDED: %lld\n", (long long)n_excluded);
                    fprintf(f, "EXAMINED: %lld\n", (long long)n_examined);
                    fprintf(f, "PAIRED: %lld\n", (long long)n_paired);
                    fprintf(f, "SINGLE: %lld\n", (long long)n_single);
                    fprintf(f, "DUPLICATE PAIR: %lld\n", (long long)dup_pair);
                    fprintf(f, "DUPLICATE SINGLE: %lld\n", (long long)dup_single);
                    fprintf(f, "DUPLICATE PAIR OPTICAL: %lld\n", 0LL);
                    fprintf(f, "DUPLICATE SINGLE OPTICAL: %lld\n", 0LL);
                    fprintf(f, "DUPLICATE NON PRIMARY: %lld\n", 0LL);
                    fprintf(f, "DUPLICATE NON PRIMARY OPTICAL: %lld\n", 0LL);
                    fprintf(f, "DUPLICATE PRIMARY TOTAL: %lld\n", (long long)(dup_pair + dup_single));
                    fprintf(f, "DUPLICATE TOTAL: %lld\n", (long long)(dup_pair + dup_single));
                    fprintf(f, "ESTIMATED_LIBRARY_SIZE: %lld\n", 0LL);
                    if (f != stderr) fclose(f);
                }
            }
        }
