    else {
        s->nreads_paired_and_mapped++;
        if (b->core.flag & FPROPER_PAIR) s->nreads_properly_paired++;
        if (b->core.tid != b->core.mtid) s->nreads_anomalous++;
    }
    count_indels(s, b);
    for (uint32_t i = 0; i < b->core.n_cigar; i++) {
        int op = cig_op(rec_cigar(b)[i]);
        if (op == C_MATCH || op == C_INS || op == C_EQUAL || op == C_DIFF) s->nbases_mapped_cigar += cig_len(rec_cigar(b)[i]);
    }
    uint8_t *nm = aux_get(b, "NM");
    if (nm) s->nmismatches += aux2i(nm);
    if (paired_mapped && is_orig) {
        int64_t isize = b->core.isize; if (isize < 0) isize = -isize;
        if (s->nisize > 0 && isize >= s->nisize) isize = s->nisize - 1;
        if (isize > 0 || b->core.tid == b->core.mtid) {
            int64_t pos_fst = b->core.mpos - b->core.pos;
            int is_fst = (b->core.flag & FREAD1) ? 1 : -1;
            int is_fwd = (b->core.flag & FREVERSE) ? -1 : 1;
            int is_mfwd = (b->core.flag & FMREVERSE) ? -1 : 1;
            if (is_fwd * is_mfwd > 0) s->is_other[isize]++;
            else if (is_fst * pos_fst > 0) { if (is_fst * is_fwd > 0) s->is_in[isize]++; else s->is_out[isize]++; }
            else if (is_fst * pos_fst < 0) { if (is_fst * is_fwd > 0) s->is_out[isize]++; else s->is_in[isize]++; }
        }
    }
    /* sortedness */
    if (s->is_sorted) {
        if (b->core.tid < s->last_tid || (b->core.tid == s->last_tid && b->core.pos < s->last_pos)) s->is_sorted = 0;
    }
    if (b->core.tid != s->last_tid) {
        if (s->is_sorted) rbuf_flush(s, -1);
        s->rbuf_pos = -1;
    }
    s->last_tid = b->core.tid; s->last_pos = b->core.pos;
    if (is_orig) {
        if (s->tid != b->core.tid || b->core.pos - s->gcd_pos > s->gcd_bin_size) {
            if (s->igcd + 2 >= s->ngcd) { s->ngcd *= 2; s->gcd = xrealloc(s->gcd, s->ngcd * sizeof(gcd_t)); }
            s->igcd++;
            s->gcd[s->igcd].gc = 0; s->gcd[s->igcd].depth = 0;
            s->tid = b->core.tid; s->gcd_pos = b->core.pos;
        }
        s->gcd[s->igcd].depth++;
        s->gcd[s->igcd].gc += (float)gc_count / seq_len;
    }
    if (s->is_sorted) {
        rbuf_flush(s, b->core.pos);
        int64_t p = b->core.pos;
        for (uint32_t i = 0; i < b->core.n_cigar; i++) {
            int op = cig_op(rec_cigar(b)[i]); int64_t l = cig_len(rec_cigar(b)[i]);
            if (op == C_MATCH || op == C_EQUAL || op == C_DIFF) { rbuf_insert(s, p, p + l - 1); p += l; }
            else if (op == C_DEL || op == C_REF_SKIP) p += l;
        }
    }
}

static int gcd_cmp(const void *a, const void *b) {
    const gcd_t *x = a, *y = b;
    if (x->gc < y->gc) return -1;
    if (x->gc > y->gc) return 1;
    if (x->depth < y->depth) return -1;
    if (x->depth > y->depth) return 1;
    return 0;
}
static float gcd_percentile(gcd_t *g, int N, int p) {
    float n, d; int k;
    n = p * (N + 1) / 100;
    k = n;
    if (k <= 0) return g[0].depth;
    if (k >= N) return g[N-1].depth;
    d = n - k;
    return g[k-1].depth + d * (g[k].depth - g[k-1].depth);
}

static void output_stats(FILE *to, stats_t *s, int sparse, int argc, char **argv) {
    int isize, ibulk = 0, icov;
    uint64_t nisize = 0, n_in = 0, n_out = 0, n_oth = 0;
    double bulk = 0, avg_isize = 0, sd_isize = 0;
    for (isize = 0; isize < s->nisize; isize++) {
        s->is_in[isize] = (uint64_t)(s->is_in[isize] * 0.5);
        s->is_out[isize] = (uint64_t)(s->is_out[isize] * 0.5);
        s->is_other[isize] = (uint64_t)(s->is_other[isize] * 0.5);
        n_in += s->is_in[isize]; n_out += s->is_out[isize]; n_oth += s->is_other[isize];
        nisize += s->is_in[isize] + s->is_out[isize] + s->is_other[isize];
    }
    for (isize = 0; isize < s->nisize; isize++) {
        uint64_t num = s->is_in[isize] + s->is_out[isize] + s->is_other[isize];
        if (num > 0) ibulk = isize + 1;
        bulk += num;
        avg_isize += isize * (double)num;
        if (bulk / nisize > s->isize_main_bulk) { ibulk = isize + 1; nisize = bulk; break; }
    }
    avg_isize /= nisize ? nisize : 1;
    for (isize = 1; isize < ibulk; isize++)
        sd_isize += (s->is_in[isize] + s->is_out[isize] + s->is_other[isize]) * (isize - avg_isize) * (isize - avg_isize) / (nisize ? nisize : 1);
    sd_isize = sqrt(sd_isize);
    fprintf(to, "# This file was produced by samtools stats (%s+htslib-%s) and can be plotted using plot-bamstats\n", g_version, "1.23.1");
    fprintf(to, "# This file contains statistics for all reads.\n");
    fprintf(to, "# The command line was:  %s", argv[0]);
    for (int i = 1; i < argc; i++) fprintf(to, " %s", argv[i]);
    fprintf(to, "\n");
    fprintf(to, "# CHK, Checksum\t[2]Read Names\t[3]Sequences\t[4]Qualities\n");
    fprintf(to, "# CHK, CRC32 of reads which passed filtering followed by addition (32bit overflow)\n");
    fprintf(to, "CHK\t%08x\t%08x\t%08x\n", s->ck_names, s->ck_reads, s->ck_quals);
    fprintf(to, "# Summary Numbers. Use `grep ^SN | cut -f 2-` to extract this part.\n");
    uint64_t nseq = s->nreads_1st + s->nreads_2nd + s->nreads_other;
    fprintf(to, "SN\traw total sequences:\t%ld\t# excluding supplementary and secondary reads\n", (long)(s->nreads_filtered + nseq));
    fprintf(to, "SN\tfiltered sequences:\t%ld\n", (long)s->nreads_filtered);
    fprintf(to, "SN\tsequences:\t%ld\n", (long)nseq);
    fprintf(to, "SN\tis sorted:\t%d\n", s->is_sorted ? 1 : 0);
    fprintf(to, "SN\t1st fragments:\t%ld\n", (long)s->nreads_1st);
    fprintf(to, "SN\tlast fragments:\t%ld\n", (long)s->nreads_2nd);
    fprintf(to, "SN\treads mapped:\t%ld\n", (long)(s->nreads_paired_and_mapped + s->nreads_single_mapped));
    fprintf(to, "SN\treads mapped and paired:\t%ld\t# paired-end technology bit set + both mates mapped\n", (long)s->nreads_paired_and_mapped);
    fprintf(to, "SN\treads unmapped:\t%ld\n", (long)s->nreads_unmapped);
    fprintf(to, "SN\treads properly paired:\t%ld\t# proper-pair bit set\n", (long)s->nreads_properly_paired);
    fprintf(to, "SN\treads paired:\t%ld\t# paired-end technology bit set\n", (long)s->nreads_paired_tech);
    fprintf(to, "SN\treads duplicated:\t%ld\t# PCR or optical duplicate bit set\n", (long)s->nreads_dup);
    fprintf(to, "SN\treads MQ0:\t%ld\t# mapped and MQ=0\n", (long)s->nreads_mq0);
    fprintf(to, "SN\treads QC failed:\t%ld\n", (long)s->nreads_QCfailed);
    fprintf(to, "SN\tnon-primary alignments:\t%ld\n", (long)s->nreads_secondary);
    fprintf(to, "SN\tsupplementary alignments:\t%ld\n", (long)s->nreads_supplementary);
    fprintf(to, "SN\ttotal length:\t%ld\t# ignores clipping\n", (long)s->total_len);
    fprintf(to, "SN\ttotal first fragment length:\t%ld\t# ignores clipping\n", (long)s->total_len_1st);
    fprintf(to, "SN\ttotal last fragment length:\t%ld\t# ignores clipping\n", (long)s->total_len_2nd);
    fprintf(to, "SN\tbases mapped:\t%ld\t# ignores clipping\n", (long)s->nbases_mapped);
    fprintf(to, "SN\tbases mapped (cigar):\t%ld\t# more accurate\n", (long)s->nbases_mapped_cigar);
    fprintf(to, "SN\tbases trimmed:\t%ld\n", (long)s->nbases_trimmed);
    fprintf(to, "SN\tbases duplicated:\t%ld\n", (long)s->total_len_dup);
    fprintf(to, "SN\tmismatches:\t%ld\t# from NM fields\n", (long)s->nmismatches);
    fprintf(to, "SN\terror rate:\t%e\t# mismatches / bases mapped (cigar)\n", s->nbases_mapped_cigar ? (float)s->nmismatches / s->nbases_mapped_cigar : 0);
    float avg_read_length = nseq ? s->total_len / nseq : 0;
    fprintf(to, "SN\taverage length:\t%.0f\n", avg_read_length);
    fprintf(to, "SN\taverage first fragment length:\t%.0f\n", s->nreads_1st ? (float)s->total_len_1st / s->nreads_1st : 0);
    fprintf(to, "SN\taverage last fragment length:\t%.0f\n", s->nreads_2nd ? (float)s->total_len_2nd / s->nreads_2nd : 0);
    fprintf(to, "SN\tmaximum length:\t%d\n", s->max_len);
    fprintf(to, "SN\tmaximum first fragment length:\t%d\n", s->max_len_1st);
    fprintf(to, "SN\tmaximum last fragment length:\t%d\n", s->max_len_2nd);
    fprintf(to, "SN\taverage quality:\t%.1f\n", s->total_len ? s->sum_qual / s->total_len : 0);
    fprintf(to, "SN\tinsert size average:\t%.1f\n", avg_isize);
    fprintf(to, "SN\tinsert size standard deviation:\t%.1f\n", sd_isize);
    fprintf(to, "SN\tinward oriented pairs:\t%ld\n", (long)n_in);
    fprintf(to, "SN\toutward oriented pairs:\t%ld\n", (long)n_out);
    fprintf(to, "SN\tpairs with other orientation:\t%ld\n", (long)n_oth);
    fprintf(to, "SN\tpairs on different chromosomes:\t%ld\n", (long)s->nreads_anomalous / 2);
    fprintf(to, "SN\tpercentage of properly paired reads (%%):\t%.1f\n", nseq ? (float)(100 * s->nreads_properly_paired) / nseq : 0);
    int ibase, iqual;
    if (s->max_len < s->nbases) s->max_len++;
    if (s->max_qual + 1 < s->nquals) s->max_qual++;
    fprintf(to, "# First Fragment Qualities. Use `grep ^FFQ | cut -f 2-` to extract this part.\n");
    fprintf(to, "# Columns correspond to qualities and rows to cycles. First column is the cycle number.\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        fprintf(to, "FFQ\t%d", ibase + 1);
        for (iqual = 0; iqual <= s->max_qual; iqual++) fprintf(to, "\t%ld", (long)s->quals_1st[(size_t)ibase * s->nquals + iqual]);
        fprintf(to, "\n");
    }
    fprintf(to, "# Last Fragment Qualities. Use `grep ^LFQ | cut -f 2-` to extract this part.\n");
    fprintf(to, "# Columns correspond to qualities and rows to cycles. First column is the cycle number.\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        fprintf(to, "LFQ\t%d", ibase + 1);
        for (iqual = 0; iqual <= s->max_qual; iqual++) fprintf(to, "\t%ld", (long)s->quals_2nd[(size_t)ibase * s->nquals + iqual]);
        fprintf(to, "\n");
    }
    fprintf(to, "# GC Content of first fragments. Use `grep ^GCF | cut -f 2-` to extract this part.\n");
    int prev = 0;
    for (ibase = 0; ibase < s->ngc; ibase++) {
        if (s->gc_1st[ibase] == s->gc_1st[prev]) continue;
        fprintf(to, "GCF\t%.2f\t%ld\n", (ibase + prev) * 0.5 * 100. / (s->ngc - 1), (long)s->gc_1st[prev]);
        prev = ibase;
    }
    fprintf(to, "# GC Content of last fragments. Use `grep ^GCL | cut -f 2-` to extract this part.\n");
    prev = 0;
    for (ibase = 0; ibase < s->ngc; ibase++) {
        if (s->gc_2nd[ibase] == s->gc_2nd[prev]) continue;
        fprintf(to, "GCL\t%.2f\t%ld\n", (ibase + prev) * 0.5 * 100. / (s->ngc - 1), (long)s->gc_2nd[prev]);
        prev = ibase;
    }
    fprintf(to, "# ACGT content per cycle. Use `grep ^GCC | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]; and N and O counts as a percentage of all A/C/G/T bases [%%]\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_t *a = &s->acgt_1st[ibase], *b = &s->acgt_2nd[ibase];
        uint64_t sum = a->a + a->c + a->g + a->t + b->a + b->c + b->g + b->t;
        if (!sum) continue;
        fprintf(to, "GCC\t%d\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1,
                100. * (a->a + b->a) / sum, 100. * (a->c + b->c) / sum, 100. * (a->g + b->g) / sum, 100. * (a->t + b->t) / sum,
                100. * (a->n + b->n) / sum, 100. * (a->other + b->other) / sum);
    }
    fprintf(to, "# ACGT content per cycle, read oriented. Use `grep ^GCT | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_t *a = &s->acgt_rev[ibase];
        uint64_t sum = a->a + a->c + a->g + a->t;
        if (!sum) continue;
        fprintf(to, "GCT\t%d\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1, 100. * a->a / sum, 100. * a->c / sum, 100. * a->g / sum, 100. * a->t / sum);
    }
    for (int w = 0; w < 2; w++) {
        acgtno_t *arr = w == 0 ? s->acgt_1st : s->acgt_2nd;
        const char *nm = w == 0 ? "first" : "last";
        const char *t1 = w == 0 ? "FBC" : "LBC", *t2 = w == 0 ? "FTC" : "LTC";
        fprintf(to, "# ACGT content per cycle for %s fragments. Use `grep ^%s | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]; and N and O counts as a percentage of all A/C/G/T bases [%%]\n", nm, t1);
        uint64_t tA = 0, tC = 0, tG = 0, tT = 0, tN = 0;
        for (ibase = 0; ibase < s->max_len; ibase++) {
            acgtno_t *a = &arr[ibase];
            uint64_t sum = a->a + a->c + a->g + a->t;
            tA += a->a; tC += a->c; tG += a->g; tT += a->t; tN += a->n;
            if (!sum) continue;
            fprintf(to, "%s\t%d\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\n", t1, ibase + 1, 100. * a->a / sum, 100. * a->c / sum,
                    100. * a->g / sum, 100. * a->t / sum, 100. * a->n / sum, 100. * a->other / sum);
        }
        fprintf(to, "# ACGT raw counters for %s fragments. Use `grep ^%s | cut -f 2-` to extract this part. The columns are: A,C,G,T,N base counters\n", nm, t2);
        fprintf(to, "%s\t%lld\t%lld\t%lld\t%lld\t%lld\n", t2, (long long)tA, (long long)tC, (long long)tG, (long long)tT, (long long)tN);
    }
    fprintf(to, "# Insert sizes. Use `grep ^IS | cut -f 2-` to extract this part. The columns are: insert size, pairs total, inward oriented pairs, outward oriented pairs, other pairs\n");
    for (isize = 0; isize < ibulk; isize++) {
        long in = s->is_in[isize], out = s->is_out[isize], oth = s->is_other[isize];
        if (!sparse || in + out + oth > 0) fprintf(to, "IS\t%d\t%ld\t%ld\t%ld\t%ld\n", isize, in + out + oth, in, out, oth);
    }
    fprintf(to, "# Read lengths. Use `grep ^RL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    for (int il = 0; il < s->max_len; il++) if (s->rl[il + 1] > 0) fprintf(to, "RL\t%d\t%ld\n", il + 1, (long)s->rl[il + 1]);
    fprintf(to, "# Read lengths - first fragments. Use `grep ^FRL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    for (int il = 0; il < s->max_len_1st; il++) if (s->rl_1st[il + 1] > 0) fprintf(to, "FRL\t%d\t%ld\n", il + 1, (long)s->rl_1st[il + 1]);
    fprintf(to, "# Read lengths - last fragments. Use `grep ^LRL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    for (int il = 0; il < s->max_len_2nd; il++) if (s->rl_2nd[il + 1] > 0) fprintf(to, "LRL\t%d\t%ld\n", il + 1, (long)s->rl_2nd[il + 1]);
    fprintf(to, "# Indel distribution. Use `grep ^ID | cut -f 2-` to extract this part. The columns are: length, number of insertions, number of deletions\n");
    for (int il = 0; il < s->nindels; il++)
        if (s->ins[il] > 0 || s->del[il] > 0) fprintf(to, "ID\t%d\t%ld\t%ld\n", il + 1, (long)s->ins[il], (long)s->del[il]);
    fprintf(to, "# Indels per cycle. Use `grep ^IC | cut -f 2-` to extract this part. The columns are: cycle, number of insertions (fwd), .. (rev) , number of deletions (fwd), .. (rev)\n");
    for (int il = 0; il <= s->nbases; il++)
        if (s->ins_1st[il] > 0 || s->ins_2nd[il] > 0 || s->del_1st[il] > 0 || s->del_2nd[il] > 0)
            fprintf(to, "IC\t%d\t%ld\t%ld\t%ld\t%ld\n", il + 1, (long)s->ins_1st[il], (long)s->ins_2nd[il], (long)s->del_1st[il], (long)s->del_2nd[il]);
    fprintf(to, "# Coverage distribution. Use `grep ^COV | cut -f 2-` to extract this part.\n");
    if (s->cov[0]) fprintf(to, "COV\t[<%d]\t%d\t%ld\n", s->cov_min, s->cov_min - 1, (long)s->cov[0]);
    for (icov = 1; icov < s->ncov - 1; icov++)
        if (s->cov[icov])
            fprintf(to, "COV\t[%d-%d]\t%d\t%ld\n", s->cov_min + (icov - 1) * s->cov_step, s->cov_min + icov * s->cov_step - 1,
                    s->cov_min + icov * s->cov_step - 1, (long)s->cov[icov]);
    if (s->cov[s->ncov - 1])
        fprintf(to, "COV\t[%d<]\t%d\t%ld\n", s->cov_min + (s->ncov - 2) * s->cov_step - 1, s->cov_min + (s->ncov - 2) * s->cov_step - 1, (long)s->cov[s->ncov - 1]);
    fprintf(to, "# GC-depth. Use `grep ^GCD | cut -f 2-` to extract this part. The columns are: GC%%, unique sequence percentiles, 10th, 25th, 50th, 75th and 90th depth percentile\n");
    for (uint32_t ig = 0; ig < s->igcd; ig++)
        if (s->gcd[ig].depth) s->gcd[ig].gc = rint(100. * s->gcd[ig].gc / s->gcd[ig].depth);
    if (s->igcd + 0 < s->ngcd && s->gcd[s->igcd].depth) s->gcd[s->igcd].gc = rint(100. * s->gcd[s->igcd].gc / s->gcd[s->igcd].depth);
    if (s->ngcd) qsort(s->gcd, s->igcd + 1, sizeof(gcd_t), gcd_cmp);
    uint32_t ig = 0;
    while (ig < s->igcd) {
        uint32_t nbins = 0, it = ig;
        float gc = s->gcd[ig].gc;
        while (it < s->igcd && fabs(s->gcd[it].gc - gc) < 0.1) { nbins++; it++; }
        fprintf(to, "GCD\t%.1f\t%.3f\t%.3f\t%.3f\t%.3f\t%.3f\t%.3f\n", gc, (ig + nbins + 1) * 100. / (s->igcd + 1),
                gcd_percentile(&s->gcd[ig], nbins, 10) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[ig], nbins, 25) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[ig], nbins, 50) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[ig], nbins, 75) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[ig], nbins, 90) * avg_read_length / s->gcd_bin_size);
        ig += nbins;
    }
}

int main_stats(int argc, char *argv[]) {
    stats_t *s = stats_init();
    int c, sparse = 0;
    char *ref = NULL;
    static const struct option lopts[] = {
        {"help", no_argument, NULL, 'h'}, {"remove-dups", no_argument, NULL, 'd'},
        {"sam", no_argument, NULL, 's'}, {"ref-seq", required_argument, NULL, 'r'},
        {"coverage", required_argument, NULL, 'c'}, {"read-length", required_argument, NULL, 'l'},
        {"insert-size", required_argument, NULL, 'i'}, {"most-inserts", required_argument, NULL, 'm'},
        {"trim-quality", required_argument, NULL, 'q'}, {"target-regions", required_argument, NULL, 't'},
        {"required-flag", required_argument, NULL, 'f'}, {"filtering-flag", required_argument, NULL, 'F'},
        {"id", required_argument, NULL, 'I'}, {"GC-depth", required_argument, NULL, 1},
        {"sparse", no_argument, NULL, 'x'}, {"split", required_argument, NULL, 'S'},
        {"split-prefix", required_argument, NULL, 'P'}, {"remove-overlaps", no_argument, NULL, 'p'},
        {"cov-threshold", required_argument, NULL, 'g'}, {"customized-index-file", no_argument, NULL, 'X'},
        {"ref-stats", no_argument, NULL, 2}, {"ref-stats-chunk", required_argument, NULL, 3},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"reference", required_argument, NULL, GO_REFERENCE},
        {"threads", required_argument, NULL, '@'},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "?hdsxpr:c:l:i:t:m:q:f:F:g:I:S:P:@:X", lopts, NULL)) >= 0) {
        switch (c) {
        case 'f': case 'F': {
            int ok; int64_t v = parse_flag_str(optarg, &ok);
            if (!ok || v < 0) { fprintf(stderr, "Could not parse flag %s\n", optarg); return 1; }
            if (c == 'f') s->flag_require |= v; else s->flag_filter |= v;
            break;
        }
        case 'd': s->flag_filter |= FDUP; break;
        case 's': break;
        case 'r': ref = optarg; break;
        case 1: s->gcd_bin_size = atof(optarg); break;
        case 'c':
            if (sscanf(optarg, "%d,%d,%d", &s->cov_min, &s->cov_max, &s->cov_step) != 3) { fprintf(stderr, "Unable to parse -c %s\n", optarg); return 1; }
            break;
        case 'l': s->filter_readlen = atoi(optarg); break;
        case 'i': s->nisize = atoi(optarg); break;
        case 'm': s->isize_main_bulk = atof(optarg); break;
        case 'q': s->trim_qual = atoi(optarg); break;
        case 'x': sparse = 1; break;
        case 't': case 'I': case 'S': case 'P': case 'p': case 'g': case 'X': case '@': case 2: case 3: break;
        case GO_INPUT_FMT_OPTION: case GO_REFERENCE: case GO_VERBOSITY: break;
        case '?': case 'h': fputs(usage_stats, stdout); return 0;
        default: fputs(usage_stats, stdout); return 1;
        }
    }
    (void)ref;
    const char *fn = optind < argc ? argv[optind] : "-";
    if (optind >= argc && isatty(STDIN_FILENO)) { fputs(usage_stats, stdout); return 1; }
    samfile_t *fp = sf_open(fn, "r");
    if (!fp) { print_error_errno("stats", "failed to open \"%s\"", fn); return 1; }
    hdr_t *h = sf_read_header(fp);
    if (!h) { fprintf(stderr, "samtools stats: failed to read header for \"%s\"\n", fn); sf_close(fp); return 1; }
    stats_setup(s);
    rec_t *b = rec_init();
    int r;
    if (optind + 1 < argc) {
        idx_t *idx = fp->fmt == FMT_BAM ? idx_load_for(fn, NULL) : NULL;
        if (!idx) { fprintf(stderr, "samtools stats: Random alignment retrieval only works for indexed BAM or CRAM files.\n"); return 1; }
        for (int i = optind + 1; i < argc; i++) {
            int tid; int64_t beg, end;
            if (parse_region(h, argv[i], &tid, &beg, &end, 0) < 0) continue;
            iter_t *it = idx_query(idx, tid, beg, end);
            while ((r = iter_next(fp, it, b)) >= 0) collect_stats(s, b);
            iter_destroy(it);
        }
        idx_destroy(idx);
    } else {
        while ((r = sf_read(fp, b)) >= 0) collect_stats(s, b);
        if (r < -1) { fprintf(stderr, "samtools stats: failure while decoding file\n"); return 1; }
    }
    if (s->is_sorted) rbuf_flush(s, -1);
    output_stats(stdout, s, sparse, argc, argv);
    rec_destroy(b);
    hdr_destroy(h);
    sf_close(fp);
    return 0;
}
EOF
