actions.command:
cd /workspace && git add -A && git commit -qm "fixes" -q; cd src && cat > cmd_stats.c <<'EOF'
/* samtools stats */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <unistd.h>
#include <zlib.h>
#include "common.h"

typedef struct { uint64_t a, c, g, t, n, other; } acgtno_t;
typedef struct { float gc; uint32_t depth; } gcd_t;

typedef struct {
    int nquals, nbases, ngc, nindels;
    uint64_t *quals_1st, *quals_2nd, *gc_1st, *gc_2nd;
    acgtno_t *acgt_1st, *acgt_2nd, *acgt_rev;
    uint64_t *rl, *rl_1st, *rl_2nd, *ins, *del, *ins_1st, *ins_2nd, *del_1st, *del_2nd;
    uint64_t *is_in, *is_out, *is_other; int nisize;
    int max_len, max_len_1st, max_len_2nd, max_qual, is_sorted;
    uint64_t total_len, total_len_1st, total_len_2nd, total_len_dup, nreads_1st, nreads_2nd, nreads_other;
    uint64_t nreads_filtered, nreads_dup, nreads_unmapped, nreads_single_mapped, nreads_paired_and_mapped;
    uint64_t nreads_properly_paired, nreads_paired_tech, nreads_anomalous, nreads_mq0, nbases_mapped;
    uint64_t nbases_mapped_cigar, nbases_trimmed, nmismatches, nreads_QCfailed, nreads_secondary, nreads_supplementary;
    uint32_t ck_names, ck_reads, ck_quals;
    uint32_t ngcd, igcd; gcd_t *gcd; int32_t tid, gcd_pos;
    int ncov; uint64_t *cov;
    int32_t *rbuf; int rbuf_size, rbuf_start; int64_t rbuf_pos;
    double sum_qual;
    int last_tid; int64_t last_pos;
    int cov_min, cov_max, cov_step, gcd_bin_size;
    float isize_main_bulk;
    int flag_require, flag_filter, filter_readlen, trim_qual;
} stats_t;

static void realloc_bases(stats_t *s, int n) {
    int old = s->nbases;
    int nn = n + 10;
    s->quals_1st = xrealloc(s->quals_1st, (size_t)nn * s->nquals * sizeof(uint64_t));
    s->quals_2nd = xrealloc(s->quals_2nd, (size_t)nn * s->nquals * sizeof(uint64_t));
    memset(s->quals_1st + (size_t)old * s->nquals, 0, (size_t)(nn - old) * s->nquals * sizeof(uint64_t));
    memset(s->quals_2nd + (size_t)old * s->nquals, 0, (size_t)(nn - old) * s->nquals * sizeof(uint64_t));
#define RA(arr, type) do { arr = xrealloc(arr, (size_t)(nn + 1) * sizeof(type)); memset(arr + old + (old ? 1 : 0), 0, (size_t)(nn + 1 - old - (old ? 1 : 0)) * sizeof(type)); } while (0)
    RA(s->acgt_1st, acgtno_t); RA(s->acgt_2nd, acgtno_t); RA(s->acgt_rev, acgtno_t);
    RA(s->rl, uint64_t); RA(s->rl_1st, uint64_t); RA(s->rl_2nd, uint64_t);
    RA(s->ins, uint64_t); RA(s->del, uint64_t);
    RA(s->ins_1st, uint64_t); RA(s->ins_2nd, uint64_t); RA(s->del_1st, uint64_t); RA(s->del_2nd, uint64_t);
#undef RA
    s->nbases = nn; s->nindels = nn;
}

static stats_t *stats_init(void) {
    stats_t *s = xcalloc(1, sizeof(stats_t));
    s->nquals = 256; s->ngc = 200;
    s->gc_1st = xcalloc(s->ngc, sizeof(uint64_t)); s->gc_2nd = xcalloc(s->ngc, sizeof(uint64_t));
    s->nbases = 0;
    realloc_bases(s, 290);
    s->nisize = 8000;
    s->is_sorted = 1;
    s->cov_min = 1; s->cov_max = 1000; s->cov_step = 1;
    s->gcd_bin_size = 20000;
    s->isize_main_bulk = 0.99;
    s->filter_readlen = -1;
    s->tid = -1; s->last_tid = -1;
    return s;
}

static void stats_setup(stats_t *s) {
    s->is_in = xcalloc(s->nisize, sizeof(uint64_t)); s->is_out = xcalloc(s->nisize, sizeof(uint64_t)); s->is_other = xcalloc(s->nisize, sizeof(uint64_t));
    s->ncov = 3 + (s->cov_max - s->cov_min) / s->cov_step;
    s->cov = xcalloc(s->ncov, sizeof(uint64_t));
    s->rbuf_size = 1000;
    s->rbuf = xcalloc(s->rbuf_size, sizeof(int32_t));
    s->rbuf_pos = -1;
    s->ngcd = 1000; s->gcd = xcalloc(s->ngcd, sizeof(gcd_t));
}

static int cov_idx(stats_t *s, int depth) {
    if (depth < s->cov_min) return 0;
    if (depth > s->cov_max) return s->ncov - 1;
    return 1 + (depth - s->cov_min) / s->cov_step;
}

static int lidx2ridx(int start, int size, int64_t ref, int64_t idx) {
    if (idx < ref) return -1;
    if (idx >= ref + size) return -1;
    int r = start + (int)(idx - ref);
    if (r >= size) r -= size;
    return r;
}

static void rbuf_flush(stats_t *s, int64_t pos) {
    if (s->rbuf_pos < 0) { s->rbuf_pos = pos < 0 ? 0 : pos; s->rbuf_start = 0; return; }
    if (pos == s->rbuf_pos) return;
    int64_t new_pos = pos;
    if (pos == -1 || pos - s->rbuf_pos >= s->rbuf_size) pos = s->rbuf_pos + s->rbuf_size - 1;
    if (pos < s->rbuf_pos) return;
    int ifrom = s->rbuf_start;
    int ito = lidx2ridx(s->rbuf_start, s->rbuf_size, s->rbuf_pos, pos - 1);
    if (ito < 0) ito = ifrom - 1 < 0 ? s->rbuf_size - 1 : ifrom - 1;
    if (pos - 1 < s->rbuf_pos) ito = -2;
    if (ito != -2) {
        if (ifrom > ito) {
            for (int i = ifrom; i < s->rbuf_size; i++) {
                if (!s->rbuf[i]) continue;
                s->cov[cov_idx(s, s->rbuf[i])]++; s->rbuf[i] = 0;
            }
            ifrom = 0;
        }
        for (int i = ifrom; i <= ito; i++) {
            if (!s->rbuf[i]) continue;
            s->cov[cov_idx(s, s->rbuf[i])]++; s->rbuf[i] = 0;
        }
    }
    s->rbuf_start = (new_pos == -1) ? 0 : lidx2ridx(s->rbuf_start, s->rbuf_size, s->rbuf_pos, pos);
    if (s->rbuf_start < 0) s->rbuf_start = 0;
    s->rbuf_pos = new_pos;
}

static void rbuf_insert(stats_t *s, int64_t from, int64_t to) {
    if (to - from >= s->rbuf_size) {
        /* grow buffer: flush everything then resize */
        int newsz = (int)(to - from + 1) * 2;
        int32_t *nb = xcalloc(newsz, sizeof(int32_t));
        for (int i = 0; i < s->rbuf_size; i++) {
            int r = s->rbuf_start + i; if (r >= s->rbuf_size) r -= s->rbuf_size;
            nb[i] = s->rbuf[r];
        }
        free(s->rbuf); s->rbuf = nb; s->rbuf_start = 0; s->rbuf_size = newsz;
    }
    if (from < s->rbuf_pos) return;
    int ifrom = lidx2ridx(s->rbuf_start, s->rbuf_size, s->rbuf_pos, from);
    int ito = lidx2ridx(s->rbuf_start, s->rbuf_size, s->rbuf_pos, to);
    if (ifrom < 0 || ito < 0) return;
    if (ifrom > ito) {
        for (int i = ifrom; i < s->rbuf_size; i++) s->rbuf[i]++;
        ifrom = 0;
    }
    for (int i = ifrom; i <= ito; i++) s->rbuf[i]++;
}

static int unclipped_length(const rec_t *b) {
    int l = b->core.l_qseq;
    for (uint32_t i = 0; i < b->core.n_cigar; i++) if (cig_op(rec_cigar(b)[i]) == C_HARD_CLIP) l += cig_len(rec_cigar(b)[i]);
    return l;
}

#define RO_FIRST 1
#define RO_LAST 2
#define RO_MIDDLE 3

static int get_order(const rec_t *b) {
    if (!(b->core.flag & FPAIRED)) return RO_FIRST;
    if (b->core.flag & FREAD1) return (b->core.flag & FREAD2) ? RO_MIDDLE : RO_FIRST;
    if (b->core.flag & FREAD2) return RO_LAST;
    return RO_MIDDLE;
}

static void count_indels(stats_t *s, const rec_t *b) {
    int is_fwd = (b->core.flag & FREVERSE) ? 0 : 1;
    int order = get_order(b);
    int icycle = 0, read_len = b->core.l_qseq;
    for (uint32_t i = 0; i < b->core.n_cigar; i++) {
        int cig = cig_op(rec_cigar(b)[i]), ncig = cig_len(rec_cigar(b)[i]);
        if (!ncig) continue;
        if (cig == C_INS) {
            int idx = is_fwd ? icycle : read_len - icycle - ncig;
            if (idx >= 0 && idx < s->nbases) {
                if (order == RO_FIRST) s->ins_1st[idx]++;
                if (order == RO_LAST) s->ins_2nd[idx]++;
            }
            icycle += ncig;
            if (ncig <= s->nindels) s->ins[ncig - 1]++;
            continue;
        }
        if (cig == C_DEL) {
            int idx = is_fwd ? icycle - 1 : read_len - icycle - 1;
            if (idx < 0) continue;
            if (idx < s->nbases) {
                if (order == RO_FIRST) s->del_1st[idx]++;
                if (order == RO_LAST) s->del_2nd[idx]++;
            }
            if (ncig <= s->nindels) s->del[ncig - 1]++;
            continue;
        }
        if (cig != C_REF_SKIP && cig != C_HARD_CLIP && cig != C_PAD) icycle += ncig;
    }
}

static void collect_orig(stats_t *s, const rec_t *b, int *gc_out) {
    int seq_len = b->core.l_qseq;
    s->total_len += seq_len;
    const uint8_t *seq = rec_seq(b);
    int reverse = (b->core.flag & FREVERSE) != 0, gc_count = 0;
    int order = get_order(b);
    acgtno_t *ac = order == RO_LAST ? s->acgt_2nd : s->acgt_1st;
    for (int i = 0; i < seq_len; i++) {
        int rc = reverse ? seq_len - i - 1 : i;
        switch (seqi(seq, i)) {
        case 1: ac[rc].a++; if (reverse) s->acgt_rev[rc].t++; else s->acgt_rev[rc].a++; break;
        case 2: ac[rc].c++; if (reverse) s->acgt_rev[rc].g++; else s->acgt_rev[rc].c++; gc_count++; break;
        case 4: ac[rc].g++; if (reverse) s->acgt_rev[rc].c++; else s->acgt_rev[rc].g++; gc_count++; break;
        case 8: ac[rc].t++; if (reverse) s->acgt_rev[rc].a++; else s->acgt_rev[rc].t++; break;
        case 15: ac[rc].n++; break;
        default: ac[rc].other++; break;
        }
    }
    int gmin = gc_count * (s->ngc - 1) / seq_len;
    int gmax = (gc_count + 1) * (s->ngc - 1) / seq_len;
    if (gmax >= s->ngc) gmax = s->ngc - 1;
    uint64_t *quals = NULL;
    const uint8_t *bq = rec_qual(b);
    if (order == RO_FIRST) {
        quals = s->quals_1st; s->nreads_1st++; s->total_len_1st += seq_len;
        for (int i = gmin; i < gmax; i++) s->gc_1st[i]++;
    } else if (order == RO_LAST) {
        quals = s->quals_2nd; s->nreads_2nd++; s->total_len_2nd += seq_len;
        for (int i = gmin; i < gmax; i++) s->gc_2nd[i]++;
    } else s->nreads_other++;
    for (int i = 0; i < seq_len; i++) {
        uint8_t q = bq[reverse ? seq_len - i - 1 : i];
        if (q > s->max_qual) s->max_qual = q;
        if (quals) quals[(size_t)i * s->nquals + q]++;
        s->sum_qual += q;
    }
    *gc_out = gc_count;
}

static void collect_stats(stats_t *s, rec_t *b) {
    if (s->flag_require && (b->core.flag & s->flag_require) != s->flag_require) { s->nreads_filtered++; return; }
    if (s->flag_filter && (b->core.flag & s->flag_filter)) { s->nreads_filtered++; return; }
    if (s->filter_readlen != -1 && b->core.l_qseq != s->filter_readlen) return;
    /* checksum */
    {
        const char *nm = rec_qname(b);
        s->ck_names += crc32(0L, (const Bytef*)nm, strlen(nm));
        int sl = b->core.l_qseq;
        if (sl) {
            s->ck_reads += crc32(0L, rec_seq(b), (sl + 1) / 2);
            s->ck_quals += crc32(0L, rec_qual(b), (sl + 1) / 2);
        }
    }
    if (b->core.flag & FSECONDARY) { s->nreads_secondary++; return; }
    int seq_len = b->core.l_qseq;
    if (!seq_len) return;
    if (b->core.flag & FDUP) { s->total_len_dup += seq_len; s->nreads_dup++; }
    int read_len = unclipped_length(b);
    if (read_len >= s->nbases) realloc_bases(s, read_len);
    if (s->max_len < read_len) s->max_len = read_len;
    int order = get_order(b);
    if (order == RO_FIRST && s->max_len_1st < read_len) s->max_len_1st = read_len;
    if (order == RO_LAST && s->max_len_2nd < read_len) s->max_len_2nd = read_len;
    int gc_count = 0;
    int is_orig = !(b->core.flag & (FSECONDARY | FSUPPLEMENTARY));
    if (b->core.flag & FSUPPLEMENTARY) s->nreads_supplementary++;
    if (b->core.flag & FQCFAIL) s->nreads_QCfailed++;
    if (b->core.flag & FPAIRED) s->nreads_paired_tech++;
    if (is_orig) {
        if (order == RO_FIRST) s->rl_1st[read_len]++;
        else if (order == RO_LAST) s->rl_2nd[read_len]++;
        s->rl[read_len]++;
        collect_orig(s, b, &gc_count);
    }
    if (b->core.flag & FUNMAP) { s->nreads_unmapped++; return; }
    s->nbases_mapped += seq_len;
    if (!b->core.qual) s->nreads_mq0++;
    int paired_mapped = (b->core.flag & FPAIRED) && !(b->core.flag & FMUNMAP);
    if (!paired_mapped) s->nreads_single_mapped++;
    else {
        s->nreads_paired_and_mapped++;
        if (b->core.flag & FPROPER_PAIR) s->nreads_properly_paired++;
        if (b->core.tid != b->core.mtid) s->nreads_anomalous++;
    }
    count_indels(s, b);
    for (uint32_t i = 0; i < b->core.n_cigar; i++) {
        int op = cig_op(rec_cigar(b)[i]);
        if (op == C_MATCH || op == C_INS || op == C_EQUAL || op == C_DIFF) s->nbases_mapped_cigar += cig_len(rec_cigar(b)[i]);
    }
    uint8_t *nm = aux_get(b, "NM");
    if (nm) s->nmismatches += aux2i(nm);
    if (paired_mapped && is_orig) {
        int64_t isize = b->core.isize; if (isize < 0) isize = -isize;
        if (s->nisize > 0 && isize >= s->nisize) isize = s->nisize - 1;
        if (isize > 0 || b->core.tid == b->core.mtid) {
            int64_t pos_fst = b->core.mpos - b->core.pos;
            int is_fst = (b->core.flag & FREAD1) ? 1 : -1;
            int is_fwd = (b->core.flag & FREVERSE) ? -1 : 1;
            int is_mfwd = (b->core.flag & FMREVERSE) ? -1 : 1;
            if (is_fwd * is_mfwd > 0) s->is_other[isize]++;
            else if (is_fst * pos_fst > 0) { if (is_fst * is_fwd > 0) s->is_in[isize]++; else s->is_out[isize]++; }
            else if (is_fst * pos_fst < 0) { if (is_fst * is_fwd > 0) s->is_out[isize]++; else s->is_in[isize]++; }
        }
    }
    /* sortedness */
    if (s->is_sorted) {
        if (b->core.tid < s->last_tid || (b->core.tid == s->last_tid && b->core.pos < s->last_pos)) s->is_sorted = 0;
    }
    if (b->core.tid != s->last_tid) {
        if (s->is_sorted) rbuf_flush(s, -1);
        s->rbuf_pos = -1;
    }
    s->last_tid = b->core.tid; s->last_pos = b->core.pos;
    if (is_orig) {
        if (s->tid != b->core.tid || b->core.pos - s->gcd_pos > s->gcd_bin_size) {
            if (s->igcd + 2 >= s->ngcd) { s->ngcd *= 2; s->gcd = xrealloc(s->gcd, s->ngcd * sizeof(gcd_t)); }
            s->igcd++;
            s->gcd[s->igcd].gc = 0; s->gcd[s->igcd].depth = 0;
            s->tid = b->core.tid; s->gcd_pos = b->core.pos;
        }
        s->gcd[s->igcd].depth++;
        s->gcd[s->igcd].gc += (float)gc_count / seq_len;
    }
    if (s->is_sorted) {
        rbuf_flush(s, b->core.pos);
        int64_t p = b->core.pos;
        for (uint32_t i = 0; i < b->core.n_cigar; i++) {
            int op = cig_op(rec_cigar(b)[i]); int64_t l = cig_len(rec_cigar(b)[i]);
            if (op == C_MATCH || op == C_EQUAL || op == C_DIFF) { rbuf_insert(s, p, p + l - 1); p += l; }
            else if (op == C_DEL || op == C_REF_SKIP) p += l;
        }
    }
}

static int gcd_cmp(const void *a, const void *b) {
    const gcd_t *x = a, *y = b;
    if (x->gc < y->gc) return -1;
    if (x->gc > y->gc) return 1;
    if (x->depth < y->depth) return -1;
    if (x->depth > y->depth) return 1;
    return 0;
}
static float gcd_percentile(gcd_t *g, int N, int p) {
    float n, d; int k;
    n = p * (N + 1) / 100;
    k = n;
    if (k <= 0) return g[0].depth;
    if (k >= N) return g[N-1].depth;
    d = n - k;
    return g[k-1].depth + d * (g[k].depth - g[k-1].depth);
}

static void output_stats(FILE *to, stats_t *s, int sparse, int argc, char **argv) {
    int isize, ibulk = 0, icov;
    uint64_t nisize = 0, n_in = 0, n_out = 0, n_oth = 0;
    double bulk = 0, avg_isize = 0, sd_isize = 0;
    for (isize = 0; isize < s->nisize; isize++) {
        s->is_in[isize] = (uint64_t)(s->is_in[isize] * 0.5);
        s->is_out[isize] = (uint64_t)(s->is_out[isize] * 0.5);
        s->is_other[isize] = (uint64_t)(s->is_other[isize] * 0.5);
        n_in += s->is_in[isize]; n_out += s->is_out[isize]; n_oth += s->is_other[isize];
        nisize += s->is_in[isize] + s->is_out[isize] + s->is_other[isize];
    }
    for (isize = 0; isize < s->nisize; isize++) {
        uint64_t num = s->is_in[isize] + s->is_out[isize] + s->is_other[isize];
        if (num > 0) ibulk = isize + 1;
        bulk += num;
        avg_isize += isize * (double)num;
        if (bulk / nisize > s->isize_main_bulk) { ibulk = isize + 1; nisize = bulk; break; }
    }
    avg_isize /= nisize ? nisize : 1;
    for (isize = 1; isize < ibulk; isize++)
        sd_isize += (s->is_in[isize] + s->is_out[isize] + s->is_other[isize]) * (isize - avg_isize) * (isize - avg_isize) / (nisize ? nisize : 1);
    sd_isize = sqrt(sd_isize);
