    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_t *a = &s->acgt_1st[ibase], *b = &s->acgt_2nd[ibase];
        uint64_t sum = a->a + a->c + a->g + a->t + b->a + b->c + b->g + b->t;
        if (!sum) continue;
        fprintf(to, "GCC\t%d\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1,
