    }
    fprintf(to, "# ACGT content per cycle, read oriented. Use `grep ^GCT | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]\n");
    for (ibase = 0; ibase < s->max_len; ibase++) {
        acgtno_t *a = &s->acgt_rev[ibase];
        uint64_t sum = a->a + a->c + a->g + a->t;
        if (!sum) continue;
        fprintf(to, "GCT\t%d\t%.2f\t%.2f\t%.2f\t%.2f\n", ibase + 1, 100. * a->a / sum, 100. * a->c / sum, 100. * a->g / sum, 100. * a->t / sum);
    }
    for (int w = 0; w < 2; w++) {
        acgtno_t *arr = w == 0 ? s->acgt_1st : s->acgt_2nd;
        const char *nm = w == 0 ? "first" : "last";
        const char *t1 = w == 0 ? "FBC" : "LBC", *t2 = w == 0 ? "FTC" : "LTC";
        fprintf(to, "# ACGT content per cycle for %s fragments. Use `grep ^%s | cut -f 2-` to extract this part. The columns are: cycle; A,C,G,T base counts as a percentage of all A/C/G/T bases [%%]; and N and O counts as a percentage of all A/C/G/T bases [%%]\n", nm, t1);
        uint64_t tA = 0, tC = 0, tG = 0, tT = 0, tN = 0;
        for (ibase = 0; ibase < s->max_len; ibase++) {
            acgtno_t *a = &arr[ibase];
            uint64_t sum = a->a + a->c + a->g + a->t;
            tA += a->a; tC += a->c; tG += a->g; tT += a->t; tN += a->n;
            if (!sum) continue;
            fprintf(to, "%s\t%d\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\t%.2f\n", t1, ibase + 1, 100. * a->a / sum, 100. * a->c / sum,
                    100. * a->g / sum, 100. * a->t / sum, 100. * a->n / sum, 100. * a->other / sum);
        }
        fprintf(to, "# ACGT raw counters for %s fragments. Use `grep ^%s | cut -f 2-` to extract this part. The columns are: A,C,G,T,N base counters\n", nm, t2);
        fprintf(to, "%s\t%lld\t%lld\t%lld\t%lld\t%lld\n", t2, (long long)tA, (long long)tC, (long long)tG, (long long)tT, (long long)tN);
    }
    fprintf(to, "# Insert sizes. Use `grep ^IS | cut -f 2-` to extract this part. The columns are: insert size, pairs total, inward oriented pairs, outward oriented pairs, other pairs\n");
