    }
    fprintf(to, "# Read lengths. Use `grep ^RL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    for (int il = 0; il < s->max_len; il++) if (s->rl[il + 1] > 0) fprintf(to, "RL\t%d\t%ld\n", il + 1, (long)s->rl[il + 1]);
    fprintf(to, "# Read lengths - first fragments. Use `grep ^FRL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    for (int il = 0; il < s->max_len_1st; il++) if (s->rl_1st[il + 1] > 0) fprintf(to, "FRL\t%d\t%ld\n", il + 1, (long)s->rl_1st[il + 1]);
    fprintf(to, "# Read lengths - last fragments. Use `grep ^LRL | cut -f 2-` to extract this part. The columns are: read length, count\n");
    for (int il = 0; il < s->max_len_2nd; il++) if (s->rl_2nd[il + 1] > 0) fprintf(to, "LRL\t%d\t%ld\n", il + 1, (long)s->rl_2nd[il + 1]);
    fprintf(to, "# Indel distribution. Use `grep ^ID | cut -f 2-` to extract this part. The columns are: length, number of insertions, number of deletions\n");
    for (int il = 0; il < s->nindels; il++)
        if (s->ins[il] > 0 || s->del[il] > 0) fprintf(to, "ID\t%d\t%ld\t%ld\n", il + 1, (long)s->ins[il], (long)s->del[il]);
    fprintf(to, "# Indels per cycle. Use `grep ^IC | cut -f 2-` to extract this part. The columns are: cycle, number of insertions (fwd), .. (rev) , number of deletions (fwd), .. (rev)\n");
    for (int il = 0; il <= s->nbases; il++)
        if (s->ins_1st[il] > 0 || s->ins_2nd[il] > 0 || s->del_1st[il] > 0 || s->del_2nd[il] > 0)
            fprintf(to, "IC\t%d\t%ld\t%ld\t%ld\t%ld\n", il + 1, (long)s->ins_1st[il], (long)s->ins_2nd[il], (long)s->del_1st[il], (long)s->del_2nd[il]);
    fprintf(to, "# Coverage distribution. Use `grep ^COV | cut -f 2-` to extract this part.\n");
    if (s->cov[0]) fprintf(to, "COV\t[<%d]\t%d\t%ld\n", s->cov_min, s->cov_min - 1, (long)s->cov[0]);
    for (icov = 1; icov < s->ncov - 1; icov++)
        if (s->cov[icov])
            fprintf(to, "COV\t[%d-%d]\t%d\t%ld\n", s->cov_min + (icov - 1) * s->cov_step, s->cov_min + icov * s->cov_step - 1,
                    s->cov_min + icov * s->cov_step - 1, (long)s->cov[icov]);
    if (s->cov[s->ncov - 1])
        fprintf(to, "COV\t[%d<]\t%d\t%ld\n", s->cov_min + (s->ncov - 2) * s->cov_step - 1, s->cov_min + (s->ncov - 2) * s->cov_step - 1, (long)s->cov[s->ncov - 1]);
    fprintf(to, "# GC-depth. Use `grep ^GCD | cut -f 2-` to extract this part. The columns are: GC%%, unique sequence percentiles, 10th, 25th, 50th, 75th and 90th depth percentile\n");
    for (uint32_t ig = 0; ig < s->igcd; ig++)
        if (s->gcd[ig].depth) s->gcd[ig].gc = rint(100. * s->gcd[ig].gc / s->gcd[ig].depth);
    if (s->igcd + 0 < s->ngcd && s->gcd[s->igcd].depth) s->gcd[s->igcd].gc = rint(100. * s->gcd[s->igcd].gc / s->gcd[s->igcd].depth);
    if (s->ngcd) qsort(s->gcd, s->igcd + 1, sizeof(gcd_t), gcd_cmp);
    uint32_t ig = 0;
    while (ig < s->igcd) {
        uint32_t nbins = 0, it = ig;
        float gc = s->gcd[ig].gc;
        while (it < s->igcd && fabs(s->gcd[it].gc - gc) < 0.1) { nbins++; it++; }
        fprintf(to, "GCD\t%.1f\t%.3f\t%.3f\t%.3f\t%.3f\t%.3f\t%.3f\n", gc, (ig + nbins + 1) * 100. / (s->igcd + 1),
                gcd_percentile(&s->gcd[ig], nbins, 10) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[ig], nbins, 25) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[ig], nbins, 50) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[ig], nbins, 75) * avg_read_length / s->gcd_bin_size,
                gcd_percentile(&s->gcd[ig], nbins, 90) * avg_read_length / s->gcd_bin_size);
        ig += nbins;
    }
}

int main_stats(int argc, char *argv[]) {
    stats_t *s = stats_init();
    int c, sparse = 0;
    char *ref = NULL;
    static const struct option lopts[] = {
        {"help", no_argument, NULL, 'h'}, {"remove-dups", no_argument, NULL, 'd'},
        {"sam", no_argument, NULL, 's'}, {"ref-seq", required_argument, NULL, 'r'},
        {"coverage", required_argument, NULL, 'c'}, {"read-length", required_argument, NULL, 'l'},
        {"insert-size", required_argument, NULL, 'i'}, {"most-inserts", required_argument, NULL, 'm'},
        {"trim-quality", required_argument, NULL, 'q'}, {"target-regions", required_argument, NULL, 't'},
        {"required-flag", required_argument, NULL, 'f'}, {"filtering-flag", required_argument, NULL, 'F'},
        {"id", required_argument, NULL, 'I'}, {"GC-depth", required_argument, NULL, 1},
        {"sparse", no_argument, NULL, 'x'}, {"split", required_argument, NULL, 'S'},
        {"split-prefix", required_argument, NULL, 'P'}, {"remove-overlaps", no_argument, NULL, 'p'},
        {"cov-threshold", required_argument, NULL, 'g'}, {"customized-index-file", no_argument, NULL, 'X'},
        {"ref-stats", no_argument, NULL, 2}, {"ref-stats-chunk", required_argument, NULL, 3},
        {"input-fmt-option", required_argument, NULL, GO_INPUT_FMT_OPTION},
        {"reference", required_argument, NULL, GO_REFERENCE},
        {"threads", required_argument, NULL, '@'},
        {"verbosity", required_argument, NULL, GO_VERBOSITY},
        {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "?hdsxpr:c:l:i:t:m:q:f:F:g:I:S:P:@:X", lopts, NULL)) >= 0) {
        switch (c) {
        case 'f': case 'F': {
            int ok; int64_t v = parse_flag_str(optarg, &ok);
            if (!ok || v < 0) { fprintf(stderr, "Could not parse flag %s\n", optarg); return 1; }
            if (c == 'f') s->flag_require |= v; else s->flag_filter |= v;
            break;
        }
        case 'd': s->flag_filter |= FDUP; break;
        case 's': break;
        case 'r': ref = optarg; break;
        case 1: s->gcd_bin_size = atof(optarg); break;
        case 'c':
            if (sscanf(optarg, "%d,%d,%d", &s->cov_min, &s->cov_max, &s->cov_step) != 3) { fprintf(stderr, "Unable to parse -c %s\n", optarg); return 1; }
            break;
        case 'l': s->filter_readlen = atoi(optarg); break;
        case 'i': s->nisize = atoi(optarg); break;
        case 'm': s->isize_main_bulk = atof(optarg); break;
        case 'q': s->trim_qual = atoi(optarg); break;
        case 'x': sparse = 1; break;
        case 't': case 'I': case 'S': case 'P': case 'p': case 'g': case 'X': case '@': case 2: case 3: break;
        case GO_INPUT_FMT_OPTION: case GO_REFERENCE: case GO_VERBOSITY: break;
        case '?': case 'h': fputs(usage_stats, stdout); return 0;
        default: fputs(usage_stats, stdout); return 1;
        }
    }
    (void)ref;
    const char *fn = optind < argc ? argv[optind] : "-";
    if (optind >= argc && isatty(STDIN_FILENO)) { fputs(usage_stats, stdout); return 1; }
    samfile_t *fp = sf_open(fn, "r");
    if (!fp) { print_error_errno("stats", "failed to open \"%s\"", fn); return 1; }
    hdr_t *h = sf_read_header(fp);
    if (!h) { fprintf(stderr, "samtools stats: failed to read header for \"%s\"\n", fn); sf_close(fp); return 1; }
    stats_setup(s);
    rec_t *b = rec_init();
    int r;
    if (optind + 1 < argc) {
        idx_t *idx = fp->fmt == FMT_BAM ? idx_load_for(fn, NULL) : NULL;
        if (!idx) { fprintf(stderr, "samtools stats: Random alignment retrieval only works for indexed BAM or CRAM files.\n"); return 1; }
        for (int i = optind + 1; i < argc; i++) {
            int tid; int64_t beg, end;
            if (parse_region(h, argv[i], &tid, &beg, &end, 0) < 0) continue;
            iter_t *it = idx_query(idx, tid, beg, end);
            while ((r = iter_next(fp, it, b)) >= 0) collect_stats(s, b);
            iter_destroy(it);
        }
        idx_destroy(idx);
    } else {
        while ((r = sf_read(fp, b)) >= 0) collect_stats(s, b);
        if (r < -1) { fprintf(stderr, "samtools stats: failure while decoding file\n"); return 1; }
    }
    if (s->is_sorted) rbuf_flush(s, -1);
    output_stats(stdout, s, sparse, argc, argv);
    rec_destroy(b);
    hdr_destroy(h);
    sf_close(fp);
    return 0;
}
