int main_reference(int argc, char *argv[]) {
    int c, quiet = 0;
    char *outfn = NULL, *reg = NULL;
    while ((c = getopt(argc, argv, "@:r:eqo:")) >= 0) {
        switch (c) {
        case 'o': outfn = optarg; break;
        case 'r': reg = optarg; break;
        case 'q': quiet = 1; break;
        case 'e': case '@': break;
        default: fputs(usage_reference, stdout); return 0;
        }
    }
    (void)quiet;
    const char *fn = optind < argc ? argv[optind] : "-";
    samfile_t *fp = sf_open(fn, "r");
    if (!fp) return 1;
    hdr_t *h = sf_read_header(fp);
    if (!h) { sf_close(fp); return 1; }
    FILE *out = outfn ? fopen(outfn, "w") : stdout;
    if (!out) { hdr_destroy(h); sf_close(fp); return 1; }
    int rtid = -1; int64_t rbeg = 0, rend = INT64_MAX;
    if (reg && parse_region(h, reg, &rtid, &rbeg, &rend, 0) < 0) { hdr_destroy(h); sf_close(fp); return 1; }
    rec_t *b = rec_init();
    char *seq = NULL; int cur = -1; int64_t len = 0;
    int r;
    #define FLUSH_REF() do { if (cur >= 0 && (rtid < 0 || cur == rtid)) { \
        int64_t s0 = rtid >= 0 ? rbeg : 0, e0 = rtid >= 0 && rend < len ? rend : len; \
        fprintf(out, ">%s\n", h->tname[cur]); \
        for (int64_t i = s0; i < e0; i += 60) { int64_t n = e0 - i < 60 ? e0 - i : 60; fwrite(seq + i, 1, n, out); fputc('\n', out); } } } while (0)
    while ((r = sf_read(fp, b)) >= 0) {
        if (b->core.tid < 0 || (b->core.flag & FUNMAP)) continue;
        if (b->core.tid != cur) {
            FLUSH_REF();
            cur = b->core.tid; len = h->tlen[cur];
            seq = xrealloc(seq, len + 1);
            memset(seq, 'N', len);
        }
        uint8_t *md = aux_get(b, "MD");
        if (!md || md[0] != 'Z') continue;
        const char *m = (char*)md + 1;
        uint32_t *cg = rec_cigar(b); uint8_t *sq = rec_seq(b);
        int64_t rp = b->core.pos, qp = 0;
        int mrun = 0;
        while (isdigit((unsigned char)*m)) mrun = mrun * 10 + (*m++ - '0');
        for (uint32_t k = 0; k < b->core.n_cigar; k++) {
            int op = cig_op(cg[k]); int l = cig_len(cg[k]);
            if (op == C_MATCH || op == C_EQUAL || op == C_DIFF) {
                for (int j = 0; j < l; j++) {
                    char base;
                    if (mrun > 0) { base = seq_nt16_str[seqi(sq, qp + j)]; mrun--; }
                    else if (*m && isalpha((unsigned char)*m)) { base = toupper((unsigned char)*m++); mrun = 0; while (isdigit((unsigned char)*m)) mrun = mrun * 10 + (*m++ - '0'); }
                    else base = seq_nt16_str[seqi(sq, qp + j)];
                    if (rp + j < len) seq[rp + j] = base;
                }
                rp += l; qp += l;
            } else if (op == C_DEL) {
                if (*m == '^') m++;
                for (int j = 0; j < l; j++) {
                    char base = 'N';
                    if (*m && isalpha((unsigned char)*m)) base = toupper((unsigned char)*m++);
                    if (rp + j < len) seq[rp + j] = base;
                }
                mrun = 0; while (isdigit((unsigned char)*m)) mrun = mrun * 10 + (*m++ - '0');
                rp += l;
            } else if (op == C_REF_SKIP) rp += l;
            else if (op == C_INS || op == C_SOFT_CLIP) qp += l;
        }
    }
    FLUSH_REF();
    free(seq);
    rec_destroy(b);
    hdr_destroy(h);
    sf_close(fp);
    if (out != stdout) fclose(out);
    return 0;
}
