typedef struct { samfile_t *fp; hdr_t *h; iter_t *iter; int incl, excl, min_mq; } caux2_t;

static int cons_read(void *data, rec_t *b) {
    caux2_t *a = data;
    int r;
    for (;;) {
        r = a->iter ? iter_next(a->fp, a->iter, b) : sf_read(a->fp, b);
