            break;
        case 'l': line_len = atoi(optarg); break;
        case 'o': outfn = optarg; break;
        case 'm': break;
        case 'a': all++; break;
        case 'd': min_depth = atoi(optarg); break;
        case 'q': use_qual = 1; break;
        case 8: use_qual = 0; break;
        case 'c': call_fract = atof(optarg); break;
        case 'H': het_fract = atof(optarg); break;
        case 'A': ambig = 1; break;
        case 1: case 2: { int ok; int64_t v = parse_flag_str(optarg, &ok); if (!ok || v < 0) { fprintf(stderr, "Unable to parse flags \"%s\"\n", optarg); return 1; } if (c == 1) incl = v; else excl = v; break; }
        case 3: min_mq = atoi(optarg); break;
        case 4: min_bq = atoi(optarg); break;
        case 5: show_del = (optarg[0] == 'y' || optarg[0] == 'Y'); break;
        case 6: show_ins = (optarg[0] == 'y' || optarg[0] == 'Y'); break;
        case 7: mark_ins = 1; break;
        default:
