    const char *fn = argv[optind];
    caux2_t a; memset(&a, 0, sizeof a);
    a.fp = sf_open(fn, "r");
    if (!a.fp) { print_error_errno("consensus", "Cannot open input file \"%s\"", fn); return 1; }
    a.h = sf_read_header(a.fp);
    if (!a.h) { print_error("consensus", "Cannot read header"); sf_close(a.fp); return 1; }
    a.incl = incl; a.excl = excl; a.min_mq = min_mq;
    int rtid = -1; int64_t rbeg = 0, rend = INT64_MAX;
    if (reg) {
