        kstr o = {0, 0, NULL}; size_t col = 0; \
        ks_putc(&o, fmt == 1 ? '@' : '>'); ks_puts(&o, a.h->tname[last_tid]); ks_putc(&o, '\n'); \
        out_wrap(&o, seq.s ? seq.s : "", seq.l, line_len, &col); if (col || seq.l == 0) ks_putc(&o, '\n'); \
        if (fmt == 1) { ks_puts(&o, "+\n"); col = 0; out_wrap(&o, qual.s ? qual.s : "", qual.l, line_len, &col); if (col || qual.l == 0) ks_putc(&o, '\n'); } \
        fwrite(o.s, 1, o.l, out); ks_free(&o); } seq.l = 0; qual.l = 0; } while (0)
    while ((pl = plp_auto(it, &tid, &pos, &n)) != NULL) {
        if (reg && (pos < rbeg || pos >= rend)) continue;
        if (tid != last_tid) {
            if (last_tid >= 0 && all) { int64_t e = reg && rend < a.h->tlen[last_tid] ? rend : a.h->tlen[last_tid]; while (++last_pos < e) { ks_putc(&seq, 'N'); ks_putc(&qual, '!'); } }
            EMIT_REF();
            last_tid = tid; last_pos = reg ? rbeg - 1 : -1;
            if (!all) last_pos = pos - 1;
        }
        while (++last_pos < pos) { if (all || 1) { ks_putc(&seq, 'N'); ks_putc(&qual, '!'); } }
        double cnt[6] = {0}; double total = 0;
        int depth = 0, nins = 0;
        for (int i = 0; i < n; i++) {
            const pileup1_t *p = pl + i;
            if (p->is_refskip) continue;
            int b; int q;
            if (p->is_del) { b = 5; q = 0; }
            else {
                q = rec_qual(p->b)[p->qpos];
                if (q < min_bq) continue;
                b = seq_nt16_int[seqi(rec_seq(p->b), p->qpos)];
            }
            double w = use_qual ? (p->is_del ? 1 : q) : 1;
            cnt[b] += w; total += w; depth++;
            if (p->indel > 0) nins++;
        }
        char call = 'N'; int cq = 0;
        if (depth >= min_depth && total > 0) {
            int best = 0;
            for (int k = 1; k < 6; k++) if (cnt[k] > cnt[best]) best = k;
            if (cnt[best] / total >= call_fract) { call = "ACGTN*"[best]; cq = (int)(100.0 * cnt[best] / total); if (cq > 93) cq = 93; }
        }
        if (call == '*') { if (show_del) { ks_putc(&seq, '*'); ks_putc(&qual, 33 + cq); } }
        else { ks_putc(&seq, call); ks_putc(&qual, 33 + cq); }
        if (show_ins && depth > 0 && nins * 2 > depth) {
            /* majority insertion: use the first read's insertion */
            for (int i = 0; i < n; i++) if (pl[i].indel > 0) { plp_insertion(&pl[i], &ins, NULL); ks_puts(&seq, ins.s); for (size_t k = 0; k < ins.l; k++) ks_putc(&qual, 33 + cq); break; }
        }
    }
    if (last_tid >= 0 && all) { int64_t e = reg && rend < a.h->tlen[last_tid] ? rend : a.h->tlen[last_tid]; while (++last_pos < e) { ks_putc(&seq, 'N'); ks_putc(&qual, '!'); } }
    EMIT_REF();
    ks_free(&seq); ks_free(&qual); ks_free(&ins);
    plp_destroy(it);
    if (out != stdout) fclose(out);
    iter_destroy(a.iter);
    hdr_destroy(a.h);
    sf_close(a.fp);
    return 0;
}
