/* samtools tview (text and html-less text output only) */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
#include <unistd.h>
#include "common.h"
#include "plp.h"
#include "fai.h"

/* ---- error model (genotype likelihoods) ---- */
typedef struct { double depcorr; double *fk, *beta, *lhet; } errmod_t;

static errmod_t *errmod_init(double depcorr) {
    errmod_t *em = xcalloc(1, sizeof(errmod_t));
    em->depcorr = depcorr;
    int k, n, q;
    long double sum_a[257], b[256], q_c[256], fk2[256];
    double *lC;
    em->fk = xcalloc(256, sizeof(double));
    em->fk[0] = fk2[0] = 1.0;
    for (n = 1; n != 256; ++n) {
        em->fk[n] = pow(1. - em->depcorr, n) * (1.0 - em->depcorr) + em->depcorr;
        fk2[n] = em->fk[n-1];
    }
    em->beta = xcalloc(256 * 256 * 64, sizeof(double));
    lC = xcalloc(256 * 256, sizeof(double));
    for (n = 1; n != 256; ++n) {
        double lgn = lgamma(n + 1);
        for (k = 1; k <= n; ++k) lC[n<<8|k] = lgn - lgamma(k + 1) - lgamma(n - k + 1);
    }
    for (q = 1; q != 64; ++q) {
        double e = pow(10.0, -q / 10.0);
        double le = log(e), le1 = log(1.0 - e);
        for (n = 1; n <= 255; ++n) {
            double *beta = em->beta + (q<<16|n<<8);
            sum_a[n+1] = 0.0;
            for (k = n; k >= 0; --k) {
                sum_a[k] = sum_a[k+1] + expl(lC[n<<8|k] + k * le + (n - k) * le1);
                b[k] = sum_a[k+1] / sum_a[k];
                if (b[k] > 0.99) b[k] = 0.99;
            }
            for (k = 0; k != n; ++k) q_c[k] = -4.343 * fk2[k] * logl(b[k] / e);
            for (k = 1; k != n; ++k) q_c[k] += q_c[k-1];
            for (k = 0; k != n; ++k) beta[k] = q_c[k];
        }
    }
    em->lhet = xcalloc(256 * 256, sizeof(double));
    for (n = 0; n < 256; ++n)
        for (k = 0; k < 256; ++k) em->lhet[n<<8|k] = lC[n<<8|k] - M_LN2 * n;
    free(lC);
    return em;
}
static void errmod_destroy(errmod_t *em) { if (!em) return; free(em->fk); free(em->beta); free(em->lhet); free(em); }

static int cmp_u16(const void *a, const void *b) { uint16_t x = *(const uint16_t*)a, y = *(const uint16_t*)b; return x < y ? -1 : x > y; }

static int errmod_cal(const errmod_t *em, int n, int m, uint16_t *bases, float *q) {
    struct { double fsum[16], bsum[16]; uint32_t c[16]; } aux;
    int i, j, k, w[32];
    memset(q, 0, m * m * sizeof(float));
    if (n == 0) return 0;
    if (n > 255) n = 255;
    qsort(bases, n, sizeof(uint16_t), cmp_u16);
    memset(w, 0, sizeof w);
    memset(&aux, 0, sizeof aux);
    for (j = n - 1; j >= 0; --j) {
        uint16_t b = bases[j];
        int qq = b >> 5 < 4 ? 4 : b >> 5;
        if (qq > 63) qq = 63;
        k = b & 0x1f;
        aux.fsum[k&0xf] += em->fk[w[k]];
        aux.bsum[k&0xf] += em->fk[w[k]] * em->beta[qq<<16|n<<8|aux.c[k&0xf]];
        ++aux.c[k&0xf];
        ++w[k];
