/* samtools tview (text and html-less text output only) */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <math.h>
#include <unistd.h>
#include "common.h"
#include "plp.h"
#include "fai.h"

/* ---- error model (genotype likelihoods) ---- */
typedef struct { double depcorr; double *fk, *beta, *lhet; } errmod_t;

static errmod_t *errmod_init(double depcorr) {
    errmod_t *em = xcalloc(1, sizeof(errmod_t));
    em->depcorr = depcorr;
    int k, n, q;
    long double sum_a[257], b[256], q_c[256], fk2[256];
    double *lC;
    em->fk = xcalloc(256, sizeof(double));
    em->fk[0] = fk2[0] = 1.0;
    for (n = 1; n != 256; ++n) {
        em->fk[n] = pow(1. - em->depcorr, n) * (1.0 - em->depcorr) + em->depcorr;
        fk2[n] = em->fk[n-1];
    }
    em->beta = xcalloc(256 * 256 * 64, sizeof(double));
    lC = xcalloc(256 * 256, sizeof(double));
    for (n = 1; n != 256; ++n) {
        double lgn = lgamma(n + 1);
        for (k = 1; k <= n; ++k) lC[n<<8|k] = lgn - lgamma(k + 1) - lgamma(n - k + 1);
    }
    for (q = 1; q != 64; ++q) {
        double e = pow(10.0, -q / 10.0);
        double le = log(e), le1 = log(1.0 - e);
        for (n = 1; n <= 255; ++n) {
            double *beta = em->beta + (q<<16|n<<8);
            sum_a[n+1] = 0.0;
            for (k = n; k >= 0; --k) {
                sum_a[k] = sum_a[k+1] + expl(lC[n<<8|k] + k * le + (n - k) * le1);
                b[k] = sum_a[k+1] / sum_a[k];
                if (b[k] > 0.99) b[k] = 0.99;
            }
            for (k = 0; k != n; ++k) q_c[k] = -4.343 * fk2[k] * logl(b[k] / e);
            for (k = 1; k != n; ++k) q_c[k] += q_c[k-1];
            for (k = 0; k != n; ++k) beta[k] = q_c[k];
        }
    }
    em->lhet = xcalloc(256 * 256, sizeof(double));
    for (n = 0; n < 256; ++n)
        for (k = 0; k < 256; ++k) em->lhet[n<<8|k] = lC[n<<8|k] - M_LN2 * n;
    free(lC);
    return em;
}
static void errmod_destroy(errmod_t *em) { if (!em) return; free(em->fk); free(em->beta); free(em->lhet); free(em); }

static int cmp_u16(const void *a, const void *b) { uint16_t x = *(const uint16_t*)a, y = *(const uint16_t*)b; return x < y ? -1 : x > y; }

static int errmod_cal(const errmod_t *em, int n, int m, uint16_t *bases, float *q) {
    struct { double fsum[16], bsum[16]; uint32_t c[16]; } aux;
    int i, j, k, w[32];
    memset(q, 0, m * m * sizeof(float));
    if (n == 0) return 0;
    if (n > 255) n = 255;
    qsort(bases, n, sizeof(uint16_t), cmp_u16);
    memset(w, 0, sizeof w);
    memset(&aux, 0, sizeof aux);
    for (j = n - 1; j >= 0; --j) {
        uint16_t b = bases[j];
        int qq = b >> 5 < 4 ? 4 : b >> 5;
        if (qq > 63) qq = 63;
        k = b & 0x1f;
        aux.fsum[k&0xf] += em->fk[w[k]];
        aux.bsum[k&0xf] += em->fk[w[k]] * em->beta[qq<<16|n<<8|aux.c[k&0xf]];
        ++aux.c[k&0xf];
        ++w[k];
    }
    for (j = 0; j < m; ++j) {
        float tmp1, tmp3; int tmp2;
        for (k = 0, tmp1 = tmp3 = 0.0, tmp2 = 0; k < m; ++k) {
            if (k == j) continue;
            tmp1 += aux.bsum[k]; tmp2 += aux.c[k]; tmp3 += aux.fsum[k];
        }
        if (tmp2) q[j*m+j] = tmp1;
        for (k = j + 1; k < m; ++k) {
            int cjk = aux.c[j] + aux.c[k];
            for (i = 0, tmp2 = 0, tmp1 = tmp3 = 0.0; i < m; ++i) {
                if (i == j || i == k) continue;
                tmp1 += aux.bsum[i]; tmp2 += aux.c[i]; tmp3 += aux.fsum[i];
            }
            if (tmp2) q[j*m+k] = q[k*m+j] = -4.343 * em->lhet[cjk<<8|aux.c[k]] + tmp1;
            else q[j*m+k] = q[k*m+j] = -4.343 * em->lhet[cjk<<8|aux.c[k]];
        }
        for (k = 0; k < m; ++k) if (q[j*m+k] < 0.0) q[j*m+k] = 0.0;
    }
    return 0;
}

/* ---- level pileup ---- */
typedef struct fnode_s { int level, cnt; struct fnode_s *next; } fnode_t;

typedef struct {
    int mcol, mrow, ccol;
    int64_t left_pos, last_pos;
    int curr_tid;
    char *ref; int64_t l_ref;
    int ins, is_dot;
    char **screen; int row_count;
    errmod_t *em;
    /* lplbuf */
    int max, n_cur, n_pre, max_level;
    int *cur_level, *pre_level;
    fnode_t *head, *tail;
    int n_nodes;
    strmap_t *rg;
} tv_t;

static void tv_addch(tv_t *tv, int y, int x, int ch) {
    if (x >= tv->mcol || x < 0 || y < 0) return;
    while (tv->row_count <= y) {
        tv->screen = xrealloc(tv->screen, (tv->row_count + 1) * sizeof(char*));
        tv->screen[tv->row_count] = xmalloc(tv->mcol);
        memset(tv->screen[tv->row_count], ' ', tv->mcol);
        tv->row_count++;
    }
    tv->screen[y][x] = ch;
}
static void tv_printnum(tv_t *tv, int y, int x, long long v) {
    char buf[32]; int n = snprintf(buf, sizeof buf, "%lld", v);
    for (int i = 0; i < n; i++) tv_addch(tv, y, x + i, buf[i]);
}

static fnode_t *fn_new(void) { return xcalloc(1, sizeof(fnode_t)); }

static int fn_lt(const fnode_t *a, const fnode_t *b) { return a->cnt < b->cnt || (a->cnt == b->cnt && a->level < b->level); }

static void tv_pl_func(tv_t *tv, int tid, int64_t pos, int n, const pileup1_t *pl) {
    int64_t cp;
    int i, j, c, rb, max_ins = 0;
    uint32_t call = 0;
    (void)tid;
    if (pos < tv->left_pos || tv->ccol > tv->mcol) return;
    rb = (tv->ref && pos - tv->left_pos < tv->l_ref) ? tv->ref[pos - tv->left_pos] : 'N';
    for (cp = tv->last_pos + 1; cp < pos; ++cp) {
        if (cp % 10 == 0 && tv->mcol - tv->ccol >= 10) tv_printnum(tv, 0, tv->ccol, cp + 1);
        c = tv->ref ? tv->ref[cp - tv->left_pos] : 'N';
        tv_addch(tv, 1, tv->ccol++, c);
    }
    if (pos % 10 == 0 && tv->mcol - tv->ccol >= 10) tv_printnum(tv, 0, tv->ccol, pos + 1);
    {
        float bp[25]; float qs[4] = {0, 0, 0, 0};
        uint16_t *bases = xmalloc((n + 1) * sizeof(uint16_t));
        int nb = 0;
        int ref4 = seq_nt16_int[seq_nt16_table[(uint8_t)rb]];
        for (i = 0; i < n; i++) {
            const pileup1_t *p = pl + i;
            if (p->is_del || p->is_refskip || (p->b->core.flag & FUNMAP)) continue;
            int q = rec_qual(p->b)[p->qpos];
            int seqQ = 99;
            if (q < 13) continue;
            if (q > seqQ) q = seqQ;
            int mapQ = p->b->core.qual < 255 ? p->b->core.qual : 20;
            if (q > mapQ) q = mapQ;
            if (q > 63) q = 63;
            if (q < 4) q = 4;
            int b = seqi(rec_seq(p->b), p->qpos);
            b = seq_nt16_int[b ? b : seq_nt16_table[(uint8_t)rb]];
            (void)ref4;
            bases[nb++] = q << 5 | ((p->b->core.flag & FREVERSE) ? 1 : 0) << 4 | b;
            if (b < 4) qs[b] += q;
        }
        errmod_cal(tv->em, nb, 5, bases, bp);
        free(bases);
        int qsum[4], a1, a2, tmp;
        double p[3], prior = 30;
        for (i = 0; i < 4; ++i) qsum[i] = ((int)qs[i]) << 2 | i;
        for (i = 1; i < 4; ++i)
            for (j = i; j > 0 && qsum[j] > qsum[j-1]; --j) tmp = qsum[j], qsum[j] = qsum[j-1], qsum[j-1] = tmp;
        a1 = qsum[0] & 3; a2 = qsum[1] & 3;
        p[0] = bp[a1*5+a1]; p[1] = bp[a1*5+a2] + prior; p[2] = bp[a2*5+a2];
        if ("ACGT"[a1] != toupper(rb)) p[0] += prior + 3;
        if ("ACGT"[a2] != toupper(rb)) p[2] += prior + 3;
        if (p[0] < p[1] && p[0] < p[2]) call = (1<<a1)<<16 | (int)((p[1] < p[2] ? p[1] : p[2]) - p[0] + .499);
        else if (p[2] < p[1] && p[2] < p[0]) call = (1<<a2)<<16 | (int)((p[0] < p[1] ? p[0] : p[1]) - p[2] + .499);
        else call = (1<<a1|1<<a2)<<16 | (int)((p[0] < p[2] ? p[0] : p[2]) - p[1] + .499);
    }
    c = ",ACMGRSVTWYHKDBN"[call>>16 & 0xf];
    if (c == toupper(rb)) c = '.';
    tv_addch(tv, 2, tv->ccol, c);
    if (tv->ins) for (i = 0; i < n; ++i) { const pileup1_t *p = pl + i; if (p->indel > 0 && max_ins < p->indel) max_ins = p->indel; }
    for (j = 0; j <= max_ins; ++j) {
        for (i = 0; i < n; ++i) {
            const pileup1_t *p = pl + i;
            int row = 2 + p->level;
            int rev = (p->b->core.flag & FREVERSE) != 0;
            if (j == 0) {
                if (!p->is_del) {
                    c = seq_nt16_str[seqi(rec_seq(p->b), p->qpos)];
                    if (tv->is_dot && toupper(c) == toupper(rb)) c = rev ? ',' : '.';
                } else c = p->is_refskip ? (rev ? '<' : '>') : '*';
            } else {
                if (j > p->indel) c = '*';
                else c = seq_nt16_str[seqi(rec_seq(p->b), p->qpos + j)];
            }
            if (row > 2 && row < tv->mrow) tv_addch(tv, row, tv->ccol, rev ? tolower(c) : toupper(c));
        }
        c = j ? '*' : rb;
        tv_addch(tv, 1, tv->ccol++, c);
    }
    tv->last_pos = pos;
}

static void tview_func(tv_t *tv, int tid, int64_t pos, int n, const pileup1_t *pl) {
    fnode_t *p;
    int i, l, max_level;
    if (tv->max < n) {
        tv->max = n;
        tv->cur_level = xrealloc(tv->cur_level, sizeof(int) * tv->max);
        tv->pre_level = xrealloc(tv->pre_level, sizeof(int) * tv->max);
    }
    tv->n_cur = n;
    for (p = tv->head; p->next; p = p->next) if (p->cnt > 0) --p->cnt;
    max_level = 0;
    for (i = l = 0; i < n; ++i) {
        pileup1_t *pp = (pileup1_t*)(pl + i);
        if (pp->is_head) {
            if (tv->head->next && tv->head->cnt == 0) {
                fnode_t *q = tv->head->next;
                tv->cur_level[i] = tv->head->level;
                free(tv->head);
                tv->head = q;
                --tv->n_nodes;
            } else tv->cur_level[i] = ++tv->max_level;
        } else {
            tv->cur_level[i] = l < tv->n_pre ? tv->pre_level[l++] : ++tv->max_level;
            if (pp->is_tail) {
                tv->tail->level = tv->cur_level[i];
                tv->tail->cnt = 2;
                tv->tail->next = fn_new();
                tv->tail = tv->tail->next;
                ++tv->n_nodes;
            }
        }
        if (tv->cur_level[i] > max_level) max_level = tv->cur_level[i];
        pp->level = tv->cur_level[i];
    }
    tv_pl_func(tv, tid, pos, n, pl);
    if (tv->n_nodes) {
        fnode_t **aux = xmalloc((tv->n_nodes + 1) * sizeof(fnode_t*));
        int k = 0;
        for (p = tv->head; p->next;) {
            if (p->level > max_level) { fnode_t *q = p->next; free(p); p = q; }
            else { aux[k++] = p; p = p->next; }
        }
        aux[k] = tv->tail;
        tv->n_nodes = k;
        if (k) {
            for (int a = 1; a < k; a++) { fnode_t *t = aux[a]; int b = a - 1; while (b >= 0 && fn_lt(t, aux[b])) { aux[b+1] = aux[b]; b--; } aux[b+1] = t; }
            for (int a = 0; a < k; ++a) aux[a]->next = aux[a+1];
            tv->head = aux[0];
        } else tv->head = tv->tail;
        free(aux);
    }
    tv->max_level = max_level;
    memcpy(tv->pre_level, tv->cur_level, tv->n_cur * sizeof(int));
    for (i = l = 0; i < n; ++i) if (!pl[i].is_tail) tv->pre_level[l++] = tv->pre_level[i];
    tv->n_pre = l;
}

typedef struct { samfile_t *fp; iter_t *it; strmap_t *rg; } tvaux_t;
static int tv_read(void *data, rec_t *b) {
    tvaux_t *a = data;
    for (;;) {
        int r = iter_next(a->fp, a->it, b);
        if (r < 0) return r;
        if (a->rg) {
            uint8_t *t = aux_get(b, "RG");
            if (!t || !sm_has(a->rg, (char*)t + 1)) continue;
        }
        return r;
    }
}

int main_tview(int argc, char *argv[]) {
    int c, mode = 0, width = 0, hide_ins = 0, has_idx = 0;
    char *samples = NULL, *position = NULL, *refopt = NULL;
    static const struct option lopts[] = {
        {"input-fmt-option", required_argument, NULL, 1}, {"reference", required_argument, NULL, 2},
        {"verbosity", required_argument, NULL, 3}, {NULL, 0, NULL, 0}
    };
    while ((c = getopt_long(argc, argv, "s:p:d:Xw:i", lopts, NULL)) >= 0) {
        switch (c) {
        case 's': samples = optarg; break;
        case 'p': position = optarg; break;
        case 'd': mode = (optarg[0] == 'T' || optarg[0] == 't') ? 1 : (optarg[0] == 'H' || optarg[0] == 'h') ? 2 : 0; break;
        case 'X': has_idx = 1; break;
        case 'w': width = strtol(optarg, NULL, 0); break;
        case 'i': hide_ins = 1; break;
        case 2: refopt = optarg; break;
        case 1: case 3: break;
        default: fputs(usage_tview, stderr); return -1;
        }
    }
    if (argc == optind) { fputs(usage_tview, stderr); return -1; }
    const char *fn = argv[optind];
    const char *fn_idx = has_idx && optind + 1 < argc ? argv[optind + 1] : NULL;
    const char *fn_fa = argc > optind + 1 + (has_idx ? 1 : 0) ? argv[optind + 1 + (has_idx ? 1 : 0)] : refopt;
    if (mode == 0 && !isatty(STDOUT_FILENO)) mode = 1;
    tv_t tv; memset(&tv, 0, sizeof tv);
    tv.mcol = 80; tv.mrow = 99999;
    char *cols = getenv("COLUMNS");
    if (cols) { tv.mcol = atoi(cols); if (tv.mcol < 10) tv.mcol = 80; }
    if (width > 0) tv.mcol = width;
    tv.is_dot = 1; tv.ins = !hide_ins;
    samfile_t *fp = sf_open(fn, "r");
    if (!fp) { fprintf(stderr, "[bam_tview] Cannot open %s\n", fn); return 1; }
    hdr_t *h = sf_read_header(fp);
    if (!h) { fprintf(stderr, "[bam_tview] Cannot read header\n"); sf_close(fp); return 1; }
    idx_t *idx = fp->fmt == FMT_BAM ? idx_load_for(fn, fn_idx) : NULL;
    if (!idx) { fprintf(stderr, "Cannot read index for %s\n", fn); exit(1); }
    fai_t *fai = fn_fa ? fai_load(fn_fa) : NULL;
    tvaux_t a; memset(&a, 0, sizeof a); a.fp = fp;
    if (samples) {
        a.rg = sm_init();
        char *d = xstrdup(samples), *save = NULL;
        for (char *t = strtok_r(d, ",", &save); t; t = strtok_r(NULL, ",", &save)) {
            for (int k = 0; k < h->nl; k++) if (h->l[k].type[0] == 'R' && h->l[k].type[1] == 'G') {
                const char *id = hline_get(&h->l[k], "ID"), *sm = hline_get(&h->l[k], "SM");
                if (id && (strcmp(id, t) == 0 || (sm && strcmp(sm, t) == 0))) sm_put(a.rg, id, 1);
            }
        }
        free(d);
    }
    tv.curr_tid = 0; tv.left_pos = 0;
    if (position) {
        char *pos = xstrdup(position);
        char *colon = strrchr(pos, ':');
        int64_t beg = 0;
        if (colon) {
            extern int64_t parse_decimal(const char *str, char **end, int flags);
            char *e; int64_t v = parse_decimal(colon + 1, &e, 0);
            if (e != colon + 1) { beg = v - 1; if (beg < 0) beg = 0; *colon = 0; }
        }
        int tid = hdr_name2tid(h, pos);
        if (tid >= 0) { tv.curr_tid = tid; tv.left_pos = beg; }
        free(pos);
    } else if (fai) {
        for (int t = 0; t < h->n_targets; t++) if (fai_tid(fai, h->tname[t]) >= 0) { tv.curr_tid = t; break; }
    }
    tv.em = errmod_init(1. - 0.83);
    /* draw */
    tv.last_pos = tv.left_pos - 1;
    tv.ccol = 0;
    if (fai) {
        int id = fai_tid(fai, hdr_tname(h, tv.curr_tid));
        int64_t len = 0;
        if (id >= 0) tv.ref = fai_fetch_seq(fai, id, tv.left_pos, tv.left_pos + tv.mcol, &len);
        if (!tv.ref) { fprintf(stderr, "Could not read the reference sequence. Is it seekable (plain text or compressed + .gzi indexed with bgzip)?\n"); exit(1); }
        tv.l_ref = len;
    }
    tv.head = tv.tail = fn_new();
    a.it = idx_query(idx, tv.curr_tid, tv.left_pos, tv.left_pos + tv.mcol);
    plp_t *it = plp_init(NULL, NULL);
    plp_set_maxcnt(it, INT32_MAX);
    rec_t *b = rec_init();
    int r, tid, np; int64_t ppos;
    const pileup1_t *pl;
    while ((r = tv_read(&a, b)) >= 0) {
        plp_push(it, b);
        while ((pl = plp_next(it, &tid, &ppos, &np)) != NULL) tview_func(&tv, tid, ppos, np, pl);
    }
    plp_push(it, NULL);
    while ((pl = plp_next(it, &tid, &ppos, &np)) != NULL) tview_func(&tv, tid, ppos, np, pl);
    while (tv.ccol < tv.mcol) {
        int64_t pos = tv.last_pos + 1;
        if (pos % 10 == 0 && tv.mcol - tv.ccol >= 10) tv_printnum(&tv, 0, tv.ccol, pos + 1);
        tv_addch(&tv, 1, tv.ccol++, (tv.ref && pos - tv.left_pos < tv.l_ref) ? tv.ref[pos - tv.left_pos] : 'N');
        ++tv.last_pos;
    }
    for (int y = 0; y < tv.row_count; y++) {
        fwrite(tv.screen[y], 1, tv.mcol, stdout);
        fputc('\n', stdout);
        free(tv.screen[y]);
    }
    free(tv.screen);
    rec_destroy(b);
    plp_destroy(it);
    iter_destroy(a.it);
    sm_destroy(a.rg);
    fnode_t *p = tv.head; while (p) { fnode_t *q = p->next; free(p); p = q; }
    free(tv.cur_level); free(tv.pre_level); free(tv.ref);
    errmod_destroy(tv.em);
    fai_destroy(fai);
    idx_destroy(idx);
    hdr_destroy(h);
    sf_close(fp);
    return 0;
}
